import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";

/**
 * Validate deletion attempt of a discussion board configuration using a non-existent id.
 *
 * This test verifies that the API returns a not found error when trying to delete a configuration record with an id that does not exist in the system. It also ensures that existing configuration records are not affected by this erroneous deletion attempt.
 *
 * Step-by-step process:
 * 1. Generate a random UUID that is highly unlikely to exist in the configuration table.
 * 2. Attempt to delete the configuration using the generated non-existent id.
 * 3. Confirm the API responds with an error (e.g. not found / does not succeed).
 * 4. Optionally, if a list/read API existed, verify that any previously existing configuration records remain unaffected after the failed deletion attempt. (Omit this check if unreadable with available API functions.)
 */
export async function test_api_discussionboard_test_delete_configuration_with_nonexistent_id(
  connection: api.IConnection,
) {
  // 1. Generate a random UUID not tied to any config
  const randomId = typia.random<string & tags.Format<"uuid">>();

  // 2. Try to delete configuration using the non-existent id
  await TestValidator.error("Deleting non-existent config should fail")(
    async () => {
      await api.functional.discussionboard.configurations.erase(connection, {
        id: randomId,
      });
    },
  );
}

