/**
 * Test the creation of a new trending topic with valid data.
 *
 * Business context:
 * Creating a trending topic in the discussion board analytics system requires all required fields: thread id, board id, ranking period (date), and trending score. This test verifies that a properly formed request results in a correctly persisted trending topic record, and that all returned schema fields are accurately populated.
 *
 * Steps:
 * 1. Prepare all required and valid fields for trending topic creation (valid UUIDs for thread/board, valid ISO date, valid numeric score).
 * 2. Call the POST /discussionboard/trendingTopics API to create the record.
 * 3. Assert that the response includes all schema-defined fields and that these fields match the sent request (for thread id, board id, date, and score). Also assert proper formatting for id (UUID) and ranking_period_date (ISO8601).
 */
export async function test_api_discussionboard_trendingTopics_create(
  connection: api.IConnection,
) {
  // 1. Prepare the valid request body for trending topic creation
  const trendingTopicInput: ITrendingTopic.ICreate = {
    discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
    ranking_period_date: typia.random<string & tags.Format<"date-time">>(),
    trending_score: typia.random<number>(),
  };

  // 2. Call the API to create trending topic
  const createdTopic: ITrendingTopic = await api.functional.discussionboard.trendingTopics.create(
    connection, { body: trendingTopicInput });
  typia.assert(createdTopic);

  // 3. Validate that returned object contains the same (input) values for key fields
  TestValidator.equals("discussionboard_thread_id")(createdTopic.discussionboard_thread_id)(trendingTopicInput.discussionboard_thread_id);
  TestValidator.equals("discussionboard_board_id")(createdTopic.discussionboard_board_id)(trendingTopicInput.discussionboard_board_id);
  TestValidator.equals("ranking_period_date")(createdTopic.ranking_period_date)(trendingTopicInput.ranking_period_date);
  TestValidator.equals("trending_score")(createdTopic.trending_score)(trendingTopicInput.trending_score);
  // Ensure id is a valid UUID and required fields are present
  typia.assert<string & tags.Format<"uuid">>(createdTopic.id);
  typia.assert<string & tags.Format<"date-time">>(createdTopic.ranking_period_date);
}

