import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardCategory";

/**
 * Validate duplicate code constraint when updating a board category.
 *
 * Business context: Board categories in the discussion board must have unique short codes (code). This is enforced both on creation and update. Attempting to update a board category's code to a value already in use by another category must fail.
 *
 * Workflow:
 * 1. Create board category A with code "alpha".
 * 2. Create board category B with code "bravo".
 * 3. Update category B attempting to set code to "alpha" (a duplicate).
 * 4. Assert that a validation/conflict error occurs due to the unique code constraint.
 *
 * This test ensures that code uniqueness is strictly enforced not only at creation, but also on category updates. This prevents accidental or malicious re-use of codes, which can cause navigation and integrity issues in the discussion board system.
 */
export async function test_api_discussionboard_boardCategories_test_update_board_category_with_duplicate_code_validation(
  connection: api.IConnection,
) {
  // 1. Create board category A with unique code "alpha"
  const boardA = await api.functional.discussionboard.boardCategories.create(connection, {
    body: {
      name: "Alpha Category",
      code: "alpha",
      description: "Alpha board category for uniqueness test.",
      position: 1
    }
  });
  typia.assert(boardA);

  // 2. Create board category B with unique code "bravo"
  const boardB = await api.functional.discussionboard.boardCategories.create(connection, {
    body: {
      name: "Bravo Category",
      code: "bravo",
      description: "Bravo board category for uniqueness test.",
      position: 2
    }
  });
  typia.assert(boardB);

  // 3. Attempt to update B's code to "alpha" (already used by A)
  await TestValidator.error("should fail to update code to duplicate value")(
    async () => {
      await api.functional.discussionboard.boardCategories.update(connection, {
        id: boardB.id,
        body: {
          code: "alpha"
        }
      });
    }
  );
}

