import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSetting";

/**
 * Validate the successful retrieval of a specific discussion board setting by its ID.
 *
 * This test simulates the business scenario where an administrator must review or audit the current configuration (such as a feature toggle or policy) for a specific area/feature within the discussion board system. To do so, the test first creates a new configuration record to guarantee a valid record exists, then fetches that precise record via its generated ID and ensures all schema fields are present and correctly returned per business contract.
 *
 * 1. Create a new discussion board setting (with defined scope_type, key, optional value & description).
 * 2. Retrieve the setting by its id using the GET /discussionboard/settings/{id} endpoint.
 * 3. Assert all response fields are present and match what was provided on insert (other than system fields like id, created_at, updated_at which are system-assigned but must be present).
 */
export async function test_api_discussionboard_settings_test_get_setting_detail_when_setting_exists(connection: api.IConnection) {
  // 1. Create a new setting record to test with
  const newSettingInput: IDiscussionboardSetting.ICreate = {
    scope_type: "feature_flag",
    key: RandomGenerator.alphabets(8),
    value: RandomGenerator.alphaNumeric(6),
    description: RandomGenerator.paragraph()(),
    // scope_id is left undefined/null to test both global usage and adherence to nullability
  };
  const created: IDiscussionboardSetting = await api.functional.discussionboard.settings.create(connection, { body: newSettingInput });
  typia.assert(created);

  // 2. Retrieve the specific setting by id
  const found: IDiscussionboardSetting = await api.functional.discussionboard.settings.at(connection, { id: created.id });
  typia.assert(found);

  // 3. Verify returned detail includes all schema fields and correct values
  TestValidator.equals("id matches")(found.id)(created.id);
  TestValidator.equals("scope_type matches")(found.scope_type)(newSettingInput.scope_type);
  TestValidator.equals("key matches")(found.key)(newSettingInput.key);
  TestValidator.equals("value matches")(found.value)(newSettingInput.value);
  TestValidator.equals("description matches")(found.description)(newSettingInput.description);
  // scope_id could be undefined/null; must match what was saved (null or omitted)
  TestValidator.equals("scope_id matches")(found.scope_id ?? null)(newSettingInput.scope_id ?? null);
  // created_at and updated_at must be present and plausibly ISO date strings
  TestValidator.predicate("created_at present and is date")(
    typeof found.created_at === "string" && !isNaN(Date.parse(found.created_at))
  );
  TestValidator.predicate("updated_at present and is date")(
    typeof found.updated_at === "string" && !isNaN(Date.parse(found.updated_at))
  );
}

