/**
 * Validate that deleting a board category with a non-existent id results in an error response (e.g., 404 Not Found).
 *
 * Business context: Irreversible deletion of board categories must be strictly managed. The system should never succeed, nor return a success status, when attempting to delete a board category id that does not exist in the database. Instead, the API should provide a clear indication of failure—such as a success flag set to false, a null deleted_id, and a textual "Not found" (or similar) reason.
 *
 * Step-by-step process:
 * 1. Generate a random UUID that will not correspond to any valid board category record (since test setup does not create one).
 * 2. Call the board category erase API endpoint with the generated UUID.
 * 3. Assert response properties: success should be false or undefined, deleted_id should be null or undefined, and reason string should contain or equal 'Not found'.
 * 4. Optionally, validate that no errors or data changes occurred elsewhere.
 */
export async function test_api_discussionboard_test_delete_nonexistent_board_category_returns_error(
  connection: api.IConnection,
) {
  // 1. Generate a random UUID (guaranteed not to exist)
  const nonExistentId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();

  // 2. Attempt to delete the nonexistent board category
  const output = await api.functional.discussionboard.boardCategories.erase(
    connection,
    { id: nonExistentId },
  );
  typia.assert(output);

  // 3. Validate API properly indicates failure
  TestValidator.equals("delete should fail - success is false")(output.success)(false);
  TestValidator.equals("deleted_id is null or undefined")(output.deleted_id)(null);
  TestValidator.predicate("reason is 'Not found' or clarifies not found")(typeof output.reason === 'string' && output.reason.toLowerCase().includes('not found'));
