/**
 * Validate that board creation fails when missing required fields (name, code, category, or section id).
 *
 * This test attempts to create boards by omitting one required field at a time. For each omission,
 * it expects a validation error from the API, and verifies that no board is created.
 *
 * Steps:
 * 1. Attempt to create a board without "name" (should fail validation)
 * 2. Attempt to create a board without "code" (should fail validation)
 * 3. Attempt to create a board without "discussionboard_board_category_id" (should fail validation)
 * 4. Attempt to create a board without "discussionboard_section_id" (should fail validation)
 * In each case, check that an error is thrown and no board is created.
 */
export async function test_api_discussionboard_test_create_board_with_missing_required_field(
  connection: api.IConnection,
) {
  // Prepare generic valid board creation data
  const validData: IBoard.ICreate = {
    discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
    name: "Sample Board",
    code: `sample_${String(Date.now())}`,
    description: "Sample board for validation test.",
    is_active: true,
    is_visible: true,
  };

  // Helper to shallow copy and omit a key
  const omit = <T extends object>(obj: T, key: keyof T): Partial<T> => {
    const { [key]: _, ...rest } = obj;
    return rest;
  };

  // 1. Omit "name"
  await TestValidator.error("missing name should fail")(() =>
    api.functional.discussionboard.boards.create(connection, {
      body: omit(validData, "name") as IBoard.ICreate,
