/**
 * Test successful hard deletion of a board category (irreversible removal).
 *
 * This test will verify the correct workflow for permanently deleting a board category from
the discussion board system. The process simulates a full end-to-end admin workflow:
 *
 * 1. Create a new board category (using valid random data for all fields to ensure uniqueness).
 * 2. Execute the DELETE endpoint with the category id to perform a hard delete.
 * 3. Validate the response object to confirm successful deletion and the correct deleted_id.
 * 4. Attempt to retrieve the deleted id and assert that a HttpError 404 is thrown, confirming irreversible removal.
 */
export async function test_api_discussionboard_boardCategories_test_delete_board_category_successfully(
  connection: api.IConnection,
) {
  // 1. Create a new board category (admin action to prepare a real entity for deletion test)
  const category = await api.functional.discussionboard.boardCategories.create(connection, {
    body: {
      name: RandomGenerator.paragraph()(1),
      code: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.content()()(),
      position: typia.random<number & tags.Type<"int32">>(),
