  await TestValidator.error("deleted board category not found")(
    async () => {
      // Simulate a GET: the recommended pattern is to re-call the delete endpoint to provoke 404
      // But since there's no GET, we check deletion by asserting that a repeated DELETE yields a failure, as no GET API is provided.
      const retry = await api.functional.discussionboard.boardCategories.erase(connection, {
        id: category.id,
      });
      // Should return success: false and a reason indicating it's already deleted or missing
      TestValidator.equals("deletion result must indicate failure")(retry.success)(false);
    }
  );
}

