import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoard";

/**
 * Test deletion of a board and the re-creation of a new board with the same unique code.
 *
 * Business context: Boards must have a unique code. This test verifies whether, after deleting a board (hard deletion), the same code can be recycled for a new board, confirming that the unique constraint is released effectively on delete (no lingering constraints/ghost references in the DB).
 *
 * Steps:
 * 1. Create a board with a unique code
 * 2. Delete that board
 * 3. Attempt to create another board with the same code
 * 4. Assert that the new creation succeeds (board is created and returned), unless some legacy/invisible constraint remains
 *
 * This test ensures that the board deletion is truly permanent and frees up all special constraints for future board creations.
 */
export async function test_api_discussionboard_test_delete_board_then_attempt_recreation_with_same_code(
  connection: api.IConnection,
) {
  // 1. Create a new board with a random, unique code
  const code: string = RandomGenerator.alphaNumeric(10);
  const categoryId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const sectionId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const createBody: IBoard.ICreate = {
    discussionboard_board_category_id: categoryId,
    discussionboard_section_id: sectionId,
    name: RandomGenerator.name(),
    code,
    description: RandomGenerator.paragraph()(),
    is_active: true,
    is_visible: true,
  };
  const created = await api.functional.discussionboard.boards.create(connection, { body: createBody });
  typia.assert(created);
  TestValidator.equals("board code matches")(created.code)(code);

  // 2. Hard delete the board
  await api.functional.discussionboard.boards.erase(connection, { id: created.id });

  // 3. Attempt to create a new board with the SAME code (should succeed)
  const createBody2: IBoard.ICreate = {
    ...createBody,
    name: RandomGenerator.name(), // give different name to differentiate
    description: RandomGenerator.paragraph()(),
  };
  const created2 = await api.functional.discussionboard.boards.create(connection, { body: createBody2 });
  typia.assert(created2);
  TestValidator.equals("board code reusable")(created2.code)(code);
}

