    connection,
    { body: input }
  );
  typia.assert(created);

  // 2. Retrieve the template by ID
  const retrieved: INotificationTemplate = await api.functional.discussionboard.notificationTemplates.at(
    connection,
    { id: created.id }
  );
  typia.assert(retrieved);

  // 3. Assert field-level equality for properties persisted from creation
