import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerationAction";

/**
 * Test updating details of a moderation action by id
 *
 * This test validates the workflow for updating a moderation action using the PUT endpoint by id.
 * The process is as follows:
 * 1. Create an initial moderation action using the POST endpoint
 * 2. Update the moderation action via PUT endpoint using new values for action_type, rationale, or target_object_type
 * 3. After updating, retrieve the updated moderation action from the API response and verify that all updated fields were correctly applied
 * 4. Ensure that only allowed (schema-defined) fields are modifiable and fields not meant to be changed (such as id) remain unchanged
 *
 * This test ensures compliance with audit and governance requirements, verifying that only permitted moderation action fields can be modified and that server-side logic correctly prevents updates to immutable fields.
 */
export async function test_api_discussionboard_moderationActions_test_update_moderation_action_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create an initial moderation action
  const initialCreate: IDiscussionboardModerationAction = await api.functional.discussionboard.moderationActions.create(
    connection,
    {
      body: {
        report_id: null,
        acting_moderator_id: typia.random<string & tags.Format<"uuid">>(),
        target_object_id: typia.random<string & tags.Format<"uuid">>(),
        target_object_type: "post",
        action_type: "warn",
        rationale: "Initial rationale.",
        actioned_at: new Date().toISOString(),
      } satisfies IDiscussionboardModerationAction.ICreate,
    },
  );
  typia.assert(initialCreate);

  // 2. Prepare update payload with new values for modifiable fields
  const updatedValues: IDiscussionboardModerationAction.IUpdate = {
    report_id: typia.random<string & tags.Format<"uuid">>(),
    acting_moderator_id: initialCreate.acting_moderator_id, // normally, moderation action is updated by original actor
    target_object_id: initialCreate.target_object_id,
    target_object_type: "comment",
    action_type: "delete",
    rationale: "Updated rationale.",
    actioned_at: new Date(Date.now() + 1000 * 60).toISOString(), // 1 minute after creation
  };

  // 3. Update the moderation action via PUT endpoint
  const updatedAction: IDiscussionboardModerationAction = await api.functional.discussionboard.moderationActions.update(
    connection,
    {
      id: initialCreate.id,
      body: updatedValues,
    },
  );
  typia.assert(updatedAction);

  // 4. Validate updated fields and immutable fields
  TestValidator.equals("id is immutable")(updatedAction.id)(initialCreate.id);
  TestValidator.equals("acting_moderator_id matches")(updatedAction.acting_moderator_id)(updatedValues.acting_moderator_id);
  TestValidator.equals("target_object_id matches")(updatedAction.target_object_id)(updatedValues.target_object_id);
  TestValidator.equals("target_object_type updated")(updatedAction.target_object_type)(updatedValues.target_object_type);
  TestValidator.equals("action_type updated")(updatedAction.action_type)(updatedValues.action_type);
  TestValidator.equals("rationale updated")(updatedAction.rationale)(updatedValues.rationale);
  TestValidator.equals("actioned_at updated")(updatedAction.actioned_at)(updatedValues.actioned_at);
  TestValidator.equals("report_id updated")(updatedAction.report_id)(updatedValues.report_id);
