import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardConfiguration";

/**
 * Validate updating the value and description of a discussion board system configuration.
 *
 * This test ensures that an admin can update the 'value' and 'description' fields of a configuration, but cannot modify immutable fields such as 'key' and 'id'.
 * The workflow simulates an actual admin updating a configuration for the system and validates that only the allowed fields change as expected, while the immutable fields remain the same.
 *
 * Step-by-step process:
 * 1. Create a system configuration using the API (as dependency).
 * 2. Update the configuration using the id, supplying a new value and a new description (possibly null).
 * 3. Verify that the updated configuration's id and key are unchanged, but value and/or description are updated as requested.
 * 4. Ensure audit fields (created_at, updated_at) are valid ISO strings and updated_at is more recent than the original created_at.
 */
export async function test_api_discussionboard_configurations_test_update_configuration_value_and_description(connection: api.IConnection) {
  // 1. Create a configuration as prerequisite.
  const createInput: IDiscussionboardConfiguration.ICreate = {
    key: RandomGenerator.alphabets(12),
    value: "original-value",
    description: "Initial setting for test.",
  };

  const created: IDiscussionboardConfiguration = await api.functional.discussionboard.configurations.create(connection, {
    body: createInput,
  });
  typia.assert(created);

  // 2. Prepare update payload with new value and description, including valid edge cases like null values.
  const updateInput: IDiscussionboardConfiguration.IUpdate = {
    value: "updated-value-test",
    description: null,
  };

  // 3. Send update request.
  const updated: IDiscussionboardConfiguration = await api.functional.discussionboard.configurations.update(connection, {
    id: created.id,
    body: updateInput,
  });
  typia.assert(updated);

  // 4. Validate immutability of 'id' and 'key'.
  TestValidator.equals("id remains unchanged")(updated.id)(created.id);
  TestValidator.equals("key remains unchanged")(updated.key)(created.key);

  // 5. Validate that value and description are updated.
  TestValidator.equals("value updated")(updated.value)(updateInput.value);
  TestValidator.equals("description updated")(updated.description)(updateInput.description);

  // 6. Validate audit fields and time progression.
  TestValidator.equals("created_at unchanged")(updated.created_at)(created.created_at);
  TestValidator.predicate("updated_at is after or equal to created_at")(
    new Date(updated.updated_at).getTime() >= new Date(created.created_at).getTime()
  );
}

