import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardEngagementMetric } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardEngagementMetric";

/**
 * Test creating an engagement metric with varied input quality.
 *
 * Business goal: Ensure full coverage for valid creation, proper schema population, constraint validations, and clear error handling for engagement metric creation. This includes failing on missing or invalid input and handling duplicate creation per any uniqueness constraints (typically on member+board+date).
 *
 * Steps:
 * 1. Create a valid engagement metric row using full data (happy path).
 *    - Confirm a new record is returned with correct types/fields populated, and that non-provided optionals default/null as expected.
 * 2. Attempt required field omissions: try creating with missing engagement_date or counts, and confirm errors occur, with no record created.
 * 3. Submit invalid values: negative values for posts_created_count, comments_created_count or votes_cast_count, or non-integers where an int is required. Each attempt should fail cleanly with no partial row.
 * 4. Edge: If uniqueness is enforced on member/board/date, attempt exact duplicate creation. Expect error, otherwise check system's behavior if duplicates are permitted.
 *
 * The test should assert that error responses never create a record and are explicit, and that happy path populates all types as documented. No invented or extra properties must be sent/received.
 */
export async function test_api_discussionboard_test_create_engagement_metric_with_valid_data_and_constraint_violations(
  connection: api.IConnection,
) {
  // 1. Happy path: valid data
  const validInput: IDiscussionboardEngagementMetric.ICreate = {
    discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
    engagement_date: typia.random<string & tags.Format<"date-time">>(),
    posts_created_count: 5,
    comments_created_count: 12,
    votes_cast_count: 4,
  };
  const created = await api.functional.discussionboard.engagementMetrics.create(connection, { body: validInput });
  typia.assert(created);
  TestValidator.equals("discussionboard_member_id")(created.discussionboard_member_id)(validInput.discussionboard_member_id);
  TestValidator.equals("discussionboard_board_id")(created.discussionboard_board_id)(validInput.discussionboard_board_id);
  TestValidator.equals("engagement_date")(created.engagement_date)(validInput.engagement_date);
  TestValidator.equals("posts_created_count")(created.posts_created_count)(validInput.posts_created_count);
  TestValidator.equals("comments_created_count")(created.comments_created_count)(validInput.comments_created_count);
  TestValidator.equals("votes_cast_count")(created.votes_cast_count)(validInput.votes_cast_count);
  // New row should have id
  TestValidator.predicate("new id exists")(!!created.id && typeof created.id === "string");

  // 2. Missing required fields: Omit engagement_date (should fail)
  const missingDate = { ...validInput };
  delete missingDate.engagement_date;
  await TestValidator.error("missing engagement_date")(async () =>
    api.functional.discussionboard.engagementMetrics.create(connection, { body: missingDate as any }),
  );

  // 3. Negative count fields (constraint violation):
  const negativePosts = { ...validInput, posts_created_count: -1 };
  await TestValidator.error("negative posts_created_count")(async () =>
    api.functional.discussionboard.engagementMetrics.create(connection, { body: negativePosts }),
  );

  const negativeComments = { ...validInput, comments_created_count: -3 };
  await TestValidator.error("negative comments_created_count")(async () =>
    api.functional.discussionboard.engagementMetrics.create(connection, { body: negativeComments }),
  );

  const negativeVotes = { ...validInput, votes_cast_count: -2 };
  await TestValidator.error("negative votes_cast_count")(async () =>
    api.functional.discussionboard.engagementMetrics.create(connection, { body: negativeVotes }),
  );

  // 4. Edge: duplicate (member+board+date)
  // Create row once more with same data (should fail if unique constraint exists)
  await TestValidator.error("duplicate member+board+date")(async () =>
    api.functional.discussionboard.engagementMetrics.create(connection, { body: validInput }),
  );
}

