 * This test simulates an end-to-end user flow:
 * 1. Register a new member (to have a valid user)
 * 2. Create a member preference for the member
 * 3. Delete the member preference (hard delete) by its ID
 * 4. Confirm the delete response is successful (i.e., no error is thrown)
 * 5. Attempt to delete again, and confirm it returns a not found error
 *
 * This covers both the happy path and the error scenario where the deleted resource does not exist anymore.
 */
export async function test_api_discussionboard_test_delete_member_preference_by_id_success(connection: api.IConnection) {
  // 1. Register a member
  const memberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(12),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    role: "member",
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create a preference for that member
  const prefInput: IMemberPreference.ICreate = {
    member_id: member.id,
    receive_email_notifications: true,
