 * 2. 여러 필드(username/email/role/is_active) 값을 임의로 일부/전체 변경
 * 3. 변경 API 호출/응답의 변경사항 반영 검증
 */
export async function test_api_discussionboard_members_test_update_member_profile_with_valid_changes(
  connection: api.IConnection,
) {
  // 1. 유효한 회원 계정 생성 (사전조건)
  const originalMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(originalMember);

  // 2. 변경할 값 설정 (username/email/role/is_active를 새 값들로 수정)
  const newUsername = RandomGenerator.alphaNumeric(10);
  const newEmail = typia.random<string & tags.Format<"email">>();
  const newRole = "moderator";
  const newIsActive = false;

  // 3. 업데이트 API 호출
  const updatedMember = await api.functional.discussionboard.members.update(connection, {
    id: originalMember.id,
    body: {
      username: newUsername,
      email: newEmail,
      role: newRole,
      is_active: newIsActive,
    } satisfies IDiscussionboardMember.IUpdate,
  });
  typia.assert(updatedMember);

  // 4. 변경사항 반영 확인
  TestValidator.equals("username 반영됨")(updatedMember.username)(newUsername);
  TestValidator.equals("email 반영됨")(updatedMember.email)(newEmail);
  TestValidator.equals("role 반영됨")(updatedMember.role)(newRole);
  TestValidator.equals("is_active 반영됨")(updatedMember.is_active)(newIsActive);
  // id 및 생성/갱신 일시 등 변하지 않아야 하는 값 확인
  TestValidator.equals("id 불변")(updatedMember.id)(originalMember.id);
}

