import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";

/**
 * Test deleting a non-existent or already deleted moderation report by ID.
 *
 * This test ensures the following:
 * 1. Attempts to delete a moderation report using a UUID that does NOT exist in the database.
 * 2. Expects the API to return a not found error (typically 404 or similar behavior with no side effects).
 * 3. Verifies that this operation does not affect or error for unrelated existing records (if any exist).
 * 4. Also attempts to delete using a (simulated) previously deleted ID, expecting the same not found error behavior.
 *
 * As there are no creation or seeding APIs defined, this test operates under the assumption that newly generated UUIDs do not correspond to real records and are thus safe to use for not-found scenarios.
 *
 * - Attempts a hard delete using eraseById API with a random UUID (no matching record).
 * - Expects a not found error.
 * - Optionally repeats with a GUID that has already been deleted, if deletion can occur (simulated here as another random UUID).
 * - No additional API calls are performed to check for unintended effects, since no list or fetch API is available for unrelated records.
 */
export async function test_api_discussionboard_test_delete_nonexistent_moderation_report_by_id(
  connection: api.IConnection,
) {
  const nonExistentId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  // Attempt to delete a non-existent ID, expecting an error (likely 404 Not Found)
  await TestValidator.error("non-existent moderation report should return not found error")(async () => {
    await api.functional.discussionboard.reports.erase(
      connection,
      { id: nonExistentId },
    );
  });

  // Optionally, try a second time to simulate 'already deleted' logic
  await TestValidator.error("already deleted ID returns not found error as well")(async () => {
    await api.functional.discussionboard.reports.erase(
      connection,
      { id: nonExistentId },
    );
  });
}

