import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IMemberPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberPreference";

/**
 * Validate retrieval of an existing member preference by ID.
 *
 * This test ensures that when a member's preferences exist in the system, fetching by ID will return an object with all expected fields, and those fields correspond exactly to what was created.
 *
 * Test steps:
 * 1. Register a new discussion board member (to obtain a valid member_id)
 * 2. Create a new member preference record tied to the created member
 * 3. Retrieve the member preference by its ID using the API
 * 4. Assert that all fields in the retrieved object match the ones from the creation step
 */
export async function test_api_discussionboard_memberPreferences_test_get_member_preference_by_id_when_exists(
  connection: api.IConnection,
) {
  // 1. Register a new discussion board member
  const memberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    role: "member",
    is_active: true,
  };
  const member: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create a member preference linked to new member
  const prefInput: IMemberPreference.ICreate = {
    member_id: member.id,
    receive_email_notifications: true,
    receive_push_notifications: false,
    preferred_language: "en",
    dark_mode_enabled: true,
  };
  const createdPref: IMemberPreference = await api.functional.discussionboard.memberPreferences.create(connection, { body: prefInput });
  typia.assert(createdPref);

  // 3. Retrieve the preference by ID
  const retrievedPref: IMemberPreference = await api.functional.discussionboard.memberPreferences.at(connection, { id: createdPref.id });
  typia.assert(retrievedPref);

  // 4. Assert all defined fields match
  TestValidator.equals("preference.id matches")(retrievedPref.id)(createdPref.id);
  TestValidator.equals("preference.member_id matches")(retrievedPref.member_id)(member.id);
  TestValidator.equals("receive_email_notifications matches")(retrievedPref.receive_email_notifications)(prefInput.receive_email_notifications);
  TestValidator.equals("receive_push_notifications matches")(retrievedPref.receive_push_notifications)(prefInput.receive_push_notifications);
  TestValidator.equals("preferred_language matches")(retrievedPref.preferred_language)(prefInput.preferred_language);
  TestValidator.equals("dark_mode_enabled matches")(retrievedPref.dark_mode_enabled)(prefInput.dark_mode_enabled);
}

