  TestValidator.equals("title")(fetched.title)(notificationInput.title);
  TestValidator.equals("body")(fetched.body)(notificationInput.body);
  TestValidator.equals("delivered")(fetched.delivered)(notificationInput.delivered);
  // target_id is optional, but included in this case
  TestValidator.equals("target_id")(fetched.target_id)(notificationInput.target_id);
  // created_at and delivered_at can have minor diffs (truncated ms); check validity
