import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardChannel";
import type { IDiscussionboardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSection";

/**
 * E2E test for permanently deleting a discussion board section by its ID.
 *
 * This test verifies that when a section is created and then permanently deleted by admin or system manager, the section is properly removed from the database and cannot be retrieved anymore. It covers full flow and deletion confirmation.
 *
 * Test workflow:
 * 1. Create a new discussion board channel (required prerequisite for section).
 * 2. Create a new section under this channel.
 * 3. Delete this section by its ID using the hard delete API.
 * 4. Verify the delete API returns a success confirmation and the ID of the deleted section matches.
 * 5. Attempt to retrieve the section by ID (should fail, not found error expected).
 */
export async function test_api_discussionboard_test_delete_section_permanently(
  connection: api.IConnection,
) {
  // 1. Create a new channel
  const channelInput: IDiscussionboardChannel.ICreate = {
    code: RandomGenerator.alphaNumeric(6),
    name: RandomGenerator.paragraph()(1),
    description: null,
    position: 1,
    active: true,
  };
  const channel = await api.functional.discussionboard.channels.create(connection, { body: channelInput });
  typia.assert(channel);

  // 2. Create a new section in the created channel
  const sectionInput: IDiscussionboardSection.ICreate = {
    discussionboard_channel_id: channel.id,
    code: RandomGenerator.alphaNumeric(6),
    name: RandomGenerator.paragraph()(1),
    description: null,
    position: 1,
    active: true,
  };
  const section = await api.functional.discussionboard.sections.create(connection, { body: sectionInput });
  typia.assert(section);

  // 3. Delete the section by id
  const deleteResult = await api.functional.discussionboard.sections.erase(connection, { id: section.id });
  typia.assert(deleteResult);
  TestValidator.equals("deletion success")(deleteResult.success)(true);
  TestValidator.equals("deleted section id")(deleteResult.id)(section.id);

  // 4. Attempt to get the deleted section (should fail)
  await TestValidator.error("section should not be found after delete")(() =>
    api.functional.discussionboard.sections.at(connection, { id: section.id })
  );
}

