import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardNotification";

/**
 * 테스트 목적: 알림 로그의 주요 필드(종류, 제목, 본문, 배달여부, 배달시각, 타겟 ID) 변경/업데이트 요청의 결과를 확인합니다. 또한, 불변 필드(id, created_at)의 변경 시도/에러 검증, 비존재 알림에 대한 404 반환, 권한 없는 접근에 대한 거부가 정상 처리되는지 확인합니다.
 *
 * 1. 관리자로 알림 로그 한 건을 생성한다.
 * 2. 허용 필드(타입, 제목, 본문, 배달여부, 배달시각, 타겟ID)만 정상 변경되며, 실제로 변경됐는지 반환 레코드로 검증한다.
 * 3. id, created_at 등 불변값 변경 시도시, 올바른 에러 혹은 무시되어야 한다(성공적으로 값이 바뀌면 안 됨).
 * 4. 존재하지 않는 id로 업데이트 요청시 404 등 에러를 반환하는지 확인한다.
 * 5. 비관리자/비인가 사용자로(로그인 없이) update 요청 시, 권한 거부(401, 403 등)되는지 확인한다.
 */
export async function test_api_discussionboard_test_update_notification_with_valid_and_invalid_fields(
  connection: api.IConnection,
) {
  // 1. Create a notification log as admin (assumed test connection already has admin/simulation rights)
  const created = await api.functional.discussionboard.notifications.create(connection, {
    body: {
      type: "system_announcement",
      title: "Original Title",
      delivered: false,
      created_at: new Date().toISOString(),
      body: "Initial notification body",
      target_id: typia.random<string & tags.Format<"uuid">>(),
      delivered_at: null,
    },
  });
  typia.assert(created);

  // 2. 정상 필드값만 변경, 결과가 잘 반영됐는지 확인
  const updateValid = await api.functional.discussionboard.notifications.update(connection, {
    id: created.id,
    body: {
      type: "user_mention",
      title: "Changed Title",
      body: "Updated notification body",
      delivered: true,
      delivered_at: new Date().toISOString(),
      target_id: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(updateValid);
  TestValidator.equals("변경된 type")(updateValid.type)("user_mention");
  TestValidator.equals("변경된 title")(updateValid.title)("Changed Title");
  TestValidator.equals("body 반영")(updateValid.body)("Updated notification body");
  TestValidator.equals("delivered 반영")(updateValid.delivered)(true);

  // 3. 불변/금지값(id, created_at 등) 값 변경 요청시 무시/에러 응답 확인(값이 변경되면 Fail 처리)
  await TestValidator.error("불변필드 created_at은 변경 불가")(
    async () => {
      await api.functional.discussionboard.notifications.update(connection, {
        id: created.id,
        body: {
          created_at: new Date(2029,1,1).toISOString(), // 불허
        } as any, // 실제 구조상 allowed fields만 허용되므로, 타입 밑돌림. 실제는 불가/실패 응답
      });
    }
  );
  // id 값 변경은 업데이트 API 구조상 body에 id를 줄 수 없으므로(파라미터이자 불변), 생략.

  // 4. 존재하지 않는 id로 업데이트 요청 시 404 에러 발생 검증
  await TestValidator.error("존재하지 않는 알림 id로 요청시 404")(
    async () => {
      await api.functional.discussionboard.notifications.update(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: {
          type: "user_mention"
        },
      });
    }
  );

  // 5. 권한 없는 연산: 비관리자 커넥션(로그인 없이)에서 권한 denial 확인
  const anon: api.IConnection = { host: connection.host };
  await TestValidator.error("비인가 사용자 접근은 금지")(
    async () => {
      await api.functional.discussionboard.notifications.update(anon, {
        id: created.id,
        body: {
          type: "system_announcement",
        },
      });
    }
  );
}

