/**
 * Test assigning moderator privileges to a member, validating successful creation, duplicate, and invalid admin assignment scenarios.
 *
 * This test ensures that moderator privilege assignments for the discussion board function as expected, enforcing uniqueness and referential integrity.
 *
 * Workflow:
 * 1. Create a member as an admin (assigner).
 * 2. Create a member as a regular member (assignee).
 * 3. Assign moderator privileges to the member with the admin as assigner. Include member_id, assigned_by_admin_id, assigned_at, and possibly expires_at.
 * 4. Validate that the moderator assignment is created with correct fields and references.
 * 5. Try to assign moderator privileges to the same member again (duplicate): Expect failure due to unique constraint.
 * 6. Attempt moderator assignment with a non-existent admin id for assigned_by_admin_id: Expect referential error/failure.
 */
export async function test_api_discussionboard_test_grant_moderator_privileges_valid_and_duplicate_assignment(connection: api.IConnection) {
  // 1. Create admin member (assigner)
  const adminInput = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphabets(16),
    role: "admin",
    is_active: true,
  } satisfies IDiscussionboardMember.ICreate;
  const admin = await api.functional.discussionboard.members.create(connection, { body: adminInput });
  typia.assert(admin);
  TestValidator.equals("admin role")(admin.role)("admin");

  // 2. Create target member (assignee)
  const memberInput = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphabets(16),
    role: "member",
    is_active: true,
  } satisfies IDiscussionboardMember.ICreate;
  const member = await api.functional.discussionboard.members.create(connection, { body: memberInput });
  typia.assert(member);
  TestValidator.equals("member role")(member.role)("member");

  // 3. Assign moderator privileges successfully
  const now = new Date().toISOString();
  const expiresAt = new Date(Date.now() + 7*86400*1000).toISOString(); // 1 week expiry
  const modAssignInput = {
    member_id: member.id,
    assigned_by_admin_id: admin.id,
    assigned_at: now,
    expires_at: expiresAt,
  } satisfies IModeratorAssignment.ICreate;
  const assignment = await api.functional.discussionboard.moderators.create(connection, { body: modAssignInput });
  typia.assert(assignment);
  TestValidator.equals("assigned member")(assignment.member_id)(member.id);
  TestValidator.equals("assigned by admin")(assignment.assigned_by_admin_id)(admin.id);
  TestValidator.equals("assigned at")(assignment.assigned_at)(now);
  TestValidator.equals("expires at")(assignment.expires_at)(expiresAt);
  TestValidator.equals("not revoked")(assignment.revoked_at)(null);

  // 4. Duplicate moderator assignment (should fail)
  await TestValidator.error("duplicate moderator assignment should fail")(async () => {
    await api.functional.discussionboard.moderators.create(connection, { body: modAssignInput });
  });

  // 5. Assign with invalid admin id (should fail)
  const fakeAdminId = typia.random<string & tags.Format<"uuid">>(); // not in DB
  const invalidInput = { ...modAssignInput, assigned_by_admin_id: fakeAdminId, assigned_at: new Date().toISOString() } satisfies IModeratorAssignment.ICreate;
  await TestValidator.error("invalid admin id should fail")(async () => {
    await api.functional.discussionboard.moderators.create(connection, { body: invalidInput });
  });
}

