      body: RandomGenerator.content()()(20, 50),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(targetPost);

  // 3. Create the post reference (source -> target)
  const postReference = await api.functional.discussionboard.postReferences.create(connection, {
    body: {
      source_post_id: sourcePost.id,
      target_post_id: targetPost.id,
      reference_type: "post",
    } satisfies IPostReference.ICreate,
  });
  typia.assert(postReference);

  // 4. Delete the post reference by id (should succeed, no error)
  await api.functional.discussionboard.postReferences.erase(connection, {
    id: postReference.id,
  });

  // 5. Try deleting again (should result in error)
  await TestValidator.error("idempotent delete fails for already deleted reference")(
