 * 3. Update ALL updatable fields (is_locked, require_approval_for_posting, max_posts_per_hour, allow_anonymous_viewing, allow_file_uploads) using valid but different values to simulate a full modification with new configuration.
 * 4. Verify the returned record reflects the updates, with each updated field set as provided.
 * 5. Confirm the updated_at field is actually newer than before (metadata audit).
 */
export async function test_api_discussionboard_boardSettings_test_update_board_setting_with_valid_data(connection: api.IConnection) {
  // Step 1: Create a board as the resource owner
  const board = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.paragraph()(),
      code: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(),
      is_active: true,
      is_visible: true,
    }
  });
  typia.assert(board);

  // Step 2: Create initial board settings record for that board
  const settings = await api.functional.discussionboard.boardSettings.create(connection, {
    body: {
      discussionboard_board_id: board.id,
      is_locked: false,
      require_approval_for_posting: false,
      max_posts_per_hour: 10,
      allow_anonymous_viewing: true,
      allow_file_uploads: false,
    }
  });
  typia.assert(settings);

  // Step 3: Update all configurable fields to new valid values
  const updates = {
    discussionboard_board_id: board.id,
    is_locked: true, // toggle board lock
    require_approval_for_posting: true, // stricter moderation
    max_posts_per_hour: settings.max_posts_per_hour + 5, // increase posting limit
    allow_anonymous_viewing: false, // more restricted
    allow_file_uploads: true, // enable uploads
  } satisfies IDiscussionboardBoardSetting.IUpdate;

  const updated = await api.functional.discussionboard.boardSettings.update(connection, {
    id: settings.id,
    body: updates,
  });
  typia.assert(updated);

  // Step 4: Validate updated fields
  TestValidator.equals("is_locked change")(updated.is_locked)(updates.is_locked);
  TestValidator.equals("require_approval_for_posting change")(updated.require_approval_for_posting)(updates.require_approval_for_posting);
  TestValidator.equals("max_posts_per_hour change")(updated.max_posts_per_hour)(updates.max_posts_per_hour);
  TestValidator.equals("allow_anonymous_viewing change")(updated.allow_anonymous_viewing)(updates.allow_anonymous_viewing);
  TestValidator.equals("allow_file_uploads change")(updated.allow_file_uploads)(updates.allow_file_uploads);

  // Step 5: Confirm updated_at is newer
  TestValidator.predicate("updated_at is newer")(new Date(updated.updated_at) > new Date(settings.updated_at));
}

