import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IMemberProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberProfile";

/**
 * Test successful update of an existing member profile by id.
 *
 * Workflow:
 * 1. Create a discussionboard_members record as the member who will own a profile.
 * 2. Create a member profile associated with this member, using initial values for all fields (including optional ones set to a value or null).
 * 3. Issue a PUT to /discussionboard/memberProfiles/{id} with new values for one or more updatable fields (choose at least display_name, and 1-2 optional fields, leave others the same or null as set).
 * 4. Confirm the response correctly reflects all values:
 *    - Updated fields are changed
 *    - Unchanged fields remain the same (or correctly null)
 *    - All response properties adhere to IMemberProfile schema
 * 5. Business rule validation: Only allow update of real profile fields (display_name, bio, avatar_url, location, website_url); should not be able to update member_id or id or add extra properties
 *
 * Detailed steps:
 * - Call api.functional.discussionboard.members.create with valid member info
 * - Call api.functional.discussionboard.memberProfiles.create with IMemberProfile.ICreate, setting all required and some optional fields
 * - Prepare a proper IMemberProfile.IUpdate payload, changing display_name and two optional fields (for instance, bio and website_url)
 * - Call api.functional.discussionboard.memberProfiles.update with correct id and body
 * - Assert the API response matches the schema and that only the intended fields are changed
 * - Assert unchanged fields retain their old values
 * - Assert output contains no extraneous properties
 */
export async function test_api_discussionboard_memberProfiles_test_update_member_profile_successful_update(
  connection: api.IConnection,
) {
  // 1. Create a member
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create initial member profile with various values
  const initialProfile = await api.functional.discussionboard.memberProfiles.create(connection, {
    body: {
      member_id: member.id,
      display_name: RandomGenerator.name(),
      bio: RandomGenerator.paragraph()(),
      avatar_url: "https://img.example.com/avatar.png",
      location: "Seoul, South Korea",
      website_url: "https://www.init-example.com",
    } satisfies IMemberProfile.ICreate,
  });
  typia.assert(initialProfile);

  // 3. Prepare update payload - update display_name, bio, and website_url
  const updatePayload = {
    display_name: initialProfile.display_name + "_updated",
    bio: initialProfile.bio ? initialProfile.bio + " UPDATED" : "Updated bio",
    website_url: "https://www.new-profile.com",
  } satisfies IMemberProfile.IUpdate;

  // 4. Update the member profile
  const updatedProfile = await api.functional.discussionboard.memberProfiles.update(connection, {
    id: initialProfile.id,
    body: updatePayload,
  });
  typia.assert(updatedProfile);

  // 5. Assert all profile fields
