import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardConfiguration";

/**
 * 이 테스트는 시스템 설정(configuration) 레코드의 key 필드가 불변(immutable)임을 검증합니다.
 * 
 * - 시나리오: 이미 존재하는 configuration 엔티티에 대해, 업데이트할 때 key 필드 값을 변경 시도하면 API가 이를 거부해야 하며, 실제로 DB의 원본 레코드의 key 값은 변화가 없어야 합니다.
 * - 목적: 잘못된 업데이트 요청이 비즈니스 룰에 의해 검출되고, 클라이언트가 해당 필드를 임의로 바꿀 수 없도록 방지함을 보장합니다.
 * 
 * [진행 단계]
 * 1. 임의의 key, value, description 조합으로 configuration을 생성한다. (dependencies: POST /discussionboard/configurations)
 * 2. 생성된 configuration id를 획득 후, PUT /discussionboard/configurations/{id}로 value/description은 그대로 두고 key 필드만 다른 임의 문자열로 변경하여 요청한다. (IUpdate에는 key가 없음)
 * 3. 필드 정의 상 key는 IUpdate의 body에 포함될 수 없으므로 실제 요청 시 타입 오류가 날 것임. → 즉, 타입 상으로도 위반이 불가능함을 검증.
 * 4. TypeScript 타입 시스템/SDK 상으로 key 필드를 넣을 수 없으므로, 실제 key 변경 시도 불가 및 런타임에서 요청이 거절되는지 확인한다.
 * 5. value, description 만을 정상적으로 변경했을 때엔 update가 정상 동작함을 재검증하여, 오직 key 필드 변경만이 금지된 점을 확실히 한다.
 */
export async function test_api_discussionboard_configurations_test_update_configuration_attempt_to_modify_key_field(
  connection: api.IConnection,
) {
  // 1. 임의의 설정 생성
  const configInput: IDiscussionboardConfiguration.ICreate = {
    key: `max_post_per_hour_${typia.random<number>()}`,
    value: "10",
    description: "최대 시간당 게시글 수 허용치",
  };
  const config = await api.functional.discussionboard.configurations.create(
    connection,
    { body: configInput }
  );
  typia.assert(config);

  // 2. 정상적인 value, description 변경은 성공해야 함
  const updated = await api.functional.discussionboard.configurations.update(
    connection,
    {
      id: config.id,
      body: {
        value: "12",
        description: "최대 시간당 게시글 수(변경됨)",
      },
    }
  );
  typia.assert(updated);
  TestValidator.equals("key는 변하지 않음")(updated.key)(config.key);
  TestValidator.equals("value는 변경")(updated.value)("12");
  TestValidator.equals("description 변경")(updated.description)("최대 시간당 게시글 수(변경됨)");

  // 3. key 필드를 포함하려 시도하면 타입 상으로도 불가하므로, 아래 코드는 컴파일러 오류여서 작성 불가함(실제 호출 차단됨)
  // 하지만 타입 안전성 외에도, 실 런타임 시 props.body에 key를 억지로 넣었다면 서버가 key 필드 변경 시도를 거부하는지 보장해야 하므로,
  // 불가피하게 런타임 오류(서버가 key 변경 거절)를 확인하는 패턴을 추가함

  TestValidator.error("key 필드 변경 시도시 거절됨")(() =>
    api.functional.discussionboard.configurations.update(
      connection,
      {
        id: config.id,
        // @ts-expect-error: 강제로 타입을 무시하고 key 수정 요청(실운영 소스에서는 불가)
        body: { key: "try_modify_key", value: "13" },
      } as any,
    )
  );

  // 4. 다시 읽어서 key가 진짜 그대로 남아있는지 확인
  // (별도의 단건조회 API 없으므로, 업데이트 결과에서 key 불변을 재확인)
  const finalConfig = await api.functional.discussionboard.configurations.update(
    connection,
    {
      id: config.id,
      body: { value: "14" },
    }
  );
  typia.assert(finalConfig);
  TestValidator.equals("key는 계속 유지됨")(finalConfig.key)(config.key);
};

