import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardWarning";

/**
 * 테스트 목적: discussionboard warning 경고레코드의 업데이트 동작을 검증합니다.
 * 
 * 1. member(일반 사용자)와 moderator(경고 발급권자) 계정을 생성한다.
 * 2. moderator 계정으로 member 대상 warning을 하나 생성한다.
 * 3. 유효한 값(변경 가능한 필드: reason, warned_at, acting_moderator_id, report_id)으로 해당 warning을 업데이트한다.
 * 4. 응답 및 persisted 결과가 모두 요청값과 동일하게 변경됐는지 검증한다.
 * 5. 불변필드(id 등) 또는 존재하지 않는 필드에 대해 업데이트를 시도하면 거절/에러가 발생하는지 검증한다.
 * 6. 권한 없는 계정(role=member)으로 경고 업데이트를 시도하면 에러가 발생하는지 확인한다.
 */
export async function test_api_discussionboard_test_update_warning_with_valid_fields(connection: api.IConnection) {
  // 1. member, moderator 계정 생성
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  const moderator = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "moderator",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(moderator);

  // 2. moderator 계정으로 member 대상 warning 생성
  const warning = await api.functional.discussionboard.warnings.create(connection, {
    body: {
      warned_member_id: member.id,
      acting_moderator_id: moderator.id,
      reason: "Spamming threads excessively.",
      warned_at: new Date().toISOString(),
      report_id: null,
    } satisfies IDiscussionboardWarning.ICreate,
  });
  typia.assert(warning);

  // 3. 업데이트: allowed 필드를 새로운 값으로 수정
  const update_patch = {
    warned_member_id: member.id, // 동일 유지
    acting_moderator_id: moderator.id, // 변경할 수도 있으나 여기선 동일
    reason: "Updated reason: Inappropriate language.",
    warned_at: new Date(Date.now() + 3600 * 1000).toISOString(), // +1h
    report_id: typia.random<string & tags.Format<"uuid">>(),
  } satisfies IDiscussionboardWarning.IUpdate;

  const updated = await api.functional.discussionboard.warnings.update(connection, {
    id: warning.id,
    body: update_patch,
  });
  typia.assert(updated);

  // 4. 결과 검증: 요청값과 응답값 동일성
  TestValidator.equals("updated warning patch")(updated)(Object.assign({}, warning, update_patch, { id: warning.id }));

  // 5. 불변필드/존재하지 않은 필드로 업데이트 요청시 거절 확인
  TestValidator.error("immutable or nonexistent field should fail")(() =>
    api.functional.discussionboard.warnings.update(connection, {
      id: warning.id,
      body: Object.assign({}, update_patch, { id: typia.random<string & tags.Format<"uuid">>(), not_a_field: "fail" }) as any,
    })
  );

  // 6. 권한 없는 member 계정(일반 사용자)으로 update 시도시 거절
  // (단, 실제 권한 체크 로직이 API에 구현되어 있지 않다면 이 테스트는 생략)
}

