  const code1 = RandomGenerator.alphaNumeric(8);
  const channel1 = await api.functional.discussionboard.channels.create(connection, {
    body: {
      code: code1,
      name: RandomGenerator.alphaNumeric(10),
      description: RandomGenerator.alphaNumeric(20),
      position: typia.random<number & tags.Type<"int32">>(),
      active: true,
