import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPrivacyPolicies } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPrivacyPolicies";

/**
 * Validate retrieving a privacy policy by ID yields the correct record and schema.
 *
 * Business context:
 * - Each privacy policy version is immutable and uniquely identified by an id (UUID).
 * - Retrieving a privacy policy by id should return the exact original entity (no computed data, no soft-deletion or archival flags).
 *
 * Test workflow:
 * 1. Create a new privacy policy using a test version, effective_date, title, and content.
 * 2. Fetch the created policy via GET /discussionboard/privacyPolicies/{id} with the returned id.
 * 3. Confirm that the returned record matches the initially created record in every schema property (id, version, effective_date, title, content, created_at, updated_at).
 * 4. Assert type correctness and exact value matching for all fields.
 */
export async function test_api_discussionboard_test_get_privacy_policy_by_id_when_exists(
  connection: api.IConnection,
) {
  // 1. Create a new privacy policy record
  const createInput: IDiscussionboardPrivacyPolicies.ICreate = {
    version: `v${new Date().getFullYear()}.${(`${new Date().getMonth()+1}`).padStart(2,"0")}`,
    effective_date: new Date(Date.now() + 86400_000).toISOString(), // 1 day in the future
    title: `Privacy Policy Test ${Math.random().toString(36).slice(-6)}`,
    content: `Full legal text for privacy policy testing. Random data: ${Math.random().toString(36)}`,
  };
  const created: IDiscussionboardPrivacyPolicies =
    await api.functional.discussionboard.privacyPolicies.create(connection, {
      body: createInput,
    });
  typia.assert(created);

  // 2. Fetch the record by ID via GET
  const found: IDiscussionboardPrivacyPolicies =
    await api.functional.discussionboard.privacyPolicies.at(connection, {
      id: created.id,
    });
  typia.assert(found);

  // 3. Confirm all schema properties are present and match the initial record
  TestValidator.equals("id")(found.id)(created.id);
  TestValidator.equals("version")(found.version)(created.version);
  TestValidator.equals("effective_date")(found.effective_date)(created.effective_date);
  TestValidator.equals("title")(found.title)(created.title);
  TestValidator.equals("content")(found.content)(created.content);
  TestValidator.equals("created_at")(found.created_at)(created.created_at);
  TestValidator.equals("updated_at")(found.updated_at)(created.updated_at);
}

