/**
 * Validate that the trending topic update API enforces request body schema constraints and rejects invalid payloads.
 *
 * Business context:
 * Only schema-defined fields for a trending topic can be updated. The API should strictly enforce types (e.g., trending_score must remain a number). If a payload includes invalid field types, missing required values (where applicable), or extra properties not in the schema, the endpoint must respond with a validation error, and the record should not be modified.
 *
 * Step-by-step process:
 * 1. Create a valid trending topic record for a controlled update scenario.
 * 2. Attempt to update the record with an invalid payload (e.g., trending_score:string instead of number, or with an undefined property).
 * 3. Assert that the API returns a validation error without changing the record.
 * 4. (Optional) Fetch the record to confirm no data was changed from the invalid request.
 */
export async function test_api_discussionboard_test_update_trending_topic_with_invalid_payload(
  connection: api.IConnection,
) {
  // 1. Create a valid trending topic for controlled testing
  const original: ITrendingTopic = await api.functional.discussionboard.trendingTopics.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      ranking_period_date: typia.random<string & tags.Format<"date-time">>(),
      trending_score: 10,
    } satisfies ITrendingTopic.ICreate,
  });
  typia.assert(original);

  // 2. Attempt to update with trending_score of wrong type (string)
  await TestValidator.error("should fail on type violation")(async () => {
    await api.functional.discussionboard.trendingTopics.update(connection, {
      id: original.id,
      body: {
        trending_score: "wrong_type" as unknown as number,
      } as any, // Deliberate type violation; as any only in test to force runtime error
    });
  });

  // 3. Attempt to update with extra unexpected property
  await TestValidator.error("should fail on extra properties")(async () => {
    await api.functional.discussionboard.trendingTopics.update(connection, {
      id: original.id,
      body: {
        trending_score: 777,
        extra_field: "not allowed", // property not in schema
      } as any, // as any to defeat TS, but API must validate and reject
    });
  });

  // 4. (Optional) Confirm original record still unchanged by a PATCH/list
  //    Ideally, would verify state; this step may be omitted if no suitable GET/list API provided.
}

