import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerationAction";

/**
 * Test the successful creation of a moderation action with valid data.
 *
 * This test checks the full end-to-end flow for creating a discussionboard moderation action. Specifically, it verifies:
 * - A moderation action can be created with a null report_id (proactive moderation scenario)
 * - A moderation action can be created referencing a specific report_id (reactive/report-driven scenario)
 * - All referenced foreign keys (moderator, target object, report) are valid UUIDs
 * - The resulting entity matches the submitted payload and all audit fields are present and correct
 *
 * Steps:
 * 1. Simulate a valid acting_moderator_id (as a UUID, to represent a real moderator)
 * 2. Simulate creation of a target object being moderated (generate UUID, set type to 'post')
 * 3. Simulate a report_id for reactive moderation scenario (generate UUID as if a report exists)
 *    (For proactive moderation, report_id is null)
 * 4. For proactive moderation (report_id = null):
 *     - Prepare and POST a moderation action payload with report_id = null
 *     - Assert the created entity matches all fields from the payload
 * 5. For reactive moderation (report_id = valid UUID):
 *     - Prepare and POST a moderation action payload with report_id as a valid UUID
 *     - Assert the created entity matches all fields from the payload
 * 6. Validate that returned id field is a valid UUID, rationale and type fields are non-empty, and actioned_at timestamp is recent.
 */
export async function test_api_discussionboard_moderationActions_test_create_moderation_action_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Simulate an existing moderator (acting_moderator_id)
  const acting_moderator_id: string = typia.random<string & tags.Format<"uuid">>();

  // 2. Simulate a target object being moderated (e.g., post)
  const target_object_id: string = typia.random<string & tags.Format<"uuid">>();
  const target_object_type: string = "post";

  // 3. Simulate a report (reactive scenario)
  const valid_report_id: string = typia.random<string & tags.Format<"uuid">>();

  // 4. Proactive moderation action (report_id = null)
  const proactivePayload: IDiscussionboardModerationAction.ICreate = {
    report_id: null,
    acting_moderator_id,
    target_object_id,
    target_object_type,
    action_type: "delete",
    rationale: "Content violated guidelines (proactive)",
    actioned_at: new Date().toISOString(),
  };
  const proactiveResult = await api.functional.discussionboard.moderationActions.create(connection, {
    body: proactivePayload,
  });
  typia.assert(proactiveResult);
  // Validate all returned fields match input or expected
  TestValidator.equals("proactive acting_moderator_id")(proactiveResult.acting_moderator_id)(proactivePayload.acting_moderator_id);
  TestValidator.equals("proactive target_object_id")(proactiveResult.target_object_id)(proactivePayload.target_object_id);
  TestValidator.equals("proactive target_object_type")(proactiveResult.target_object_type)(proactivePayload.target_object_type);
  TestValidator.equals("proactive action_type")(proactiveResult.action_type)(proactivePayload.action_type);
  TestValidator.equals("proactive rationale")(proactiveResult.rationale)(proactivePayload.rationale);
  TestValidator.equals("proactive actioned_at")(proactiveResult.actioned_at)(proactivePayload.actioned_at);
  TestValidator.equals("proactive report_id")(proactiveResult.report_id)(null);
  TestValidator.predicate("proactive id is non-empty uuid")(!!proactiveResult.id && typeof proactiveResult.id === "string" && proactiveResult.id.length > 0);
  TestValidator.predicate("proactive rationale non-empty")(!!proactiveResult.rationale && proactiveResult.rationale.length > 0);
  TestValidator.predicate("proactive target_object_type non-empty")(!!proactiveResult.target_object_type && proactiveResult.target_object_type.length > 0);
  // Validate actioned_at is ISO and no more than 1 minute in the future
  TestValidator.predicate("actioned_at is recent")(Date.parse(proactiveResult.actioned_at) - Date.now() < 60000);

  // 5. Reactive moderation action (report_id = valid uuid, report exists)
  const reactivePayload: IDiscussionboardModerationAction.ICreate = {
    report_id: valid_report_id,
    acting_moderator_id,
    target_object_id,
    target_object_type,
    action_type: "warn",
    rationale: "Addressing reported content (reactive)",
    actioned_at: new Date().toISOString(),
  };
  const reactiveResult = await api.functional.discussionboard.moderationActions.create(connection, {
    body: reactivePayload,
  });
  typia.assert(reactiveResult);
  // Validate all returned fields match input or expected
  TestValidator.equals("reactive acting_moderator_id")(reactiveResult.acting_moderator_id)(reactivePayload.acting_moderator_id);
  TestValidator.equals("reactive target_object_id")(reactiveResult.target_object_id)(reactivePayload.target_object_id);
  TestValidator.equals("reactive target_object_type")(reactiveResult.target_object_type)(reactivePayload.target_object_type);
  TestValidator.equals("reactive action_type")(reactiveResult.action_type)(reactivePayload.action_type);
  TestValidator.equals("reactive rationale")(reactiveResult.rationale)(reactivePayload.rationale);
  TestValidator.equals("reactive actioned_at")(reactiveResult.actioned_at)(reactivePayload.actioned_at);
  TestValidator.equals("reactive report_id")(reactiveResult.report_id)(valid_report_id);
  TestValidator.predicate("reactive id is non-empty uuid")(!!reactiveResult.id && typeof reactiveResult.id === "string" && reactiveResult.id.length > 0);
  TestValidator.predicate("reactive rationale non-empty")(!!reactiveResult.rationale && reactiveResult.rationale.length > 0);
  TestValidator.predicate("reactive target_object_type non-empty")(!!reactiveResult.target_object_type && reactiveResult.target_object_type.length > 0);
  TestValidator.predicate("reactive actioned_at is recent")(Date.parse(reactiveResult.actioned_at) - Date.now() < 60000);
}

