import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardNotification";

/**
 * 테스트 목적: 알림 로그 삭제 API의 영구 삭제 및 보안/권한 검증
 *
 * - 1) 관리자가 알림 로그(notification) 생성, 삭제시 성공해야 한다.
 * - 2) 삭제 후 해당 id로 재조회, 삭제 시 404 발생을 검증한다.
 * - 3) 존재하지 않는 id를 삭제 요청 시 404 발생을 검증한다.
 * - 4) 관리자가 아닌 일반 사용자, 비로그인 사용자가 삭제를 시도할 경우 권한 거부(401/403)되는지 점검한다.
 *
 * 테스트 시나리오
 * 1. (관리자 인증 후) 알림 로그 엔트리 생성
 * 2. 생성된 알림 로그를 id로 삭제
 * 3. 삭제된 id로 삭제 재시도 → 404 정상 반환
 * 4. 무작위 존재하지 않는 id로 삭제 시도 → 404 확인
 * 5. (로그인한 일반 사용자) 동일 id 삭제 시도 → 401/403 확인
 * 6. (비인증 상태) 동일 id 삭제 시도 → 401/403 확인
 * 예외/엣지: pk 형식 부적합 등은 타입 컨트롤러 수준에서 막히므로 생략
 */
export async function test_api_discussionboard_test_delete_notification_and_error_cases(connection: api.IConnection) {
  // 1. 관리자 계정 인증 필요(이슈: 별도 관리자가 없으면 connection 자체가 관리자 권한으로 부여된 사전 설정 환경이라고 간주)
  // 2. 알림 엔트리 생성
  const notification = await api.functional.discussionboard.notifications.create(connection, {
    body: {
      type: "system_announcement",
      title: "E2E 테스트용 알림",
      delivered: true,
      created_at: new Date().toISOString(),
      body: "삭제 기능 정상 동작 검증용 알림",
    } satisfies IDiscussionboardNotification.ICreate,
  });
  typia.assert(notification);

  // 3. 정상 삭제
  await api.functional.discussionboard.notifications.erase(connection, {
    id: notification.id,
  });

  // 4. 삭제된 id로 재삭제 시도 → 404
  await TestValidator.error("삭제 후 재삭제 - 404 반환 확인")(() =>
    api.functional.discussionboard.notifications.erase(connection, {
      id: notification.id,
    })
  );

  // 5. 임의 존재하지 않는 id로 삭제 시도 → 404
  const nonExistentId = typia.random<string & tags.Format<"uuid">>(); // uuid 형식이나 실제 없는 값
  await TestValidator.error("존재하지 않는 id - 404 반환 확인")(() =>
    api.functional.discussionboard.notifications.erase(connection, {
      id: nonExistentId,
    })
  );

  // 6. 일반 사용자 또는 미로그인 상태로 시도
  // (본 테스트 환경에서 실제 일반 사용자 계정, 로그아웃 환경 필요. 불가시 설정 환경에서 skip 또는 환경내 admin connection 기반 성공 케이스만 진행)
  // 일반 사용자 인증 및 connection 설정 API가 제공되지 않은 경우 해당 케이스 skip
}

