import type { IDeleteConfirmation } from "@ORGANIZATION/PROJECT-api/lib/structures/IDeleteConfirmation";

/**
 * Validate the deletion and idempotency of board-moderator assignment deletion endpoint.
 *
 * Business context:
 * This test ensures that deleting a board-moderator assignment functions correctly, removing the relationship and returning a proper confirmation. Furthermore, it verifies that repeating the delete operation on the same assignment correctly returns a not found error, confirming idempotency and robust error handling for already-deleted assignments. The test also indirectly confirms the resource is no longer present.
 *
 * Step-by-step process:
 * 1. Create a board (dependency for assignment)
 * 2. Create a moderator (dependency for assignment)
 * 3. Assign the moderator to the board (creates the record to delete)
 * 4. Call the delete endpoint to remove the assignment (should succeed, verify confirmation)
 * 5. Attempt to delete the same assignment again (should fail with an error)
 * 6. Optionally further validate the assignment can no longer be deleted or found
 */
export async function test_api_discussionboard_test_delete_board_moderator_assignment_and_idempotency(
  connection: api.IConnection,
) {
  // 1. Create a board
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const sectionId = typia.random<string & tags.Format<"uuid">>();
  const board = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: categoryId,
      discussionboard_section_id: sectionId,
      name: RandomGenerator.paragraph()(3),
      code: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(),
      is_active: true,
      is_visible: true,
    },
  });
  typia.assert(board);

  // 2. Create a moderator assignment (grants moderator role to a user for the board)
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString();
  const moderator = await api.functional.discussionboard.moderators.create(connection, {
    body: {
      member_id: memberId,
      assigned_by_admin_id: adminId,
      assigned_at: now,
      expires_at: null,
    },
  });
  typia.assert(moderator);

  // 3. Assign the moderator to the board
  const assignment = await api.functional.discussionboard.boardModerators.create(connection, {
    body: {
      discussionboard_board_id: board.id,
      discussionboard_moderator_id: moderator.id,
      is_primary: true,
      joined_at: now,
    },
  });
  typia.assert(assignment);

  // 4. Delete the moderator assignment (should succeed)
  const del = await api.functional.discussionboard.boardModerators.erase(connection, {
    id: assignment.id,
  });
  typia.assert(del);
  TestValidator.predicate("first delete status")(del.status === undefined || del.status === "deleted");
  TestValidator.equals("deleted assignment id")(del.deleted_id)(assignment.id);

  // 5. Attempt to delete again, should error
  await TestValidator.error("repeat delete not found error")(() =>
    api.functional.discussionboard.boardModerators.erase(connection, {
      id: assignment.id,
    }),
  );
}

