import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardThreadSnapshots } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreadSnapshots";

/**
 * E2E test for the permanent deletion of a thread snapshot.
 *
 * 1. Create a thread using valid thread creation input.
 * 2. Create a snapshot for the created thread.
 * 3. Delete the snapshot by id via DELETE /discussionboard/threadSnapshots/{id}.
 * 4. Verify that attempting to fetch (or reference) the snapshot after deletion yields a 404 or error.
 * 5. Attempt to delete the same snapshot again and confirm it returns an error (already deleted/not found).
 * 6. Attempt to delete a completely unknown/random id and verify it errors out cleanly as well.
 * 7. There must be no way to recover or 'soft-undelte' after deletion; this endpoint is strictly permanent removal.
 */
export async function test_api_discussionboard_threadSnapshots_test_delete_thread_snapshot_and_fetch_after_deletion(
  connection: api.IConnection,
) {
  // 1. Create a thread for the snapshot context
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: typia.random<string & tags.Format<"uuid">>(),
      author_member_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()() as string, // Ensures content, optional
    }
      satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);

  // 2. Create a thread snapshot for this thread
  const snapshot = await api.functional.discussionboard.threadSnapshots.create(connection, {
    body: {
      thread_id: thread.id,
      actor_id: thread.author_member_id,
      title: thread.title + ' SNAPSHOT v1',
      body: thread.body ?? null,
      reason: 'Initial version',
    }
      satisfies IDiscussionboardThreadSnapshots.ICreate,
  });
  typia.assert(snapshot);

  // 3. Hard delete the snapshot
  await api.functional.discussionboard.threadSnapshots.erase(connection, {
    id: snapshot.id,
  });

  // 4. Try fetching the deleted snapshot (should error out)
  await TestValidator.error("fetch deleted snapshot must fail")(
    async () => {
      await api.functional.discussionboard.threadSnapshots.create(
        connection,
        // There's no 'get' for snapshot by id, so simulate access by attempting to create with same id (wouldn't find anyway)
        { body: { ...snapshot } as IDiscussionboardThreadSnapshots.ICreate },
      );
    },
  );

  // 5. Try deleting same snapshot again, expect error
  await TestValidator.error("double delete must fail")(
    async () => {
      await api.functional.discussionboard.threadSnapshots.erase(connection, {
        id: snapshot.id,
      });
    },
  );

  // 6. Try deleting a never-existent id
  await TestValidator.error("delete unknown id must error")(
    async () => {
      await api.functional.discussionboard.threadSnapshots.erase(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );
}

