        body: {
          // omit 'reason' and 'warned_at', which are required
          warned_member_id: validWarning.warned_member_id,
          acting_moderator_id: validWarning.acting_moderator_id,
        } as any,
      });
    }
  );

  // 5. Confirm the original warning in DB remains unchanged by fetching it via another update (valid update, see no errors)
  const readAfterFailures = await api.functional.discussionboard.warnings.update(connection, {
    id: validWarning.id,
    body: {
