 *
 * This test scenario checks if updating title and body of a post snapshot (through PUT /discussionboard/postSnapshots/{id}) works as intended, with strict adherence to allowed schema fields. It first creates a post, then creates a post snapshot linked to that post, then performs the update on the snapshot with new values for title and/or body. Finally, it validates that the response matches all expectations and schema constraints.
 *
 * Steps:
 * 1. Create a new post (for association with the snapshot).
 * 2. Create a post snapshot for this post (with initial title and body).
 * 3. Update the snapshot using valid changes for title and body via PUT endpoint.
 * 4. Check that the response reflects the new values and satisfies all schema properties.
 */
export async function test_api_discussionboard_test_update_post_snapshot_with_valid_changes(connection: api.IConnection) {
  // 1. Create a post
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Original Post Title",
      body: "Initial post body.",
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 2. Create a post snapshot associated with the post
  const initialSnapshot = await api.functional.discussionboard.postSnapshots.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      editor_member_id: typia.random<string & tags.Format<"uuid">>(),
      title: post.title,
      body: post.body,
      taken_at: new Date().toISOString(),
    } satisfies Idiscussionboard_post_snapshots.ICreate,
  });
  typia.assert(initialSnapshot);

  // 3. Prepare update data for snapshot (update title and body)
  const updateData: Idiscussionboard_post_snapshots.IUpdate = {
    title: "Updated Snapshot Title",
    body: "Updated snapshot body content.",
  };

  // 4. Update the post snapshot
  const updatedSnapshot = await api.functional.discussionboard.postSnapshots.update(connection, {
    id: initialSnapshot.id,
    body: updateData,
  });
