  TestValidator.equals("id is unchanged")(updatedSnapshot.id)(initialSnapshot.id);
  TestValidator.equals("discussionboard_post_id unchanged")(updatedSnapshot.discussionboard_post_id)(initialSnapshot.discussionboard_post_id);
  if (initialSnapshot.editor_member_id !== undefined) {
    TestValidator.equals("editor_member_id unchanged")(updatedSnapshot.editor_member_id)(initialSnapshot.editor_member_id);
  }
  TestValidator.equals("title updated")(updatedSnapshot.title)(updateData.title);
  TestValidator.equals("body updated")(updatedSnapshot.body)(updateData.body);
  // taken_at field: should be unchanged unless specified; here, we expect it remains as before
  TestValidator.equals("taken_at unchanged")(updatedSnapshot.taken_at)(initialSnapshot.taken_at);
}

