import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IPostReference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostReference";

/**
 * Test updating an existing post reference, including both successful field updates and typical error conditions.
 *
 * This test ensures:
 * 1. A post reference can have its reference_type and target_post_id updated, with correct database and business rules enforced.
 * 2. Updating a post reference with a non-existent id returns a not-found error.
 * 3. Attempting to set target_post_id or target_thread_id to non-existent values results in constraint (foreign key) violation errors.
 *
 * Workflow:
 * 1. Create two valid posts that will serve as the source and possible targets.
 * 2. Create a post reference from postA (source) to postB (target), type 'post'.
 * 3. Update that post reference to change its reference_type and target_post_id. Validate the results by checking new values in the response.
 * 4. Attempt to update a post reference with a completely random (unused) id, expecting a not-found error.
 * 5. Attempt to update the valid post reference to a target_post_id and target_thread_id using fake (non-existent) UUIDs, expecting constraint violation/failure errors.
 */
export async function test_api_discussionboard_test_update_post_reference_fields_and_error_cases(
  connection: api.IConnection,
) {
  // Step 1: Create two posts (postA and postB)
  const postA = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Source post A",
      body: "Test content for postA",
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(postA);
  const postB = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Target post B",
      body: "Test content for postB",
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(postB);

  // Step 2: Create a post reference from postA (source) to postB (target)
  const postRef = await api.functional.discussionboard.postReferences.create(connection, {
    body: {
      source_post_id: postA.id,
      target_post_id: postB.id,
      reference_type: "post",
    } satisfies IPostReference.ICreate,
  });
  typia.assert(postRef);

  // Step 3: Update the post reference to change the reference_type and target_post_id
  const updateNewType = "comment";
  const newTargetId = typia.random<string & tags.Format<"uuid">>();
  const updatedRef = await api.functional.discussionboard.postReferences.update(connection, {
    id: postRef.id,
    body: {
      reference_type: updateNewType,
      target_post_id: newTargetId,
    } satisfies IPostReference.IUpdate,
  });
  typia.assert(updatedRef);
  TestValidator.equals("updated reference_type")(updatedRef.reference_type)(updateNewType);
  TestValidator.equals("updated target_post_id")(updatedRef.target_post_id)(newTargetId);

  // Step 4: Attempt to update with a non-existent id (should error)
  await TestValidator.error("Not found on non-existent id")(() =>
    api.functional.discussionboard.postReferences.update(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { reference_type: "thread" } satisfies IPostReference.IUpdate,
    })
  );

  // Step 5: Attempt to update to invalid references (constraint error)
  const invalidThreadId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Constraint error on invalid post/thread id")(() =>
    api.functional.discussionboard.postReferences.update(connection, {
      id: postRef.id,
      body: {
        target_post_id: typia.random<string & tags.Format<"uuid">>(),
        target_thread_id: invalidThreadId,
        reference_type: "thread",
      } satisfies IPostReference.IUpdate,
    })
  );
}

