  for (const item of activeList.data) {
    TestValidator.predicate("id format")(/^[0-9a-f\-]{36}$/.test(item.id));
    TestValidator.equals("active field is boolean")(typeof item.active)("boolean");
  }

  // 2. List inactive report types
  const inactiveList = await api.functional.discussionboard.reportTypes.index(connection, {
    body: {
      active: false,
    },
  });
  typia.assert(inactiveList);
  for (const item of inactiveList.data) {
    TestValidator.equals("All results should be inactive")(item.active)(false);
  }

  // 3. Search by display_name with rare string
  const rareString = "unlikelystring-" + Math.random().toString(36).slice(2);
  const emptyResult = await api.functional.discussionboard.reportTypes.index(connection, {
    body: {
      display_name: rareString,
    },
  });
  typia.assert(emptyResult);
  TestValidator.equals("data array is empty")(emptyResult.data.length)(0);
  // Pagination for empty result
  TestValidator.equals("zero records for rare string")(emptyResult.pagination.records)(0);
}

