import type { IDiscussionboardThreadTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreadTag";

/**
 * Test updating (PUT) on a thread tag assignment (/discussionboard/threadTags/{id}).
 *
 * Validates the ability to mark a thread tag as removed (set removed_at timestamp), audit correction on permitted fields, and checks error handling for non-existent IDs.
 * - Step 1: Create a thread (dependency)
 * - Step 2: Assign a tag to this thread (dependency)
 * - Step 3: Mark the created assignment as removed by PATCHing removed_at with a current timestamp. Confirm returned removed_at and all schema properties remain correct.
 * - Step 4: (If permitted) Attempt to update other fields (assigned_at) - since the update DTO only allows removed_at, this tests only allowed updatable properties are affected.
 * - Step 5: Negative test: Attempt to update a non-existent assignment (random UUID, expect error thrown).
 */
export async function test_api_discussionboard_threadTags_test_update_thread_tag_assignment_set_removed_at_and_edit_assignment_fields(
  connection: api.IConnection,
) {
  // Step 1: Create a thread
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: typia.random<string & tags.Format<"uuid">>(),
      author_member_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Thread for tag assignment update",
      body: "Testing update on thread tag assignment.",
    },
  });
  typia.assert(thread);

  // Step 2: Create a tag assignment for this thread
  const tagAssignment = await api.functional.discussionboard.threadTags.create(connection, {
    body: {
      thread_id: thread.id,
      assigned_at: new Date().toISOString(),
    },
  });
