  // Step 3: Mark the tag assignment as removed
  const removedAt = new Date().toISOString();
  const updatedTag = await api.functional.discussionboard.threadTags.update(connection, {
    id: tagAssignment.id,
    body: { removed_at: removedAt },
  });
  typia.assert(updatedTag);
  TestValidator.equals("removed_at update")(updatedTag.removed_at)(removedAt);
  TestValidator.equals("id unchanged")(updatedTag.id)(tagAssignment.id);

  // Step 4: Attempt to update assigned_at (should not change as it's not updatable)
