import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardDataErasureRequests } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardDataErasureRequests";
import type { IPageIDiscussionboardDataErasureRequests } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardDataErasureRequests";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionboardDataErasureRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardDataErasureRequest";

/**
 * 테스트 목적: 데이터 삭제 요청 목록의 필터/페이지네이션/전체 반환을 검증하는 e2e 시나리오입니다. 
 *
 * 1. 테스트를 위한 멤버를 생성
 * 2. 해당 멤버로 데이터 삭제 요청을 2건 이상 생성
 * 3. (필터 검증) status별(pending, approved)로 쿼리: 각 필터별로 반환되는 데이터의 status가 항상 일치하는지 검증
 * 4. (멤버 아이디 별) discussionboard_member_id로만 검색 시 해당 멤버의 삭제 요청만 반환되는지 검증
 * 5. (페이지네이션) limit=1 page=1,2로 쿼리: 첫 번째/두 번째 요청이 각각 반환되는지 검증, 페이지네이션 count 정보가 정상인지 확인
 * 6. 전체 조회(필터/페이지네이션 없이)도 수행, 2건 모두 반환되는지 검증
 * 7. 반환되는 요청 객체들이 schema 정의 필드만 포함하고, 의도하지 않은 필드가 추가로 없는지 typia.assert로 검증
 *
 * 예외 케이스) 존재하지 않는 status로 필터시 빈 목록 반환, 존재하지 않는 멤버 ID로 필터시 빈 목록 반환
 */
export async function test_api_discussionboard_test_list_data_erasure_requests_with_filter_and_pagination(connection: api.IConnection) {
  // 1. 테스트 멤버 생성
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: memberEmail,
      hashed_password: RandomGenerator.alphaNumeric(30),
      role: "member",
      is_active: true,
    }
  });
  typia.assert(member);

  // 2. 멤버로 데이터 삭제 요청 2건 생성
  const request1 = await api.functional.discussionboard.dataErasureRequests.create(connection, {
    body: { discussionboard_member_id: member.id }
  });
  typia.assert(request1);
  // 바로 두번째 요청 생성 (비즈니스 로직상 pending 이라면 중복 제출이 안될 수 있는데, 테스트 목적상 여러 케이스 실험)
  let request2;
  try {
    request2 = await api.functional.discussionboard.dataErasureRequests.create(connection, {
      body: { discussionboard_member_id: member.id }
    });
    typia.assert(request2);
  } catch (err) {
    // 하나만 생성되는 정책이면 무시하고 이후 테스트 진행
    request2 = null;
  }

  // 3. status별 필터 쿼리 (pending만 있을 수 있음)
  const byStatusPending = await api.functional.discussionboard.dataErasureRequests.index(connection, {
    body: { status: "pending" }
  });
  typia.assert(byStatusPending);
  TestValidator.predicate("status 가 모두 pending인지 확인")(byStatusPending.data.every(r => r.status === "pending"));

  // 4. discussionboard_member_id 별 쿼리
  const byMember = await api.functional.discussionboard.dataErasureRequests.index(connection, {
    body: { discussionboard_member_id: member.id }
  });
  typia.assert(byMember);
  TestValidator.predicate("모든 결과의 멤버ID가 동일한지")(
    byMember.data.every(r => r.discussionboard_member_id === member.id)
  );

  // 5. 페이지네이션 limit=1, page=1,2
  const page1 = await api.functional.discussionboard.dataErasureRequests.index(connection, {
    body: { discussionboard_member_id: member.id, limit: 1, page: 1 }
  });
  typia.assert(page1);
  TestValidator.equals("페이지네이션-현재페이지")(page1.pagination.current)(1);
  TestValidator.equals("페이지네이션-limit")(page1.pagination.limit)(1);
