      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(adminMember);

  // 2. 감사 로그 생성 (actor: admin)
  const auditLog: IDiscussionboardAuditLog = await api.functional.discussionboard.auditLogs.create(connection, {
    body: {
