import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardCategory";

/**
 * Test the business rule enforcing unique code constraint on board category creation.
 *
 * Board categories are administrative groupings in the discussion board system. The `code` field
 * serves as a unique programmatic identifier used in URLs, navigation, and configuration. To ensure
 * no ambiguity or accidental overlap in board routing and UI, codes must be unique across all categories.
 *
 * This test validates that an attempt to create a category with a duplicate code results in a business validation error:
 *
 * 1. Create a board category with a randomly generated unique code, name, and position.
 * 2. Attempt to create a second board category with a different name and position, but the exact same code.
 * 3. Expect the API to throw a validation, duplication, or conflict error due to the non-unique code.
 * 4. Verify that the first category is successfully created and the second creation attempt fails as expected.
 */
export async function test_api_discussionboard_test_create_board_category_with_duplicate_code(
  connection: api.IConnection,
) {
  // 1. Create a new board category with a unique code
  const uniqueCode: string = RandomGenerator.alphaNumeric(8);
  const initialCategory = await api.functional.discussionboard.boardCategories.create(
    connection,
    {
      body: {
        name: RandomGenerator.paragraph()(),
        code: uniqueCode,
        description: RandomGenerator.content()()(),
        position: typia.random<number & tags.Type<"int32">>(),
      } satisfies IDiscussionboardBoardCategory.ICreate,
    },
  );
  typia.assert(initialCategory);
  TestValidator.equals("Category code should match input:")(initialCategory.code)(uniqueCode);

  // 2. Try to create another category with the duplicate code
  //    (Different name/position, identical code)
