 * - Deleting an assignment must permanently and fully remove the assignment record (no soft delete).
 * - Deletion has no cascade effect on the related member; only the admin status assignment is removed.
 *
 * Test steps:
 * 1. Create a base member (future admin). Save their id.
 * 2. Create a second member to act as the assigning admin. Save their id.
 * 3. Assign admin privileges to the base member by creating an admin assignment, specifying both their id and the assigning admin id.
 * 4. Delete the just created admin assignment by id using the dedicated delete API.
 * 5. Attempt to delete the same assignment again and confirm a 404 error is returned (it is already gone).
 *
 * Validation:
 * - After the first deletion, the assignment should be completely gone.
 * - The API should not return or find the resource after deletion.
 * - The delete call itself should return success without errors the first time.
 * - A second delete should fail (404) as the resource no longer exists.
 */
export async function test_api_discussionboard_test_delete_admin_assignment_by_id_success(
  connection: api.IConnection,
) {
  // 1. Create a base member who will be assigned as admin
  const memberUsername = RandomGenerator.alphabets(8);
  const baseMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: memberUsername,
      email: `${memberUsername}@example.com`,
      hashed_password: RandomGenerator.alphabets(10),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(baseMember);

  // 2. Create an assigning admin member
  const adminUsername = RandomGenerator.alphabets(8);
  const assigningAdmin = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: adminUsername,
      email: `${adminUsername}@example.com`,
      hashed_password: RandomGenerator.alphabets(10),
      role: "admin",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(assigningAdmin);

  // 3. Assign admin privileges to the base member
  const assignedAt = new Date().toISOString();
  const adminAssignment = await api.functional.discussionboard.admins.create(connection, {
    body: {
      member_id: baseMember.id,
      assigned_by_admin_id: assigningAdmin.id,
      assigned_at: assignedAt,
    } satisfies IAdminAssignment.ICreate,
  });
  typia.assert(adminAssignment);

  // 4. Delete the admin assignment (permanent)
  await api.functional.discussionboard.admins.erase(connection, {
    id: adminAssignment.id,
  });

  // 5. Attempt to delete again (should fail with 404)
  await TestValidator.error("delete already removed admin assignment should fail")(
    async () => {
      await api.functional.discussionboard.admins.erase(connection, { id: adminAssignment.id });
    },
  );
}

