import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardActivityLog";
import type { IActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IActivityLog";

/**
 * Test full update of an activity log record by id for success and various failure cases.
 *
 * Business context: Activity logs are central to audit trails, compliance, user/session analytics, and traceability on the discussion board. This test ensures administrators (or any privileged API consumer) can successfully update an activity log's event type, timestamp, references (thread, board, post, comment, member), and metadata, but only by passing fields that the schema supports—nothing extra or invalid. Additionally, verifies the API rejects improper input and returns errors for not found.
 *
 * Process:
 * 1. Create an activity log (dependency)
 * 2. Update the record by id using valid new values for each field
 * 3. Validate the response reflects the new input values
 * 4. Negative test: Try updating a non-existent id, expect error
 * 5. Negative test: Attempt update with missing required fields (event_type, event_timestamp); expect error
 * 6. Negative test: Attempt update with an extra (non-schema) property; expect error or property ignored.
 */
export async function test_api_discussionboard_activityLogs_test_update_activity_log_fields_by_id_success_and_failure(
  connection: api.IConnection,
) {
  // 1. Create an original log record to update
  const origLog = await api.functional.discussionboard.activityLogs.create(connection, {
    body: {
      event_type: "login",
      event_timestamp: new Date().toISOString(),
      event_metadata: JSON.stringify({ device: "browser", ip: "192.168.1.2" }),
      // Optionally, add some UUID references
      discussionboard_member_id: typia.random<string & tags.Format<'uuid'>>(),
      discussionboard_board_id: typia.random<string & tags.Format<'uuid'>>(),
      discussionboard_thread_id: typia.random<string & tags.Format<'uuid'>>(),
      discussionboard_post_id: typia.random<string & tags.Format<'uuid'>>(),
      discussionboard_comment_id: typia.random<string & tags.Format<'uuid'>>(),
    }
  });
  typia.assert(origLog);

  // 2. Update all relevant fields
  const updateInput: IActivityLog.IUpdate = {
    event_type: "post_create",
    event_timestamp: new Date(Date.now() + 10 * 60000).toISOString(),
    event_metadata: JSON.stringify({ ref: "updated", custom: 123 }),
    discussionboard_member_id: typia.random<string & tags.Format<'uuid'>>(),
    discussionboard_board_id: typia.random<string & tags.Format<'uuid'>>(),
    discussionboard_thread_id: typia.random<string & tags.Format<'uuid'>>(),
    discussionboard_post_id: typia.random<string & tags.Format<'uuid'>>(),
    discussionboard_comment_id: typia.random<string & tags.Format<'uuid'>>(),
  };
  const updated = await api.functional.discussionboard.activityLogs.update(connection, {
    id: origLog.id,
    body: updateInput,
  });
  typia.assert(updated);
  // 3. Confirm key field values updated as intended
  TestValidator.equals("event_type updated")(updated.event_type)(updateInput.event_type);
  TestValidator.equals("event_timestamp updated")(updated.event_timestamp)(updateInput.event_timestamp);
  TestValidator.equals("member id updated")(updated.discussionboard_member_id)(updateInput.discussionboard_member_id);
  TestValidator.equals("board id updated")(updated.discussionboard_board_id)(updateInput.discussionboard_board_id);
  TestValidator.equals("thread id updated")(updated.discussionboard_thread_id)(updateInput.discussionboard_thread_id);
  TestValidator.equals("post id updated")(updated.discussionboard_post_id)(updateInput.discussionboard_post_id);
  TestValidator.equals("comment id updated")(updated.discussionboard_comment_id)(updateInput.discussionboard_comment_id);
  TestValidator.equals("event_metadata updated")(updated.event_metadata)(updateInput.event_metadata);

  // 4. Negative: Update with non-existent id (should error)
  await TestValidator.error("update with invalid id should fail")(() =>
    api.functional.discussionboard.activityLogs.update(connection, {
      id: typia.random<string & tags.Format<'uuid'>>(), // random uuid, presumed not found
      body: updateInput,
    })
  );

  // 5. Negative: Try update missing required fields
  await TestValidator.error("missing event_type should fail")(() =>
    api.functional.discussionboard.activityLogs.update(connection, {
      id: origLog.id,
      body: {
        ...updateInput,
        event_type: undefined as any, // this would cause compile error, skip in practice
      } as any // skipped: can't reproduce TS compiler error at runtime, negative runtime test can't omit required TS fields
    })
  );
  await TestValidator.error("missing event_timestamp should fail")(() =>
    api.functional.discussionboard.activityLogs.update(connection, {
      id: origLog.id,
      body: {
        ...updateInput,
        event_timestamp: undefined as any,
      } as any // same as above
    })
  );

  // 6. Negative: Try update with extraneous (non-schema) property, expect error or ignore
  await TestValidator.error("extra property should be rejected")(() =>
    api.functional.discussionboard.activityLogs.update(connection, {
      id: origLog.id,
      body: {
        ...updateInput,
        not_a_schema_field: 12345, // Non-schema
      } as any, // should error or be ignored
    })
  );
}

