import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IDiscussionboardCommentVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentVote";

/**
 * Validate creation and uniqueness enforcement for comment vote records.
 *
 * This test covers successful creation of a comment vote with valid payload (existing comment, member, and a valid vote_type),
 * triggers a unique constraint error by submitting a duplicate vote for the same comment/member pair, and explores edge cases such as
 * passing invalid vote_type values or referencing a nonexistent comment/member ID. Finally, it verifies that after a vote is deleted
 * for the same pair, a new (re-)vote is possible.
 *
 * Steps:
 * 1. Create a discussionboard member with unique username/email.
 * 2. Create a (dummy) post ID, create a comment authored by this member on that post.
 * 3. Create a valid comment vote (vote_type: "up") for the member+comment pair (should succeed).
 * 4. Attempt to create another vote for the same member+comment pair (should fail with unique constraint error).
 * 5. Try to create a vote with an invalid vote_type value (e.g., "INVALID_TYPE"). Validate error.
 * 6. Try to create a vote with non-existent comment ID (random uuid). Validate error.
 * 7. Try to create a vote with non-existent member ID (random uuid). Validate error.
 *
 * (The scenario states deletion and then re-creation of vote, but no DELETE API is present for commentVotes, so that part will be omitted.)
 */
export async function test_api_discussionboard_test_create_comment_vote_success_duplicate_vote_type_violation(
  connection: api.IConnection,
) {
  // 1. Create a new member
  const memberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    role: "member",
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create a dummy post id, then a comment
  const postId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const commentInput: IComment.ICreate = {
    discussionboard_post_id: postId,
    discussionboard_member_id: member.id,
    body: "Test comment body",
  };
  const comment = await api.functional.discussionboard.comments.create(connection, { body: commentInput });
  typia.assert(comment);

  // 3. Record a valid vote ("up")
  const voteInput: IDiscussionboardCommentVote.ICreate = {
    discussionboard_comment_id: comment.id,
    discussionboard_member_id: member.id,
    vote_type: "up",
  };
  const vote = await api.functional.discussionboard.commentVotes.create(connection, { body: voteInput });
  typia.assert(vote);

  // 4. Attempt duplicate vote (same member+comment)
  await TestValidator.error("Should reject duplicate vote for same (comment, member)")(
    () => api.functional.discussionboard.commentVotes.create(connection, { body: voteInput }),
  );

  // 5. Attempt vote with invalid vote_type
  const badTypeVoteInput = { ...voteInput, vote_type: "INVALID_TYPE" };
  await TestValidator.error("Should reject invalid vote_type")(
    () => api.functional.discussionboard.commentVotes.create(connection, { body: badTypeVoteInput }),
  );

  // 6. Attempt vote with non-existent comment id
  const badCommentIdVoteInput = { ...voteInput, discussionboard_comment_id: typia.random<string & tags.Format<"uuid">>() };
  await TestValidator.error("Should reject non-existent comment id")(
    () => api.functional.discussionboard.commentVotes.create(connection, { body: badCommentIdVoteInput }),
  );

  // 7. Attempt vote with non-existent member id
  const badMemberIdVoteInput = { ...voteInput, discussionboard_member_id: typia.random<string & tags.Format<"uuid">>() };
  await TestValidator.error("Should reject non-existent member id")(
    () => api.functional.discussionboard.commentVotes.create(connection, { body: badMemberIdVoteInput }),
  );
}

