import type { IModeratorAssignment } from "@ORGANIZATION/PROJECT-api/lib/structures/IModeratorAssignment";

/**
 * 테스트: 특정 id로 모더레이터 할당 상세 조회 (성공 & 실패 케이스)
 *
 * - 성공 시나리오: 
 *   1. 멤버 계정 하나 생성
 *   2. 관리자 계정 하나 생성
 *   3. (관리자가) 위 멤버를 모더레이터로 할당 (할당 시각 직접 지정)
 *   4. 생성된 모더레이터 할당의 id로 상세조회
 *   5. 조회 결과의 모든 필드(member_id, assigned_by_admin_id 및 할당/만료/revoke 타임스탬프 등) 값이 예상과 일치하는지 검증
 *
 * - 실패(비정상) 시나리오:
 *   6. 존재하지 않는 id로 조회 시도 → 404 not found 예외 발생 검증
 */
export async function test_api_discussionboard_moderators_test_get_moderator_assignment_detail_success_and_not_found(connection: api.IConnection) {
  // 1. 멤버 계정 생성
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate
  });
  typia.assert(member);

  // 2. 관리자 계정 생성
  const admin = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "admin",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate
  });
  typia.assert(admin);

  // 3. (관리자가) 멤버를 모더레이터로 할당 (임의 만료 일자는 설정하지 않음)
  const assignedAt = new Date().toISOString();
  const assignment = await api.functional.discussionboard.moderators.create(connection, {
    body: {
      member_id: member.id,
      assigned_by_admin_id: admin.id,
      assigned_at: assignedAt,
      expires_at: null,
    } satisfies IModeratorAssignment.ICreate
  });
  typia.assert(assignment);
  TestValidator.equals("할당 member_id 동일 여부")(assignment.member_id)(member.id);
  TestValidator.equals("할당 admin_id 동일 여부")(assignment.assigned_by_admin_id)(admin.id);
  TestValidator.equals("할당 시점 동일 여부")(assignment.assigned_at)(assignedAt);
  TestValidator.equals("만료일 없음")(assignment.expires_at)(null);
  TestValidator.equals("revoke 시점 없음")(assignment.revoked_at)(null);

  // 4. 상기 id로 상세 조회 및 모든 필드값 검증
  const detail = await api.functional.discussionboard.moderators.at(connection, { id: assignment.id });
  typia.assert(detail);
  TestValidator.equals("조회 id")(detail.id)(assignment.id);
  TestValidator.equals("조회 member_id")(detail.member_id)(assignment.member_id);
  TestValidator.equals("조회 assigned_by_admin_id")(detail.assigned_by_admin_id)(assignment.assigned_by_admin_id);
  TestValidator.equals("조회 assigned_at")(detail.assigned_at)(assignment.assigned_at);
  TestValidator.equals("조회 expires_at")(detail.expires_at)(assignment.expires_at);
