 *
 * 1. 서로 다른 post_id를 가진 discussionboard_posts 여러 개를 생성한다
 * 2. 각 post에 대해 post snapshot을 생성한다 (discussionboard_post_snapshots에 insert)
 * 3. 필터 없이 (body: {}) postSnapshots.index(PATCH)를 호출한다
 * 4. 반환된 data 목록에 모든 post들의 snapshot이 포함되어 있는지 확인한다
 * 5. 페이지네이션 관련 pagination 필드가 반환되고 의미가 일치하는지도 검증한다
 */
export async function test_api_discussionboard_test_list_post_snapshots_with_missing_criteria_returns_all(connection: api.IConnection) {
  // 1. 여러 개의 post 생성
  const NUM_POSTS = 3;
  const postList = [];
  for (let i = 0; i < NUM_POSTS; ++i) {
    const post = await api.functional.discussionboard.posts.create(connection, {
      body: {
        discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
        title: `Post Title ${i}`,
        body: `Content for post #${i}`,
      },
    });
    typia.assert(post);
    postList.push(post);
  }

  // 2. 각 post마다 post snapshot 1개씩 생성 (총 NUM_POSTS개)
  const snapshots = await ArrayUtil.asyncMap(postList)(async (post) => {
    const snapshot = await api.functional.discussionboard.postSnapshots.create(connection, {
      body: {
        discussionboard_post_id: post.id,
        // 실제 편집자(작성자) ID 기록
        editor_member_id: post.discussionboard_member_id,
        title: post.title + ' (snapshot)',
        body: post.body + ' [snapshot]',
        taken_at: new Date().toISOString(),
      },
    });
    typia.assert(snapshot);
    return snapshot;
  });

  // 3. body: {}로 post snapshot 목록조회
  const result = await api.functional.discussionboard.postSnapshots.index(connection, {
    body: {}, // 필터 없음 → 전체
  });
