  // 4. 모든 방금 생성된 snapshot들이 목록에 포함됐는지 title/body 기준 등으로 검증
  for (const snap of snapshots) {
    const found = result.data.find((row) => row.id === snap.id);
    TestValidator.predicate("snapshot in all-list")(!!found);
    TestValidator.equals("title")(found?.title)(snap.title);
    TestValidator.equals("discussionboard_post_id")(found?.discussionboard_post_id)(snap.discussionboard_post_id);
  }

  // 5. pagination 내용 검증
  TestValidator.predicate("pagination 필드 존재")(!!result.pagination && typeof result.pagination.current === "number");
  TestValidator.predicate("data 배열 존재")(Array.isArray(result.data));
}

