  TestValidator.equals("updated title")(updatedThread.title)(newTitle);
  TestValidator.equals("updated body")(updatedThread.body)(newBody);

  // Step 6. Validate updated_at changed
  TestValidator.predicate("updated_at should be changed")(
    updatedThread.updated_at > originalUpdatedAt,
  );
}

