/**
 * Validate ban creation error handling and duplicate prevention on the discussion board.
 *
 * This test ensures that moderation ban creation enforces foreign key integrity,
 * and that overlapping duplicate bans for the same member are properly rejected by business logic.
 *
 * 1. Create two members: one as the banned member, one as the moderator
 * 2. Attempt to create a ban supplying a non-existent banned_member_id and expect a foreign key error
 * 3. Attempt to create a ban with a non-existent acting_moderator_id and expect a foreign key error
 * 4. Attempt to create a ban referencing a non-existent report_id and expect a foreign key error
 * 5. Successfully create a valid ban for a member (test setup for duplicate logic)
 * 6. Attempt to create another ban for the same banned_member_id within an overlapping period and expect a business rule rejection (if enforced)
 */
export async function test_api_discussionboard_test_create_ban_with_invalid_references_or_duplicate(
  connection: api.IConnection,
) {
  // 1. Create members
  const bannedMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(bannedMember);

  const moderator = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "moderator",
      is_active: true,
    },
  });
  typia.assert(moderator);

  // 2. FK error: Nonexistent banned_member_id
  await TestValidator.error("ban creation with invalid banned_member_id")(() =>
    api.functional.discussionboard.bans.create(connection, {
      body: {
        banned_member_id: typia.random<string & tags.Format<"uuid">>(),
        acting_moderator_id: moderator.id,
        reason: "Testing invalid banned member",
        ban_type: "temporary",
        banned_at: new Date().toISOString(),
        expires_at: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),
      },
    })
  );

  // 3. FK error: Nonexistent acting_moderator_id
  await TestValidator.error("ban creation with invalid acting_moderator_id")(() =>
    api.functional.discussionboard.bans.create(connection, {
      body: {
        banned_member_id: bannedMember.id,
        acting_moderator_id: typia.random<string & tags.Format<"uuid">>(),
        reason: "Testing invalid moderator",
        ban_type: "temporary",
        banned_at: new Date().toISOString(),
        expires_at: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),
      },
    })
  );

  // 4. FK error: Nonexistent report_id
  await TestValidator.error("ban creation with invalid report_id")(() =>
    api.functional.discussionboard.bans.create(connection, {
      body: {
        banned_member_id: bannedMember.id,
        acting_moderator_id: moderator.id,
        report_id: typia.random<string & tags.Format<"uuid">>(),
        reason: "Testing invalid report",
        ban_type: "temporary",
        banned_at: new Date().toISOString(),
        expires_at: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),
      },
    })
  );

  // 5. Create valid ban for the member
  const ban = await api.functional.discussionboard.bans.create(connection, {
    body: {
      banned_member_id: bannedMember.id,
      acting_moderator_id: moderator.id,
      reason: "Valid ban for duplicate test",
      ban_type: "temporary",
      banned_at: new Date().toISOString(),
      expires_at: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
    },
  });
  typia.assert(ban);

  // 6. Attempt duplicate ban in overlapping period
  await TestValidator.error("duplicate/overlapping ban for same member")(() =>
    api.functional.discussionboard.bans.create(connection, {
      body: {
        banned_member_id: bannedMember.id,
        acting_moderator_id: moderator.id,
        reason: "Overlapping duplicate ban",
        ban_type: "temporary",
        banned_at: new Date().toISOString(),
        expires_at: new Date(Date.now() + 5 * 24 * 60 * 60 * 1000).toISOString(),
      },
    })
  );
}

