 * 3. Passing all required and several optional fields (display_name, bio, avatar_url, etc.).
 * 4. Validating the successful creation, and verifying all returned fields are properly set and public.
 * 5. Confirming that only one profile can be created per member (uniqueness constraint enforcement).
 * 6. Verifying schema correctness and that profile data is accessible/readable as expected.
 */
export async function test_api_discussionboard_test_create_member_profile_for_existing_member(
  connection: api.IConnection,
) {
