 * 4. Attempt to fetch a non-existent snapshot using a random UUID; verify the API returns a not found (404) error or an appropriate error response per the contract.
 */
export async function test_api_discussionboard_test_get_thread_snapshot_by_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. Create a thread to associate a snapshot with
  const board_id = typia.random<string & tags.Format<"uuid">>();
  const author_member_id = typia.random<string & tags.Format<"uuid">>();
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id,
      author_member_id,
      title: "Thread for snapshot fetch test",
      body: "Initial body for audit history test.",
    },
  });
