    body: snapshotInput,
  });
  typia.assert(snapshot);

  // 3. Fetch the thread snapshot by id
  const fetched = await api.functional.discussionboard.threadSnapshots.at(connection, {
    id: snapshot.id,
  });
  typia.assert(fetched);
  TestValidator.equals("id matches")(fetched.id)(snapshot.id);
  TestValidator.equals("thread id matches")(fetched.thread_id)(snapshot.thread_id);
  TestValidator.equals("actor id matches")(fetched.actor_id)(snapshot.actor_id);
  TestValidator.equals("title matches")(fetched.title)(snapshot.title);
  TestValidator.equals("body matches")(fetched.body)(snapshot.body);
  TestValidator.equals("reason matches")(fetched.reason)(snapshot.reason);

  // 4. Attempt to fetch with a random, invalid snapshot id (expect 404)
  await TestValidator.error("fetching non-existent thread snapshot should fail")(
    async () => {
      await api.functional.discussionboard.threadSnapshots.at(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    },
