 * 2. Create a valid post snapshot for that post (Idiscussionboard_post_snapshots).
 * 3. Perform DELETE on the snapshot via api.functional.discussionboard.postSnapshots.erase.
 * 4. Attempt lingering retrieval if any function exists (in this case, since no GET by id is available, skip retrieval—but logic can check the absence by reusing the id for another create).
 * 5. Final check: Attempt redundant deletion, expect error (not-found, indeterminate, or ignore if no error handling is needed in required interface).
 */
export async function test_api_discussionboard_test_delete_post_snapshot_success(
  connection: api.IConnection,
) {
