import type { IPageDiscussionboardCommentVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardCommentVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates the filtering and pagination of comment vote listings.
 *
 * This test ensures that the API for listing comment votes properly respects filter parameters
 * (comment ID, member ID), returns only matching results, and that paging metadata is correctly
 * reported. Multiple comments and members are created, votes are cast (up/down), and the endpoint
 * is queried with different filters and pagination options. Additionally, it checks that requesting
 * a filter for a non-existent comment ID returns an empty result without error.
 *
 * Steps:
 * 1. Create two members (memberA, memberB).
 * 2. Create two comments (commentA, commentB) – using random post IDs.
 * 3. Cast the following votes:
 *    a) memberA upvotes commentA.
 *    b) memberA downvotes commentB.
 *    c) memberB upvotes commentA.
 *    d) memberB downvotes commentB.
 * 4. Query votes filtered by commentA ID: should return only votes for commentA.
 * 5. Query votes filtered by memberB ID: should return only votes cast by memberB.
 * 6. Query votes paginated (limit=1): should show correct pagination for total result set.
 * 7. Query votes with a non-existent comment ID: should yield empty data, no error.
 */
export async function test_api_discussionboard_test_list_comment_votes_with_filtering_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create two members
  const memberA = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(20),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(memberA);

  const memberB = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(20),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(memberB);

  // 2. Create two comments (on random posts)
  const postIdA = typia.random<string & tags.Format<"uuid">>();
  const postIdB = typia.random<string & tags.Format<"uuid">>();

  const commentA = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: postIdA,
      discussionboard_member_id: memberA.id,
      body: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(commentA);

  const commentB = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: postIdB,
      discussionboard_member_id: memberB.id,
      body: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(commentB);

  // 3. Cast votes
  // a) memberA upvotes commentA
  const vote1 = await api.functional.discussionboard.commentVotes.create(connection, {
    body: {
      discussionboard_comment_id: commentA.id,
      discussionboard_member_id: memberA.id,
      vote_type: "up",
    },
  });
  typia.assert(vote1);

  // b) memberA downvotes commentB
  const vote2 = await api.functional.discussionboard.commentVotes.create(connection, {
    body: {
      discussionboard_comment_id: commentB.id,
      discussionboard_member_id: memberA.id,
      vote_type: "down",
    },
  });
  typia.assert(vote2);

  // c) memberB upvotes commentA
  const vote3 = await api.functional.discussionboard.commentVotes.create(connection, {
    body: {
      discussionboard_comment_id: commentA.id,
      discussionboard_member_id: memberB.id,
      vote_type: "up",
    },
  });
  typia.assert(vote3);

  // d) memberB downvotes commentB
  const vote4 = await api.functional.discussionboard.commentVotes.create(connection, {
    body: {
      discussionboard_comment_id: commentB.id,
      discussionboard_member_id: memberB.id,
      vote_type: "down",
    },
  });
  typia.assert(vote4);

  // 4. Query votes filtered by commentA ID
  const pageByCommentA = await api.functional.discussionboard.commentVotes.index(connection, {
    body: { discussionboard_comment_id: commentA.id },
  });
  typia.assert(pageByCommentA);
  TestValidator.predicate("all returned votes belong to commentA")(pageByCommentA.data.every(v => v.discussionboard_comment_id === commentA.id));

  // 5. Query votes filtered by memberB ID
  const pageByMemberB = await api.functional.discussionboard.commentVotes.index(connection, {
    body: { discussionboard_member_id: memberB.id },
  });
  typia.assert(pageByMemberB);
  TestValidator.predicate("all votes are by memberB")(pageByMemberB.data.every(v => v.discussionboard_member_id === memberB.id));

  // 6. Query votes paginated (limit=1)
  const pageLimited = await api.functional.discussionboard.commentVotes.index(connection, {
    body: { limit: 1 },
  });
  typia.assert(pageLimited);
  TestValidator.equals("page limit is 1")(pageLimited.pagination.limit)(1);
  TestValidator.predicate("pagination total matches data length <= limit")(pageLimited.data.length <= 1);

  // 7. Query with non-existent comment ID
  const nonexistentCommentId = typia.random<string & tags.Format<"uuid">>();
  const pageByNonExistent = await api.functional.discussionboard.commentVotes.index(connection, {
    body: { discussionboard_comment_id: nonexistentCommentId },
  });
  typia.assert(pageByNonExistent);
  TestValidator.equals("no data for nonexistent comment")(pageByNonExistent.data.length)(0);
}

