import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IDiscussionboardPostSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostSnapshot";
import type { IPageDiscussionboardPostSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardPostSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { Idiscussionboard_post_snapshots } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_post_snapshots";

/**
 * Validate paginated retrieval of post snapshots filtered by a specific post ID.
 *
 * This test verifies that an admin or moderator can retrieve versions of a post through paginated endpoint, using a filter on the discussionboard_post_id. The business goal is to ensure change tracking (versioning) works correctly and moderation access to edit history is reliable.
 *
 * Step-by-step process:
 * 1. Create a discussionboard post to obtain a valid post ID.
 * 2. Create at least two post snapshot records using that post ID.
 * 3. Call the PATCH /discussionboard/postSnapshots endpoint, filtering by discussionboard_post_id, to obtain the post's versions.
 * 4. Validate the results:
 *   - All returned snapshots must have discussionboard_post_id == created post ID.
 *   - Pagination summary/metadata reflects the correct number of created rows (at least two).
 *   - Each snapshot record matches expected schema.
 */
export async function test_api_discussionboard_test_list_post_snapshots_with_valid_post_id_filter(
  connection: api.IConnection,
) {
  // 1. Create a discussionboard post
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_member_id: memberId,
      discussionboard_board_id: boardId,
      title: "Snapshot test post",
      body: "Initial content for snapshot test"
    } satisfies IDiscussionboardPost.ICreate
  });
  typia.assert(post);

  // 2. Create at least two snapshots for this post
  const firstSnapshot = await api.functional.discussionboard.postSnapshots.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      editor_member_id: post.discussionboard_member_id,
      title: "First version",
      body: "Version 1 of the content",
      taken_at: new Date().toISOString()
    } satisfies Idiscussionboard_post_snapshots.ICreate
  });
  typia.assert(firstSnapshot);

  const secondSnapshot = await api.functional.discussionboard.postSnapshots.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      editor_member_id: post.discussionboard_member_id,
      title: "Second version",
      body: "Version 2 of the content",
      taken_at: new Date(Date.now() + 1000).toISOString()
    } satisfies Idiscussionboard_post_snapshots.ICreate
  });
  typia.assert(secondSnapshot);

  // 3. Retrieve snapshots filtered by post ID
  const result = await api.functional.discussionboard.postSnapshots.index(connection, {
    body: {
      discussionboard_post_id: post.id
    } satisfies IDiscussionboardPostSnapshot.IRequest
  });
  typia.assert(result);

  // 4. Validate all returned snapshots belong to post.id
  for (const snapshot of result.data) {
    typia.assert(snapshot);
    TestValidator.equals("snapshot discussionboard_post_id matches")(snapshot.discussionboard_post_id)(post.id);
  }
  // Pagination should count at least 2 just-created snapshots
  TestValidator.predicate("pagination.record count >= 2")(result.pagination.records >= 2);
}

