import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IDiscussionboardCommentSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentSnapshot";
import type { IPageDiscussionboardCommentSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardCommentSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for the listing/filtering of comment snapshots with various filters and pagination.
 *
 * This workflow tests the ability to retrieve comment snapshots using all supported filters and pagination options. 
 * The dependencies are:
 * 1. Create multiple comments so that there are snapshot history records associated with different comments, posts, and members.
 * 2. For those comments, create multiple comment snapshot history entries, some overlapping comments/members/posts and some unique.
 * 
 * Test Steps:
 * 1. Create several comments with at least two different comment authors (discussionboard_member_id) and at least two different posts.
 * 2. For each comment, create multiple snapshot versions (simulate edits), spreading across different members if possible (mimic comment edits by different users).
 * 3. Retrieve all snapshots with no filter; expect all records, paginated.
 * 4. Filter by specific comment id, expect only that comment's snapshots.
 * 5. Filter by member id, expect only that member's history entries (could be across multiple comments/posts).
 * 6. Filter by post id, expect only snapshots for that post.
 * 7. Filter by version, expect only the snapshot matching that version.
 * 8. Filter by snapshot_created_at range (from/to), expect only those with timestamps in range.
 * 9. Check pagination: set limit to 1 or 2, confirm only limit results per page and that the page metadata is correct.
 * 10. Request a page beyond the number of available results, expect zero results/data array.
 * 11. Test that only schema-present fields appear in results.
 * 12. Try using an invalid filter (e.g. an unsupported property or wrong data type) and confirm an error is returned.
 */
export async function test_api_discussionboard_test_list_comment_snapshots_with_various_filters_and_pagination(connection: api.IConnection) {
  // 1. Create two distinct members (simulate by creating comments with different member IDs)
  const memberId1 = typia.random<string & tags.Format<"uuid">>();
  const memberId2 = typia.random<string & tags.Format<"uuid">>();
  // 2. Create two distinct posts
  const postId1 = typia.random<string & tags.Format<"uuid">>();
  const postId2 = typia.random<string & tags.Format<"uuid">>();
  // 3. Create three comments (c1, c2 for post1; c3 for post2)
  const comment1 = await api.functional.discussionboard.comments.create(connection, { body: { discussionboard_post_id: postId1, discussionboard_member_id: memberId1, body: "Alpha comment" } });
  const comment2 = await api.functional.discussionboard.comments.create(connection, { body: { discussionboard_post_id: postId1, discussionboard_member_id: memberId2, body: "Beta comment" } });
  const comment3 = await api.functional.discussionboard.comments.create(connection, { body: { discussionboard_post_id: postId2, discussionboard_member_id: memberId1, body: "Gamma comment" } });
  // 4. Create several snapshots for each comment
  const now = new Date();
  const SNAPSHOT_CT = 3;
  function advanceMinutes(d, min) { return new Date(d.getTime() + min*60000); }
  const snapshots = [];
  for (const [idx, comment] of [[0, comment1], [1, comment2], [2, comment3]]) {
    for (let v = 1; v <= SNAPSHOT_CT; ++v) {
      const snap_date = advanceMinutes(now, idx*10+v);
      const snap = await api.functional.discussionboard.commentSnapshots.create(connection, {
        body: {
          discussionboard_comment_id: comment.id,
          discussionboard_member_id: (v % 2 === 1) ? memberId1 : memberId2,
          discussionboard_post_id: comment.discussionboard_post_id,
          body: `${comment.body} v${v}`,
          version: v,
          snapshot_created_at: snap_date.toISOString(),
        },
      });
      snapshots.push(snap);
    }
  }
  // 5. Retrieve all snapshots without filter
  const all = await api.functional.discussionboard.commentSnapshots.index(connection, { body: {} });
  typia.assert(all);
  TestValidator.predicate("all records come back")(all.data.length >= snapshots.length);
  // 6. Filter by comment_id
  const filteredByComment = await api.functional.discussionboard.commentSnapshots.index(connection, { body: { discussionboard_comment_id: comment1.id } });
  typia.assert(filteredByComment);
  TestValidator.predicate("filter by comment")(filteredByComment.data.every(d => d.discussionboard_comment_id === comment1.id));
  // 7. Filter by member_id
  const filteredByMember = await api.functional.discussionboard.commentSnapshots.index(connection, { body: { discussionboard_member_id: memberId1 } });
  typia.assert(filteredByMember);
  TestValidator.predicate("filter by member")(filteredByMember.data.every(d => d.discussionboard_member_id === memberId1));
  // 8. Filter by post_id
  const filteredByPost = await api.functional.discussionboard.commentSnapshots.index(connection, { body: { discussionboard_post_id: postId2 } });
  typia.assert(filteredByPost);
  TestValidator.predicate("filter by post")(filteredByPost.data.every(d => d.discussionboard_post_id === postId2));
  // 9. Filter by version
  const version = 2;
  const filteredByVersion = await api.functional.discussionboard.commentSnapshots.index(connection, { body: { version } });
  typia.assert(filteredByVersion);
  TestValidator.predicate("filter by version")(filteredByVersion.data.every(d => d.version === version));
  // 10. Filter by snapshot_created_at range
  const fromDate = advanceMinutes(now, 1).toISOString();
  const toDate = advanceMinutes(now, 15).toISOString();
  const filteredByDate = await api.functional.discussionboard.commentSnapshots.index(connection, { body: { snapshot_created_from: fromDate, snapshot_created_to: toDate } });
  typia.assert(filteredByDate);
  TestValidator.predicate("filter by date")(filteredByDate.data.every(d => d.snapshot_created_at >= fromDate && d.snapshot_created_at <= toDate));
  // 11. Pagination (limit=2, check first page, then page 2)
  const page1 = await api.functional.discussionboard.commentSnapshots.index(connection, { body: { limit: 2, page: 1 } });
  typia.assert(page1);
  TestValidator.equals("pagination limit")(page1.data.length)(2);
  const page2 = await api.functional.discussionboard.commentSnapshots.index(connection, { body: { limit: 2, page: 2 } });
  typia.assert(page2);
  TestValidator.predicate("pagination page 2")(page2.pagination.current === 2);
  // 12. Out-of-bounds page
  const totalPages = page1.pagination.pages;
  const pageBeyond = await api.functional.discussionboard.commentSnapshots.index(connection, { body: { limit: 2, page: totalPages + 10 } });
  typia.assert(pageBeyond);
  TestValidator.equals("out of bounds")(pageBeyond.data.length)(0);
  // 13. Schema field validation
  if(page1.data.length) {
    const sample = page1.data[0];
    const allowedFields = ["id","discussionboard_comment_id","discussionboard_member_id","discussionboard_post_id","body","version","snapshot_created_at"];
    for(const k of Object.keys(sample)) {
      TestValidator.predicate(`schema only fields: ${k}`)(allowedFields.includes(k));
    }
  }
  // 14. Error on unsupported filter property (simulate type error)
  await TestValidator.error("unsupported filter error")(async () => {
    await api.functional.discussionboard.commentSnapshots.index(connection, { body: { not_a_field: "bad" } as any });
  });
}

