import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";
import type { IPageIDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IModeratorAssignment } from "@ORGANIZATION/PROJECT-api/lib/structures/IModeratorAssignment";

/**
 * 테스트 목적: 다양한 필터 및 페이지네이션 파라미터를 이용해 moderator assignment 목록을 올바르게 조회하는지 검증합니다.
 *
 * 이 시나리오는 시스템에서 다음을 검증합니다:
 * 1. 전체 moderator assignments 조회
 * 2. member_id로 필터링
 * 3. assigned_by_admin_id로 필터링
 * 4. 현재 유효한(활성, revoked_at이 null이거나 미래인) assignment만 필터링
 * 5. 올바른 필터로는 적절한 목록이 반환되고, 잘못된 필터(존재하지 않는 필드로 요청) 시 validation error가 발생함을 확인
 *
 * 절차:
 * 1. 테스트용 member 2명(1명은 admin, 1명은 moderator 예정)을 생성한다.
 * 2. admin이 moderator 권한을 부여(assignment 생성)한다.
 *  - expires_at/revoked_at 조합으로 영구 및 임시, 활성/비활성 assignment 모두 생성한다.
 * 3. 전체 목록을 조회하여 전체 assignment가 포함되는지 확인한다.
 * 4. member_id로 필터하고 해당 멤버의 assignment만 반환되는지 확인
 * 5. assigned_by_admin_id로 필터하고 해당 admin이 할당한 assignment만 반환되는지 확인
 * 6. revoked_at이 null 또는 미래인 assignment만 필터해 활성 목록만 반환되는지 확인
 * 7. schema에 없는 필터필드로 요청 시 validation error가 발생하는지 확인
 */
export async function test_api_discussionboard_test_list_moderator_assignments_with_various_filters(connection: api.IConnection) {
  // 1. 테스트에 사용할 멤버 각각 생성 (admin, 일반 유저)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const modEmail = typia.random<string & tags.Format<"email">>();
  const now = new Date();
  const admin = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: adminEmail,
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "admin",
      is_active: true,
    }
  });
  typia.assert(admin);
  const moderator = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: modEmail,
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    }
  });
  typia.assert(moderator);

  // 2. 다양한 assignment 생성 (영구/임시, 활성/비활성)
  // 영구 & 활성
  const permActiveAssignment = await api.functional.discussionboard.moderators.create(connection, {
    body: {
      member_id: moderator.id,
      assigned_by_admin_id: admin.id,
      assigned_at: now.toISOString(),
      expires_at: null,
    }
  });
  typia.assert(permActiveAssignment);
  // 임시 & 활성
  const tempFutureExpiry = new Date(now.getTime() + 86400 * 1000); //+ 1일
  const tempActiveAssignment = await api.functional.discussionboard.moderators.create(connection, {
    body: {
      member_id: moderator.id,
      assigned_by_admin_id: admin.id,
      assigned_at: now.toISOString(),
      expires_at: tempFutureExpiry.toISOString(),
    }
  });
  typia.assert(tempActiveAssignment);
  // 영구 & 비활성 (revoked 처리)
  const revokedPast = new Date(now.getTime() - 3600 * 1000); // -1시간
  const revokedAssignment = await api.functional.discussionboard.moderators.create(connection, {
    body: {
      member_id: moderator.id,
      assigned_by_admin_id: admin.id,
      assigned_at: now.toISOString(),
      expires_at: null,
    }
  });
  // 강제로 revoked_at 직접 셋팅 기능 없음(assignment 생성만 가능)이므로, 이건 후단 필터 테스트에서 일부 제한적으로 활용
  typia.assert(revokedAssignment);

  // 3. 전체 목록 조회 (필터 없음)
  const allAssignments = await api.functional.discussionboard.moderators.index(connection, {
    body: {}
  });
  typia.assert(allAssignments);
  TestValidator.predicate("전체 assignment 개수 2개 이상임")(allAssignments.data.length >= 2);

  // 4. member_id 필터 테스트
  const byMember = await api.functional.discussionboard.moderators.index(connection, {
    body: { member_id: moderator.id }
  });
  typia.assert(byMember);
  TestValidator.predicate("member_id로 조회 시 모두 일치")(byMember.data.every(a => a.member_id === moderator.id));

  // 5. assigned_by_admin_id 필터 테스트
  const byAdmin = await api.functional.discussionboard.moderators.index(connection, {
    body: { assigned_by_admin_id: admin.id }
  });
  typia.assert(byAdmin);
  TestValidator.predicate("assigned_by_admin_id로 필터된 결과 모두 일치")(byAdmin.data.every(a => a.assigned_by_admin_id === admin.id));

  // 6. 활성 assignment만: revoked_at이 null 또는 미래
  const nowIso = new Date().toISOString();
  const activeAssignments = await api.functional.discussionboard.moderators.index(connection, {
    body: { revoked_at: null }
  });
  typia.assert(activeAssignments);
  TestValidator.predicate("revoked_at이 null이거나 미래인 assignment만 포함")(activeAssignments.data.every(a => !a.revoked_at || a.revoked_at > nowIso));

  // 7. 스키마에 없는 잘못된 필터 필드 시도
  await TestValidator.error("존재하지 않는 필터 필드로 에러 발생 확인")(async () => {
    // @ts-expect-error: 존재하지 않는 필터 필드 deliberately 넣음
    await api.functional.discussionboard.moderators.index(connection, {
      body: { not_a_field: 123 },
    });
  });
}

