import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";
import type { IPageIDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IModeratorAssignment } from "@ORGANIZATION/PROJECT-api/lib/structures/IModeratorAssignment";

/**
 * 다양한 필터와 페이지네이션 파라미터로 moderator assignment 목록 조회 동작을 검증합니다.
 *
 * - 전체 assignment 조회, member_id/assigned_by_admin_id별 필터
 * - 활성 assignment만(revoked_at=null 또는 미래) 필터
 * - 없는 필드로 filter 시 validation error 발생 여부
 *
 * 1. 관리(admin)용 회원과 일반 회원을 각각 생성
 * 2. 이들로 assignment 여러 개(영구, 임시, 활성/비활성) 생성
 * 3. 전체 목록, member_id, assigned_by_admin_id별 목록 조회 및 데이터 정합성 검증
 * 4. 활성 assignment만 남기는 filter로 조회 및 데이터 유효성 검증
 * 5. 잘못된 필드 사용 시 validation error 발생 확인
 *
 * revoked_at을 직접 세팅하는 기능은 없으므로, 비활성화 assignment 검증은 제한적으로만 가능
 */
export async function test_api_discussionboard_test_list_moderator_assignments_with_various_filters(
  connection: api.IConnection,
) {
  // 1. 테스트용 admin/일반 member 생성
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const modEmail = typia.random<string & tags.Format<"email">>();
  const now = new Date();
  const admin = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: adminEmail,
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "admin",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(admin);
  const moderator = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: modEmail,
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(moderator);

  // 2. assignment 여러 개 생성(영구/임시)
  // 영구 & 활성
  const permActiveAssignment = await api.functional.discussionboard.moderators.create(connection, {
    body: {
      member_id: moderator.id,
      assigned_by_admin_id: admin.id,
      assigned_at: now.toISOString(),
      expires_at: null,
    } satisfies IModeratorAssignment.ICreate,
  });
  typia.assert(permActiveAssignment);
  // 임시&활성(미래 만료)
  const tempFutureExpiry = new Date(now.getTime() + 86400 * 1000); // +1일
  const tempActiveAssignment = await api.functional.discussionboard.moderators.create(connection, {
    body: {
      member_id: moderator.id,
      assigned_by_admin_id: admin.id,
      assigned_at: now.toISOString(),
      expires_at: tempFutureExpiry.toISOString(),
    } satisfies IModeratorAssignment.ICreate,
  });
  typia.assert(tempActiveAssignment);

  // 3. 전체 목록 조회(필터 없음)
  const allAssignments = await api.functional.discussionboard.moderators.index(connection, {
    body: {},
  });
  typia.assert(allAssignments);
  TestValidator.predicate("전체 assignment 개수 2개 이상임")(allAssignments.data.length >= 2);

  // 4. member_id로 필터
  const byMember = await api.functional.discussionboard.moderators.index(connection, {
    body: { member_id: moderator.id },
  });
  typia.assert(byMember);
  TestValidator.predicate("member_id 일치")(byMember.data.every(a => a.member_id === moderator.id));

  // 5. assigned_by_admin_id로 필터
  const byAdmin = await api.functional.discussionboard.moderators.index(connection, {
    body: { assigned_by_admin_id: admin.id },
  });
  typia.assert(byAdmin);
  TestValidator.predicate("assigned_by_admin_id 일치")(byAdmin.data.every(a => a.assigned_by_admin_id === admin.id));

  // 6. 활성 assignment만(revoked_at=null)
  const nowIso = new Date().toISOString();
  const activeAssignments = await api.functional.discussionboard.moderators.index(connection, {
    body: { revoked_at: null },
  });
  typia.assert(activeAssignments);
  TestValidator.predicate("revoked_at이 null이거나 미래")(activeAssignments.data.every(a => !a.revoked_at || a.revoked_at > nowIso));

  // 7. 스키마에 없는 필드 사용시 error
  await TestValidator.error("존재하지 않는 필드 error")(
    async () =>
      // 타입 안전하게 any 사용 없이 property 넘김
      await api.functional.discussionboard.moderators.index(
        connection,
        { body: { ["not_a_field" as keyof never]: 1 } as any },
      ),
  );
}

