          inapp_enabled: null as any,
          browser_enabled: null as any,
        } as any,
      });
    },
  );

  // 3. Optionally, check original record is unchanged (by refetching or knowing immutability on error)
  // No GET endpoint: Assume database row is unchanged if all updates errored.
}

