import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardEngagementMetric } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardEngagementMetric";

/**
 * Validate retrieving an engagement metric by ID and handling not-found errors.
 *
 * This test ensures the engagement metric retrieval endpoint works for both valid and invalid IDs,
 * including the edge case of accessing a deleted record.
 *
 * Steps:
 * 1. Create an engagement metric record using the POST endpoint.
 * 2. Retrieve it by its unique ID using the GET endpoint and verify all returned fields match.
 * 3. Request an engagement metric by a random (non-existent) ID and confirm a not-found error is thrown.
 * 4. Delete the previously created metric using the DELETE endpoint.
 * 5. Attempt to fetch the now-deleted metric and confirm a not-found error is thrown.
 */
export async function test_api_discussionboard_engagementMetrics_test_get_engagement_metric_by_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. Create an engagement metric
  const createInput: IDiscussionboardEngagementMetric.ICreate = {
    discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
    engagement_date: typia.random<string & tags.Format<"date-time">>(),
    posts_created_count: typia.random<number & tags.Type<"int32">>(),
    comments_created_count: typia.random<number & tags.Type<"int32">>(),
    votes_cast_count: typia.random<number & tags.Type<"int32">>(),
  };
  const created: IDiscussionboardEngagementMetric =
    await api.functional.discussionboard.engagementMetrics.create(connection, {
      body: createInput,
    });
  typia.assert(created);

  // 2. Retrieve by ID and check fields match
  const retrieved: IDiscussionboardEngagementMetric =
    await api.functional.discussionboard.engagementMetrics.at(connection, {
      id: created.id,
    });
  typia.assert(retrieved);
  TestValidator.equals("fields match")(retrieved)({ ...created });

  // 3. Attempt to fetch with a non-existent ID
  await TestValidator.error("not found for random id")(() =>
    api.functional.discussionboard.engagementMetrics.at(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );

  // 4. Delete the created record
  await api.functional.discussionboard.engagementMetrics.erase(connection, {
    id: created.id,
  });

  // 5. Attempt to fetch now-deleted record
  await TestValidator.error("not found after delete")(() =>
    api.functional.discussionboard.engagementMetrics.at(connection, {
      id: created.id,
    })
  );
}

