 * filtering by display_name works as expected, and pagination is handled correctly. No authentication
 * is required for this operation.
 *
 * Steps:
 * 1. Create several members (with unique emails/usernames).
 * 2. For each member, create a public member profile with unique display names (some shared substrings).
 * 3. Use the PATCH /discussionboard/memberProfiles endpoint to search for profiles
 *    with a partial display_name substring, adding pagination parameters (limit, current page).
 * 4. Validate the API returns only matching profiles, correct page metadata, and all fields strictly
 *    match the IMemberProfile schema.
 * 5. Confirm that email, role, or other private data is not present in the profile results.
 */
export async function test_api_discussionboard_test_list_member_profiles_with_pagination_and_filter(
  connection: api.IConnection,
) {
  // 1. Create members
  const memberCount = 5;
  const baseDisplay = "Alpha";
  const members: IDiscussionboardMember[] = [];
  for (let i = 0; i < memberCount; ++i) {
    const member: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, {
      body: {
        username: `${baseDisplay}_${i}`,
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(16),
        role: "member",
        is_active: true
      } satisfies IDiscussionboardMember.ICreate
    });
    typia.assert(member);
    members.push(member);
  }

  // 2. Create member profiles
  const profileNames = [
    "Alpha Wolf",
    "Beta Tester",
    "Alpha Centauri",
    "Gamma Ray",
    "AlphaDog"
  ];
  const createdProfiles: IMemberProfile[] = [];
  for (let i = 0; i < members.length; ++i) {
    const profile: IMemberProfile = await api.functional.discussionboard.memberProfiles.create(connection, {
      body: {
        member_id: members[i].id,
        display_name: profileNames[i],
        bio: RandomGenerator.paragraph()(),
        avatar_url: typia.random<string & tags.Format<"uri">>(),
        location: RandomGenerator.name(),
        website_url: typia.random<string & tags.Format<"uri">>()
      } satisfies IMemberProfile.ICreate
    });
    typia.assert(profile);
    createdProfiles.push(profile);
  }

  // 3. Query with filter and pagination - filter for display_name containing "Alpha"
  const filterDisplay = "Alpha";
  const limit = 2;
  const current = 1;
  const response = await api.functional.discussionboard.memberProfiles.index(connection, {
    body: {
      display_name: filterDisplay,
      // Extra fields for pagination
      // The pagination itself is handled in response, but accepted in the request depending on API design
      // (IMemberProfile.IRequest doesn't define limit/current, but business scenario assumes they exist in endpoint)
    } satisfies IMemberProfile.IRequest
  });
  typia.assert(response);

  // 4. Validate that all returned profiles contain the substring and page info is structured
  for (const profile of response.data) {
    typia.assert(profile);
    TestValidator.predicate("Contains filter substring")(profile.display_name.includes(filterDisplay));

    // Ensure only public fields are returned
    TestValidator.predicate("No private fields")(!('email' in profile) && !('role' in profile));
  }
  TestValidator.predicate("Pagination valid")(typeof response.pagination.current === "number" && response.pagination.current >= 1);
  TestValidator.predicate("Pagination valid")(response.pagination.limit >= 1);
  TestValidator.predicate("Correct data length")(response.data.length <= limit);
}

