import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IAdminAssignment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAssignment";

/**
 * Test the full admin assignment revoke and restore lifecycle with /discussionboard/admins/{id} (PUT).
 *
 * 1. Create the user who will become the admin target member.
 * 2. Create the admin who assigns admin privileges.
 * 3. Assign admin privilege from the admin to the member (should be active/no revoked_at).
 * 4. Update the admin assignment and set revoked_at to now (revoke privileges).
 * 5. Assert that revoked_at is set and assignment is effectively inactive.
 * 6. Update again - set revoked_at to null (restore privileges).
 * 7. Assert that revoked_at is null and assignment is active again.
 */
export async function test_api_discussionboard_test_update_admin_assignment_revoke_and_reassign(
  connection: api.IConnection,
) {
  // 1. Create member (target for admin assignment)
  const member: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create admin (who assigns the privilege)
  const assigner: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "admin",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(assigner);

  // 3. Assign admin privilege (active, no revoked_at)
  const now = new Date().toISOString();
  const adminAssignment = await api.functional.discussionboard.admins.create(connection, {
    body: {
      member_id: member.id,
      assigned_by_admin_id: assigner.id,
      assigned_at: now,
      revoked_at: null,
    } satisfies IAdminAssignment.ICreate,
  });
  typia.assert(adminAssignment);
  TestValidator.equals("initial assignment active")(adminAssignment.revoked_at)(null);

  // 4. Update to set revoked_at (revoke privileges)
  const revokeTime = new Date(Date.now() + 1000).toISOString();
  const revoked = await api.functional.discussionboard.admins.update(connection, {
    id: adminAssignment.id,
    body: {
      revoked_at: revokeTime,
    } satisfies IAdminAssignment.IUpdate,
  });
  typia.assert(revoked);
  TestValidator.equals("assignment revoked")(revoked.revoked_at)(revokeTime);

  // 5. Update again - set revoked_at to null (restore privileges)
  const restored = await api.functional.discussionboard.admins.update(connection, {
    id: adminAssignment.id,
    body: {
      revoked_at: null,
    } satisfies IAdminAssignment.IUpdate,
  });
  typia.assert(restored);
  TestValidator.equals("assignment restored active")(restored.revoked_at)(null);
}

