import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IPageIComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing and filtering of comments with advanced scenarios:
 *   - Filtering comments by post, author, parent comment, nesting (replies to comments)
 *   - Filtering by creation and update timestamps (date/time windows)
 *   - Filtering soft-deleted (deleted_at) comments
 *   - Edge: no comments under a post, or soft-deleted only
 *   - Pagination and ordering
 *   - Schema integrity for all returned comment fields
 *
 * The steps are:
 * 1. Create two posts and at least two member IDs (for author variety)
 * 2. Create several top-level comments for post A (with different authors)
 * 3. Create replies (child comments) under some comments, building a tree
 * 4. Soft-delete one comment and its child (simulate moderation/audit)
 * 5. Issue search requests:
 *    - List all comments for post A; validate total, ordering, and correspondence
 *    - Filter by author and check author-only comments are returned
 *    - Fetch only top-level (parent_id null) vs only children (parent_id set)
 *    - List soft-deleted comments for post A
 *    - Paginate: Limit = 2 per page, fetch page 1, then page 2 and compare
 *    - For post B, confirm empty result (no comments)
 *    - For each result, validate all fields match IComment (esp. deleted_at)
 */
export async function test_api_discussionboard_test_list_comments_with_various_filters_and_pagination(connection: api.IConnection) {
  // 1. Create two posts
  const memberA = typia.random<string & tags.Format<"uuid">>();
  const memberB = typia.random<string & tags.Format<"uuid">>();
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const postA = await api.functional.discussionboard.posts.create(connection, { body: { discussionboard_thread_id: threadId, discussionboard_member_id: memberA, discussionboard_board_id: boardId, title: "Post A", body: "Body A" }});
  const postB = await api.functional.discussionboard.posts.create(connection, { body: { discussionboard_thread_id: threadId, discussionboard_member_id: memberB, discussionboard_board_id: boardId, title: "Post B", body: "Body B" }});
  typia.assert(postA); typia.assert(postB);

  // 2. Create top-level comments for postA, multiple members
  const commentA1 = await api.functional.discussionboard.comments.create(connection, { body: { discussionboard_post_id: postA.id, discussionboard_member_id: memberA, body: "Top by A" }});
  const commentA2 = await api.functional.discussionboard.comments.create(connection, { body: { discussionboard_post_id: postA.id, discussionboard_member_id: memberB, body: "Top by B" }});
  typia.assert(commentA1); typia.assert(commentA2);

  // 3. Child comments (nested)
  const childA1 = await api.functional.discussionboard.comments.create(connection, { body: { discussionboard_post_id: postA.id, discussionboard_member_id: memberB, parent_id: commentA1.id, body: "Reply to Top by A (by B)" }});
  const childA2 = await api.functional.discussionboard.comments.create(connection, { body: { discussionboard_post_id: postA.id, discussionboard_member_id: memberA, parent_id: commentA2.id, body: "Reply to Top by B (by A)" }});
  typia.assert(childA1); typia.assert(childA2);

  // 4. Mark commentA2 and its child as soft-deleted (simulate by providing deleted_at)
  // Since there is no explicit delete endpoint, direct DB operation is not available, so we skip active deletion; but we'll set deleted filter for query tests.

  // 5. Issue search requests
  // All for postA
  const allForPostA = await api.functional.discussionboard.comments.index(connection, { body: { discussionboard_post_id: postA.id }});
  typia.assert(allForPostA);
  allForPostA.data.forEach(typia.assert);
  // Confirm all are for postA
  allForPostA.data.forEach(c => TestValidator.equals("post id")(c.discussionboard_post_id)(postA.id));

  // Filter by author (memberA)
  const byMemberA = await api.functional.discussionboard.comments.index(connection, { body: { discussionboard_post_id: postA.id, discussionboard_member_id: memberA }});
  typia.assert(byMemberA);
  byMemberA.data.forEach(typia.assert);
  byMemberA.data.forEach(c => TestValidator.equals("author")(c.discussionboard_member_id)(memberA));

  // Only top-level
  const topLevel = await api.functional.discussionboard.comments.index(connection, { body: { discussionboard_post_id: postA.id, parent_id: null }});
  typia.assert(topLevel);
  topLevel.data.forEach(typia.assert);
  topLevel.data.forEach(c => TestValidator.equals("top-level")(c.parent_id)(null));

  // Only children of commentA1
  const children = await api.functional.discussionboard.comments.index(connection, { body: { discussionboard_post_id: postA.id, parent_id: commentA1.id }});
  typia.assert(children);
  children.data.forEach(typia.assert);
  children.data.forEach(c => TestValidator.equals("parent id")(c.parent_id)(commentA1.id));

  // Soft-deleted filter (should be empty as we cannot truly delete, but query should work)
  const deletedOnly = await api.functional.discussionboard.comments.index(connection, { body: { discussionboard_post_id: postA.id, deleted: true }});
  typia.assert(deletedOnly); // Should be empty unless test infra supports it, but schema/logic must work
  deletedOnly.data.forEach(c => TestValidator.predicate("deleted_at present")(!!c.deleted_at));

  // Pagination: limit=2, page=1, then page=2
  const page1 = await api.functional.discussionboard.comments.index(connection, { body: { discussionboard_post_id: postA.id, page: 1, limit: 2 }});
  typia.assert(page1); page1.data.forEach(typia.assert);
  const page2 = await api.functional.discussionboard.comments.index(connection, { body: { discussionboard_post_id: postA.id, page: 2, limit: 2 }});
  typia.assert(page2); page2.data.forEach(typia.assert);
  // Pagination sanity check
  TestValidator.equals("pagination.fields")(page1.pagination.limit)(2);
  TestValidator.equals("pagination.page")(page1.pagination.current)(1);
  TestValidator.equals("pagination.page")(page2.pagination.current)(2);

  // Post B: no comments
  const empty = await api.functional.discussionboard.comments.index(connection, { body: { discussionboard_post_id: postB.id }});
  typia.assert(empty);  TestValidator.equals("no comments")(empty.data.length)(0);
}

