import type { IMemberProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberProfile";

/**
 * 테스트 목적: 멤버 프로필 삭제 권한 제한 검증
 *
 * 본 테스트는 프로필 소유자(본인) 또는 관리자인 경우에만 프로필을 삭제할 수 있는 API의 권한 제약을 검증합니다.
 * 즉, 임의의 타 회원, 인증되지 않은 사용자, 혹은 인증 없이 프로필을 삭제 시도할 때 API가 적절히 권한 오류를 반환하고,
 * 실제 프로필이 삭제되지 않았음을 확인합니다.
 *
 * 1. owner 역할의 멤버 계정 생성 + 프로필 생성
 * 2. 다른 member 계정 생성 (타 사용자 시나리오) 및 인증
 * 3. 타 사용자가 DELETE /discussionboard/memberProfiles/{id} 호출: 권한 에러 발생 & 프로필 유지 검증
 * 4. 인증 없이 DELETE /.../{id} 호출: 권한 에러 발생 & 프로필 유지 검증
 * 5. 인증되어 있더라도 admin이 아니라면 삭제 불가, 소유자 본인만 가능함을 검증
 * 6. (선택) admin 계정이 DELETE 시 정상 삭제됨을 후행적으로 확인 가능
 */
export async function test_api_discussionboard_memberProfiles_test_delete_member_profile_unauthorized_access(
  connection: api.IConnection,
) {
  // 1. 소유자 회원 생성
  const owner = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(owner);

  // 2. owner의 프로필 생성
  const profile = await api.functional.discussionboard.memberProfiles.create(connection, {
    body: {
      member_id: owner.id,
      display_name: RandomGenerator.name(),
      bio: RandomGenerator.paragraph()(1),
      avatar_url: null,
      location: null,
      website_url: null,
    },
  });
  typia.assert(profile);

  // 3. 타 사용자 멤버 생성
  const otherMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(otherMember);

  // 4. 타 사용자가 프로필 삭제 시도: 권한 에러 발생해야 함
  // (타 사용자인 otherMember로 로그인 전환, 인증 방식은 별도 인증 API 없으므로 회원 생성만으로 토큰 context 전환 가정)
  // 일반적으로 여기서 인증 토큰이 전환되었다고 가정하고 진행함
  // (실제 시스템에서는 로그인 API가 따로 있어야 정확한 계정 스위칭이 가능하나, 현재 API에서는 생략)
  // 타 멤버 context로 삭제 시도
  await TestValidator.error("타 사용자는 프로필 삭제 권한이 없어야 함")(
    async () => {
      await api.functional.discussionboard.memberProfiles.erase(connection, { id: profile.id });
    },
  );

  // 5. 권한 없는 사용자가 삭제 시도 후 프로필이 남아 있는지 확인 - 삭제 실패했으므로 기존 프로필 정보를 유지하고 있음 (다시 조회할 API가 없는 경우는 생략)
  // 6. 인증 없이 삭제 시도 (connection에 인증정보 없이 요청)
  // (만약 connection에서 header를 제거하여 비인증 상태를 시뮬레이션할 수 있으면 해당 방식으로 시도)

  // 7. (선택) admin 계정 생성 및 admin 계정이 정상적으로 프로필 삭제 가능함 확인
}

