import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";

/**
 * Test soft-deleting a discussion board comment (logical deletion).
 *
 * Validates that deleting a comment sets its deleted_at timestamp without hard removal
 * - Covers success path, idempotency (repeat delete), and non-existent-comment edge case.
 * - Ensures deleted_at field is appropriately updated.
 * - Guarantees no hard deletion occurs; the comment remains in storage with a deleted_at mark.
 *
 * Stepwise process:
 * 1. Create a new member (comment author)
 * 2. Create a new post
 * 3. Create a new comment for the post as the member
 * 4. Soft-delete the comment (delete by ID)
 * 5. Retrieve the comment by re-creating (since no comment retrieval API is present, this step cannot re-check via GET)
 * 6. Verify deleted_at is set after deletion
 * 7. Attempt to delete the same comment again (idempotency)
 *    - No error expected, deleted_at should be updated again (or left unchanged)
 * 8. Attempt to delete a non-existent comment
 *    - Should not hard error, test for proper handling (error or silent accept)
 *    - Confirm system stability (no real deletion, errors are graceful)
 */
export async function test_api_discussionboard_test_soft_delete_comment_and_idempotency(
  connection: api.IConnection,
) {
  // 1. Create a new member (author)
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(member);

  // 2. Create a new post
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: member.id,
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(1),
    },
  });
  typia.assert(post);

  // 3. Create a comment for the post
  const comment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
      parent_id: null,
      body: RandomGenerator.paragraph()(1),
    },
