  TestValidator.equals("pagination page 1")(page1.pagination.current)(1);
  TestValidator.equals("records in data")(page1.data.length)(2);
  TestValidator.equals("first snapshot matches")(page1.data[0].id)(snap1.id);
  TestValidator.equals("second snapshot matches")(page1.data[1].id)(snap2.id);

  // 4. Query page=2
  const page2 = await api.functional.discussionboard.threadSnapshots.index(connection, {
    body: { thread_id: thread.id, limit: 2, page: 2 },
  });
  typia.assert(page2);
  TestValidator.equals("pagination page 2")(page2.pagination.current)(2);
  TestValidator.equals("page 2 should have 1 result")(page2.data.length)(1);
  TestValidator.equals("third snapshot matches")(page2.data[0].id)(snap3.id);

  // 5. Filter by actor_id (actorB)
  const byActorB = await api.functional.discussionboard.threadSnapshots.index(connection, {
    body: { thread_id: thread.id, actor_id: actorB },
  });
  typia.assert(byActorB);
  TestValidator.equals("only snap2 by actorB")([snap2.id])(byActorB.data.map(x => x.id));

  // 6. Filter by title substring
  const byTitle = await api.functional.discussionboard.threadSnapshots.index(connection, {
    body: { thread_id: thread.id, title: "final" },
  });
  typia.assert(byTitle);
  TestValidator.predicate("finds snap3 by 'final'")(byTitle.data.some(x => x.id === snap3.id));

  // 7. Filter by creation time (from snap2.created_at)
  const byCreated = await api.functional.discussionboard.threadSnapshots.index(connection, {
    body: { thread_id: thread.id, created_at_from: snap2.created_at },
  });
  typia.assert(byCreated);
  TestValidator.equals("snap2 and snap3 included")(
    new Set(byCreated.data.map(x => x.id))
  )(new Set([snap2.id, snap3.id]));

  // 8. Edge case: non-existent actor, should be empty
  const byMissingActor = await api.functional.discussionboard.threadSnapshots.index(connection, {
    body: { thread_id: thread.id, actor_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(byMissingActor);
  TestValidator.equals("no data for random actor")(byMissingActor.data.length)(0);

  // 9. Edge case: page beyond available results, should be empty
  const pageBeyond = await api.functional.discussionboard.threadSnapshots.index(connection, {
    body: { thread_id: thread.id, page: 10, limit: 3 },
  });
  typia.assert(pageBeyond);
  TestValidator.equals("empty data for far page")(pageBeyond.data.length)(0);
}
function sleep(ms: number) {
  return new Promise(res => setTimeout(res, ms));
}

