import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IMemberProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberProfile";
import type { IPageIMemberProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIMemberProfile";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test filtering discussion board member profiles by location using the PATCH endpoint.
 *
 * Business context:
 * - The system allows public member profiles to be filtered/searchable by 'location' via a PATCH request to /discussionboard/memberProfiles.
 * - This test ensures the filter logic for location matches only the correct profiles, both when there are matches and when there are not.
 *
 * Steps:
 * 1. Create multiple unique members using the discussionboard.members.create endpoint.
 * 2. For each member, create a corresponding profile via discussionboard.memberProfiles.create, assigning
distinct 'location' values (e.g., 'Seoul', 'Busan', null, 'New York').
 * 3. Filter member profiles by location 'Seoul' and verify only profiles with location 'Seoul' are returned.
 * 4. Filter by location 'New York' and verify only that profile is returned.
 * 5. Filter by a location that does not exist among the test profiles (e.g., 'London') and verify no data is returned.
 * 6. Filter with an empty/location=null keyword to check proper handling of missing values (optional edge case).
 */
export async function test_api_discussionboard_test_list_member_profiles_filter_by_location(connection: api.IConnection) {
  // 1. Create members
  const memberInfos = await Promise.all([
    api.functional.discussionboard.members.create(connection, {
      body: {
        username: RandomGenerator.alphabets(8),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(12),
        role: "member",
        is_active: true,
      } satisfies IDiscussionboardMember.ICreate,
    }),
    api.functional.discussionboard.members.create(connection, {
      body: {
        username: RandomGenerator.alphabets(8),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(12),
        role: "member",
        is_active: true,
      } satisfies IDiscussionboardMember.ICreate,
    }),
    api.functional.discussionboard.members.create(connection, {
      body: {
        username: RandomGenerator.alphabets(8),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(12),
        role: "member",
        is_active: true,
      } satisfies IDiscussionboardMember.ICreate,
    }),
    api.functional.discussionboard.members.create(connection, {
      body: {
        username: RandomGenerator.alphabets(8),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(12),
        role: "member",
        is_active: true,
      } satisfies IDiscussionboardMember.ICreate,
    })
  ]);
  typia.assert(memberInfos);

  // 2. Create profiles with different locations
  const profileData = [
    { display_name: "Alice", location: "Seoul" },
    { display_name: "Bob", location: "Busan" },
    { display_name: "Charlie", location: null },
    { display_name: "Dana", location: "New York" },
  ];
  const profileInfos = await Promise.all(memberInfos.map((member, i) =>
    api.functional.discussionboard.memberProfiles.create(connection, {
      body: {
        member_id: member.id,
        display_name: profileData[i].display_name,
        location: profileData[i].location,
      } satisfies IMemberProfile.ICreate,
    })
  ));
  typia.assert(profileInfos);

  // 3. Filter for location 'Seoul'
  const seoulResult = await api.functional.discussionboard.memberProfiles.index(connection, {
    body: { location: "Seoul" },
  });
  typia.assert(seoulResult);
  TestValidator.predicate("all results have location Seoul")(
    seoulResult.data.every(profile => profile.location === "Seoul")
  );
  TestValidator.equals("single Seoul profile returned")(seoulResult.data.length)(1);
  TestValidator.equals("Seoul profile's memberId matches")(seoulResult.data[0].member_id)(memberInfos[0].id);

  // 4. Filter for location 'New York'
  const nyResult = await api.functional.discussionboard.memberProfiles.index(connection, {
    body: { location: "New York" },
  });
  typia.assert(nyResult);
  TestValidator.predicate("all results have location New York")(
    nyResult.data.every(profile => profile.location === "New York")
  );
  TestValidator.equals("single New York profile returned")(nyResult.data.length)(1);
  TestValidator.equals("NY profile's memberId matches")(nyResult.data[0].member_id)(memberInfos[3].id);

  // 5. Filter for a missing location 'London', expect no matches
  const missingResult = await api.functional.discussionboard.memberProfiles.index(connection, {
    body: { location: "London" },
  });
  typia.assert(missingResult);
  TestValidator.equals("no profiles for missing location")(missingResult.data.length)(0);

  // 6. (Edge) Filter by location = null, matches only profiles with location == null
  const nullLocResult = await api.functional.discussionboard.memberProfiles.index(connection, {
    body: { location: null },
  });
  typia.assert(nullLocResult);
  TestValidator.predicate("all results have location null")(
    nullLocResult.data.every(profile => profile.location === null)
  );
  // There is only one such test profile
  TestValidator.equals("only profile with null location in result")(nullLocResult.data.length)(1);
  TestValidator.equals("profile with null location's memberId")(nullLocResult.data[0].member_id)(memberInfos[2].id);
}

