import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { Idiscussionboard_post_votes } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_post_votes";

/**
 * Validate successful retrieval of a post vote by its existing ID.
 *
 * This test covers the workflow for capturing and reading a post vote in the discussion board system.
 * It performs the following sequence:
 * 1. Registers a new member with realistic details for voting.
 * 2. Creates a post authored by that member using valid associations.
 * 3. Casts a vote by the registered member on the created post using the valid vote type and timestamp.
 * 4. Retrieves the vote just created by its unique ID using the `GET /discussionboard/postVotes/{id}` endpoint.
 * 5. Validates that all returned vote details (IDs, type, and timestamps) match what was used when creating the vote.
 */
export async function test_api_discussionboard_test_get_post_vote_by_existing_id(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const memberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(14),
    role: "member",
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create a post authored by the new member
  const postInput: IDiscussionboardPost.ICreate = {
    discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_member_id: member.id,
    discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
  };
  const post = await api.functional.discussionboard.posts.create(connection, { body: postInput });
  typia.assert(post);

  // 3. Cast a vote on the post by the member
  const now = new Date().toISOString();
  const voteInput: Idiscussionboard_post_votes.ICreate = {
    discussionboard_post_id: post.id,
    discussionboard_member_id: member.id,
    vote_type: 1,
    created_at: now,
  };
  const vote = await api.functional.discussionboard.postVotes.create(connection, { body: voteInput });
  typia.assert(vote);

  // 4. Retrieve the vote by ID
  const fetchedVote = await api.functional.discussionboard.postVotes.at(connection, { id: vote.id });
  typia.assert(fetchedVote);

  // 5. Validate returned data matches creation
  TestValidator.equals("vote id")(fetchedVote.id)(vote.id);
  TestValidator.equals("post id")(fetchedVote.discussionboard_post_id)(voteInput.discussionboard_post_id);
  TestValidator.equals("member id")(fetchedVote.discussionboard_member_id)(voteInput.discussionboard_member_id);
  TestValidator.equals("vote type")(fetchedVote.vote_type)(voteInput.vote_type);
  TestValidator.equals("created_at")(fetchedVote.created_at)(voteInput.created_at);
}

