import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardWarning";

/**
 * 검토 대상 경고 레코드 하나를 가져올 수 있는 권한이 관리자인지(혹은 모더레이터)만을 확인한다.
 * 1. 권한이 있는 관리자 혹은 모더레이터(시뮬레이션: 인증 상태 유지)로 warning을 생성하고, 해당 warning의 id로 단일 조회를 해본다. 성공적으로 데이터를 받아야 한다.
 * 2. 인증되지 않은 상태(Authorization 없이)에서 같은 id로 접근, 에러(접근 거부)가 발생해야 한다.
 * 3. 권한이 부족한 일반 discussionboard member 역할로 로그인하여 접근했을 때도 반드시 거부되어야 한다.
 * 주의: 인증 방식은 시뮬레이터 혹은 실제 프로젝트 정책에 따라 다르지만, 본 구현에서는 로그인/인증 상태 context(authorization header) 조작 테스트만으로 충분하다.
 * 추가적으로, 테스트에 사용할 warning 데이터는 의존성: discussionboard.warnings.create로 생성한다.
 */
export async function test_api_discussionboard_test_get_warning_access_control(connection: api.IConnection) {
  // 1. 관리자 혹은 모더레이터 권한으로 warning을 생성한다.
  const warning = await api.functional.discussionboard.warnings.create(connection, {
    body: typia.random<IDiscussionboardWarning.ICreate>(),
  });
  typia.assert(warning);

  // 2. 정상적으로 관리자/모더레이터 인증 토큰 유지 상태에서 warning 단건 조회
  const adminFetched = await api.functional.discussionboard.warnings.at(connection, { id: warning.id });
  typia.assert(adminFetched);
  TestValidator.equals("admin/mod data equal")(adminFetched)(warning);

  // 3. 인증 없이(Authorization unset) 단건 조회 시도 → 접근 거부 에러 확인
  const noAuthConnection = { ...connection, headers: { ...connection.headers } };
  delete noAuthConnection.headers.Authorization;
  await TestValidator.error("unauthenticated cannot fetch")(
    async () => {
      await api.functional.discussionboard.warnings.at(noAuthConnection, { id: warning.id });
    }
  );

  // 4. 권한이 없는 일반 member 사용자 로그인 후 조회 시도 → 접근 거부 에러 확인
  // 일반 멤버 인증 정보로 authorization context 갱신(예: connection.headers.Authorization = memberToken) 후 호출
