import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoard";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IPageDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Tests paginated, thread-filtered post list retrieval w/ correct pagination and soft-delete display.
 *
 * - Validates only posts from the target thread are listed for the thread filter
 * - Paging logic: correct page/limit/data slice, page overflow returns empty results but valid metadata
 * - Soft-deleted posts' is_deleted flag appears as set
 * - Empty threads return empty array with correct pagination
 *
 * [Test process]
 * 1. Create a board for testing
 * 2. Register two members
 * 3. Create a thread in the board (authored by member1)
 * 4. Insert multiple posts into the thread by both members (some soft-deleted)
 * 5. Retrieve paginated post lists (e.g., limit=3 across 4+ pages)
 * 6. Confirm all posts belong to the thread, is_deleted values, and pagination counts/edges
 * 7. Request a page after the last; expect empty data & proper meta
 * 8. Test retrieval from a thread with no posts; expect empty results/valid meta
 */
export async function test_api_discussionboard_test_list_posts_with_thread_filter_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create test board
  const board = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.paragraph()(3),
      code: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(1),
      is_active: true,
      is_visible: true,
    } satisfies IBoard.ICreate,
  });
  typia.assert(board);

  // 2. Register two members
  const member1 = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(6),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member1);
  const member2 = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(7),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member2);

  // 3. Create a thread in the board, authored by member1
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: board.id,
      author_member_id: member1.id,
      title: RandomGenerator.paragraph()(2),
      body: RandomGenerator.paragraph()(1),
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);

  // 4. Insert 10 posts into the thread (alternating member, some is_deleted)
  const posts: IDiscussionboardPost[] = [];
  for (let i = 0; i < 10; ++i) {
    const member = i % 2 === 0 ? member1 : member2;
    const post = await api.functional.discussionboard.posts.create(connection, {
      body: {
        discussionboard_thread_id: thread.id,
        discussionboard_member_id: member.id,
        discussionboard_board_id: board.id,
        title: `Test Post #${i + 1}`,
        body: RandomGenerator.paragraph()(),
      } satisfies IDiscussionboardPost.ICreate,
    });
    typia.assert(post);
    // Soft-delete even-indexed (i.e., is_deleted=true for 0,2,4,...)
    const full = i % 2 === 0 ? { ...post, is_deleted: true } : post;
    posts.push(full);
  }
  // Post soft-delete (simulate is_deleted=true by patching DB/endpoint if possible, otherwise just set in data)
  // For this test, just flag expected outcome (the API supports only create, not update/delete).

  // 5. Retrieve paginated lists: page size 3, iterate pages, validate data
  const pageSize = 3;
  const totalPosts = posts.length;
  const totalPages = Math.ceil(totalPosts / pageSize);
  for (let page = 1; page <= totalPages; ++page) {
    const res = await api.functional.discussionboard.posts.index(connection, {
      body: {
        discussionboard_thread_id: thread.id,
        // Pagination is expected in IRequest as 'limit'/'current', even though not detailed in DTO (may depend on API impl).
        // Add if supported, skip if not. For test, include both for full coverage.
        // If limit/current not in DTO, the API may fallback to default pagination size.
        limit: pageSize,
        current: page,
      } as any, // Type safe workaround: limit/current may not be in .IRequest but are in API per returned meta
    });
    typia.assert(res);
    // All returned posts should belong to intended thread
    for (const p of res.data) {
      TestValidator.equals("thread id matches")(p.discussionboard_thread_id)(thread.id);
    }
    // Page meta checks
    TestValidator.equals("pagination.current")(res.pagination.current)(page);
    TestValidator.equals("pagination.limit")(res.pagination.limit)(pageSize);
    // is_deleted flag (should be as per original post creation, since we can't truly soft-delete)
    for (const [idx, p] of res.data.entries()) {
      const expected = posts[(page - 1) * pageSize + idx];
      if (!expected) continue;
      TestValidator.equals(`is_deleted matches for #${(page - 1) * pageSize + idx}`)(p.is_deleted)(expected.is_deleted);
    }
  }

  // 6. Request a page after the last (should return empty data, proper meta)
  const overflowRes = await api.functional.discussionboard.posts.index(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      limit: pageSize,
      current: totalPages + 1,
    } as any,
  });
  typia.assert(overflowRes);
  TestValidator.equals("overflow page is empty")(overflowRes.data.length)(0);
  TestValidator.equals("pagination.current overflows")(overflowRes.pagination.current)(totalPages + 1);

  // 7. Query a different (empty) thread; expect empty results
  const emptyThread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: board.id,
      author_member_id: member2.id,
      title: RandomGenerator.paragraph()(1),
      body: "Test empty thread, no posts",
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(emptyThread);
  const emptyRes = await api.functional.discussionboard.posts.index(connection, {
    body: {
      discussionboard_thread_id: emptyThread.id,
      limit: pageSize,
      current: 1,
    } as any,
  });
  typia.assert(emptyRes);
  TestValidator.equals("empty thread: no posts")(emptyRes.data.length)(0);
  TestValidator.equals("empty thread: meta records")(emptyRes.pagination.records)(0);
}

