import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { Idiscussionboard_post_votes } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_post_votes";

/**
 * Validate update of a discussion board post vote's vote_type by ID.
 *
 * This test covers the scenario where a member changes their voting action on a post (e.g., from upvote to downvote). Workflow:
 * 1. Register a member for voting.
 * 2. Create a new post by that member (assuming member is the author).
 * 3. The member casts an initial upvote (vote_type=1) for the post.
 * 4. Use the update endpoint to change the vote_type from 1 (upvote) to -1 (downvote).
 * 5. Assert that the returned entity has vote_type updated to -1 and all other fields (post, member, created_at) preserved.
 * 6. Optionally, try to repeat the update to verify uniqueness and idempotency (should succeed since updating own vote is legal, but no duplicates created).
 */
export async function test_api_discussionboard_test_update_post_vote_vote_type_successfully(connection: api.IConnection) {
  // 1. Create discussion board member
  const memberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    role: "member",
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create a post with required foreign key values
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const postInput: IDiscussionboardPost.ICreate = {
    discussionboard_thread_id: threadId,
    discussionboard_member_id: member.id,
    discussionboard_board_id: boardId,
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()(1)(1),
  };
  const post = await api.functional.discussionboard.posts.create(connection, { body: postInput });
  typia.assert(post);

  // 3. Initial upvote
  const initialVoteInput: Idiscussionboard_post_votes.ICreate = {
    discussionboard_post_id: post.id,
    discussionboard_member_id: member.id,
    vote_type: 1,
    created_at: new Date().toISOString(),
  };
  const initialVote = await api.functional.discussionboard.postVotes.create(connection, { body: initialVoteInput });
  typia.assert(initialVote);

  // 4. Update to downvote
  const updateVoteInput: Idiscussionboard_post_votes.IUpdate = {
    discussionboard_post_id: post.id,
    discussionboard_member_id: member.id,
    vote_type: -1,
    created_at: initialVote.created_at, // preserve original timestamp for idempotency
  };
  const updatedVote = await api.functional.discussionboard.postVotes.update(connection, {
    id: initialVote.id,
    body: updateVoteInput
  });
  typia.assert(updatedVote);
  TestValidator.equals("id")(updatedVote.id)(initialVote.id);
  TestValidator.equals("vote_type")(updatedVote.vote_type)(-1);
  TestValidator.equals("discussionboard_post_id")(updatedVote.discussionboard_post_id)(post.id);
  TestValidator.equals("discussionboard_member_id")(updatedVote.discussionboard_member_id)(member.id);
  TestValidator.equals("created_at")(updatedVote.created_at)(initialVote.created_at);

  // 5. Ensure only one vote per (member, post) by repeating update does not create duplicates
  const repeatUpdate = await api.functional.discussionboard.postVotes.update(connection, {
    id: initialVote.id,
    body: updateVoteInput
  });
  typia.assert(repeatUpdate);
  TestValidator.equals("idempotent update vote_type")(repeatUpdate.vote_type)(-1);
  TestValidator.equals("idempotent unique vote per user/post")(repeatUpdate.id)(initialVote.id);
}

