import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBan";
import type { IPageIDiscussionboardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardBan";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 테스트 목적: 어드민 또는 모더레이터가 ban 목록을 다양한 필터와 페이징 조건으로 가져올 수 있음을 검증
 *
 * 1. 테스트용 회원 여러 명(admin, moderator, 일반 멤버) 생성
 * 2. ban type, acting_moderator_id, banned_member_id, report_id, reason, banned_at, expires_at가 서로 다르게 조합된 밴 레코드 4개 이상 생성
 * 3. 필터 없이 전체 요청 시 모든 ban 레코드가 페이지네이션과 함께 반환되는지 검증
 * 4. acting_moderator_id로 필터링(각 모더레이터별로 한 개 이상 생성) → 제대로 필터됨을 확인
 * 5. banned_member_id로 필터링 → 해당 멤버가 ban된 항목만 조회되는지 확인
 * 6. ban_type으로 필터 후 확인(temporary, permanent 등)
 * 7. reason substring 필터 사용 시 올바른 ban만 나오는지 확인
 * 8. report_id값을 기준으로 필터 시 정확한 항목만 반환되는지 확인
 * 9. banned_at, expires_at 활용(페이징/범위조건 포함)
 * 10. 없는 banned_member_id, ban_type 등으로 조회 시 데이터 없음 확인
 * 11. 페이지, limit 옵션 다양하게 조합 → 페이징 내역 및 데이터 개수 확인
 */
export async function test_api_discussionboard_test_list_bans_with_various_filters_and_pagination(connection: api.IConnection) {
  // 1. 여러 회원 생성 (어드민, 모더레이터, 멤버)
  const admin = await api.functional.discussionboard.members.create(connection, { body: { username: RandomGenerator.alphaNumeric(8), email: typia.random<string & tags.Format<"email">>(), hashed_password: RandomGenerator.alphaNumeric(12), role: "admin", is_active: true } });
  const moderator = await api.functional.discussionboard.members.create(connection, { body: { username: RandomGenerator.alphaNumeric(8), email: typia.random<string & tags.Format<"email">>(), hashed_password: RandomGenerator.alphaNumeric(12), role: "moderator", is_active: true } });
  const member1 = await api.functional.discussionboard.members.create(connection, { body: { username: RandomGenerator.alphaNumeric(8), email: typia.random<string & tags.Format<"email">>(), hashed_password: RandomGenerator.alphaNumeric(12), role: "member", is_active: true } });
  const member2 = await api.functional.discussionboard.members.create(connection, { body: { username: RandomGenerator.alphaNumeric(8), email: typia.random<string & tags.Format<"email">>(), hashed_password: RandomGenerator.alphaNumeric(12), role: "member", is_active: true } });

  // 2. report_id, banned_at, expires_at 등 조합 달리해 밴 생성
  const now = new Date();
  const ban1 = await api.functional.discussionboard.bans.create(connection, { body: { banned_member_id: member1.id, acting_moderator_id: moderator.id, report_id: null, reason: "spam", ban_type: "temporary", banned_at: new Date(now.getTime() - 800000).toISOString(), expires_at: new Date(now.getTime() + 20000).toISOString() } });
  const ban2 = await api.functional.discussionboard.bans.create(connection, { body: { banned_member_id: member2.id, acting_moderator_id: admin.id, report_id: typia.random<string & tags.Format<"uuid">>(), reason: "abuse report", ban_type: "permanent", banned_at: new Date(now.getTime() - 600000).toISOString(), expires_at: null } });
  const ban3 = await api.functional.discussionboard.bans.create(connection, { body: { banned_member_id: member1.id, acting_moderator_id: moderator.id, report_id: null, reason: "foul language", ban_type: "temporary", banned_at: new Date(now.getTime() - 400000).toISOString(), expires_at: new Date(now.getTime() + 600000).toISOString() } });
  const ban4 = await api.functional.discussionboard.bans.create(connection, { body: { banned_member_id: member2.id, acting_moderator_id: moderator.id, report_id: null, reason: "other case", ban_type: "temporary", banned_at: new Date(now.getTime() - 200000).toISOString(), expires_at: null } });

  // 3. 전체조회(페이징X), ban 모두 반환 확인
  const allBans = await api.functional.discussionboard.bans.index(connection, { body: {} });
  typia.assert(allBans);
  TestValidator.predicate("all bans present")(allBans.data.length >= 4);

  // 4. acting_moderator_id 필터링
  const filterByModerator = await api.functional.discussionboard.bans.index(connection, { body: { acting_moderator_id: moderator.id } });
  TestValidator.predicate("filtered by moderator")(filterByModerator.data.every(ban => ban.acting_moderator_id === moderator.id));

  // 5. banned_member_id 필터링
  const filterByMember1 = await api.functional.discussionboard.bans.index(connection, { body: { banned_member_id: member1.id } });
  TestValidator.predicate("filtered by member1")(filterByMember1.data.every(ban => ban.banned_member_id === member1.id));

  // 6. ban_type 필터링(temporary)
  const filterByTypeTemp = await api.functional.discussionboard.bans.index(connection, { body: { ban_type: "temporary" } });
  TestValidator.predicate("filtered by type temporary")(filterByTypeTemp.data.every(ban => ban.ban_type === "temporary"));

  // 7. reason substring(예: 'spam' 문자열 포함)
  const filterByReason = await api.functional.discussionboard.bans.index(connection, { body: { reason: "spam" } });
  TestValidator.predicate("reason contains")(filterByReason.data.every(ban => ban.reason.includes("spam")));

  // 8. report_id 기준 (ban2)
  const filterByReport = await api.functional.discussionboard.bans.index(connection, { body: { report_id: ban2.report_id } });
  TestValidator.predicate("filtered by report_id")(filterByReport.data.every(ban => ban.report_id === ban2.report_id));

  // 9. banned_at, expires_at 범위검색(미래 만료)
  const filterByExpireFuture = await api.functional.discussionboard.bans.index(connection, { body: { expires_at: new Date(now.getTime() + 100000).toISOString() } });
  TestValidator.predicate("expires_at filter include banned")(filterByExpireFuture.data.some(ban => ban.expires_at && new Date(ban.expires_at) >= new Date(now.getTime() + 100000)));

  // 10. 조회 결과 없음: 존재하지 않는 member/ban_type
  const filterByNoneMember = await api.functional.discussionboard.bans.index(connection, { body: { banned_member_id: typia.random<string & tags.Format<"uuid">>() } });
  TestValidator.equals("none for random banned_member_id")(filterByNoneMember.data.length)(0);
  const filterByNoneType = await api.functional.discussionboard.bans.index(connection, { body: { ban_type: "nonexistent_type" } });
  TestValidator.equals("none for nonexistent type")(filterByNoneType.data.length)(0);

  // 11. 페이징 조합(page/limit)
  const firstPage = await api.functional.discussionboard.bans.index(connection, { body: { page: 1, limit: 2 } });
  TestValidator.equals("paging first page count")(firstPage.data.length)(Math.min(2, allBans.data.length));
  const secondPage = await api.functional.discussionboard.bans.index(connection, { body: { page: 2, limit: 2 } });
  TestValidator.equals("paging second page count")(secondPage.data.length)(Math.max(0, allBans.data.length - 2));
}

