import type { IDiscussionboardCommentSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentSnapshot";

/**
 * Test updating a comment snapshot record by its id with a valid payload, and ensure changes are reflected.
 * Checks that full replacement (PUT) works as expected for valid update data.
 * Negative test: Tries with an invalid id (malformed and non-existent) expecting errors.
 * Negative test: Tries with constraint-violating data (e.g., empty body, invalid date/time formats, etc.).
 * Negative test: (If applicable) Attempts to update forbidden fields and checks for proper error responses.
 *
 * Steps:
 * 1. Create a discussionboard member (for authoring and updating).
 * 2. Create a comment with that member.
 * 3. Create a comment snapshot for that comment/member.
 * 4. Update the snapshot via PUT with a valid edit, then verify the update.
 * 5. Attempt to update with an invalid id (e.g., malformed UUID, non-existent id), verify error responses.
 * 6. Attempt to update with constraint-violating IUpdate payload (e.g., empty string body, negative version number, malformed date), verify error responses.
 * 7. (If possible) Attempt to update forbidden/immutable fields (should fail or be ignored as per business rule).
 */
export async function test_api_discussionboard_test_update_comment_snapshot_with_valid_and_invalid_payloads(connection: api.IConnection) {
  // 1. Create a discussionboard member for authorship
  const memberEmail = typia.random<string & tags.Format<'email'>>();
  const member: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: memberEmail,
      hashed_password: RandomGenerator.alphaNumeric(20),
      role: 'member',
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate
  });
  typia.assert(member);

  // 2. Create a comment authored by the member
  const comment: IComment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: typia.random<string & tags.Format<'uuid'>>(),
      discussionboard_member_id: member.id,
      body: RandomGenerator.paragraph()(3),
    } satisfies IComment.ICreate
  });
  typia.assert(comment);

  // 3. Create a comment snapshot for the comment
  const origSnapshot: IDiscussionboardCommentSnapshot = await api.functional.discussionboard.commentSnapshots.create(connection, {
    body: {
      discussionboard_comment_id: comment.id,
      discussionboard_member_id: member.id,
      discussionboard_post_id: comment.discussionboard_post_id,
      body: comment.body,
      version: 1,
      snapshot_created_at: new Date().toISOString(),
    } satisfies IDiscussionboardCommentSnapshot.ICreate
  });
  typia.assert(origSnapshot);

  // 4. Update the snapshot (valid case)
  const newBody = RandomGenerator.paragraph()(2);
  const newVersion = origSnapshot.version + 1;
  const newSnapshotCreatedAt = new Date(Date.now() + 60000).toISOString();
  const updatedSnapshot = await api.functional.discussionboard.commentSnapshots.update(connection, {
    id: origSnapshot.id,
    body: {
      body: newBody,
      version: newVersion,
      snapshot_created_at: newSnapshotCreatedAt,
    } satisfies IDiscussionboardCommentSnapshot.IUpdate
  });
  typia.assert(updatedSnapshot);
  TestValidator.equals('body updated')(updatedSnapshot.body)(newBody);
  TestValidator.equals('version incremented')(updatedSnapshot.version)(newVersion);
  TestValidator.equals('snapshot_created_at updated')(updatedSnapshot.snapshot_created_at)(newSnapshotCreatedAt);

  // 5. Attempt to update with invalid id (malformed UUID)
  await TestValidator.error('malformed id should error')(async () => {
    await api.functional.discussionboard.commentSnapshots.update(connection, {
      id: 'invalid-uuid' as any,
      body: { body: RandomGenerator.paragraph()(1), version: 21, snapshot_created_at: new Date().toISOString() },
    });
  });

  // 6. Attempt to update with non-existent id (synthetically valid UUID that doesn't exist)
  await TestValidator.error('non-existent id should error')(async () => {
    await api.functional.discussionboard.commentSnapshots.update(connection, {
      id: typia.random<string & tags.Format<'uuid'>>(),
      body: { body: RandomGenerator.paragraph()(1), version: 22, snapshot_created_at: new Date().toISOString() },
    });
  });

  // 7. Attempt to update with invalid (constraint-violating) payloads
  // 7-1. Empty body
  await TestValidator.error('empty body should error')(async () => {
    await api.functional.discussionboard.commentSnapshots.update(connection, {
      id: origSnapshot.id,
      body: { body: '', version: 3, snapshot_created_at: new Date().toISOString() },
    });
  });

  // 7-2. Negative version
  await TestValidator.error('negative version should error')(async () => {
    await api.functional.discussionboard.commentSnapshots.update(connection, {
      id: origSnapshot.id,
      body: { body: RandomGenerator.paragraph()(1), version: -1 as any, snapshot_created_at: new Date().toISOString() },
    });
  });

  // 7-3. Malformed date
  await TestValidator.error('malformed snapshot_created_at should error')(async () => {
    await api.functional.discussionboard.commentSnapshots.update(connection, {
      id: origSnapshot.id,
      body: { body: RandomGenerator.paragraph()(1), version: 4, snapshot_created_at: 'not-a-date' as any },
    });
  });
}

