 * 1. Create a comment as a base entity (using a valid random post & member UUID).
 * 2. Create a comment snapshot for that comment with explicit version/body/text/timestamps.
 * 3. GET the snapshot by its id using api.functional.discussionboard.commentSnapshots.at and assert response matches creation.
 * 4. GET with a random valid UUID not attached to any snapshot – expect error.
 * 5. GET with an invalid UUID string (malformed) – expect error.
 */
export async function test_api_discussionboard_test_get_comment_snapshot_by_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. Prepare and create a comment as base entity
  const postId = typia.random<string & tags.Format<"uuid">>();
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const commentBody = "Comment body for snapshot test " + RandomGenerator.alphaNumeric(8);

  const comment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: postId,
      discussionboard_member_id: memberId,
      body: commentBody,
    }
  });
  typia.assert(comment);

  // 2. Create a comment snapshot for the comment
  const snapshotInput: IDiscussionboardCommentSnapshot.ICreate = {
    discussionboard_comment_id: comment.id,
    discussionboard_member_id: comment.discussionboard_member_id,
    discussionboard_post_id: comment.discussionboard_post_id,
    body: comment.body,
    version: 1,
    snapshot_created_at: new Date().toISOString(),
  };

  const snapshot = await api.functional.discussionboard.commentSnapshots.create(connection, { body: snapshotInput });
  typia.assert(snapshot);

  // 3. GET snapshot by its id, assert all fields match
  const fetchedSnapshot = await api.functional.discussionboard.commentSnapshots.at(connection, { id: snapshot.id });
  typia.assert(fetchedSnapshot);
  TestValidator.equals("snapshot id matches")(fetchedSnapshot.id)(snapshot.id);
  TestValidator.equals("comment id matches")(fetchedSnapshot.discussionboard_comment_id)(snapshotInput.discussionboard_comment_id);
  TestValidator.equals("member id matches")(fetchedSnapshot.discussionboard_member_id)(snapshotInput.discussionboard_member_id);
  TestValidator.equals("post id matches")(fetchedSnapshot.discussionboard_post_id)(snapshotInput.discussionboard_post_id);
  TestValidator.equals("body matches")(fetchedSnapshot.body)(snapshotInput.body);
  TestValidator.equals("version matches")(fetchedSnapshot.version)(snapshotInput.version);
  TestValidator.equals("snapshot_created_at matches")(fetchedSnapshot.snapshot_created_at)(snapshotInput.snapshot_created_at);

  // 4. Negative case: random valid UUID not found
  const randomUuid = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("not-found for non-existent snapshot")(() =>
    api.functional.discussionboard.commentSnapshots.at(connection, { id: randomUuid })
  );

  // 5. Negative case: invalid UUID format
  TestValidator.error("validation error for malformed UUID")(() =>
    api.functional.discussionboard.commentSnapshots.at(connection, { id: "not-a-uuid" as any })
  );
}

