import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { Idiscussionboard_post_reports } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_post_reports";
import type { Idiscussionboard_report_types } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_report_types";

/**
 * Validate the creation of a new discussion board post report, covering both valid and invalid scenarios.
 *
 * This test ensures the /discussionboard/postReports endpoint correctly handles report creation for abusive content, and enforces all schema-level validation and referential integrity (FK) rules.
 *
 * Steps:
 * 1. Create a report type to use for reporting (e.g., 'abuse').
 * 2. Create a discussion member who will act as the reporter.
 * 3. Create a discussion post to be reported (and associated thread/board FKs).
 * 4. Use the returned entities' IDs to build a valid post report request (all required fields present: discussionboard_post_id, reporter_member_id, report_type_id, description (optional), and created_at).
 * 5. Call the postReports.create API, validating a successful creation and that all returned fields match the schema and request values (except system-generated report id).
 * 6. Attempt to create a report with missing required fields (e.g., omit report_type_id or created_at), and assert that validation errors occur.
 * 7. Attempt to create a report referencing non-existent FK ids for post, reporter, or report type, and assert that FK errors or validation failures occur.
 * 8. Confirm that no extraneous properties are accepted and that error responses are as expected (error message inspection is skipped per requirements).
 */
export async function test_api_discussionboard_test_create_post_report_with_valid_and_invalid_data(connection: api.IConnection) {
  // Step 1: Create report type
  const reportType = await api.functional.discussionboard.reportTypes.create(connection, {
    body: {
      code: RandomGenerator.alphabets(6),
      display_name: "Abuse",
      description: "Abusive content",
      active: true
    } satisfies Idiscussionboard_report_types.ICreate,
  });
  typia.assert(reportType);

  // Step 2: Create discussion member (reporter)
  const password = RandomGenerator.alphaNumeric(12);
  const reporter = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.name(),
      email: typia.random<string & tags.Format<'email'>>(),
      hashed_password: password,
      role: "member",
      is_active: true
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(reporter);

  // Step 3: Create discussion post (with dummy thread and board IDs)
  const discussionboard_thread_id = typia.random<string & tags.Format<'uuid'>>();
  const discussionboard_board_id = typia.random<string & tags.Format<'uuid'>>();
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id,
      discussionboard_member_id: reporter.id,
      discussionboard_board_id,
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()()(30)
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // Step 4: Create VALID post report (all required fields populated)
  const created_at = new Date().toISOString();
  const description = "Abusive post example.";
  const report = await api.functional.discussionboard.postReports.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      reporter_member_id: reporter.id,
      report_type_id: reportType.id,
      description,
      created_at
    } satisfies Idiscussionboard_post_reports.ICreate,
  });
  typia.assert(report);
  TestValidator.equals("reported post id")(report.discussionboard_post_id)(post.id);
  TestValidator.equals("reporter id")(report.reporter_member_id)(reporter.id);
  TestValidator.equals("report type id")(report.report_type_id)(reportType.id);
  TestValidator.equals("description")(report.description)(description);
  TestValidator.equals("created_at")(report.created_at)(created_at);
  TestValidator.predicate("report id exists")(typeof report.id === "string" && report.id.length > 0);

  // Step 5: ERROR CASE - Missing required field (e.g., missing report_type_id)
  await TestValidator.error("Missing required field report_type_id")(() =>
    api.functional.discussionboard.postReports.create(connection, {
      body: {
        discussionboard_post_id: post.id,
        reporter_member_id: reporter.id,
        // report_type_id intentionally omitted
        description: null,
        created_at
        // satisfies Idiscussionboard_post_reports.ICreate is not possible here (would fail compile), skip explicit typing
      } as any,
    })
  );

  // Step 6: ERROR CASE - Invalid FK for post, reporter, and report_type
  const randomUUID = () => typia.random<string & tags.Format<'uuid'>>();
  // Invalid post id
  await TestValidator.error("Nonexistent post id")(() =>
    api.functional.discussionboard.postReports.create(connection, {
      body: {
        discussionboard_post_id: randomUUID(),
        reporter_member_id: reporter.id,
        report_type_id: reportType.id,
        description,
        created_at
      } satisfies Idiscussionboard_post_reports.ICreate,
    })
  );
  // Invalid reporter id
  await TestValidator.error("Nonexistent reporter id")(() =>
    api.functional.discussionboard.postReports.create(connection, {
      body: {
        discussionboard_post_id: post.id,
        reporter_member_id: randomUUID(),
        report_type_id: reportType.id,
        description,
        created_at
      } satisfies Idiscussionboard_post_reports.ICreate,
    })
  );
  // Invalid report type id
  await TestValidator.error("Nonexistent report type id")(() =>
    api.functional.discussionboard.postReports.create(connection, {
      body: {
        discussionboard_post_id: post.id,
        reporter_member_id: reporter.id,
        report_type_id: randomUUID(),
        description,
        created_at
      } satisfies Idiscussionboard_post_reports.ICreate,
    })
  );
}

