import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardActivityLog";
import type { IPageIDiscussionboardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardActivityLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for paginated and filtered retrieval of activity logs in discussion board.
 *
 * This test verifies correct filtering by event type, member, date range, and related entities (board, thread, post, comment).
 * Confirms paged results reflect accurate metadata. Also checks schema-restricted filtering and proper error handling for invalid filters.
 *
 * Steps:
 * 1. Query activity logs without filters (default pagination, expect success).
 * 2. Query with event_type filter (e.g., 'post_create'), check all records match.
 * 3. Query with member, board, thread, post, comment filters; verify entity association in all results.
 * 4. Query events within a time range (from/to); validate timestamps within bounds.
 * 5. Query with multiple filters combined (e.g., event_type + board + thread).
 * 6. Test pagination with custom limit/page values; confirm metadata (current/limit/records/pages) and result slicing.
 * 7. Attempt filter with unauthorized or non-schema fields and expect graceful rejection (error/validation).
 * 8. Attempt invalid filter values (malformed uuid, invalid date); expect error/validation failure.
 */
export async function test_api_discussionboard_test_list_activity_logs_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Query logs without filters (default page/limit)
  const res1 = await api.functional.discussionboard.activityLogs.index(connection, {
    body: {},
  });
  typia.assert(res1);
  // Validate pagination meta and data array exists
  TestValidator.predicate('default page has valid pagination')(!!res1.pagination && Array.isArray(res1.data));

  // If no records, skip further tests (no logs to filter)
  if (!res1.data.length) return;
  // Pick sample log for filter cases
  const ref = res1.data[0];

  // 2. Filter by event_type
  if (ref.event_type) {
    const res2 = await api.functional.discussionboard.activityLogs.index(connection, {
      body: { event_type: ref.event_type },
    });
    typia.assert(res2);
    TestValidator.predicate('all logs have event_type')(res2.data.every(l => l.event_type === ref.event_type));
  }

  // 3. Filter by member, board, thread, post, comment (pick fields that are not null)
  const filterCases = [
    ['discussionboard_member_id', ref.discussionboard_member_id],
    ['discussionboard_board_id', ref.discussionboard_board_id],
    ['discussionboard_thread_id', ref.discussionboard_thread_id],
    ['discussionboard_post_id', ref.discussionboard_post_id],
    ['discussionboard_comment_id', ref.discussionboard_comment_id],
  ].filter(([_, v]) => !!v);
  for (const [key, value] of filterCases) {
    const body: any = { [key]: value };
    const res = await api.functional.discussionboard.activityLogs.index(connection, { body });
    typia.assert(res);
    TestValidator.predicate(`${key} filter matches`)(res.data.every(l => l[key] === value));
  }

  // 4. Filter by time range
  const ts = ref.event_timestamp;
  const from = new Date(new Date(ts).getTime() - 1000).toISOString();
  const to = new Date(new Date(ts).getTime() + 1000).toISOString();
  const res4 = await api.functional.discussionboard.activityLogs.index(connection, {
    body: { event_timestamp_from: from, event_timestamp_to: to },
  });
  typia.assert(res4);
  TestValidator.predicate('timestamp in range')(
    res4.data.every((l) =>
      new Date(l.event_timestamp) >= new Date(from) && new Date(l.event_timestamp) <= new Date(to)
    ),
  );

  // 5. Multiple filters simultaneously
  const multiBody: any = { event_type: ref.event_type };
  filterCases.forEach(([k, v]) => (multiBody[k] = v));
  const res5 = await api.functional.discussionboard.activityLogs.index(connection, {
    body: multiBody,
  });
  typia.assert(res5);
  for (const [k, v] of Object.entries(multiBody)) {
    if (k === 'event_type') {
      TestValidator.predicate(`${k} filter matches`)(res5.data.every(l => l[k] === v));
    } else {
      TestValidator.predicate(`${k} filter matches`)(res5.data.every(l => !v || l[k] === v));
    }
  }

  // 6. Pagination (limit/page)
  const res6a = await api.functional.discussionboard.activityLogs.index(connection, {
    body: { limit: 1, page: 1 },
  });
  typia.assert(res6a);
  TestValidator.equals('pagination.limit')(res6a.pagination.limit)(1);
  TestValidator.equals('pagination.current')(res6a.pagination.current)(1);
  TestValidator.equals('single record page')(res6a.data.length)(Math.min(1, res1.data.length));

  // If >1 record, fetch page 2
  if (res1.data.length > 1) {
    const res6b = await api.functional.discussionboard.activityLogs.index(connection, {
      body: { limit: 1, page: 2 },
    });
    typia.assert(res6b);
    TestValidator.equals('pagination.current')(res6b.pagination.current)(2);
    // Prevent overlap with page 1
    if (res6b.data.length && res6a.data.length) {
      TestValidator.notEquals('page 1/2 first record different')(res6a.data[0].id)(res6b.data[0].id);
    }
  }

  // 7. Reject non-schema/unauthorized filter fields
  await TestValidator.error('unknown field rejected')(async () => {
    // @ts-expect-error
    await api.functional.discussionboard.activityLogs.index(connection, {
      body: { unknown_field: 'x' },
    });
  });

  // 8. Invalid filter parameter types
  await TestValidator.error('invalid uuid rejected')(async () => {
    await api.functional.discussionboard.activityLogs.index(connection, {
      body: { discussionboard_board_id: 'not-an-uuid' },
    });
  });
  await TestValidator.error('invalid date rejected')(async () => {
    await api.functional.discussionboard.activityLogs.index(connection, {
      body: { event_timestamp_from: 'no-date-format' },
    });
  });
}

