 *   - Several dates (date1, date2, date3) within different weeks
 *   - Some records with both member and board null
 * 2. Filter by a specific member and verify only that member's metrics come back (all boards, all dates)
 * 3. Filter by a specific board and verify only that board's metrics come back (all members, all dates)
 * 4. Filter by date range and verify only records in that range are returned
 * 5. Filter by member+board for a case with no records, assert empty results
 * 6. Paginate results for large datasets, validate correct current/limit/pages metadata and data paging (split results by limit)
 * 7. Filter for records with null member and/or null board and assert those are returned correctly
 */
export async function test_api_discussionboard_test_list_engagement_metrics_with_various_filters_and_pagination(connection: api.IConnection) {
  // 1. Create diverse metric records
  // - 2 members, 2 boards, 3 dates, plus 'global' (null member or board)
  const memberA = typia.random<string & tags.Format<"uuid">>();
  const memberB = typia.random<string & tags.Format<"uuid">>();
  const boardX = typia.random<string & tags.Format<"uuid">>();
  const boardY = typia.random<string & tags.Format<"uuid">>();
  const date1 = new Date("2023-07-20T00:00:00Z").toISOString();
  const date2 = new Date("2023-07-21T00:00:00Z").toISOString();
  const date3 = new Date("2023-07-22T00:00:00Z").toISOString();
  // (member, board, date) all combinations (excluding all-null)
  const recordParams: {m?: string|null, b?: string|null, d:string}[] = [
    { m: memberA, b: boardX, d: date1 }, { m: memberA, b: boardX, d: date2 },
    { m: memberA, b: boardY, d: date1 }, { m: memberA, b: boardY, d: date2 },
    { m: memberB, b: boardX, d: date2 }, { m: memberB, b: boardX, d: date3 },
    { m: memberB, b: boardY, d: date3 },
    { m: null,     b: boardX, d: date1 }, // null member
    { m: memberB, b: null,   d: date3 }, // null board
    { m: null,     b: null,   d: date2 }, // both null
  ];
  const createdMetrics = await ArrayUtil.asyncMap(recordParams)(async (r, i) => {
    const createInput = {
      discussionboard_member_id: r.m ?? null,
      discussionboard_board_id: r.b ?? null,
      engagement_date: r.d,
      posts_created_count:  10 + i,
      comments_created_count: 20 + i,
      votes_cast_count: 30 + i,
    } satisfies IDiscussionboardEngagementMetric.ICreate;
    const result = await api.functional.discussionboard.engagementMetrics.create(connection, { body: createInput });
    typia.assert(result);
    return result;
  });

  // 2. Filter by memberA: get all records where memberA (any board, any date)
  const byMemberA = await api.functional.discussionboard.engagementMetrics.index(connection, {
    body: { discussionboard_member_id: memberA } satisfies IDiscussionboardEngagementMetric.IRequest,
  });
  typia.assert(byMemberA);
  TestValidator.predicate("only records with memberA")(
    byMemberA.data.every(r => r.discussionboard_member_id === memberA)
  );

  // 3. Filter by boardY: get all records where boardY (any member, any date)
  const byBoardY = await api.functional.discussionboard.engagementMetrics.index(connection, {
    body: { discussionboard_board_id: boardY } satisfies IDiscussionboardEngagementMetric.IRequest,
  });
  typia.assert(byBoardY);
  TestValidator.predicate("only records with boardY")(
    byBoardY.data.every(r => r.discussionboard_board_id === boardY)
  );

  // 4. Filter by date range: date2 ~ date3
  const byDate = await api.functional.discussionboard.engagementMetrics.index(connection, {
    body: { date_from: date2, date_to: date3 } satisfies IDiscussionboardEngagementMetric.IRequest,
  });
  typia.assert(byDate);
  TestValidator.predicate("all records in date2 to date3")(
    byDate.data.every(r => [date2, date3].includes(r.engagement_date))
  );

  // 5. Filter for non-existent member+board (should return empty set)
  const byBogusCombo = await api.functional.discussionboard.engagementMetrics.index(connection, {
    body: { discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(), discussionboard_board_id: typia.random<string & tags.Format<"uuid">>() } satisfies IDiscussionboardEngagementMetric.IRequest,
  });
  typia.assert(byBogusCombo);
  TestValidator.equals("no such records")(byBogusCombo.data.length)(0);

  // 6. Pagination test: limit=4, page=1,2,3
  const allInDate1 = createdMetrics.filter(r => r.engagement_date === date1);
  const byPage1 = await api.functional.discussionboard.engagementMetrics.index(connection, {
    body: { date_from: date1, date_to: date1, limit: 4, page: 1 } satisfies IDiscussionboardEngagementMetric.IRequest,
  });
  typia.assert(byPage1);
  TestValidator.equals("pagination: first page count")(byPage1.data.length)(Math.min(4, allInDate1.length));
  TestValidator.equals("pagination: metadata current page")(byPage1.pagination.current)(1);
  // Get page 2 if enough records
  if (allInDate1.length > 4) {
    const byPage2 = await api.functional.discussionboard.engagementMetrics.index(connection, {
      body: { date_from: date1, date_to: date1, limit: 4, page: 2 } satisfies IDiscussionboardEngagementMetric.IRequest,
    });
    typia.assert(byPage2);
    TestValidator.equals("pagination: second page count")(byPage2.data.length)(Math.max(0, allInDate1.length - 4));
    TestValidator.equals("pagination: metadata current page")(byPage2.pagination.current)(2);
  }

  // 7. Filter for records with null member/board
  const byNullMember = await api.functional.discussionboard.engagementMetrics.index(connection, {
    body: { discussionboard_member_id: null } satisfies IDiscussionboardEngagementMetric.IRequest
  });
  typia.assert(byNullMember);
  TestValidator.predicate("records where member is null")(
    byNullMember.data.every(r => r.discussionboard_member_id === null)
  );

  const byNullBoard = await api.functional.discussionboard.engagementMetrics.index(connection, {
    body: { discussionboard_board_id: null } satisfies IDiscussionboardEngagementMetric.IRequest
  });
  typia.assert(byNullBoard);
  TestValidator.predicate("records where board is null")(
    byNullBoard.data.every(r => r.discussionboard_board_id === null)
  );

  // Also combination of null member and board
  const byNullBoth = await api.functional.discussionboard.engagementMetrics.index(connection, {
    body: { discussionboard_member_id: null, discussionboard_board_id: null } satisfies IDiscussionboardEngagementMetric.IRequest
  });
  typia.assert(byNullBoth);
  TestValidator.predicate("records where both member and board are null")(
    byNullBoth.data.every(r => r.discussionboard_member_id === null && r.discussionboard_board_id === null)
  );
}

