import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IMemberPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberPreference";
import type { IPageIMemberPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIMemberPreference";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E 테스트: 멤버 환경설정 리스트 조회 (다양한 필터와 페이지네이션)
 *
 * - 여러 개의 discussionboard 멤버 계정을 만든다.
 * - 각 멤버마다 다양한 조합(이메일/푸시/언어/다크모드)으로 환경설정(Preferences) 레코드를 생성한다.
 * - Preferences 목록 조회 API(discussionboard/memberPreferences.index)에 대해 아래 케이스를 각각 검증한다.
 *   1. 아무 필터 없는 전체 조회 (모든 Preference 반환)
 *   2. receive_email_notifications=true/false 별 필터
 *   3. receive_push_notifications=true/false 별 필터
 *   4. preferred_language 값별 (en/ko/ja 등) 필터
 *   5. dark_mode_enabled=true/false 별 필터
 *   6. 페이지네이션(page/limit) 활용 - 전체 레코드의 2개 단위씩 2페이지
