 * - 각 필터에 대해 반환되는 데이터가 조건과 정확히 일치하는지 검증한다.
 * - 반환 결과에 hashed_password 등 노출 금지 필드가 포함되어 있지 않은지 확인한다.
 * - 존재하지 않는 역할 값, 범위를 벗어난 페이지 요청 등 엣지 케이스도 검증한다.
 */
export async function test_api_discussionboard_members_test_list_members_with_pagination_and_filtering(
  connection: api.IConnection,
) {
  // 1. 테스트용 멤버 데이터셋 준비
  const roles = ["member", "moderator", "admin"];
  const actives = [true, false];
  const createdMembers: IDiscussionboardMember[] = [];
  const memberCountPerRole = 3;

  // 임의의 과거와 현재 시간값(�~현재)을 만들기 위한 기준
  const now = new Date();
  const daysAgo = (days: number) => {
    const date = new Date(now.getTime() - days * 24 * 60 * 60 * 1000);
    return date.toISOString();
  };

  // 다양한 조건 조합으로 회원 사전등록
  for (const role of roles)
    for (const is_active of actives)
      for (let i = 0; i < memberCountPerRole; ++i) {
        // 서로 다른 시간에 가입한 것처럼 임의로 created_at 조정
        const days = i * 5 + (is_active ? 0 : 2);
        const member: IDiscussionboardMember = await api.functional.discussionboard.members.create(
          connection,
          {
            body: {
              username: `${role}_${is_active ? "active" : "inactive"}_${i}`,
              email: `${role}_${is_active ? "active" : "inactive"}_${i}_${typia.random<string & tags.Format<"email">>()}`,
              hashed_password: typia.random<string>(),
              role,
              is_active,
            } satisfies IDiscussionboardMember.ICreate,
          },
        );
        typia.assert(member);
        createdMembers.push(member);
      }

  // 전체 회원 수: roles * actives * memberCountPerRole
  const totalMembers = roles.length * actives.length * memberCountPerRole;

  // 2. 필터 없이 전체 조회: 전체 회원이 노출되고 페이지네이션도 동작하는지 확인
  {
    const output = await api.functional.discussionboard.members.index(connection, {
      body: { page: 1, limit: totalMembers } satisfies IDiscussionboardMember.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("전체 회원 수")(output.data.length)(totalMembers);
    // 각 멤버에 비공개 필드 노출 없음/ 검증
    for (const member of output.data) {
      if ("hashed_password" in member)
        throw new Error("hashed_password 필드는 목록에 노출되면 안 됩니다");
    }
  }

  // 3. 역할별 조회(modorator) 필터: moderator만 반환되는지
  {
    const role = "moderator";
    const expected = createdMembers.filter((m) => m.role === role);
    const output = await api.functional.discussionboard.members.index(connection, {
      body: { role } satisfies IDiscussionboardMember.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("moderator 필터 회원 수")(
      output.data.length
    )(expected.length);
    for (const member of output.data) {
      if (member.role !== role)
        throw new Error("role 필터 무시됨");
      if ("hashed_password" in member)
        throw new Error("hashed_password 노출 금지 위반");
    }
  }

  // 4. 활성/비활성별 조회(is_active = false): 비활성 회원만 반환
  {
    const expected = createdMembers.filter((m) => m.is_active === false);
    const output = await api.functional.discussionboard.members.index(connection, {
      body: { is_active: false } satisfies IDiscussionboardMember.IRequest,
    });
    typia.assert(output);
    TestValidator.equals("비활성 회원 수")(output.data.length)(expected.length);
    for (const member of output.data) {
      if (member.is_active !== false)
        throw new Error("is_active 필터 무시됨");
      if ("hashed_password" in member)
        throw new Error("hashed_password 노출 금지 위반");
    }
  }

  // 5. 페이지네이션 동작 확인(페이지 크기 4, 여러 페이지)
  {
    const perPage = 4;
    const page1 = await api.functional.discussionboard.members.index(connection, {
      body: { page: 1, limit: perPage } satisfies IDiscussionboardMember.IRequest,
    });
    typia.assert(page1);
    TestValidator.equals("1페이지 노출 회원 수")(
      page1.data.length
    )(perPage);
    TestValidator.equals("총 회원 수 (pagination.records)")(
      page1.pagination.records
    )(totalMembers);
    for (const member of page1.data) {
      if ("hashed_password" in member)
        throw new Error("hashed_password 노출 금지 위반");
    }

    const page2 = await api.functional.discussionboard.members.index(connection, {
      body: { page: 2, limit: perPage } satisfies IDiscussionboardMember.IRequest,
    });
    typia.assert(page2);
    // 2페이지 역시 perPage 개수 또는 그 이하
    TestValidator.equals("2페이지 회원 수")(
      page2.data.length
    )(
      totalMembers > perPage * 2
        ? perPage
        : Math.max(0, totalMembers - perPage)
    );
    for (const member of page2.data) {
      if ("hashed_password" in member)
        throw new Error("hashed_password 노출 금지 위반");
    }
  }

  // 6. 가입일 기간 검색(created_at_from, created_at_to)
  {
    // 7일 전~2일 전 가입자만 필터
    const from = daysAgo(7);
    const to = daysAgo(2);
    // 입력된 값으로 직접 필터링
    const expected = createdMembers.filter(
      (m) => m.created_at >= from && m.created_at <= to,
    );

    const output = await api.functional.discussionboard.members.index(
      connection,
      {
        body: { created_at_from: from, created_at_to: to } satisfies IDiscussionboardMember.IRequest,
      },
    );
    typia.assert(output);
    TestValidator.equals("기간 필터 회원 수")(
      output.data.length
    )(expected.length);
    for (const member of output.data) {
      if (member.created_at < from || member.created_at > to)
        throw new Error("created_at 필터 무시됨");
      if ("hashed_password" in member)
        throw new Error("hashed_password 노출 금지 위반");
    }
  }

  // 7. Edge: 존재하지 않는 역할(ghost) => 빈 배열
  {
    const output = await api.functional.discussionboard.members.index(
      connection,
      {
        body: { role: "ghost" } satisfies IDiscussionboardMember.IRequest,
      },
    );
    typia.assert(output);
    TestValidator.equals("존재하지 않는 role 필터")(
      output.data.length
    )(0);
  }

  // 8. Edge: 범위를 벗어난 페이지(page = 999) => 빈 배열
  {
    const output = await api.functional.discussionboard.members.index(
      connection,
      {
        body: { page: 999, limit: 2 } satisfies IDiscussionboardMember.IRequest,
      },
    );
    typia.assert(output);
    TestValidator.equals("범위 벗어난 페이지 결과")(
      output.data.length
    )(0);
    // 페이지 관련 값들(최대 pages, 총 records 등)도 유효해야 함
    if (
      output.pagination.current !== 999 ||
      output.pagination.limit !== 2 ||
      output.pagination.pages < 1 ||
      output.pagination.records !== totalMembers
    ) {
      throw new Error("페이지네이션 메타데이터 불일치");
    }
  }
}

