import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { Idiscussionboard_post_reports } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_post_reports";
import type { Idiscussionboard_report_types } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_report_types";

/**
 * Validate hard deletion of a post report by its unique id.
 *
 * Business context:
 * Moderators may need to remove erroneous or abusive post reports from the moderation queue. Deleting a report should not affect original posts or reporter member data; only the report entity itself will be permanently erased. After successful deletion, no further delete on the same id should succeed, and a 'not found' error or similar should be returned if retried.
 *
 * Test steps:
 * 1. Create a unique member to act as the reporter.
 * 2. Create a report type (active) which will be used for the report.
 * 3. Create a new discussion board post, using referenced entities (member, etc).
 * 4. Create a post report, associating the created post, member, and report type.
 * 5. Hard delete the created post report by its id; verify the operation completes without error.
 * 6. Attempt to hard delete the report again using the same id; confirm that an error or 'not found' response is thrown.
 * 7. Confirm that the original discussion post and member can still be retrieved or inferred as unaffected (cannot verify via read API directly, so just assert the deletion does not throw for unrelated ids).
 */
export async function test_api_discussionboard_test_delete_post_report_success_and_not_found(connection: api.IConnection) {
  // 1. Create a member (reporter).
  const memberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(30),
    role: "member",
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create a report type (active).
  const reportTypeInput = {
    code: RandomGenerator.alphaNumeric(8),
    display_name: "Test Abuse",
    active: true,
    description: "Auto-generated test report type.",
  } satisfies Idiscussionboard_report_types.ICreate;
  const reportType = await api.functional.discussionboard.reportTypes.create(connection, { body: reportTypeInput });
  typia.assert(reportType);

  // 3. Create a post.
  // For post creation, we need thread_id and board_id - use random UUIDs for test isolation.
  const postInput: IDiscussionboardPost.ICreate = {
    discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_member_id: member.id,
    discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()(1)(),
  };
  const post = await api.functional.discussionboard.posts.create(connection, { body: postInput });
  typia.assert(post);

  // 4. Create a post report for that post.
  const reportInput = {
    discussionboard_post_id: post.id,
    reporter_member_id: member.id,
    report_type_id: reportType.id,
    description: "Inappropriate content detected by automation.",
    created_at: new Date().toISOString(),
  } satisfies Idiscussionboard_post_reports.ICreate;
  const report = await api.functional.discussionboard.postReports.create(connection, { body: reportInput });
  typia.assert(report);

  // 5. Hard delete the created report by its id.
  await api.functional.discussionboard.postReports.erase(connection, { id: report.id });

  // 6. Attempt to delete the report again; should throw (e.g., not found).
  await TestValidator.error("Deleting nonexistent report id must error")(async () => {
    await api.functional.discussionboard.postReports.erase(connection, { id: report.id });
  });

  // 7. (Best effort) Ensure that deleting a fake/unrelated id also errors, but original post/member are unaffected.
  await TestValidator.error("Deleting fake report id must error")(async () => {
    await api.functional.discussionboard.postReports.erase(connection, { id: typia.random<string & tags.Format<"uuid">>() });
  });
}

