import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { Idiscussionboard_post_reports } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_post_reports";
import type { IPostReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostReport";
import type { Idiscussionboard_report_types } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_report_types";

/**
 * Test updating the details of a post report in the discussion board (moderation flow).
 *
 * BUSINESS GOAL: Ensure that moderation/admin can successfully update details of an existing post report — including changing the report type, description, and assignment fields. Also ensure API properly handles update attempts for non-existent records or with invalid references.
 *
 * Steps:
 * 1. Create a discussionboard member (to act as the reporter).
 * 2. Create a discussionboard report type (as the initial type).
 * 3. Create a discussionboard post (so there is something to report).
 * 4. Create a post report against that post, from that member, with that report type and (optionally) a description.
 * 5. Create a second report type (to test report type change on update).
 * 6. Update the report: change at least one field (e.g., report type and description). Confirm changes are applied and returned in API response.
 * 7. Error test: try updating a report by passing a random uuid that doesn't exist (should yield error).
 * 8. Error test: try updating with bad references (invalid/missing member, post, or type uuid values — should yield error). Use valid report id, but break fields.
 */
export async function test_api_discussionboard_test_update_post_report_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Create reporter member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: memberEmail,
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create initial report type
  const reportType: Idiscussionboard_report_types = await api.functional.discussionboard.reportTypes.create(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(5),
      display_name: RandomGenerator.alphaNumeric(8),
      description: "First report type.",
      active: true,
    } satisfies Idiscussionboard_report_types.ICreate,
  });
  typia.assert(reportType);

  // 3. Create the post
  const post: IDiscussionboardPost = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: member.id,
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 4. Create a post report
  const createdAt: string & tags.Format<"date-time"> = new Date().toISOString() as string & tags.Format<"date-time">;
  const postReport: Idiscussionboard_post_reports = await api.functional.discussionboard.postReports.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      reporter_member_id: member.id,
      report_type_id: reportType.id,
      description: "Initial description", 
      created_at: createdAt,
    } satisfies Idiscussionboard_post_reports.ICreate,
  });
  typia.assert(postReport);

  // 5. Create a second report type for update test
  const secondReportType: Idiscussionboard_report_types = await api.functional.discussionboard.reportTypes.create(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(6),
      display_name: RandomGenerator.alphaNumeric(8),
      description: "Second report type.",
      active: true,
    } satisfies Idiscussionboard_report_types.ICreate,
  });
  typia.assert(secondReportType);

  // 6. Update the post report: change report_type and description
  const updatedDescription = "Updated report description.";
  const updatedAt = new Date().toISOString() as string & tags.Format<"date-time">;
  const updatedReport: IPostReport = await api.functional.discussionboard.postReports.update(connection, {
    id: postReport.id,
    body: {
      discussionboard_post_id: post.id,
      reporter_member_id: member.id,
      report_type_id: secondReportType.id,
      description: updatedDescription,
      created_at: updatedAt,
    } satisfies IPostReport.IUpdate,
  });
  typia.assert(updatedReport);

  // Validate updated fields
  TestValidator.equals("updated report_type_id")(updatedReport.report_type_id)(secondReportType.id);
  TestValidator.equals("updated description")(updatedReport.description)(updatedDescription);

  // 7. Error test: Update with a non-existent report id
  await TestValidator.error("update fails for missing report")(
    async () => {
      await api.functional.discussionboard.postReports.update(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: {
          discussionboard_post_id: post.id,
          reporter_member_id: member.id,
          report_type_id: reportType.id,
          description: "should not succeed",
          created_at: updatedAt,
        } satisfies IPostReport.IUpdate,
      });
    },
  );

  // 8. Error test: Update with bad references (invalid post, member, type IDs)
  await TestValidator.error("update fails for bad post id")(
    async () => {
      await api.functional.discussionboard.postReports.update(connection, {
        id: postReport.id,
        body: {
          discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
          reporter_member_id: member.id,
          report_type_id: reportType.id,
          description: "bad post id test",
          created_at: updatedAt,
        } satisfies IPostReport.IUpdate,
      });
    },
  );
  await TestValidator.error("update fails for bad member id")(
    async () => {
      await api.functional.discussionboard.postReports.update(connection, {
        id: postReport.id,
        body: {
          discussionboard_post_id: post.id,
          reporter_member_id: typia.random<string & tags.Format<"uuid">>(),
          report_type_id: reportType.id,
          description: "bad member id test",
          created_at: updatedAt,
        } satisfies IPostReport.IUpdate,
      });
    },
  );
  await TestValidator.error("update fails for bad report_type id")(
    async () => {
      await api.functional.discussionboard.postReports.update(connection, {
        id: postReport.id,
        body: {
          discussionboard_post_id: post.id,
          reporter_member_id: member.id,
          report_type_id: typia.random<string & tags.Format<"uuid">>(),
          description: "bad report type id test",
          created_at: updatedAt,
        } satisfies IPostReport.IUpdate,
      });
    },
  );
}

