import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardNotification";
import type { IPageIDiscussionboardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardNotification";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate notification log list retrieval (with filter, pagination, and sorting).
 *
 * This test creates multiple notifications of different types ('system_announcement', 'user_mention', etc.), target_ids, delivered states, and timestamps. Then, it queries the notifications index API with a variety of filters and combinations:
 *   - filter by target_id
 *   - filter by type
 *   - filter by delivered=true/false
 *   - filter by created_at range
 *   - combine above filters
 *   - test sorting (orderBy, orderDirection)
 *   - test pagination (page, limit, edge case where page yields no results)
 *
 * Steps:
 * 1. Create several notification records with a mix of:
 *      - types: 'system_announcement', 'user_mention', 'ban', 'reply_created'
 *      - target_id: use at least two distinct target_id values (uuid)
 *      - delivered: true/false
 *      - delivered_at: set for some notifications (optional)
 *      - created_at: distributed over a range (at least two date clusters)
 * 2. Call notifications index (PATCH /discussionboard/notifications) with:
 *      a. filter by target_id (should only return matching records)
 *      b. filter by type (should return only specified type)
 *      c. filter by delivered
 *      d. filter by created_at range (e.g. only recent)
 *      e. combine e.g. target_id+delivered
 *      f. order by created_at desc/asc, check correct order
 *      g. paginate - use limit/page to get partial results, check pagination meta
 *      h. request out-of-range page (should return empty data[], correct pagination info)
 * 3. For each, verify all returned records satisfy the filters, order, and are paginated per the spec.
 * 4. (Optionally) Simulate/validate permission by user role (admin, moderator) if supported by connection/auth context (actual role login omitted here for brevity, but noted for completeness).
 *
 * Edge cases and validation:
 *  - Filtering should not return records outside query parameters.
 *  - Empty results for pages beyond data.
 *  - Sorting order (created_at asc/desc) is respected.
 *  - Pagination meta matches expected values.
 */
export async function test_api_discussionboard_test_list_notifications_with_filter_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create test data: notifications of mixed types, target_ids, delivered states, dates.
  const targetIdA = typia.random<string & tags.Format<"uuid">>();
  const targetIdB = typia.random<string & tags.Format<"uuid">>();

  // Date clusters
  const dateNow = new Date();
  const dateOld = new Date(dateNow.getTime() - 7 * 24 * 60 * 60 * 1000); // 1 week ago
  const createdAtNow = dateNow.toISOString();
  const createdAtOld = dateOld.toISOString();

  // Notification records: build combinations
  const notifications = [
    { type: 'system_announcement', title: 'Announcement 1', delivered: true, created_at: createdAtOld, target_id: targetIdA },
    { type: 'user_mention', title: 'Mentioned you', delivered: false, created_at: createdAtNow, target_id: targetIdA },
    { type: 'system_announcement', title: 'Announcement 2', delivered: false, created_at: createdAtNow, target_id: targetIdB },
    { type: 'ban', title: 'You were banned', delivered: true, created_at: createdAtNow, target_id: targetIdB },
    { type: 'reply_created', title: 'New reply', delivered: true, created_at: createdAtOld, target_id: targetIdB },
    // No target_id notifications (system-wide)
    { type: 'user_mention', title: 'Mention, system', delivered: true, created_at: createdAtNow },
  ];

  // Optionally add unique delivered_at for delivered=true
  for (const n of notifications) {
    if (n.delivered) n.delivered_at = n.created_at;
  }

  // Create records in backend (dependencies: POST /discussionboard/notifications)
  const createdRecords = [];
  for (const n of notifications) {
    const created = await api.functional.discussionboard.notifications.create(connection, { body: n satisfies IDiscussionboardNotification.ICreate });
    typia.assert(created);
    createdRecords.push(created);
  }

  // 2a. Filter by target_id (targetIdA)
  {
    const output = await api.functional.discussionboard.notifications.index(connection, { body: { target_id: targetIdA } satisfies IDiscussionboardNotification.IRequest });
    typia.assert(output);
    TestValidator.predicate('all results match target_id')(output.data.every(n => n.target_id === targetIdA));
  }
  // 2b. Filter by type 'system_announcement'
  {
    const output = await api.functional.discussionboard.notifications.index(connection, { body: { type: 'system_announcement' } satisfies IDiscussionboardNotification.IRequest });
    typia.assert(output);
    TestValidator.predicate('all results match type')(output.data.every(n => n.type === 'system_announcement'));
  }
  // 2c. Filter by delivered=false
  {
    const output = await api.functional.discussionboard.notifications.index(connection, { body: { delivered: false } satisfies IDiscussionboardNotification.IRequest });
    typia.assert(output);
    TestValidator.predicate('all results are not delivered')(output.data.every(n => n.delivered === false));
  }
  // 2d. Filter by created_at range (created_at >= createdAtNow)
  {
    const output = await api.functional.discussionboard.notifications.index(connection, { body: { created_at: createdAtNow } satisfies IDiscussionboardNotification.IRequest });
    typia.assert(output);
    TestValidator.predicate('all results after created_at')(output.data.every(n => n.created_at >= createdAtNow));
  }
  // 2e. Combination (target_id=targetIdB, delivered=true)
  {
    const output = await api.functional.discussionboard.notifications.index(connection, { body: { target_id: targetIdB, delivered: true } satisfies IDiscussionboardNotification.IRequest });
    typia.assert(output);
    TestValidator.predicate('all results target_id and delivered')(output.data.every(n => n.target_id === targetIdB && n.delivered === true));
  }
  // 2f. Sort by created_at desc
  {
    const output = await api.functional.discussionboard.notifications.index(connection, { body: { orderBy: 'created_at', orderDirection: 'desc' } satisfies IDiscussionboardNotification.IRequest });
    typia.assert(output);
    for (let i=1;i<output.data.length;i++) {
      TestValidator.predicate('sorted desc')(output.data[i-1].created_at >= output.data[i].created_at);
    }
  }
  // 2f2. Sort by created_at asc
  {
    const output = await api.functional.discussionboard.notifications.index(connection, { body: { orderBy: 'created_at', orderDirection: 'asc' } satisfies IDiscussionboardNotification.IRequest });
    typia.assert(output);
    for (let i=1;i<output.data.length;i++) {
      TestValidator.predicate('sorted asc')(output.data[i-1].created_at <= output.data[i].created_at);
    }
  }
  // 2g. Pagination: limit=2, page=1 and page=2
  {
    const output1 = await api.functional.discussionboard.notifications.index(connection, { body: { limit: 2, page: 1, orderBy: 'created_at', orderDirection: 'desc' } satisfies IDiscussionboardNotification.IRequest });
    typia.assert(output1);
    TestValidator.equals('limit 2')(output1.data.length)(Math.min(2, createdRecords.length));
    TestValidator.equals('page 1 number')(output1.pagination.current)(1);
    const output2 = await api.functional.discussionboard.notifications.index(connection, { body: { limit: 2, page: 2, orderBy: 'created_at', orderDirection: 'desc' } satisfies IDiscussionboardNotification.IRequest });
    typia.assert(output2);
    TestValidator.equals('limit 2, page 2')(output2.data.length)(Math.max(0, createdRecords.length-2)); // for 6 records: page 2 should have rest
    TestValidator.equals('page 2 number')(output2.pagination.current)(2);
  }
  // 2h. Page out-of-range (page > pages)
  {
    const output = await api.functional.discussionboard.notifications.index(connection, { body: { limit: 2, page: 100 } satisfies IDiscussionboardNotification.IRequest });
    typia.assert(output);
    TestValidator.equals('out-of-range page returns no data')(output.data.length)(0);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardNotification";

/**
 * Validate retrieval of a single notification log record by id, including success and error scenarios.
 *
 * Business context:
 * This test ensures that the API can fetch a notification record with a valid id and that the returned data conforms to the expected schema, including all required and optional fields. It also ensures robust error handling by testing a request using a non-existent or invalid id, expecting a 404 error response. Since notification management may be permissioned, the test should assume roles with appropriate access rights.
 *
 * Step-by-step process:
 * 1. Create a new notification using the POST /discussionboard/notifications API to obtain a valid id.
 * 2. Fetch the notification by id with GET /discussionboard/notifications/{id} and assert the returned object matches all expected schema properties.
 * 3. Use TestValidator.equals for field-by-field (or full object) validation.
 * 4. Attempt to GET a notification with an obviously invalid or random uuid (guaranteed non-existent) and use TestValidator.error to validate a 404 error occurs.
 * 5. (Assume permission context: If relevant, ensure operation as a role with permission to access notification records, e.g., admin/moderator.)
 */
export async function test_api_discussionboard_test_get_notification_by_valid_and_invalid_id(connection: api.IConnection) {
  // 1. Create a notification
  const notificationInput: IDiscussionboardNotification.ICreate = {
    type: "system_announcement",
    title: RandomGenerator.paragraph()(5),
    delivered: true,
    created_at: new Date().toISOString(),
    body: RandomGenerator.content()()(),
    delivered_at: new Date().toISOString(),
    target_id: typia.random<string & tags.Format<"uuid">>(),
  };
  const created = await api.functional.discussionboard.notifications.create(connection, { body: notificationInput });
  typia.assert(created);

  // 2. Fetch by id and validate schema & property accuracy
  const fetched = await api.functional.discussionboard.notifications.at(connection, { id: created.id });
  typia.assert(fetched);
  // Field-by-field validation
  TestValidator.equals("type")(fetched.type)(notificationInput.type);
  TestValidator.equals("title")(fetched.title)(notificationInput.title);
  TestValidator.equals("body")(fetched.body)(notificationInput.body);
  TestValidator.equals("delivered")(fetched.delivered)(notificationInput.delivered);
  // target_id is optional, but included in this case
  TestValidator.equals("target_id")(fetched.target_id)(notificationInput.target_id);
  // created_at and delivered_at can have minor diffs (truncated ms); check validity
  TestValidator.predicate("created_at looks ISO 8601")(!!Date.parse(fetched.created_at));
  if (notificationInput.delivered_at)
    TestValidator.predicate("delivered_at looks ISO 8601")(!!Date.parse(fetched.delivered_at ?? undefined));

  // 3. Try fetching with invalid ID and expect 404 error
  const invalidId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("Not found for invalid id")(() => api.functional.discussionboard.notifications.at(connection, { id: invalidId }));
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardConfiguration";

/**
 * 시스템 설정(configuration) 업데이트 시 key 필드가 불변(immutable)임을 검증하는 테스트입니다.
 *
 * - 이미 생성된 configuration에 대해 value, description 변경 시 update가 정상 동작하는지 확인합니다.
 * - 반대로 key 필드 변경을 시도할 경우, 타입 시스템에서 차단될 뿐 아니라 서버도 해당 변경을 거부해야 함을 검증합니다.
 * - 마지막으로 여러 번 업데이트 후에도 key 값이 계속 유지되는지 확인합니다.
 *
 * 테스트 목적: 시스템 불변 규칙이 API 및 타입/런타임에서 모두 지켜짐을 보장합니다.
 *
 * 1. configuration 생성 (POST)
 * 2. value/description 업데이트 (PUT)
 * 3. key 필드 변경 강제 시도(런타임 에러 확인)
 * 4. 여러 번 변경후에도 key값이 그대로임을 확인
 */
export async function test_api_discussionboard_configurations_test_update_configuration_attempt_to_modify_key_field(
  connection: api.IConnection,
) {
  // 1. configuration 생성
  const configInput: IDiscussionboardConfiguration.ICreate = {
    key: `max_post_per_hour_${typia.random<number>()}`,
    value: "10",
    description: "최대 시간당 게시글 수 허용치",
  };
  const config = await api.functional.discussionboard.configurations.create(
    connection,
    { body: configInput }
  );
  typia.assert(config);

  // 2. value/description 정상 업데이트
  const updated = await api.functional.discussionboard.configurations.update(
    connection,
    {
      id: config.id,
      body: {
        value: "12",
        description: "최대 시간당 게시글 수(변경됨)",
      },
    }
  );
  typia.assert(updated);
  TestValidator.equals("key 변함없음")(updated.key)(config.key);
  TestValidator.equals("value 변경")(updated.value)("12");
  TestValidator.equals("description 변경")(updated.description)("최대 시간당 게시글 수(변경됨)");

  // 3. 강제로 key 필드 변경 포함 시도시 거절되는지(RUNTIME 에러만!)
  TestValidator.error("key 필드 변경 시도 → 서버 거절")(() =>
    api.functional.discussionboard.configurations.update(
      connection,
      {
        id: config.id,
        // @ts-expect-error: 강제로 key 포함, 타입 무시
        body: { key: "try_modify_key", value: "13" },
      } as any,
    ),
  );

  // 4. 여러 번 업데이트 후에도 key 원본 값 불변 확인
  const finalConfig = await api.functional.discussionboard.configurations.update(
    connection,
    {
      id: config.id,
      body: { value: "14" },
    },
  );
  typia.assert(finalConfig);
  TestValidator.equals("key 변함없음")(finalConfig.key)(config.key);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IPageIComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing and filtering of comments with advanced scenarios:
 *   - Filtering comments by post, author, parent comment, nesting (replies to comments)
 *   - Filtering by creation and update timestamps (date/time windows)
 *   - Filtering soft-deleted (deleted_at) comments
 *   - Edge: no comments under a post, or soft-deleted only
 *   - Pagination and ordering
 *   - Schema integrity for all returned comment fields
 *
 * Steps:
 * 1. Create two posts and two member IDs
 * 2. Create several top-level comments for post A (with different authors)
 * 3. Create replies (child comments) under some comments
 * 4. Attempt to soft-delete one comment and its child (note: as there is no delete endpoint, can only test filter semantics)
 * 5. Issue search/filter requests:
 *    - List all comments for post A
 *    - Filter by author
 *    - Only top-level, only children
 *    - List soft-deleted comments for post A (should be empty in this environment)
 *    - Paginate: two comments per page
 *    - Confirm empty for post B
 *    - For each result, validate fields (deleted_at especially)
 */
export async function test_api_discussionboard_test_list_comments_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create two posts and two members
  const memberA = typia.random<string & tags.Format<"uuid">>();
  const memberB = typia.random<string & tags.Format<"uuid">>();
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const postA = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_member_id: memberA,
      discussionboard_board_id: boardId,
      title: "Post A",
      body: "Body A",
    },
  });
  const postB = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_member_id: memberB,
      discussionboard_board_id: boardId,
      title: "Post B",
      body: "Body B",
    },
  });
  typia.assert(postA);
  typia.assert(postB);

  // 2. Create top-level comments (postA, two authors)
  const commentA1 = await api.functional.discussionboard.comments.create(
    connection,
    {
      body: {
        discussionboard_post_id: postA.id,
        discussionboard_member_id: memberA,
        body: "Top by A",
      },
    },
  );
  const commentA2 = await api.functional.discussionboard.comments.create(
    connection,
    {
      body: {
        discussionboard_post_id: postA.id,
        discussionboard_member_id: memberB,
        body: "Top by B",
      },
    },
  );
  typia.assert(commentA1);
  typia.assert(commentA2);

  // 3. Create replies (children)
  const childA1 = await api.functional.discussionboard.comments.create(
    connection,
    {
      body: {
        discussionboard_post_id: postA.id,
        discussionboard_member_id: memberB,
        parent_id: commentA1.id,
        body: "Reply to Top by A (by B)",
      },
    },
  );
  const childA2 = await api.functional.discussionboard.comments.create(
    connection,
    {
      body: {
        discussionboard_post_id: postA.id,
        discussionboard_member_id: memberA,
        parent_id: commentA2.id,
        body: "Reply to Top by B (by A)",
      },
    },
  );
  typia.assert(childA1);
  typia.assert(childA2);

  // 4. No delete endpoint; can only test semantics of filter with 'deleted'.
  // 5a. List all comments for postA
  const allForPostA = await api.functional.discussionboard.comments.index(
    connection,
    { body: { discussionboard_post_id: postA.id } },
  );
  typia.assert(allForPostA);
  allForPostA.data.forEach(typia.assert);
  allForPostA.data.forEach((c) =>
    TestValidator.equals("post id")(c.discussionboard_post_id)(postA.id),
  );

  // 5b. Filter by author (memberA)
  const byMemberA = await api.functional.discussionboard.comments.index(
    connection,
    { body: { discussionboard_post_id: postA.id, discussionboard_member_id: memberA } },
  );
  typia.assert(byMemberA);
  byMemberA.data.forEach(typia.assert);
  byMemberA.data.forEach((c) =>
    TestValidator.equals("author")(c.discussionboard_member_id)(memberA),
  );

  // 5c. Only top-level (parent_id = null)
  const topLevel = await api.functional.discussionboard.comments.index(
    connection,
    { body: { discussionboard_post_id: postA.id, parent_id: null } },
  );
  typia.assert(topLevel);
  topLevel.data.forEach(typia.assert);
  topLevel.data.forEach((c) =>
    TestValidator.equals("top-level")(c.parent_id)(null),
  );

  // 5d. Only children for commentA1
  const childrenA1 = await api.functional.discussionboard.comments.index(
    connection,
    { body: { discussionboard_post_id: postA.id, parent_id: commentA1.id } },
  );
  typia.assert(childrenA1);
  childrenA1.data.forEach(typia.assert);
  childrenA1.data.forEach((c) =>
    TestValidator.equals("parent id")(c.parent_id)(commentA1.id),
  );

  // 5e. Soft-deleted comments (should be empty as within environment we can't delete)
  const deletedOnly = await api.functional.discussionboard.comments.index(
    connection,
    { body: { discussionboard_post_id: postA.id, deleted: true } },
  );
  typia.assert(deletedOnly);
  deletedOnly.data.forEach((c) =>
    TestValidator.predicate("deleted_at present")(!!c.deleted_at),
  );

  // 5f. Pagination, limit=2, page=1 and 2
  const page1 = await api.functional.discussionboard.comments.index(
    connection,
    { body: { discussionboard_post_id: postA.id, page: 1, limit: 2 } },
  );
  typia.assert(page1);
  page1.data.forEach(typia.assert);
  const page2 = await api.functional.discussionboard.comments.index(
    connection,
    { body: { discussionboard_post_id: postA.id, page: 2, limit: 2 } },
  );
  typia.assert(page2);
  page2.data.forEach(typia.assert);
  TestValidator.equals("pagination.limit")(page1.pagination.limit)(2);
  TestValidator.equals("pagination.page")(page1.pagination.current)(1);
  TestValidator.equals("pagination.page")(page2.pagination.current)(2);

  // 5g. Post B: should be empty
  const empty = await api.functional.discussionboard.comments.index(
    connection,
    { body: { discussionboard_post_id: postB.id } },
  );
  typia.assert(empty);
  TestValidator.equals("no comments")(empty.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerationAction";
import type { IPageIDiscussionboardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardModerationAction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate moderator/admin can retrieve paginated and filtered moderation actions
 *
 * This test covers the ability of a privileged user (moderator or admin) to fetch and filter the moderation actions list from
 * discussionboard_moderation_actions with various valid and invalid filters, and verify pagination/edge cases.
 *
 * Steps:
 * 1. Fetch moderation actions with no filters (default list, default pagination).
 * 2. Fetch with a valid filter on action_type and verify only matching results returned.
 * 3. Fetch with a valid filter on acting_moderator_id and verify only that moderator's actions are returned.
 * 4. Fetch with a valid filter on report_id (if any actions are linked to reports) and validate filtering.
 * 5. Test pagination by requesting page 1, a middle page (if exists), and last page. Verify pagination metadata.
 * 6. Fetch with filter values that are known to NOT match (e.g., nonexistent moderator ID, bogus action_type) and expect empty results.
 * 7. Fetch with invalid pagination values (page=0 or negative, limit=0 or negative) and ensure error or empty results, not server crash.
 */
export async function test_api_discussionboard_test_list_moderation_actions_with_pagination_and_filters(connection: api.IConnection) {
  // 1. Fetch first page without filters - expect at least valid pagination format
  const page1 = await api.functional.discussionboard.moderationActions.index(connection, {
    body: {},
  });
  typia.assert(page1);
  TestValidator.predicate("first page starts at 1")(page1.pagination.current === 1);
  TestValidator.predicate("limit is positive")(page1.pagination.limit > 0);
  TestValidator.predicate("records count matches data length or is larger")(page1.pagination.records >= page1.data.length);
  TestValidator.predicate("pages is positive")(page1.pagination.pages > 0);

  // If there are no moderation actions, skip further positive filter checks
  if (page1.data.length === 0)
    return;

  // 2. Filter by action_type of first returned entry
  const actionType = page1.data[0].action_type;
  const filteredByType = await api.functional.discussionboard.moderationActions.index(connection, {
    body: { action_type: actionType },
  });
  typia.assert(filteredByType);
  TestValidator.predicate("all returned have requested action_type")(filteredByType.data.every(a => a.action_type === actionType));

  // 3. Filter by acting_moderator_id
  const moderatorId = page1.data[0].acting_moderator_id;
  const filteredByModerator = await api.functional.discussionboard.moderationActions.index(connection, {
    body: { acting_moderator_id: moderatorId },
  });
  typia.assert(filteredByModerator);
  TestValidator.predicate("all returned have requested moderator")(filteredByModerator.data.every(a => a.acting_moderator_id === moderatorId));

  // 4. If any action has a report_id, filter by it
  const withReport = page1.data.find(a => a.report_id !== null && a.report_id !== undefined);
  if (withReport) {
    const filteredByReport = await api.functional.discussionboard.moderationActions.index(connection, {
      body: { report_id: withReport.report_id! },
    });
    typia.assert(filteredByReport);
    TestValidator.predicate("all returned have requested report_id")(filteredByReport.data.every(a => a.report_id === withReport.report_id));
  }

  // 5. Test pagination
  if (page1.pagination.pages > 1) {
    const midPage = Math.ceil(page1.pagination.pages / 2);
    const pageMid = await api.functional.discussionboard.moderationActions.index(connection, {
      body: {},
    });
    typia.assert(pageMid);
    TestValidator.equals("middle page")(pageMid.pagination.current)(midPage);
    const lastPage = await api.functional.discussionboard.moderationActions.index(connection, {
      body: {},
    });
    typia.assert(lastPage);
    TestValidator.equals("last page")(lastPage.pagination.current)(page1.pagination.pages);
  }

  // 6. Nonexistent/bogus filter values (should yield empty result)
  const filteredByBogusType = await api.functional.discussionboard.moderationActions.index(connection, {
    body: { action_type: "nonexistent-bogus-type-xyz" },
  });
  typia.assert(filteredByBogusType);
  TestValidator.equals("no results for bogus action_type")(filteredByBogusType.data.length)(0);

  const filteredByBogusModerator = await api.functional.discussionboard.moderationActions.index(connection, {
    body: { acting_moderator_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(filteredByBogusModerator);
  TestValidator.equals("no results for bogus moderator")(filteredByBogusModerator.data.length)(0);

  // 7. Invalid and edge-case pagination values
  for (const bad of [{ page: 0 }, { page: -5 }, { limit: 0 }, { limit: -20 }]) {
    await TestValidator.error(`bad pagination ${JSON.stringify(bad)}`)(async () => {
      await api.functional.discussionboard.moderationActions.index(connection, {
        body: bad,
      });
    });
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardThreadTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreadTag";

/**
 * 테스트: 스레드 태그 할당 업데이트 (removed_at 설정 및 필드 편집 제한)
 *
 * 이 테스트는 /discussionboard/threadTags/{id} API를 통해 스레드 태그 할당 엔티티를 업데이트하는 시나리오를 검증합니다.
 * 1. 스레드와 태그 할당 엔티티를 선행 생성합니다.
 * 2. removed_at 필드를 현재 시각으로 지정하여 태그 할당을 "제거됨" 처리하고, 필드 변경이 정상적으로 반영되는지 확인합니다.
 * 3. removed_at=null로 재설정하여 서프트 삭제 클리어가 허용되는지 확인합니다.
 * 4. 할당되지 않은(random uuid) 태그 할당에 업데이트를 시도하여 에러(존재하지 않는 id) 발생을 검증합니다.
 * 5. update DTO가 허용하는 removed_at 외에는 변화가 발생하지 않는 점을 보장합니다.
 */
export async function test_api_discussionboard_threadTags_test_update_thread_tag_assignment_set_removed_at_and_edit_assignment_fields(
  connection: api.IConnection,
) {
  // 1. 스레드 엔티티 생성 (의존성)
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: typia.random<string & tags.Format<"uuid">>(),
      author_member_id: typia.random<string & tags.Format<"uuid">>(),
      title: "태그 업데이트 테스트 스레드",
      body: "스레드 태그 할당 업데이트 E2E.",
    },
  });
  typia.assert(thread);

  // 2. 태그 할당 생성 (의존성)
  const tagAssignment = await api.functional.discussionboard.threadTags.create(connection, {
    body: {
      thread_id: thread.id,
      assigned_at: new Date().toISOString(),
    },
  });
  typia.assert(tagAssignment);

  // 3. removed_at 업데이트: 할당 해제
  const removedAt = new Date().toISOString();
  const updated1 = await api.functional.discussionboard.threadTags.update(connection, {
    id: tagAssignment.id,
    body: { removed_at: removedAt },
  });
  typia.assert(updated1);
  TestValidator.equals("removed_at 변경됨")(updated1.removed_at)(removedAt);
  TestValidator.equals("id 불변")(updated1.id)(tagAssignment.id);
  TestValidator.equals("assigned_at 불변")(updated1.assigned_at)(tagAssignment.assigned_at);

  // 4. removed_at 다시 null로 복구 (서프트 삭제 해제)
  const updated2 = await api.functional.discussionboard.threadTags.update(connection, {
    id: tagAssignment.id,
    body: { removed_at: null },
  });
  typia.assert(updated2);
  TestValidator.equals("removed_at cleared")(updated2.removed_at)(null);
  TestValidator.equals("assigned_at 유지")(updated2.assigned_at)(updated1.assigned_at);

  // 5. 음수 시나리오: 존재하지 않는 id 업데이트 시도시 에러 반환
  await TestValidator.error("없는 태그 할당 업데이트 시 에러")(() =>
    api.functional.discussionboard.threadTags.update(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { removed_at: new Date().toISOString() },
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
