import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IMemberPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberPreference";

/**
 * Test updating a member preference with valid fields.
 *
 * Scenario:
 * 1. Create a member (using the member registration endpoint).
 * 2. Create a preferences record for that member (set various initial fields).
 * 3. Use the update endpoint (PUT) to change push notifications setting and preferred language.
 * 4. Validate that:
 *    a. The updated fields reflect the new values
 *    b. Unchanged fields (such as receive_email_notifications, dark_mode_enabled) are the same as before
 *    c. updated_at timestamp is advanced compared to the previous preference record
 */
export async function test_api_memberPreferences_test_update_member_preference_with_valid_fields(
  connection: api.IConnection,
) {
  // 1. Create a discussionboard member
  const memberInput = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(12),
    role: "member",
    is_active: true,
  } satisfies IDiscussionboardMember.ICreate;
  const member = await api.functional.discussionboard.members.create(connection, {
    body: memberInput,
  });
  typia.assert(member);

  // 2. Create initial preferences for this member
  const initialPreference = {
    member_id: member.id,
    receive_email_notifications: true,
    receive_push_notifications: false,
    preferred_language: "en",
    dark_mode_enabled: false,
  } satisfies IMemberPreference.ICreate;
  const prefBefore = await api.functional.discussionboard.memberPreferences.create(connection, {
    body: initialPreference,
  });
  typia.assert(prefBefore);
  const prevUpdatedAt = prefBefore.updated_at;

  // 3. Update push notifications and preferred_language via PUT
  const updateInput = {
    receive_push_notifications: true,
    preferred_language: "ko",
  } satisfies IMemberPreference.IUpdate;

  const prefAfter = await api.functional.discussionboard.memberPreferences.update(connection, {
    id: prefBefore.id,
    body: updateInput,
  });
  typia.assert(prefAfter);

  // 4a. Confirm mutated fields reflect update
  TestValidator.equals("updated push notifications")(prefAfter.receive_push_notifications)(true);
  TestValidator.equals("updated preferred_language")(prefAfter.preferred_language)("ko");

  // 4b. Confirm unchanged fields persist
  TestValidator.equals("unchanged: receive_email_notifications")(
    prefAfter.receive_email_notifications
  )(prefBefore.receive_email_notifications);
  TestValidator.equals("unchanged: dark_mode_enabled")(
    prefAfter.dark_mode_enabled
  )(prefBefore.dark_mode_enabled);

  // 4c. Confirm updated_at advanced
  TestValidator.predicate("updated_at advanced")(
    new Date(prefAfter.updated_at).getTime() > new Date(prevUpdatedAt).getTime()
  );

  // 4d. The member_id and pref id must remain the same
  TestValidator.equals("member_id unchanged")(prefAfter.member_id)(member.id);
  TestValidator.equals("preference id unchanged")(prefAfter.id)(prefBefore.id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoard";
import type { IDiscussionboardBoardSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardSetting";
import type { IPageDiscussionboardBoardSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardBoardSetting";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E: Validate board settings listing (with filter, sort, and pagination).
 *
 * Simulates an admin accessing the dashboard to:
 * 1. Create several boards and boardSettings (mix of is_locked, require_approval_for_posting, allow_file_uploads, etc.)
 * 2. List with various filters: is_locked, require_approval_for_posting, allow_file_uploads, or combinations
 * 3. Validate each API result contains only settings that match the filter criteria (no leakages)
 * 4. Test pagination logic (page offset + limit)
 * 5. Test response data integrity and proper error response for unsupported fields
 *
 * Full coverage for admin management/analytics with filtering and paging.
 */
export async function test_api_discussionboard_test_list_board_settings_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // -- Step 1: Create several boards with diverse category/section/name/code --
  const sectionId = typia.random<string & tags.Format<"uuid">>();
  const categoryId = typia.random<string & tags.Format<"uuid">>();

  // We'll create 5 boards for coverage.
  const boards = await Promise.all(
    ArrayUtil.repeat(5)(() =>
      api.functional.discussionboard.boards.create(connection, {
        body: {
          discussionboard_board_category_id: categoryId,
          discussionboard_section_id: sectionId,
          name: RandomGenerator.paragraph()(),
          code: RandomGenerator.alphaNumeric(8),
          description: RandomGenerator.paragraph()(),
          is_active: true,
          is_visible: true,
        } satisfies IBoard.ICreate,
      })
    )
  );
  boards.forEach(typia.assert);

  // -- Step 2: For each board, create unique settings combo --
  // We'll use a pattern to hit all key filterable fields coverage
  const settingsCombos = [
    { is_locked: true, require_approval_for_posting: true, allow_file_uploads: true },
    { is_locked: false, require_approval_for_posting: true, allow_file_uploads: false },
    { is_locked: true, require_approval_for_posting: false, allow_file_uploads: true },
    { is_locked: false, require_approval_for_posting: false, allow_file_uploads: false },
    { is_locked: true, require_approval_for_posting: true, allow_file_uploads: false },
  ];

  const settings = await Promise.all(
    boards.map((board, i) =>
      api.functional.discussionboard.boardSettings.create(connection, {
        body: {
          discussionboard_board_id: board.id,
          ...settingsCombos[i],
          max_posts_per_hour: 10 + i,
          allow_anonymous_viewing: i % 2 === 0,
        } satisfies IDiscussionboardBoardSetting.ICreate,
      })
    )
  );
  settings.forEach(typia.assert);

  // -- Step 3: List with filter: is_locked=true --
  {
    const result = await api.functional.discussionboard.boardSettings.index(connection, {
      body: { is_locked: true },
    });
    typia.assert(result);
    for (const s of result.data) {
      TestValidator.equals("is_locked filter")(s.is_locked)(true);
    }
  }

  // -- Step 4: List with filter: require_approval_for_posting=true --
  {
    const result = await api.functional.discussionboard.boardSettings.index(connection, {
      body: { require_approval_for_posting: true },
    });
    typia.assert(result);
    for (const s of result.data) {
      TestValidator.equals("require_approval_for_posting")(s.require_approval_for_posting)(true);
    }
  }

  // -- Step 5: List with filter: allow_file_uploads=false --
  {
    const result = await api.functional.discussionboard.boardSettings.index(connection, {
      body: { allow_file_uploads: false },
    });
    typia.assert(result);
    for (const s of result.data) {
      TestValidator.equals("allow_file_uploads")(s.allow_file_uploads)(false);
    }
  }

  // -- Step 6: List with combined filters (is_locked=true, allow_file_uploads=true) --
  {
    const result = await api.functional.discussionboard.boardSettings.index(connection, {
      body: {
        is_locked: true,
        allow_file_uploads: true,
      },
    });
    typia.assert(result);
    for (const s of result.data) {
      TestValidator.equals("is_locked")(s.is_locked)(true);
      TestValidator.equals("allow_file_uploads")(s.allow_file_uploads)(true);
    }
  }

  // -- Step 7: Pagination check --
  {
    // Artificially page with limit=2 to check surfaces as expected
    const resultPage1 = await api.functional.discussionboard.boardSettings.index(connection, {
      body: { },
    });
    typia.assert(resultPage1);
    const totalRecords = resultPage1.pagination.records;
    const pagedSettings = [] as typeof settings;
    let page = 1;
    const limit = 2;
    let remain = totalRecords;
    while (remain > 0) {
      const resp = await api.functional.discussionboard.boardSettings.index(connection, {
        body: { }, // No filter, so gets all
      });
      typia.assert(resp);
      resp.data.forEach((row) => pagedSettings.push(row));
      remain -= resp.data.length;
      page++;
      if (pagedSettings.length >= settings.length) break; // test optimization: don't fetch more than available
    }
    // surface all known created ids are present in paged results
    const createdIds = settings.map((s) => s.id).sort();
    const pagedIds = pagedSettings.map((s) => s.id).sort();
    TestValidator.equals("all created settings visible in paging list")(pagedIds)(createdIds);
  }

  // -- Step 8: Error on bad filter property --
  {
    await TestValidator.error("unsupported filter field causes error")(
      async () => {
        await api.functional.discussionboard.boardSettings.index(connection, {
          body: { nonexistent_field: true } as any,
        });
      },
    );
  }
}

