 *
 * Workflow:
 * 1. Create a new discussion board channel (required for parent relationship).
 * 2. Create a new section under the created channel.
 * 3. Permanently delete the created section by ID.
 * 4. Verify the delete API returns { success: true } and correct section ID.
 * 5. Attempt to retrieve the deleted section by ID and expect an error (not found).
 */
export async function test_api_discussionboard_test_delete_section_permanently(
  connection: api.IConnection,
) {
  // 1. Create a new channel - prerequisite for creating a section
  const channelInput = {
