import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { Idiscussionboard_post_snapshots } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_post_snapshots";

/**
 * 테스트: 권한 없는 사용자가 게시글 스냅샷 ID로 조회를 시도할 때 접근이 거부되는지 검증합니다.
 *
 * 이 테스트는 게시글 스냅샷 정보를 읽기 위한 API에 대해, 권한이 없는 사용자(로그인하지 않았거나, 관리자가 아닌 일반 사용자)의 접근이 차단(401 또는 403 오류)되는지 확인합니다. 잘못된 권한 상태에서 스냅샷을 성공적으로 조회하거나 데이터가 노출되어서는 안 됩니다.
 *
 * 테스트 프로세스:
 * 1. 권한이 있는 사용자로 게시글을 생성합니다.
 * 2. 같은 권한으로 해당 게시글에 대한 스냅샷을 생성합니다.
 * 3. 인증 정보가 없는(권한 없는) 연결 객체를 준비합니다.
 * 4. 이 연결로 스냅샷 단건 조회를 시도하고, 401 또는 403 오류가 발생함을 확인합니다.
 * 5. 에러 발생 시 반환 데이터에 스냅샷 정보가 노출되지 않는 것도 보장합니다.
 *
 * 권한 제어 및 민감 데이터 보호가 정상적으로 동작하는지 확인하는 중요한 시나리오입니다.
 */
export async function test_api_discussionboard_test_get_post_snapshot_unauthorized_access(
  connection: api.IConnection,
) {
  // 1. 권한 있는 사용자로 게시글 생성
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Test Post for Unauthorized Access",
      body: "This is the body of the test post.",
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 2. 권한 있는 사용자로 해당 게시글 스냅샷 생성
  const now = new Date().toISOString();
  const snapshot = await api.functional.discussionboard.postSnapshots.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      editor_member_id: post.discussionboard_member_id,
      title: post.title,
      body: post.body,
      taken_at: now,
    } satisfies Idiscussionboard_post_snapshots.ICreate,
  });
  typia.assert(snapshot);

  // 3. 인증 정보가 없는(권한 없는) 연결로 시도: Authorization 헤더 제거
  const unauthorizedConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: undefined,
    },
  };

  // 4. 권한 없는 사용자가 스냅샷을 조회하려 할 때 401 또는 403 에러가 발생해야 함을 검증
  await TestValidator.error("권한 없는 스냅샷 조회 시도는 실패해야 합니다.")(() =>
    api.functional.discussionboard.postSnapshots.at(unauthorizedConnection, {
      id: snapshot.id,
    }),
  );
  // 주의: 에러 발생 시 반환 데이터 내 스냅샷 정보 노출이 없는지도 간접적으로 보호됩니다.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
