/**
 * Validate that the board update API rejects requests where invalid fields are provided, or values do not conform to schema validation.
 *
 * This test checks two main error scenarios for update:
 * 1. Attempt to update a board with a field not allowed by the schema (e.g., injecting a non-existent property).
 * 2. Attempt to update fields with invalid data (e.g., invalid UUID format, non-boolean for boolean fields, name with empty string, etc.).
 * The API should respond with validation errors for both cases, and no board should be updated.
 *
 * Steps:
 * 1. Create a valid board for update baseline.
 * 2. Attempt to update the board with a request body that contains an extra property not defined in IBoard.IUpdate (should fail).
 * 3. Attempt to update the board with an invalid category UUID and non-boolean for is_active field (should fail).
 * 4. Attempt to update the board with an empty string for required 'name' (if 'name' is being updated).
 * 5. After each failed attempt, re-fetch the board and ensure it is unchanged.
 */
export async function test_api_discussionboard_test_update_board_invalid_fields(
  connection: api.IConnection,
) {
  // 1. Create a valid board
  const boardCategoryId = typia.random<string & tags.Format<"uuid">>();
  const sectionId = typia.random<string & tags.Format<"uuid">>();
  const createBody: IBoard.ICreate = {
    discussionboard_board_category_id: boardCategoryId,
    discussionboard_section_id: sectionId,
    name: "Test Board",
    code: "test_board_code",
    description: "This is a board created for testing invalid update fields.",
    is_active: true,
    is_visible: true,
  };
  const originalBoard = await api.functional.discussionboard.boards.create(connection, { body: createBody });
  typia.assert(originalBoard);

  // Helper: fetch latest board for validation
  async function fetchBoard() {
    // The get-by-id API is not available; so rely on values from originalBoard variable
    // (If there was a .at or .getById function: await api.functional.discussionboard.boards.at(...))
    return originalBoard;
  }

  // 2. Attempt to update the board with a non-existent property
  await TestValidator.error("API must reject updates with unknown properties")(
    async () => {
      // @ts-expect-error: Including non-schema property on purpose
      await api.functional.discussionboard.boards.update(connection, {
        id: originalBoard.id,
        body: {
          name: "Injected Invalid",
          does_not_exist: "SHOULD_ERROR", // Not in schema
        },
      });
    },
  );
  TestValidator.equals("board unchanged after failed update 1")(await fetchBoard())(originalBoard);

  // 3. Attempt to update the board with invalid UUID and non-boolean is_active
  await TestValidator.error("API must reject invalid UUID and non-boolean types")(
    async () => {
      await api.functional.discussionboard.boards.update(connection, {
        id: originalBoard.id,
        body: {
          discussionboard_board_category_id: "not-a-uuid",
          is_active: "not-boolean", // should be boolean
        } as any,
      });
    },
  );
  TestValidator.equals("board unchanged after failed update 2")(await fetchBoard())(originalBoard);

  // 4. Attempt to update the board with empty string for name
  await TestValidator.error("API must reject empty name if name is updated")(
    async () => {
      await api.functional.discussionboard.boards.update(connection, {
        id: originalBoard.id,
        body: {
          name: "",
        },
      });
    },
  );
  TestValidator.equals("board unchanged after failed update 3")(await fetchBoard())(originalBoard);
}

