 *
 * Steps:
 * 1. Create a valid engagement metric row using full data (happy path).
 *    - Confirm a new record is returned with correct types/fields populated, and that non-provided optionals default/null as expected.
 * 2. Attempt required field omissions: try creating with missing engagement_date or counts, and confirm errors occur, with no record created.
 * 3. Submit invalid values: negative values for posts_created_count, comments_created_count or votes_cast_count, or non-integers where an int is required. Each attempt should fail cleanly with no partial row.
 * 4. Edge: If uniqueness is enforced on member/board/date, attempt exact duplicate creation. Expect error, otherwise check system's behavior if duplicates are permitted.
 *
 * The test should assert that error responses never create a record and are explicit, and that happy path populates all types as documented. No invented or extra properties must be sent/received.
 */
export async function test_api_discussionboard_test_create_engagement_metric_with_valid_data_and_constraint_violations(
  connection: api.IConnection,
) {
  // 1. Happy path: valid data
  const validInput: IDiscussionboardEngagementMetric.ICreate = {
    discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
