  TestValidator.equals("engagement_date")(created.engagement_date)(validInput.engagement_date);
  TestValidator.equals("posts_created_count")(created.posts_created_count)(validInput.posts_created_count);
  TestValidator.equals("comments_created_count")(created.comments_created_count)(validInput.comments_created_count);
  TestValidator.equals("votes_cast_count")(created.votes_cast_count)(validInput.votes_cast_count);
  // New row should have id
  TestValidator.predicate("new id exists")(!!created.id && typeof created.id === "string");

