  const negativeVotes = { ...validInput, votes_cast_count: -2 };
  await TestValidator.error("negative votes_cast_count")(async () =>
    api.functional.discussionboard.engagementMetrics.create(connection, { body: negativeVotes }),
  );

  // 4. Edge: duplicate (member+board+date)
  // Create row once more with same data (should fail if unique constraint exists)
  await TestValidator.error("duplicate member+board+date")(async () =>
    api.functional.discussionboard.engagementMetrics.create(connection, { body: validInput }),
  );
}

