import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { INotificationTemplate } from "@ORGANIZATION/PROJECT-api/lib/structures/INotificationTemplate";
import type { IPageINotificationTemplate } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageINotificationTemplate";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate paginated and filtered retrieval of notification templates for the discussion board (admin-only).
 *
 * Ensures that templates can be listed using various search queries and pagination params, and that filtering by fields such as name, code, and 'is_active' works as expected. Both successful queries and queries returning no matches are covered.
 *
 * Steps:
 * 1. Setup: Create multiple notification templates with diverse names, codes and is_active values (for realistic filtering/pagination coverage)
 * 2. List: Retrieve templates with no filters, default pagination (should get all or first page of created templates)
 * 3. Filter by name keyword: Retrieve with a name substring, should get only matching templates
 * 4. Filter by is_active=false: Retrieve only inactive templates
 * 5. Pagination tests: Retrieve a subset by setting limit=1 and different pages, check correct data per page
 * 6. No-match test: Request a page with offset beyond data volume or an impossible filter, verify empty result
 * 7. For each, verify response matches the IPageINotificationTemplate schema, pagination fields are correct, and no data outside the schema shape is present
 */
export async function test_api_discussionboard_test_list_notification_templates_with_search_and_pagination(connection: api.IConnection) {
  // 1. Setup: Create multiple notification templates with diverse properties
  const templates: INotificationTemplate[] = [];
  for (const [name, code, is_active] of [
    [
      "User registration",
      "user_reg",
      true
    ],
    [
      "Account deactivation",
      "acct_deact",
      false
    ],
    [
      "Reply notification",
      "reply_ntf",
      true
    ],
    [
      "Post liked",
      "post_liked",
      true
    ],
    [
      "Admin alert",
      "admin_alert",
      false
    ]
  ]) {
    const item = await api.functional.discussionboard.notificationTemplates.create(connection, {
      body: {
        code,
        name,
        description: `${name} template`,
        subject: `${name} Subject`,
        body: `${name} Body Message`,
        is_active
      } satisfies INotificationTemplate.ICreate
    });
    typia.assert(item);
    templates.push(item);
  }

  // 2. List with no filters (should see all created templates - page=1, limit=100)
  {
    const result = await api.functional.discussionboard.notificationTemplates.index(connection, {
      body: { page: 1, limit: 100 }
    });
    typia.assert(result);
    TestValidator.predicate("should include all created templates")(
      templates.every(t => result.data.some(r => r.id === t.id))
    );
  }

  // 3. Filter by name substring (e.g., 'Reply')
  {
    const filter = templates.find(t => t.name.includes("Reply"));
    if (filter) {
      const result = await api.functional.discussionboard.notificationTemplates.index(connection, {
        body: { name: "Reply", page: 1, limit: 10 }
      });
      typia.assert(result);
      TestValidator.predicate("filtered results match name substring")(
        result.data.length > 0 && result.data.every(t => t.name.includes("Reply"))
      );
    }
  }

  // 4. Filter by is_active=false
  {
    const result = await api.functional.discussionboard.notificationTemplates.index(connection, {
      body: { is_active: false, page: 1, limit: 10 }
    });
    typia.assert(result);
    TestValidator.predicate("filtered only inactive")(
      result.data.every(t => !t.is_active)
    );
  }

  // 5. Pagination: limit=1, page 1 & 2
  {
    const result1 = await api.functional.discussionboard.notificationTemplates.index(connection, {
      body: { page: 1, limit: 1 }
    });
    typia.assert(result1);
    TestValidator.equals("only 1 per page")(1)(result1.data.length);
    const result2 = await api.functional.discussionboard.notificationTemplates.index(connection, {
      body: { page: 2, limit: 1 }
    });
    typia.assert(result2);
    TestValidator.equals("only 1 per page")(1)(result2.data.length);
    TestValidator.notEquals("templates for pages differ")(result1.data[0].id)(result2.data[0].id);
  }

  // 6. No-match (impossible filter & far page)
  {
    const result = await api.functional.discussionboard.notificationTemplates.index(connection, {
      body: { code: "no-such-template", page: 1, limit: 10 }
    });
    typia.assert(result);
    TestValidator.equals("no template matched")(0)(result.data.length);
    const farPage = await api.functional.discussionboard.notificationTemplates.index(connection, {
      body: { page: 100, limit: 10 }
    });
    typia.assert(farPage);
    TestValidator.equals("empty for non-existent page")(0)(farPage.data.length);
  }
}

