import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { Idiscussionboard_reports } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_reports";

/**
 * Validate successful creation of a new moderation report with all required fields.
 *
 * 이 테스트는 필수 및 선택 필드가 모두 채워진 상태로 moderation report가 성공적으로 생성되는지 검증합니다.
 *
 * [검증 내용]
 * 1. 신고 유형, 신고자, 대상 오브젝트 ID/타입, 상세 설명, 신고 시각 등 모든 필드를 입력하여 신고 생성
 * 2. 요청값과 응답값의 모든 필드가 일치하는지 검증
 *
 * [절차]
 * 1. moderation report용 유효 페이로드를 준비한다 (UUID, 문자열, timestamp 적합히 생성)
 * 2. POST /discussionboard/reports로 생성 요청 수행
 * 3. 반환된 오브젝트의 모든 필드가 입력과 일치하는지 TestValidator로 검증
 *
 * (별도 신고 단건 조회 API가 제공되지 않아 재조회 검증은 미수행)
 */
export async function test_api_discussionboard_test_create_moderation_report_with_valid_data(
  connection: api.IConnection,
) {
  // 1. moderation report 생성 페이로드 준비
  const payload: Idiscussionboard_reports.ICreate = {
    discussionboard_report_type_id: typia.random<string & tags.Format<"uuid">>(),
    reporting_member_id: typia.random<string & tags.Format<"uuid">>(),
    target_object_id: typia.random<string & tags.Format<"uuid">>(),
    target_object_type: "post",
    report_description: "이 게시물은 허위광고 스팸입니다.",
  };
  // ISO 8601 형식 timestamp
  const reported_at: string & tags.Format<"date-time"> = new Date().toISOString() as string & tags.Format<"date-time">;

  // 2. moderation report 생성 API 호출
  const result = await api.functional.discussionboard.reports.create(connection, {
    body: {
      ...payload,
      reported_at,
    },
  });
  typia.assert(result);

  // 3. 반환값: 입력 필드가 모두 일치해야 함 (ID/Payload validation)
  TestValidator.equals("신고 유형 matches")(result.discussionboard_report_type_id)(payload.discussionboard_report_type_id);
  TestValidator.equals("신고자 matches")(result.reporting_member_id)(payload.reporting_member_id);
  TestValidator.equals("대상 오브젝트 ID matches")(result.target_object_id)(payload.target_object_id);
  TestValidator.equals("타입 matches")(result.target_object_type)(payload.target_object_type);
  TestValidator.equals("상세 설명 matches")(result.report_description)(payload.report_description);
  TestValidator.equals("신고 시각 matches")(result.reported_at)(reported_at);
}

