import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardChannel";
import type { IDiscussionboardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSection";

/**
 * E2E test for permanently deleting a discussion board section by its ID.
 *
 * This test verifies that after a section is created and then permanently deleted, the section is truly removed and cannot be fetched anymore. The test flows through the actual business process of channel and section creation, followed by permanent deletion and error-checking for retrieval post-deletion.
 *
 * Workflow:
 * 1. Create a new discussion board channel (required for parent relationship).
 * 2. Create a new section under the created channel.
 * 3. Permanently delete the created section by ID.
 * 4. Verify the delete API returns { success: true } and correct section ID.
 * 5. Attempt to retrieve the deleted section by ID and expect an error (not found).
 */
export async function test_api_discussionboard_test_delete_section_permanently(
  connection: api.IConnection,
) {
  // 1. Create a new channel - prerequisite for creating a section
  const channelInput = {
    code: RandomGenerator.alphaNumeric(6),
    name: RandomGenerator.paragraph()(1),
    description: null,
    position: 1,
    active: true,
  } satisfies IDiscussionboardChannel.ICreate;
  const channel = await api.functional.discussionboard.channels.create(
    connection,
    { body: channelInput },
  );
  typia.assert(channel);

  // 2. Create a new section in the created channel
  const sectionInput = {
    discussionboard_channel_id: channel.id,
    code: RandomGenerator.alphaNumeric(6),
    name: RandomGenerator.paragraph()(1),
    description: null,
    position: 1,
    active: true,
  } satisfies IDiscussionboardSection.ICreate;
  const section = await api.functional.discussionboard.sections.create(
    connection,
    { body: sectionInput },
  );
  typia.assert(section);

  // 3. Permanently delete the created section by id
  const deleteResult = await api.functional.discussionboard.sections.erase(
    connection,
    { id: section.id },
  );
  typia.assert(deleteResult);
  TestValidator.equals("deletion success")(deleteResult.success)(true);
  TestValidator.equals("deleted section id")(deleteResult.id)(section.id);

  // 4. Attempt to fetch the deleted section by id (should fail/not found)
  await TestValidator.error("deleted section should not be found")(() =>
    api.functional.discussionboard.sections.at(connection, { id: section.id }),
  );
}

