 *
 * Steps:
 * 1. Attempt to search using a filter property not present in the allowed schema (e.g., { non_existent_field: "value" })
 * 2. Assert that the endpoint rejects the request—triggering an error due to schema validation failure
 * 3. Confirm no results are returned, and the error is specifically a schema/type validation rejection
 */
export async function test_api_discussionboard_test_list_sections_with_invalid_filters(
  connection: api.IConnection,
) {
  // Step 1: Attempt to search with an invalid (schema-forbidden) filter property
  await TestValidator.error("should fail on non-schema filter causes validation error")(
    async () => {
      // Intentionally bypassing TypeScript check to simulate client misuse of API contract. This must fail server-side.
      // @ts-expect-error - purposely injecting a non-schema property to test validation enforcement
      await api.functional.discussionboard.sections.index(connection, {
        body: {
          non_existent_field: "schema violation trigger",
        },
      });
    },
  );
}

