import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IMemberProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberProfile";

/**
 * Validate failure cases when updating a member profile with invalid data.
 *
 * This test ensures that the system correctly rejects updates when invalid field
 * types or unsupported extra properties are provided in a PUT request to update
 * a member profile. It covers the following scenarios:
 *
 * 1. Successfully create a discussion board member, which initializes a profile
 *    (profile ID assumed identical to the new member's ID).
 * 2. Update the member's profile with valid data so the expected state is known.
 * 3. Attempt to update the member's profile with:
 *    a. Fields with incorrect types (e.g., number for display_name, boolean for bio).
 *    b. A payload including extra unsupported properties.
 *    c. Null value for required field (display_name).
 * 4. Assert all invalid attempts fail with validation errors using TestValidator.error.
 * 5. Confirm (if profile fetch API exists) that the profile remains unchanged after failed updates.
 *
 * This guards API input validation robustness and schema enforcement for the
 * profile update endpoint.
 */
export async function test_api_discussionboard_test_update_member_profile_invalid_fields(
  connection: api.IConnection,
) {
  // 1. Create a valid member to obtain a profile for updates.
  const memberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphabets(16),
    role: "member",
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 2. Set the profile to a valid state first.
  const validUpdate: IMemberProfile.IUpdate = {
    display_name: RandomGenerator.alphabets(10),
    bio: "Original bio",
    avatar_url: null,
    location: "Seoul",
    website_url: "https://example.com",
  };
  const validProfile = await api.functional.discussionboard.memberProfiles.update(connection, { id: member.id, body: validUpdate });
  typia.assert(validProfile);

  // 3a. Invalid: display_name as a number
  await TestValidator.error("display_name as number should fail")(
    () => api.functional.discussionboard.memberProfiles.update(connection, {
      id: member.id,
      body: {
        ...validUpdate,
        display_name: 12345 as any,
      },
    })
  );

  // 3b. Invalid: Extra unsupported field
  await TestValidator.error("extra field should fail")(
    () => api.functional.discussionboard.memberProfiles.update(connection, {
      id: member.id,
      body: {
        ...validUpdate,
        randomField: "not allowed" as any,
      },
    })
  );

  // 3c. Invalid: Null required display_name
  await TestValidator.error("display_name null should fail")(
    () => api.functional.discussionboard.memberProfiles.update(connection, {
      id: member.id,
      body: {
        ...validUpdate,
        display_name: null as any,
      },
    })
  );

  // 3d. Invalid: bio as boolean
  await TestValidator.error("bio as boolean should fail")(
    () => api.functional.discussionboard.memberProfiles.update(connection, {
      id: member.id,
      body: {
        ...validUpdate,
        bio: false as any,
      },
    })
  );

  // 4. (Optional) Fetch again to confirm unchanged state if getter exists.
  // If such API is implemented, fetch and compare:
  // TestValidator.equals("profile unchanged")(/* actual output */)(validProfile);
}

