import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardNotification";

/**
 * Validate retrieval of a single notification log record by id, including success and error scenarios.
 *
 * Business context:
 * This test ensures that the API can fetch a notification record with a valid id and that the returned data conforms to the expected schema, including all required and optional fields. It also ensures robust error handling by testing a request using a non-existent or invalid id, expecting a 404 error response. Since notification management may be permissioned, the test should assume roles with appropriate access rights.
 *
 * Step-by-step process:
 * 1. Create a new notification using the POST /discussionboard/notifications API to obtain a valid id.
 * 2. Fetch the notification by id with GET /discussionboard/notifications/{id} and assert the returned object matches all expected schema properties.
 * 3. Use TestValidator.equals for field-by-field (or full object) validation.
 * 4. Attempt to GET a notification with an obviously invalid or random uuid (guaranteed non-existent) and use TestValidator.error to validate a 404 error occurs.
 * 5. (Assume permission context: If relevant, ensure operation as a role with permission to access notification records, e.g., admin/moderator.)
 */
export async function test_api_discussionboard_test_get_notification_by_valid_and_invalid_id(connection: api.IConnection) {
  // 1. Create a notification
  const notificationInput: IDiscussionboardNotification.ICreate = {
    type: "system_announcement",
    title: RandomGenerator.paragraph()(5),
    delivered: true,
    created_at: new Date().toISOString(),
    body: RandomGenerator.content()()(),
    delivered_at: new Date().toISOString(),
    target_id: typia.random<string & tags.Format<"uuid">>(),
  };
  const created = await api.functional.discussionboard.notifications.create(connection, { body: notificationInput });
  typia.assert(created);

  // 2. Fetch by id and validate schema & property accuracy
  const fetched = await api.functional.discussionboard.notifications.at(connection, { id: created.id });
  typia.assert(fetched);
  // Field-by-field validation
  TestValidator.equals("type")(fetched.type)(notificationInput.type);
  TestValidator.equals("title")(fetched.title)(notificationInput.title);
  TestValidator.equals("body")(fetched.body)(notificationInput.body);
  TestValidator.equals("delivered")(fetched.delivered)(notificationInput.delivered);
  // target_id is optional, but included in this case
  TestValidator.equals("target_id")(fetched.target_id)(notificationInput.target_id);
  // created_at and delivered_at can have minor diffs (truncated ms); check validity
  TestValidator.predicate("created_at looks ISO 8601")(!!Date.parse(fetched.created_at));
  if (notificationInput.delivered_at)
    TestValidator.predicate("delivered_at looks ISO 8601")(!!Date.parse(fetched.delivered_at ?? undefined));

  // 3. Try fetching with invalid ID and expect 404 error
  const invalidId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("Not found for invalid id")(() => api.functional.discussionboard.notifications.at(connection, { id: invalidId }));
}

