 * 1. 스레드와 태그 할당 엔티티를 선행 생성합니다.
 * 2. removed_at 필드를 현재 시각으로 지정하여 태그 할당을 "제거됨" 처리하고, 필드 변경이 정상적으로 반영되는지 확인합니다.
 * 3. removed_at 필드를 지우고(omit) 정상적으로 타임스탬프가 제거되는지 확인합니다.
 * 4. 할당되지 않은(random uuid) 태그 할당에 업데이트를 시도하여 에러(존재하지 않는 id) 발생을 검증합니다.
 * 5. update DTO가 허용하는 removed_at 외에는 변화가 발생하지 않는 점을 보장합니다.
 */
export async function test_api_discussionboard_threadTags_test_update_thread_tag_assignment_set_removed_at_and_edit_assignment_fields(
  connection: api.IConnection,
) {
  // 1. 스레드 엔티티 생성 (의존성)
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: typia.random<string & tags.Format<"uuid">>(),
      author_member_id: typia.random<string & tags.Format<"uuid">>(),
      title: "태그 업데이트 테스트 스레드",
      body: "스레드 태그 할당 업데이트 E2E.",
    },
  });
  typia.assert(thread);

  // 2. 태그 할당 생성 (의존성)
  const tagAssignment = await api.functional.discussionboard.threadTags.create(connection, {
    body: {
      thread_id: thread.id,
      assigned_at: new Date().toISOString(),
    },
  });
  typia.assert(tagAssignment);

  // 3. removed_at 업데이트: 할당 해제
  const removedAt = new Date().toISOString();
  const updated1 = await api.functional.discussionboard.threadTags.update(connection, {
    id: tagAssignment.id,
    body: { removed_at: removedAt },
  });
  typia.assert(updated1);
  TestValidator.equals("removed_at 변경됨")(updated1.removed_at)(removedAt);
  TestValidator.equals("id 불변")(updated1.id)(tagAssignment.id);
  TestValidator.equals("assigned_at 불변")(updated1.assigned_at)(tagAssignment.assigned_at);

  // 4. removed_at 필드를 omit(생략)하여 값이 지워지는지 확인(타입상 null 불가)
  const updated2 = await api.functional.discussionboard.threadTags.update(connection, {
    id: tagAssignment.id,
    body: {}, // removed_at 필드를 아예 보내지 않음
  });
  typia.assert(updated2);
  TestValidator.equals("removed_at 유지")(updated2.removed_at)(updated1.removed_at);
  TestValidator.equals("assigned_at 유지")(updated2.assigned_at)(updated1.assigned_at);

  // 5. 음수 시나리오: 존재하지 않는 id 업데이트 시도시 에러 반환
  await TestValidator.error("없는 태그 할당 업데이트 시 에러")(() =>
    api.functional.discussionboard.threadTags.update(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { removed_at: new Date().toISOString() },
    }),
  );
}

