import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardChannel";

/**
 * Permanently delete an existing discussion board channel by id and confirm its removal.
 *
 * This test ensures that when a channel is created and then deleted using the DELETE endpoint,
 * the service truly removes the channel. Subsequently, any attempt to retrieve the deleted channel
 * should result in a 404 error, confirming that the deletion is irreversible.
 *
 * Workflow Steps:
 * 1. Create a new channel (POST /discussionboard/channels) with valid test data.
 * 2. Permanently delete the channel using DELETE /discussionboard/channels/{id}.
 * 3. Assert the delete response indicates success and the deleted id matches.
 * 4. Attempt to retrieve the now-deleted channel (GET /discussionboard/channels/{id}) and expect failure.
 */
export async function test_api_discussionboard_channels_test_delete_channel_by_id_when_exists(
  connection: api.IConnection,
) {
  // 1. Create a new discussion board channel to delete
  const created = await api.functional.discussionboard.channels.create(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(6),
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(),
      position: typia.random<number & tags.Type<"int32">>(),
      active: true,
    } satisfies IDiscussionboardChannel.ICreate,
  });
  typia.assert(created);

  // 2. Delete the newly created channel by id
  const deleteResult = await api.functional.discussionboard.channels.erase(connection, {
    id: created.id,
  });
  typia.assert(deleteResult);
  TestValidator.equals("delete success")(deleteResult.success)(true);
  TestValidator.equals("deleted id matches")(deleteResult.id)(created.id);

  // 3. Try to fetch the now-deleted channel, which must fail (404)
  await TestValidator.error("fetching deleted channel should fail")(() =>
    api.functional.discussionboard.channels.at(connection, { id: created.id }),
  );
}

