import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { INotificationTemplate } from "@ORGANIZATION/PROJECT-api/lib/structures/INotificationTemplate";

/**
 * Test permanent deletion of a notification template by ID.
 *
 * This test covers: (1) creating a notification template, (2) hard-deleting it via the API, (3) verifying it cannot be retrieved (should return not found after deletion), and (4) confirming other templates remain unaffected.
 *
 * 1. Create a notification template to be deleted ("target")
 * 2. Create a second notification template ("control") which should not be deleted
 * 3. Delete the first template (target)
 * 4. Attempt to get the deleted template and assert not found error thrown
 * 5. (Optional: if GET/list API exists in future) Ensure that the second template still exists
 */
export async function test_api_discussionboard_test_delete_notification_template_successful(
  connection: api.IConnection,
) {
  // 1. Create the target notification template
  const targetTemplate = await api.functional.discussionboard.notificationTemplates.create(
    connection,
    {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        name: RandomGenerator.alphabets(12),
        description: RandomGenerator.paragraph()(),
        subject: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
        is_active: true,
      } satisfies INotificationTemplate.ICreate,
    },
  );
  typia.assert(targetTemplate);

  // 2. Create another template as a control
  const controlTemplate = await api.functional.discussionboard.notificationTemplates.create(
    connection,
    {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        name: RandomGenerator.alphabets(12),
        description: RandomGenerator.paragraph()(),
        subject: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
        is_active: true,
      } satisfies INotificationTemplate.ICreate,
    },
  );
  typia.assert(controlTemplate);

  // 3. Delete the target template
  await api.functional.discussionboard.notificationTemplates.erase(
    connection,
    { id: targetTemplate.id },
  );

  // 4. Verify the deleted template cannot be retrieved
  await TestValidator.error("deleted template cannot be found")(async () => {
    await api.functional.discussionboard.notificationTemplates.at(
      connection,
      { id: targetTemplate.id },
    );
  });

  // 5. The control template should still exist (if GET API is available)
  // If a GET API for controlTemplate exists, validate it is still retrievable
  /*
  const controlReloaded = await api.functional.discussionboard.notificationTemplates.at(
    connection,
    { id: controlTemplate.id },
  );
  typia.assert(controlReloaded);
  TestValidator.equals("control remains")(controlReloaded.id)(controlTemplate.id);
  */
}

