import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";

/**
 * Validate that member creation fails if required fields are missing.
 *
 * This test checks that the API enforces required fields (username, email, hashed_password, role, is_active)
 * when creating a new discussion board member. For each required field, it attempts to create a member
 * with that field missing from the request body. It expects that the API responds with a validation error,
 * and no member is created in these cases (assuming server-side checks, as there is no list API to verify creation).
 *
 * Steps:
 * 1. Prepare a valid member creation request body.
 * 2. For each required field, attempt creation with that field omitted.
 * 3. For each case, assert that the API throws an error (runtime validation failure).
 * 4. Do not check for record creation as no list/search API exists; rely on error response only.
 */
export async function test_api_discussionboard_test_create_member_missing_required_fields(
  connection: api.IConnection,
) {
  // 1. Prepare a valid body
  const validBody: api.IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(32),
    role: "member",
    is_active: true,
  };

  // 2. Each required field is omitted in turn and error is expected

  // a) Missing username
  await TestValidator.error("Missing username should fail")(() =>
    api.functional.discussionboard.members.create(connection, {
      body: { ...validBody, username: undefined as any },
    }),
  );

  // b) Missing email
  await TestValidator.error("Missing email should fail")(() =>
    api.functional.discussionboard.members.create(connection, {
      body: { ...validBody, email: undefined as any },
    }),
  );

  // c) Missing hashed_password
  await TestValidator.error("Missing hashed_password should fail")(() =>
    api.functional.discussionboard.members.create(connection, {
      body: { ...validBody, hashed_password: undefined as any },
    }),
  );

  // d) Missing role
  await TestValidator.error("Missing role should fail")(() =>
    api.functional.discussionboard.members.create(connection, {
      body: { ...validBody, role: undefined as any },
    }),
  );

  // e) Missing is_active
  await TestValidator.error("Missing is_active should fail")(() =>
    api.functional.discussionboard.members.create(connection, {
      body: { ...validBody, is_active: undefined as any },
    }),
  );
}

