import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { INotificationTemplate } from "@ORGANIZATION/PROJECT-api/lib/structures/INotificationTemplate";

/**
 * Validate the creation of a notification template with valid data through the admin privilege API.
 *
 * This test ensures the following:
 * 1. Providing all required fields creates a notification template successfully.
 * 2. Returned object contains autogenerated fields (`id`, `created_at`, `updated_at`).
 * 3. Business logic is enforced (the `code` is unique, only admin can create).
 *
 * Detailed Steps:
 * 1. Prepare valid notification template data including all required fields.
 * 2. Call the create notification template API as an administrator.
 * 3. Assert that the returned object contains:
 *    - All values matching the input.
 *    - Autogenerated fields present (with valid formats for `id`, `created_at`, `updated_at`).
 * 4. Attempt to create a template with the same `code` and verify that a business error is thrown enforcing uniqueness.
 * 5. Optionally, simulate a call as a non-admin and verify permission is denied (if possible in the provided API/SDK context).
 */
export async function test_api_discussionboard_test_create_notification_template_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Prepare valid input data
  const templateInput: INotificationTemplate.ICreate = {
    code: `nt-code-${typia.random<number & tags.Format<"uint32">>()}`,
    name: `Template ${RandomGenerator.paragraph()(1)}`,
    description: RandomGenerator.paragraph()(1),
    subject: `Subject: ${RandomGenerator.paragraph()(1)}`,
    body: `Body: ${RandomGenerator.content()()()}`,
    is_active: true,
  };

  // 2. Call the create notification template API as an admin
  const createdTemplate = await api.functional.discussionboard.notificationTemplates.create(
    connection,
    { body: templateInput },
  );
  typia.assert(createdTemplate);

  // 3. Assert all result fields
  TestValidator.equals("code matches")(createdTemplate.code)(templateInput.code);
  TestValidator.equals("name matches")(createdTemplate.name)(templateInput.name);
  TestValidator.equals("description matches")(createdTemplate.description)(templateInput.description);
  TestValidator.equals("subject matches")(createdTemplate.subject)(templateInput.subject);
  TestValidator.equals("body matches")(createdTemplate.body)(templateInput.body);
  TestValidator.equals("is_active matches")(createdTemplate.is_active)(templateInput.is_active);

  // Autogenerated fields format assertion
  typia.assert<string & tags.Format<"uuid">>(createdTemplate.id);
  typia.assert<string & tags.Format<"date-time">>(createdTemplate.created_at);
  typia.assert<string & tags.Format<"date-time">>(createdTemplate.updated_at);

  // 4. Try to create another template with the same code to check unique constraint enforcement
  TestValidator.error("duplicate code should fail")(() =>
    api.functional.discussionboard.notificationTemplates.create(connection, {
      body: { ...templateInput, name: templateInput.name + " (duplicate)" },
    })
  );
  // 5. (Optional) Attempt as non-admin is not implemented unless a method for changing privilege is provided.
}

