/**
 * Validate that the board update API rejects requests where invalid values are provided for schema-defined fields.
 *
 * This test checks error scenarios for update:
 * 1. Attempt to update the board with invalid UUID format (for category ID).
 * 2. Attempt to update boolean fields with incorrect types (e.g., string instead of boolean).
 * 3. Attempt to update the board with empty string for the required 'name' (if updated).
 * The API should respond with validation errors for these cases, and no board should be updated.
 *
 * Steps:
 * 1. Create a valid board for update baseline.
 * 2. Try to update with an invalid category UUID (should fail).
 * 3. Try to update 'is_active' and/or 'is_visible' with invalid types (should fail).
 * 4. Try to update 'name' with an empty string (should fail, if business logic applies).
 * 5. After each failed attempt, re-validate board hasn't changed from creation.
 */
export async function test_api_discussionboard_test_update_board_invalid_fields(
  connection: api.IConnection,
) {
  // 1. Create a valid board
  const boardCategoryId = typia.random<string & tags.Format<"uuid">>();
  const sectionId = typia.random<string & tags.Format<"uuid">>();
  const createBody: IBoard.ICreate = {
    discussionboard_board_category_id: boardCategoryId,
    discussionboard_section_id: sectionId,
    name: "Test Board",
    code: "test_board_code",
    description: "This is a board created for testing invalid update fields.",
    is_active: true,
    is_visible: true,
  };
  const originalBoard = await api.functional.discussionboard.boards.create(connection, { body: createBody });
  typia.assert(originalBoard);

  // Helper: fetch latest board for validation (can't actually re-fetch by id, so use originalBoard)
  async function fetchBoard() { return originalBoard; }

  // 2. Attempt to update the board with an invalid category UUID
  await TestValidator.error("API must reject invalid UUID for category")(
    async () => {
      await api.functional.discussionboard.boards.update(connection, {
        id: originalBoard.id,
        body: {
          discussionboard_board_category_id: "not-a-uuid" as any, // Simulate invalid UUID at runtime
        } as any, // Unavoidable for runtime invalid value injection, but remove if strictly forbidden
      });
    },
  );
  TestValidator.equals("board unchanged after failed update 1")(await fetchBoard())(originalBoard);

  // 3. Attempt to update 'is_active' and 'is_visible' with invalid types
  await TestValidator.error("API must reject non-boolean for is_active/is_visible")(
    async () => {
      await api.functional.discussionboard.boards.update(connection, {
        id: originalBoard.id,
        body: {
          is_active: "string-instead-of-boolean" as any, // Simulate bad input at runtime
          is_visible: 1234 as any,
        } as any,
      });
    },
  );
  TestValidator.equals("board unchanged after failed update 2")(await fetchBoard())(originalBoard);

  // 4. Attempt to update the board with empty string for 'name'
  await TestValidator.error("API must reject empty string for name")(
    async () => {
      await api.functional.discussionboard.boards.update(connection, {
        id: originalBoard.id,
        body: {
          name: "",
        },
      });
