import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { Idiscussionboard_reports } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_reports";
import type { IPageIdiscussionboard_reports } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIdiscussionboard_reports";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate pagination, filtering, and error handling on moderation report list endpoint.
 *
 * This test ensures that filtering and paginating moderation reports works as intended,
 * and that only valid schema fields are accepted in filter input.
 *
 * 1. Create several reports with varied types, reporting members, and targets as test data.
 * 2. For each filter (report_type, member, target, etc.), call the report list API and assert only matching reports are returned.
 * 3. Confirm pagination fields and record count are correct.
 * 4. Attempt to use an unsupported filter property, and expect an error to confirm schema strictness.
 * 5. Attempt to use an invalid value format for a filter field (e.g., non-uuid where uuid required), and expect an error.
 */
export async function test_api_discussionboard_reports_test_list_moderation_reports_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create several reports with unique type, member, target, and description/date
  const reports: Idiscussionboard_reports[] = [];
  for (let i = 0; i < 6; ++i) {
    // Synthesize unique attributes for each report
    const report_type_id = typia.random<string & tags.Format<"uuid">>();
    const reporting_member_id = typia.random<string & tags.Format<"uuid">>();
    const target_object_id = typia.random<string & tags.Format<"uuid">>();
    const target_object_type = ["post", "comment", "member"][i % 3];
    const report_description = `desc_${RandomGenerator.alphabets(5)}_${i}`;
    const now = new Date();
    const dt = new Date(now.getTime() - (i * 3600 * 1000));
    const reported_at = dt.toISOString();
    const created: Idiscussionboard_reports = await api.functional.discussionboard.reports.create(connection, {
      body: {
        discussionboard_report_type_id: report_type_id,
        reporting_member_id,
        target_object_id,
        target_object_type,
        report_description,
      },
    });
    typia.assert(created);
    // Update reported_at via direct patch not supported, so accept generated value
    reports.push({ ...created, reported_at: created.reported_at });
  }

  // 2. Test filter by report_type
  {
    const pick = RandomGenerator.pick(reports);
    const res = await api.functional.discussionboard.reports.index(connection, {
      body: {
        discussionboard_report_type_id: pick.discussionboard_report_type_id,
      },
    });
    typia.assert(res);
    TestValidator.predicate("type filter")(
      res.data.every(r => r.discussionboard_report_type_id === pick.discussionboard_report_type_id),
    );
  }

  // 3. Test filter by reporting_member_id
  {
    const pick = RandomGenerator.pick(reports);
    const res = await api.functional.discussionboard.reports.index(connection, {
      body: {
        reporting_member_id: pick.reporting_member_id,
      },
    });
    typia.assert(res);
    TestValidator.predicate("reporting_member filter")(
      res.data.every(r => r.reporting_member_id === pick.reporting_member_id),
    );
  }

  // 4. Test filter by target_object_id
  {
    const pick = RandomGenerator.pick(reports);
    const res = await api.functional.discussionboard.reports.index(connection, {
      body: {
        target_object_id: pick.target_object_id,
      },
    });
    typia.assert(res);
    TestValidator.predicate("target_object_id filter")(
      res.data.every(r => r.target_object_id === pick.target_object_id),
    );
  }

  // 5. Test filter by target_object_type
  {
    const pick = RandomGenerator.pick(reports);
    const res = await api.functional.discussionboard.reports.index(connection, {
      body: {
        target_object_type: pick.target_object_type,
      },
    });
    typia.assert(res);
    TestValidator.predicate("target_object_type filter")(
      res.data.every(r => r.target_object_type === pick.target_object_type),
    );
  }

  // 6. Test filter by report_description
  {
    const pick = RandomGenerator.pick(reports);
    const res = await api.functional.discussionboard.reports.index(connection, {
      body: {
        report_description: pick.report_description,
      },
    });
    typia.assert(res);
    TestValidator.predicate("report_description filter")(
      res.data.every(r => r.report_description === pick.report_description),
    );
  }

  // 7. Test filter by reported_at
  {
    const pick = RandomGenerator.pick(reports);
    const res = await api.functional.discussionboard.reports.index(connection, {
      body: {
        reported_at: pick.reported_at,
      },
    });
    typia.assert(res);
    TestValidator.predicate("reported_at filter")(
      res.data.every(r => r.reported_at === pick.reported_at),
    );
  }

  // 8. Test combined filters
  {
    const pick = RandomGenerator.pick(reports);
    const res = await api.functional.discussionboard.reports.index(connection, {
      body: {
        discussionboard_report_type_id: pick.discussionboard_report_type_id,
        reporting_member_id: pick.reporting_member_id,
        target_object_id: pick.target_object_id,
        target_object_type: pick.target_object_type,
        report_description: pick.report_description,
        reported_at: pick.reported_at,
      },
    });
    typia.assert(res);
    // Only the exact report expected, if unique
    TestValidator.predicate("combined filter")(
      res.data.some(r => r.id === pick.id),
    );
  }

  // 9. Test pagination (limit=2, page=1)
  {
    // As page/limit not directly in schema, but IPageIdiscussionboard_reports.pagination is returned,
    // infer this is handled internally or via system values; but filters can be made unique to reduce result count.
