import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoard";
import type { IPageIBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBoard";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing of boards with filter and pagination parameters.
 *
 * This test ensures the board listing API correctly implements business filtering and result validation, covering:
 *   1. Board creation with varied categories, sections, attributes
 *   2. No-filter: All boards should appear
 *   3. Filtering by exact category/section/code (unique result)
 *   4. Filtering by is_active/is_visible
 *   5. Searching by substring in name
 *   6. Filter expected to yield zero results (random ids)
 *   7. Paginated result: structure/metadata is checked (cannot directly change limit/page)
 *   8. Out-of-bounds paging: only structure can be checked, as no such param exists in schema
 *
 * This covers both success and empty/failure edge cases.
 */
export async function test_api_discussionboard_test_list_boards_with_filter_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create boards with known values
  const categories = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>()
  ];
  const sections = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>()
  ];
  const boards = [
    await api.functional.discussionboard.boards.create(connection, {
      body: {
        discussionboard_board_category_id: categories[0],
        discussionboard_section_id: sections[0],
        name: "Alpha Forum",
        code: "alpha_forum",
        description: "Test board alpha.",
        is_active: true,
        is_visible: true,
      }
    }),
    await api.functional.discussionboard.boards.create(connection, {
      body: {
        discussionboard_board_category_id: categories[1],
        discussionboard_section_id: sections[0],
        name: "Beta Lounge",
        code: "beta_lounge",
        description: "Test board beta.",
        is_active: false,
        is_visible: true,
      }
    }),
    await api.functional.discussionboard.boards.create(connection, {
      body: {
        discussionboard_board_category_id: categories[0],
        discussionboard_section_id: sections[1],
        name: "Gamma Club",
        code: "gamma_club",
        description: "Test board gamma.",
        is_active: true,
        is_visible: false,
      }
    }),
    await api.functional.discussionboard.boards.create(connection, {
      body: {
        discussionboard_board_category_id: categories[1],
        discussionboard_section_id: sections[1],
        name: "Delta Room",
        code: "delta_room",
        description: "Test board delta.",
        is_active: false,
        is_visible: false,
      }
    }),
  ];
  boards.forEach(typia.assert);

  // 2. List all (no filter) and check all present
  const pageAll = await api.functional.discussionboard.boards.index(connection, {
    body: {}
  });
  typia.assert(pageAll);
  boards.forEach((created) => {
    TestValidator.predicate("created board exists in all")(pageAll.data.some(x => x.id === created.id));
  });

  // 3. Filter by category+section+code (should only match one)
  const boardToFilter = boards[1];
  const exactFilter = await api.functional.discussionboard.boards.index(connection, {
    body: {
      board_category_id: boardToFilter.discussionboard_board_category_id,
      section_id: boardToFilter.discussionboard_section_id,
      code: boardToFilter.code
    }
  });
  typia.assert(exactFilter);
  TestValidator.equals("exact filter yields one")(exactFilter.data.length)(1);
  TestValidator.equals("correct exact board")(exactFilter.data[0].id)(boardToFilter.id);

  // 4. Filter by is_active
  const actives = boards.filter(b => b.is_active);
  const activeList = await api.functional.discussionboard.boards.index(connection, {
    body: { is_active: true }
  });
  typia.assert(activeList);
  TestValidator.predicate("only is_active: true returned")(activeList.data.every(b => b.is_active === true));
  actives.forEach((expect) => {
    TestValidator.predicate("active matches returned")(activeList.data.some(x => x.id === expect.id));
  });

  // 5. Filter by is_visible
  const visibles = boards.filter(b => b.is_visible);
  const visibleList = await api.functional.discussionboard.boards.index(connection, {
    body: { is_visible: true }
  });
  typia.assert(visibleList);
  TestValidator.predicate("only is_visible: true returned")(visibleList.data.every(b => b.is_visible === true));
  visibles.forEach((expect) => {
    TestValidator.predicate("visible matches returned")(visibleList.data.some(x => x.id === expect.id));
  });

  // 6. Filter by name substring
  const alphaPage = await api.functional.discussionboard.boards.index(connection, {
    body: { name: "Alpha" }
  });
  typia.assert(alphaPage);
  TestValidator.predicate("name filter matches")(alphaPage.data.every(b => b.name.includes("Alpha")));

  // 7. Ensure empty results for non-existent random ids
  const none = await api.functional.discussionboard.boards.index(connection, {
    body: {
      board_category_id: typia.random<string & tags.Format<"uuid">>(),
      section_id: typia.random<string & tags.Format<"uuid">>()
    }
  });
  typia.assert(none);
  TestValidator.equals("empty filter yields zero")(none.data.length)(0);

  // 8. Paginated result/metadata structure check
  const paged = await api.functional.discussionboard.boards.index(connection, {
    body: {}
  });
  typia.assert(paged);
  TestValidator.equals("failsafe, all data present")(paged.data.length >= boards.length)(true);
  TestValidator.predicate("pagination meta type")(typeof paged.pagination.current === "number" && typeof paged.pagination.limit === "number");

  // 9. Out-of-bounds page: As IRequest does not support page param, cannot test
}

