import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardActivityLog";
import type { IPageIDiscussionboardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardActivityLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for paginated and filtered retrieval of activity logs in discussion board.
 *
 * This test verifies correct filtering by event type, member, date range, and related entities (board, thread, post, comment).
 * It also validates that only schema-defined fields are accepted as filters, and improper fields or invalid types are gracefully rejected.
 * Pagination correctness and filter combinatorics for audit/review scenarios are fully exercised.
 *
 * Steps:
 * 1. Query activity logs with no filters (default page/limit), expect valid page/data.
 * 2. Query with event_type filter (all results match).
 * 3. Query with each entity (member, board, thread, post, comment) as filter; all results must match value.
 * 4. Query with time range (event_timestamp_from/to) and assert all in bounds.
 * 5. Query with all available filters combined.
 * 6. Pagination sanity checks (limit/page values & data slicing/no overlap).
 * 7. Attempt non-schema/unauthorized filter fields (error expected).
 * 8. Attempt invalid filter values for schema fields (error expected).
 */
export async function test_api_discussionboard_test_list_activity_logs_with_various_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Query all activity logs (no filter)
  const page1 = await api.functional.discussionboard.activityLogs.index(connection, {
    body: {},
  });
  typia.assert(page1);
  TestValidator.predicate('pagination metadata exists')(
    !!page1.pagination && Array.isArray(page1.data),
  );

  // Early exit: Skip filter tests if no data
  if (!page1.data.length) return;
  const sample = page1.data[0];

  // 2. Filter by event_type
  if (sample.event_type) {
    const etype = sample.event_type;
    const resp2 = await api.functional.discussionboard.activityLogs.index(connection, {
      body: { event_type: etype },
    });
    typia.assert(resp2);
    TestValidator.predicate('event_type filter')(resp2.data.every(l => l.event_type === etype));
  }

  // 3. Each entity id filter (skip null cases)
  type FilterTuple = [keyof IDiscussionboardActivityLog.IRequest, string];
  const entityFields: FilterTuple[] = [
    ['discussionboard_member_id', sample.discussionboard_member_id],
    ['discussionboard_board_id', sample.discussionboard_board_id],
    ['discussionboard_thread_id', sample.discussionboard_thread_id],
    ['discussionboard_post_id', sample.discussionboard_post_id],
    ['discussionboard_comment_id', sample.discussionboard_comment_id],
  ].filter(([_, v]) => !!v);

  for (const [field, val] of entityFields) {
    const req: Partial<IDiscussionboardActivityLog.IRequest> = { [field]: val };
    const resp = await api.functional.discussionboard.activityLogs.index(connection, {
      body: req,
    });
    typia.assert(resp);
    TestValidator.predicate(`${field} filter`)(resp.data.every(l => l[field] === val));
  }

  // 4. Filter by event_timestamp range
  const ts = sample.event_timestamp;
  const from = new Date(new Date(ts).getTime() - 1000).toISOString();
  const to = new Date(new Date(ts).getTime() + 1000).toISOString();
  const resp4 = await api.functional.discussionboard.activityLogs.index(connection, {
    body: { event_timestamp_from: from, event_timestamp_to: to },
  });
  typia.assert(resp4);
  TestValidator.predicate('timestamps in range')(
    resp4.data.every(
      (l) => new Date(l.event_timestamp) >= new Date(from) && new Date(l.event_timestamp) <= new Date(to),
    ),
  );

  // 5. Combination of all available filters (fields present in sample)
  const comboBody: Partial<IDiscussionboardActivityLog.IRequest> = { event_type: sample.event_type };
  for (const [field, val] of entityFields) comboBody[field] = val;
  const comboResp = await api.functional.discussionboard.activityLogs.index(connection, {
    body: comboBody,
  });
  typia.assert(comboResp);
  for (const [field, val] of Object.entries(comboBody)) {
    if (val !== undefined && val !== null)
      TestValidator.predicate(`${field} combo filter matches`)(comboResp.data.every(l => l[field] === val));
  }

  // 6. Pagination: limit/page and cross-page uniqueness
  const onePage = await api.functional.discussionboard.activityLogs.index(connection, {
    body: { limit: 1, page: 1 },
  });
  typia.assert(onePage);
  TestValidator.equals('paginated limit')(onePage.pagination.limit)(1);
  TestValidator.equals('current page')(onePage.pagination.current)(1);
  TestValidator.equals('data slice length')(onePage.data.length)(Math.min(1, page1.data.length));
  if (page1.data.length > 1) {
    const twoPage = await api.functional.discussionboard.activityLogs.index(connection, {
      body: { limit: 1, page: 2 },
    });
    typia.assert(twoPage);
    TestValidator.equals('page 2 index')(twoPage.pagination.current)(2);
    if (onePage.data.length && twoPage.data.length) {
      TestValidator.notEquals('unique page rows')(onePage.data[0].id)(twoPage.data[0].id);
    }
  }

  // 7. Invalid property (not in schema) is rejected
  await TestValidator.error('unknown property rejected')(async () => {
    // @ts-expect-error
    await api.functional.discussionboard.activityLogs.index(connection, {
      body: { unknown_field: 'fail' },
    });
  });

  // 8. Schema property type violations
  await TestValidator.error('invalid uuid in filter')(async () => {
    await api.functional.discussionboard.activityLogs.index(connection, {
      body: { discussionboard_board_id: 'not-a-uuid' },
    });
  });
  await TestValidator.error('invalid date string in filter')(async () => {
    await api.functional.discussionboard.activityLogs.index(connection, {
      body: { event_timestamp_from: 'notadate' },
    });
  });
}

