import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardNotification";
import type { IPageIDiscussionboardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardNotification";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate notification log list retrieval (with filter, pagination, and sorting).
 *
 * This test creates multiple notifications of different types ('system_announcement', 'user_mention', etc.), target_ids, delivered states, and timestamps. Then, it queries the notifications index API with a variety of filters and combinations:
 *   - filter by target_id
 *   - filter by type
 *   - filter by delivered=true/false
 *   - filter by created_at range
 *   - combine above filters
 *   - test sorting (orderBy, orderDirection)
 *   - test pagination (page, limit, edge case where page yields no results)
 *
 * Steps:
 * 1. Create several notification records with a mix of:
 *      - types: 'system_announcement', 'user_mention', 'ban', 'reply_created'
 *      - target_id: use at least two distinct target_id values (uuid)
 *      - delivered: true/false
 *      - delivered_at: set for some notifications (optional)
 *      - created_at: distributed over a range (at least two date clusters)
 * 2. Call notifications index (PATCH /discussionboard/notifications) with:
 *      a. filter by target_id (should only return matching records)
 *      b. filter by type (should return only specified type)
 *      c. filter by delivered
 *      d. filter by created_at range (e.g. only recent)
 *      e. combine e.g. target_id+delivered
 *      f. order by created_at desc/asc, check correct order
 *      g. paginate - use limit/page to get partial results, check pagination meta
 *      h. request out-of-range page (should return empty data[], correct pagination info)
 * 3. For each, verify all returned records satisfy the filters, order, and are paginated per the spec.
 * 4. (Optionally) Simulate/validate permission by user role (admin, moderator) if supported by connection/auth context (actual role login omitted here for brevity, but noted for completeness).
 *
 * Edge cases and validation:
 *  - Filtering should not return records outside query parameters.
 *  - Empty results for pages beyond data.
 *  - Sorting order (created_at asc/desc) is respected.
 *  - Pagination meta matches expected values.
 */
export async function test_api_discussionboard_test_list_notifications_with_filter_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create test data: notifications of mixed types, target_ids, delivered states, dates.
  const targetIdA = typia.random<string & tags.Format<"uuid">>();
  const targetIdB = typia.random<string & tags.Format<"uuid">>();

  // Date clusters
  const dateNow = new Date();
  const dateOld = new Date(dateNow.getTime() - 7 * 24 * 60 * 60 * 1000); // 1 week ago
  const createdAtNow = dateNow.toISOString();
  const createdAtOld = dateOld.toISOString();

  // Notification records: build combinations
  const notifications = [
    { type: 'system_announcement', title: 'Announcement 1', delivered: true, created_at: createdAtOld, target_id: targetIdA },
    { type: 'user_mention', title: 'Mentioned you', delivered: false, created_at: createdAtNow, target_id: targetIdA },
    { type: 'system_announcement', title: 'Announcement 2', delivered: false, created_at: createdAtNow, target_id: targetIdB },
    { type: 'ban', title: 'You were banned', delivered: true, created_at: createdAtNow, target_id: targetIdB },
    { type: 'reply_created', title: 'New reply', delivered: true, created_at: createdAtOld, target_id: targetIdB },
    // No target_id notifications (system-wide)
    { type: 'user_mention', title: 'Mention, system', delivered: true, created_at: createdAtNow },
  ];

  // Optionally add unique delivered_at for delivered=true
  for (const n of notifications) {
    if (n.delivered) n.delivered_at = n.created_at;
  }

  // Create records in backend (dependencies: POST /discussionboard/notifications)
  const createdRecords = [];
  for (const n of notifications) {
    const created = await api.functional.discussionboard.notifications.create(connection, { body: n satisfies IDiscussionboardNotification.ICreate });
    typia.assert(created);
    createdRecords.push(created);
  }

  // 2a. Filter by target_id (targetIdA)
  {
    const output = await api.functional.discussionboard.notifications.index(connection, { body: { target_id: targetIdA } satisfies IDiscussionboardNotification.IRequest });
    typia.assert(output);
    TestValidator.predicate('all results match target_id')(output.data.every(n => n.target_id === targetIdA));
  }
  // 2b. Filter by type 'system_announcement'
  {
    const output = await api.functional.discussionboard.notifications.index(connection, { body: { type: 'system_announcement' } satisfies IDiscussionboardNotification.IRequest });
    typia.assert(output);
    TestValidator.predicate('all results match type')(output.data.every(n => n.type === 'system_announcement'));
  }
  // 2c. Filter by delivered=false
  {
    const output = await api.functional.discussionboard.notifications.index(connection, { body: { delivered: false } satisfies IDiscussionboardNotification.IRequest });
    typia.assert(output);
    TestValidator.predicate('all results are not delivered')(output.data.every(n => n.delivered === false));
  }
  // 2d. Filter by created_at range (created_at >= createdAtNow)
  {
    const output = await api.functional.discussionboard.notifications.index(connection, { body: { created_at: createdAtNow } satisfies IDiscussionboardNotification.IRequest });
    typia.assert(output);
    TestValidator.predicate('all results after created_at')(output.data.every(n => n.created_at >= createdAtNow));
  }
  // 2e. Combination (target_id=targetIdB, delivered=true)
  {
    const output = await api.functional.discussionboard.notifications.index(connection, { body: { target_id: targetIdB, delivered: true } satisfies IDiscussionboardNotification.IRequest });
    typia.assert(output);
    TestValidator.predicate('all results target_id and delivered')(output.data.every(n => n.target_id === targetIdB && n.delivered === true));
  }
  // 2f. Sort by created_at desc
  {
    const output = await api.functional.discussionboard.notifications.index(connection, { body: { orderBy: 'created_at', orderDirection: 'desc' } satisfies IDiscussionboardNotification.IRequest });
    typia.assert(output);
    for (let i=1;i<output.data.length;i++) {
      TestValidator.predicate('sorted desc')(output.data[i-1].created_at >= output.data[i].created_at);
    }
  }
  // 2f2. Sort by created_at asc
  {
    const output = await api.functional.discussionboard.notifications.index(connection, { body: { orderBy: 'created_at', orderDirection: 'asc' } satisfies IDiscussionboardNotification.IRequest });
    typia.assert(output);
    for (let i=1;i<output.data.length;i++) {
      TestValidator.predicate('sorted asc')(output.data[i-1].created_at <= output.data[i].created_at);
    }
  }
  // 2g. Pagination: limit=2, page=1 and page=2
  {
    const output1 = await api.functional.discussionboard.notifications.index(connection, { body: { limit: 2, page: 1, orderBy: 'created_at', orderDirection: 'desc' } satisfies IDiscussionboardNotification.IRequest });
    typia.assert(output1);
    TestValidator.equals('limit 2')(output1.data.length)(Math.min(2, createdRecords.length));
    TestValidator.equals('page 1 number')(output1.pagination.current)(1);
    const output2 = await api.functional.discussionboard.notifications.index(connection, { body: { limit: 2, page: 2, orderBy: 'created_at', orderDirection: 'desc' } satisfies IDiscussionboardNotification.IRequest });
    typia.assert(output2);
    TestValidator.equals('limit 2, page 2')(output2.data.length)(Math.max(0, createdRecords.length-2)); // for 6 records: page 2 should have rest
    TestValidator.equals('page 2 number')(output2.pagination.current)(2);
  }
  // 2h. Page out-of-range (page > pages)
  {
    const output = await api.functional.discussionboard.notifications.index(connection, { body: { limit: 2, page: 100 } satisfies IDiscussionboardNotification.IRequest });
    typia.assert(output);
    TestValidator.equals('out-of-range page returns no data')(output.data.length)(0);
  }
}

