/**
 * Test creating notification logs with both valid and invalid data, with admin privileges and as an unauthorized user.
 *
 * Steps:
 * 1. As an admin, create a notification with valid IDiscussionboardNotification.ICreate data (required: type, title, delivered, created_at; optional: target_id, body, delivered_at). Assert that response contains correct fields and values.
 * 2. As an admin, attempt to create a notification missing each required field (e.g., omit title, omit type, omit delivered, omit created_at)—expect API validation failure (error thrown).
 * 3. As an admin, attempt to create a notification with an obviously invalid type value (e.g., empty string)—expect validation error.
 * 4. As a non-admin (unauthorized user), attempt to create a notification (with valid data). Expect access denied error.
 *
 * Validation: Use typia.assert after each API response. Use TestValidator.error to confirm validation and authorization failure. Ensure no required properties are skipped in successful requests, and that failures are for the correct reasons (validation or authorization errors).
 */
export async function test_api_discussionboard_test_create_notification_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // Step 1: Valid creation with all required/optional fields as admin
  const validCreate: IDiscussionboardNotification.ICreate = {
    type: 'system_announcement',
    title: '전체 시스템 공지',
    delivered: true,
    created_at: new Date().toISOString(),
    target_id: typia.random<string & tags.Format<'uuid'>>(),
    body: '모든 사용자에게 알립니다.',
    delivered_at: new Date().toISOString(),
  };
  const created = await api.functional.discussionboard.notifications.create(connection, {
    body: validCreate,
  });
  typia.assert(created);
  TestValidator.equals('notification type')(created.type)(validCreate.type);
  TestValidator.equals('notification title')(created.title)(validCreate.title);
  TestValidator.equals('notification delivered')(created.delivered)(validCreate.delivered);
  // created.id, created.created_at 등은 자동 생성됨 – 포맷과 존재성 검사
  TestValidator.predicate('created.id is uuid')(typeof created.id === 'string' && /^[0-9a-f-]{36}$/.test(created.id));
  TestValidator.predicate('created_at ISO string generated')(typeof created.created_at === 'string' && !isNaN(Date.parse(created.created_at)));
  if (validCreate.target_id)
    TestValidator.equals('target_id reflected')(created.target_id)(validCreate.target_id);
  if (validCreate.body)
    TestValidator.equals('body reflected')(created.body)(validCreate.body);
  if (validCreate.delivered_at)
    TestValidator.equals('delivered_at reflected')(created.delivered_at)(validCreate.delivered_at);

  // Step 2: Missing each required field (title, type, delivered, created_at)
  for (const omitField of ['type','title','delivered','created_at'] as const) {
    const invalidCreate = { ...validCreate };
    delete (invalidCreate as any)[omitField];
    TestValidator.error(`missing required field: ${omitField}`)(async () => {
      await api.functional.discussionboard.notifications.create(connection, {
        body: invalidCreate as IDiscussionboardNotification.ICreate,
      });
    });
  }

  // Step 3: Invalid type value (empty string)
  const invalidType = { ...validCreate, type: '' };
  TestValidator.error('invalid notification type value')(async () => {
    await api.functional.discussionboard.notifications.create(connection, {
      body: invalidType,
    });
  });

  // Step 4: Non-admin user attempt (simulate by clearing/removing admin credentials from connection)
  const connectionNonAdmin = { ...connection, headers: { ...connection.headers } };
  delete connectionNonAdmin.headers['Authorization'];
  TestValidator.error('only admin can create notification')(async () => {
    await api.functional.discussionboard.notifications.create(connectionNonAdmin, {
      body: validCreate,
    });
  });
}

