/**
 * Test repeatedly creating notifications of the same type and same target_id.
 *
 * This test validates whether the notification system allows duplicates or enforces uniqueness for the (type, target_id) pair. It sends two creation requests with identical type and target_id, and expects either both succeed (if duplicates are allowed), or the second call fails (if uniqueness is enforced).
 *
 * Steps:
 * 1. Create a notification with specific type and target_id (pick a fixed event type and random target UUID)
 * 2. Attempt to create another notification with exactly the same type and target_id (with a new title/body)
 * 3. If both succeed, assert both are saved and have different ids. If second fails, assert the error is appropriate (conflict/duplicate logic)
 */
export async function test_api_discussionboard_test_create_duplicate_notifications_for_same_target_and_type(
  connection: api.IConnection,
) {
  // 1. Prepare fixed type and target_id to test duplication
  const fixedType = "test_event_type";
  const fixedTargetId = typia.random<string & tags.Format<"uuid">>();
  const baseInput: IDiscussionboardNotification.ICreate = {
    type: fixedType,
    target_id: fixedTargetId,
    title: "First notification - duplicate check",
    body: "Testing duplicate notification creation",
    delivered: true,
    created_at: new Date().toISOString(),
    delivered_at: new Date().toISOString(),
  };

  // 2. Create the first notification
  const first = await api.functional.discussionboard.notifications.create(
    connection,
    { body: baseInput },
  );
  typia.assert(first);

  // 3. Attempt to create a duplicate notification (same type/target_id)
  const duplicateInput: IDiscussionboardNotification.ICreate = {
    ...baseInput,
    title: "Second notification - duplicate check",
    body: "Second creation with same type/target_id for deduplication/idempotency test",
    created_at: new Date().toISOString(),
    delivered_at: new Date().toISOString(),
  };
  let duplicate: IDiscussionboardNotification | undefined;
  try {
    duplicate = await api.functional.discussionboard.notifications.create(
      connection,
      { body: duplicateInput },
    );
    typia.assert(duplicate);
    // If both requests succeed, their IDs must be different
    TestValidator.notEquals("distinct notification IDs for duplicates")(
      first.id,
    )(duplicate.id);
  } catch (err) {
    // If failure is enforced, it must be due to uniqueness/duplication
    TestValidator.error(
      "Duplicate notification creation should fail with uniqueness error",
    )(() => {
      throw err;
    });
  }
}

