/**
 * Test notification log update (valid/invalid fields, permissions, existence).
 *
 * This function validates the update behavior for discussionboard notification logs.
 *
 * 1. Create a notification log entry as admin (assume test connection is admin).
 * 2. Update only allowed fields (type, title, body, delivered, delivered_at, target_id) and verify the result reflects the changes.
 * 3. Attempt update with disallowed/immutable fields (created_at) and confirm error/ignored.
 * 4. Attempt update for a non-existent id and assert that a 404 error is thrown.
 * 5. Attempt update with unauthorized (anonymous) connection and confirm permission denial error.
 */
export async function test_api_discussionboard_test_update_notification_with_valid_and_invalid_fields(
  connection: api.IConnection,
) {
  // 1. Create notification as admin
  const created = await api.functional.discussionboard.notifications.create(connection, {
    body: {
      type: "system_announcement",
      title: "Original Title",
      delivered: false,
      created_at: new Date().toISOString(),
      body: "Initial notification body",
      target_id: typia.random<string & tags.Format<"uuid">>(),
      delivered_at: null,
    },
  });
  typia.assert(created);

  // 2. Update allowed fields and verify
  const updated = await api.functional.discussionboard.notifications.update(connection, {
    id: created.id,
    body: {
      type: "user_mention",
      title: "Changed Title",
      body: "Updated notification body",
      delivered: true,
      delivered_at: new Date().toISOString(),
      target_id: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(updated);
  TestValidator.equals("type updated")(updated.type)("user_mention");
  TestValidator.equals("title updated")(updated.title)("Changed Title");
  TestValidator.equals("body updated")(updated.body)("Updated notification body");
  TestValidator.equals("delivered updated")(updated.delivered)(true);

  // 3. Attempt updating immutable field created_at (should error/ignore)
  await TestValidator.error("created_at field is immutable")(
    async () => {
      await api.functional.discussionboard.notifications.update(connection, {
        id: created.id,
        body: {
          created_at: new Date(2029, 1, 1).toISOString(),
        } as any,
      });
    }
  );
  // (id field cannot be sent in body by DTO definition)

  // 4. Attempt update for non-existent id (should get 404 error)
  await TestValidator.error("404 for non-existent id")(
    async () => {
      await api.functional.discussionboard.notifications.update(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: {
          type: "user_mention",
        },
      });
    }
  );

  // 5. Attempt update with unauthorized connection (should get permission error)
  const anon: api.IConnection = { host: connection.host };
  await TestValidator.error("unauthorized update denied")(
    async () => {
      await api.functional.discussionboard.notifications.update(anon, {
        id: created.id,
        body: {
          type: "system_announcement",
        },
      });
    }
  );
}

