/**
 * 알림 로그 영구 삭제 API의 정상 동작 및 예외/권한 처리를 검증합니다.
 *
 * - 알림(notification) 로그 엔트리 생성 후, 관리자 권한으로 id 삭제 성공을 확인합니다.
 * - 삭제 직후 동일 id로 재삭제 또는 존재하지 않는 id 삭제 시 404 에러를 검사합니다.
 * - (환경이 허용하는 경우) 관리자가 아닌 사용자 또는 미로그인 상태에서 삭제 요청 시 권한 거부(401/403)됨을 확인합니다.
 *
 * 테스트 절차:
 * 1. (관리자 인증 상태) 알림 notification 생성
 * 2. 해당 엔트리 id로 삭제 → 삭제 성공
 * 3. 삭제된 id로 재삭제 → 404 에러 반환 확인
 * 4. 무작위 존재하지 않는 id로 삭제 → 404 에러 확인
 * 5. (가능하면) 일반 사용자/비인증 상태에서 삭제 요청 → 401/403 확인
 *
 * 비고:
 * - 테스트 환경에 따라 실제 일반 사용자 connection 또는 로그아웃 처리 기능이 없으면 권한 테스트 케이스는 skip 가능
 * - 알림 생성시 필수값 및 타입 정확성 보장, TestValidator로 결과 판별
 */
export async function test_api_discussionboard_test_delete_notification_and_error_cases(
  connection: api.IConnection,
) {
  // 1. 관리자 권한에서 알림 로그 엔트리 생성
  const notification = await api.functional.discussionboard.notifications.create(connection, {
    body: {
      type: "system_announcement",
      title: "E2E 테스트용 알림",
      delivered: true,
      created_at: new Date().toISOString(),
      body: "삭제 기능 정상 동작 검증용 알림",
    } satisfies IDiscussionboardNotification.ICreate,
  });
  typia.assert(notification);

  // 2. 해당 알림 로그 id로 정상 삭제 (Admin)
  await api.functional.discussionboard.notifications.erase(connection, {
    id: notification.id,
  });

  // 3. 삭제된 id로 재삭제 시도 → 404 발생 확인
  await TestValidator.error("삭제 후 재삭제시 404 반환")(() =>
