import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IDiscussionboardCommentSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentSnapshot";

/**
 * Test creation of comment snapshots with valid and invalid data in the discussion board system.
 *
 * This test verifies that a snapshot record can be successfully created using all required properties (discussionboard_comment_id, discussionboard_member_id, discussionboard_post_id, body, version, snapshot_created_at) and that the response matches the input. It also ensures that errors are raised when non-existent foreign keys are used.
 *
 * Steps:
 * 1. Create a new member (discussionboard_member).
 * 2. Using this member, create a new comment (discussionboard_comment). This provides valid discussionboard_comment_id and post_id for snapshot.
 * 3. Create a valid comment snapshot with all required fields provided. Confirm response matches input. Assert all schema fields are correct.
 * 4. Attempt to use invalid foreign key values (e.g., random UUID not present in members/comments/posts tables) for discussionboard_member_id or discussionboard_comment_id and confirm appropriate error handling.
 */
export async function test_api_discussionboard_test_create_comment_snapshot_with_valid_and_invalid_data(connection: api.IConnection) {
  // Step 1: Create a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: memberEmail,
      hashed_password: RandomGenerator.alphaNumeric(32),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // Step 2: Create a new comment
  const commentBody = RandomGenerator.paragraph()();
  const postId = typia.random<string & tags.Format<"uuid">>(); // NOTE: No endpoint to create posts, so supply random UUID for now.
  const comment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: postId,
      discussionboard_member_id: member.id,
      body: commentBody,
    } satisfies IComment.ICreate,
  });
  typia.assert(comment);

  // Step 3: Create a valid snapshot using all required fields
  const now = new Date().toISOString();
  const snapshotInput = {
    discussionboard_comment_id: comment.id,
    discussionboard_member_id: member.id,
    discussionboard_post_id: comment.discussionboard_post_id,
    body: comment.body,
    version: 1,
    snapshot_created_at: now,
  } satisfies IDiscussionboardCommentSnapshot.ICreate;

  const snapshot = await api.functional.discussionboard.commentSnapshots.create(
    connection,
    { body: snapshotInput },
  );
  typia.assert(snapshot);
  TestValidator.equals("snapshot fields")(snapshot.discussionboard_comment_id)(snapshotInput.discussionboard_comment_id);
  TestValidator.equals("snapshot fields")(snapshot.discussionboard_member_id)(snapshotInput.discussionboard_member_id);
  TestValidator.equals("snapshot fields")(snapshot.discussionboard_post_id)(snapshotInput.discussionboard_post_id);
  TestValidator.equals("snapshot fields")(snapshot.body)(snapshotInput.body);
  TestValidator.equals("snapshot fields")(snapshot.version)(snapshotInput.version);
  TestValidator.equals("snapshot fields")(snapshot.snapshot_created_at)(snapshotInput.snapshot_created_at);

  // Step 4: Using invalid foreign keys (nonexistent comment & member)
  await TestValidator.error("invalid foreign key")(async () => {
    await api.functional.discussionboard.commentSnapshots.create(connection, {
      body: {
        discussionboard_comment_id: typia.random<string & tags.Format<"uuid">>(), // Not in DB
        discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(), // Not in DB
        discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
        body: RandomGenerator.alphabets(10),
        version: 2,
        snapshot_created_at: new Date().toISOString(),
      } satisfies IDiscussionboardCommentSnapshot.ICreate,
    });
  });
}

