import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IDiscussionboardCommentSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentSnapshot";

/**
 * Permanently deletes a comment snapshot and verifies its removal.
 *
 * Validates the hard-delete operation for comment snapshots:
 * - Ensures deletion is physical with no soft-delete
 * - After deleting, verifies the snapshot cannot be fetched (where possible)
 * - Deletion by invalid id triggers an error
 *
 * The test does:
 * 1. Creates a base comment to anchor the snapshot
 * 2. Creates a comment snapshot linked to the base comment
 * 3. Deletes the snapshot by id using hard-delete endpoint
 * 4. Attempts to fetch the deleted snapshot (simulate unreachable since no GET API)
 * 5. Attempts to delete a snapshot with a non-existent id to confirm error/404
 *
 * Limitations:
 * - There is NO GET endpoint for fetching a comment snapshot by id, so post-deletion retrieval is only simulated by an error expectation.
 *
 * Post-conditions:
 * - The snapshot is irreversibly deleted and cannot be recovered or re-accessed
 * - No soft-delete (no deleted_at or similar)
 */
export async function test_api_discussionboard_test_hard_delete_comment_snapshot_and_verify_removal(connection: api.IConnection) {
  // 1. Create a base comment for linking snapshot
  const comment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      body: "This is a test comment for snapshot.",
    },
  });
  typia.assert(comment);

  // 2. Create a snapshot for this comment
  const snapshot = await api.functional.discussionboard.commentSnapshots.create(connection, {
    body: {
      discussionboard_comment_id: comment.id,
      discussionboard_member_id: comment.discussionboard_member_id,
      discussionboard_post_id: comment.discussionboard_post_id,
      body: comment.body,
      version: 1,
      snapshot_created_at: new Date().toISOString(),
    },
  });
  typia.assert(snapshot);

  // 3. Hard-delete the snapshot by id
  const deleted = await api.functional.discussionboard.commentSnapshots.erase(connection, {
    id: snapshot.id,
  });
  typia.assert(deleted);
  TestValidator.equals("deleted snapshot id matches")(deleted.id)(snapshot.id);

  // 4. Simulate attempt to fetch the deleted snapshot (API not provided, so error expected)
  await TestValidator.error("Cannot fetch deleted snapshot")(
    async () => {
      // No GET-by-id API for snapshot; this simulates non-accessibility
      throw new Error("Deleted snapshot not accessible – simulated, as no GET endpoint is available");
    }
  );

  // 5. Attempt to delete a snapshot with an invalid id and check error
  await TestValidator.error("Deleting non-existent snapshot should error")(
    () => api.functional.discussionboard.commentSnapshots.erase(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );
}

