/**
 * Validate updating the value and description of a discussion board system configuration.
 *
 * This test ensures that an admin can update the 'value' and 'description' fields of a configuration, but cannot modify immutable fields such as 'key' and 'id'.
 * The workflow simulates an actual admin updating a configuration for the system and validates that only the allowed fields change as expected, while the immutable fields remain the same.
 *
 * Step-by-step process:
 * 1. Create a system configuration using the API (as dependency).
 * 2. Update the configuration using the id, supplying a new value and a new description (possibly null).
 * 3. Verify that the updated configuration's id and key are unchanged, but value and/or description are updated as requested.
 * 4. Ensure audit fields (created_at, updated_at) are valid ISO strings and updated_at is more recent than the original created_at.
 */
export async function test_api_discussionboard_configurations_test_update_configuration_value_and_description(
  connection: api.IConnection,
) {
  // 1. Create a configuration as prerequisite.
  const createInput: IDiscussionboardConfiguration.ICreate = {
    key: RandomGenerator.alphabets(12),
    value: "original-value",
    description: "Initial setting for update test.",
  };

  const created: IDiscussionboardConfiguration = await api.functional.discussionboard.configurations.create(connection, {
    body: createInput,
  });
  typia.assert(created);

  // 2. Prepare update payload with new value and description, including edge case (null description).
  const updateInput: IDiscussionboardConfiguration.IUpdate = {
    value: "updated-value-test",
    description: null,
  };

  // 3. Send update request.
  const updated: IDiscussionboardConfiguration = await api.functional.discussionboard.configurations.update(connection, {
    id: created.id,
    body: updateInput,
  });
  typia.assert(updated);

  // 4. Validate immutability of 'id' and 'key'.
  TestValidator.equals("id remains unchanged")(updated.id)(created.id);
  TestValidator.equals("key remains unchanged")(updated.key)(created.key);

  // 5. Validate value and description are updated correctly.
  TestValidator.equals("value updated")(updated.value)(updateInput.value);
  TestValidator.equals("description updated")(updated.description)(updateInput.description);

  // 6. Validate audit fields and timestamps.
  TestValidator.equals("created_at unchanged")(updated.created_at)(created.created_at);
  TestValidator.predicate("updated_at is after or equal to created_at")(
    new Date(updated.updated_at).getTime() >= new Date(created.created_at).getTime()
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardConfiguration";

/**
 * 시스템 설정(configuration) 업데이트 시 key 필드가 불변(immutable)임을 검증하는 테스트입니다.
 *
 * - 이미 생성된 configuration에 대해 value, description 변경 시 update가 정상 동작하는지 확인합니다.
 * - 반대로 key 필드 변경을 시도할 경우, 서버에서 해당 변경을 거부해야 함을 검증합니다(TypeScript 타입은 맞지 않는 body지만, 런타임 에러만 검증).
 * - 여러 번 업데이트 후에도 key 값이 계속 유지되는지 확인합니다.
 *
 * 테스트 목적: 시스템 불변 규칙이 API 및 타입/런타임에서 모두 지켜짐을 보장합니다.
 *
 * 1. configuration 생성 (POST)
 * 2. value/description 업데이트 (PUT)
 * 3. key 필드 포함 업데이트(body를 any로 전달) 시도 → 서버 거절
 * 4. 여러 번 변경후에도 key값이 그대로임을 확인
 */
export async function test_api_discussionboard_configurations_test_update_configuration_attempt_to_modify_key_field(
  connection: api.IConnection,
) {
  // 1. configuration 생성
  const configInput: IDiscussionboardConfiguration.ICreate = {
    key: `max_post_per_hour_${typia.random<number>()}`,
    value: "10",
    description: "최대 시간당 게시글 수 허용치",
  };
  const config = await api.functional.discussionboard.configurations.create(
    connection,
    { body: configInput }
  );
  typia.assert(config);

  // 2. value/description 정상 업데이트
  const updated = await api.functional.discussionboard.configurations.update(
    connection,
    {
      id: config.id,
      body: {
        value: "12",
        description: "최대 시간당 게시글 수(변경됨)",
      },
    }
  );
  typia.assert(updated);
  TestValidator.equals("key 변함없음")(updated.key)(config.key);
  TestValidator.equals("value 변경")(updated.value)("12");
  TestValidator.equals("description 변경")(updated.description)("최대 시간당 게시글 수(변경됨)");

  // 3. 강제로 key 필드 포함 시도(body에 key 넣기, 타입 체크 생략)
  TestValidator.error("key 필드 포함시 서버 거절")(() =>
    api.functional.discussionboard.configurations.update(
      connection,
      {
        id: config.id,
        body: Object.assign({
          value: "13",
        }, { key: "try_modify_key" }) as any, // 의도적으로 key 포함: 타입 회피
      },
    ),
  );

  // 4. 여러 번 업데이트 후에도 key 원본 값 불변 확인
  const finalConfig = await api.functional.discussionboard.configurations.update(
    connection,
    {
      id: config.id,
      body: { value: "14" },
    },
  );
  typia.assert(finalConfig);
  TestValidator.equals("key 변함없음")(finalConfig.key)(config.key);
}

