import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAuditLog";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";

/**
 * 감사 로그 상세 단일 조회 정상 및 오류 케이스 E2E 테스트
 *
 * - 적법한 actor(member)로 감사 로그를 생성하고, 해당 id로 단일 상세 조회가 정상 동작하여 모든 필드가 기대대로 반환됨을 검증합니다.
 * - 또한 존재하지 않는 audit_log id 및 잘못된 id 형식으로 요청 시 404 또는 validation error가 발생되는지 점검합니다.
 * - 관리자/모더레이터 등 감사 추적 workflow와 audit log 예외 케이스가 모두 올바르게 동작하는지 확인하는 용도의 통합 테스트입니다.
 *
 * 테스트 플로우:
 * 1. 테스트 멤버(관리자 권한) 생성
 * 2. 해당 멤버 id로 감사 로그 생성 (actor 및 타겟)
 * 3. 정상 id로 감사로그 단일 상세 조회 및 핵심 필드 값 assert
 * 4. 존재하지 않는 id(uuid)/비정상 id로 조회 시 404 또는 validation error 확인
 */
export async function test_api_discussionboard_test_get_audit_log_detail_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. 테스트 멤버(관리자) 생성
  const memberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<'email'>>(),
    hashed_password: RandomGenerator.alphaNumeric(12),
    role: 'admin',
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 2. 감사 로그 생성 (actor: 위 멤버)
  const logInput: IDiscussionboardAuditLog.ICreate = {
    actor_id: member.id,
    action: 'role_assigned',
    target_id: member.id,
    payload: JSON.stringify({ granted_role: 'admin' }),
  };
  const log = await api.functional.discussionboard.auditLogs.create(connection, { body: logInput });
  typia.assert(log);

  // 3. 정상 id로 감사로그 상세 조회 후 키 필드 assert
  const detail = await api.functional.discussionboard.auditLogs.at(connection, { id: log.id });
  typia.assert(detail);
  TestValidator.equals('감사 로그 id')(detail.id)(log.id);
  TestValidator.equals('감사 로그 actor_id')(detail.actor_id)(member.id);
  TestValidator.equals('감사 로그 action')(detail.action)('role_assigned');
  TestValidator.equals('감사 로그 target_id')(detail.target_id)(member.id);
  TestValidator.predicate('감사 로그 created_at 필드 존재')(!!detail.created_at);

  // 4. 존재하지 않는 id (임의 uuid) 조회 시 404, 비정상 id 조회 시 validation error
  await TestValidator.error('존재하지 않는 id')(
    async () => {
      await api.functional.discussionboard.auditLogs.at(connection, {
        id: typia.random<string & tags.Format<'uuid'>>()
      });
    },
  );
  await TestValidator.error('잘못된 id 형식')(
    async () => {
      await api.functional.discussionboard.auditLogs.at(connection, {
        id: 'not-a-uuid' as unknown as string & tags.Format<'uuid'>,
      });
    },
  );
}

