import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAuditLog";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";

/**
 * Test updating the payload field of a discussion board audit log as an admin, ensuring only allowed fields are modifiable, and forbidden changes are rejected.
 *
 * Business context:
 * - Audit log update is only for permitted fields (payload for added context/corrections)
 * - Attempts to change core action or attribution fields should be blocked by validation
 * - System must reject updates on non-existent ids
 * - Only compliance-allowed fields may change; audit integrity is paramount
 *
 * Steps:
 * 1. Register an admin user
 * 2. Create an audit log record using that admin as actor
 * 3. Update only the payload field (should succeed, result persisted)
 * 4. Attempt to update forbidden fields (action, actor_id) – expect validation error (skipped: not allowed by type)
 * 5. Attempt to update a non-existent audit log id – expect 404 or error
 * 6. Confirm update succeeded for payload, and forbidden fields remain unchanged
 */
export async function test_api_discussionboard_test_update_audit_log_payload_and_permissions(
  connection: api.IConnection,
) {
  // 1. Register admin member
  const adminInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(20),
    role: "admin",
    is_active: true,
  };
  const admin = await api.functional.discussionboard.members.create(connection, { body: adminInput });
  typia.assert(admin);

  // 2. Create audit log event by admin
  const auditCreateInput: IDiscussionboardAuditLog.ICreate = {
    actor_id: admin.id,
    target_id: null,
    action: "role_assigned",
    payload: JSON.stringify({ context: "initial role grant" }),
  };
  const audit = await api.functional.discussionboard.auditLogs.create(connection, { body: auditCreateInput });
  typia.assert(audit);

  // 3. Update only payload: should be allowed
  const newPayload = JSON.stringify({ context: "Appended context - after review" });
  const updated = await api.functional.discussionboard.auditLogs.update(connection, {
    id: audit.id,
    body: { payload: newPayload },
  });
  typia.assert(updated);
  TestValidator.equals("payload updated")(updated.payload)(newPayload);
  TestValidator.equals("id unchanged")(updated.id)(audit.id);
  TestValidator.equals("actor_id unchanged")(updated.actor_id)(audit.actor_id);
  TestValidator.equals("action unchanged")(updated.action)(audit.action);

  // 4. Attempt update forbidden fields (not implemented – enforced by type, so skipped per requirements)

  // 5. Attempt update to non-existent id
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("404 update non-existent id")(() =>
    api.functional.discussionboard.auditLogs.update(connection, {
      id: nonExistentId,
      body: { payload: "{\"context\":\"should not update\"}" },
    })
  );
}

