import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAuditLog";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";

/**
 * 감사 로그 하드 삭제 기능(e2e):
 *
 * 1. admin 회원을 생성하고, 해당 계정에서 감사 로그를 신규 생성한다.
 * 2. 생성된 감사 로그를 해당 admin 계정으로 하드 삭제(irreversible)한다.
 *    - 이후 복구 불가 & 조회 불가 여부는 조회 API 미제공으로, 실제 조회 검증은 생략.
 * 3. 존재하지 않는 임의의 UUID id에 대해 삭제 요청 시 적절한 에러(404 등)를 발생시키는지 검증한다.
 * 4. admin이 아닌 member 계정의 권한으로 삭제 요청시 거절되어야 하나,
 *    계정 토큰 전환/role switching을 지원하지 않아 실제 권한테스트는 생략한다.
 *
 * @scenario 감사로그(admin) 하드 삭제/예외 케이스 검증
 */
export async function test_api_discussionboard_test_delete_audit_log_by_admin_and_nonexistent_id(
  connection: api.IConnection,
) {
  // 1. admin 회원 생성
  const adminMember: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "admin",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(adminMember);

  // 2. 감사 로그 생성 (actor: admin)
  const auditLog: IDiscussionboardAuditLog = await api.functional.discussionboard.auditLogs.create(connection, {
    body: {
      actor_id: adminMember.id,
      action: "settings_changed",
      payload: null,
    } satisfies IDiscussionboardAuditLog.ICreate,
  });
  typia.assert(auditLog);

  // 3. 생성된 감사 로그 하드 삭제 (정상 삭제)
  await api.functional.discussionboard.auditLogs.erase(connection, {
    id: auditLog.id,
  });
  // (별도 조회 API 미제공이라 삭제 후 검증은 생략함)

  // 4. 존재하지 않는 id로 삭제 요청시 에러(404 등) 반환 검증
  const nonExistId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("존재하지 않는 감사로그 id 삭제시 404 에러를 반환해야 한다.")(
    () => api.functional.discussionboard.auditLogs.erase(connection, { id: nonExistId })
  );

  // 5. admin이 아닌 member 계정의 권한 제한 (role switching 미지원으로 실제 테스트는 생략)
  const generalMember: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(generalMember);
  // (계정/토큰 전환 기능 미지원으로 권한 제한 실제 동작 검증은 불가)
}

