import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IPageIComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing and filtering of comments with advanced scenarios:
 *   - Filtering comments by post, author, parent comment, nesting (replies to comments)
 *   - Filtering by creation and update timestamps (date/time windows)
 *   - Filtering soft-deleted (deleted_at) comments
 *   - Edge: no comments under a post, or soft-deleted only
 *   - Pagination and ordering
 *   - Schema integrity for all returned comment fields
 *
 * Steps:
 * 1. Create two posts and two member IDs
 * 2. Create several top-level comments for post A (with different authors)
 * 3. Create replies (child comments) under some comments
 * 4. Attempt to soft-delete one comment and its child (note: as there is no delete endpoint, can only test filter semantics)
 * 5. Issue search/filter requests:
 *    - List all comments for post A
 *    - Filter by author
 *    - Only top-level, only children
 *    - List soft-deleted comments for post A (should be empty in this environment)
 *    - Paginate: two comments per page
 *    - Confirm empty for post B
 *    - For each result, validate fields (deleted_at especially)
 */
export async function test_api_discussionboard_test_list_comments_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create two posts and two members
  const memberA = typia.random<string & tags.Format<"uuid">>();
  const memberB = typia.random<string & tags.Format<"uuid">>();
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const postA = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_member_id: memberA,
      discussionboard_board_id: boardId,
      title: "Post A",
      body: "Body A",
    },
  });
  const postB = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_member_id: memberB,
      discussionboard_board_id: boardId,
      title: "Post B",
      body: "Body B",
    },
  });
  typia.assert(postA);
  typia.assert(postB);

  // 2. Create top-level comments (postA, two authors)
  const commentA1 = await api.functional.discussionboard.comments.create(
    connection,
    {
      body: {
        discussionboard_post_id: postA.id,
        discussionboard_member_id: memberA,
        body: "Top by A",
      },
    },
  );
  const commentA2 = await api.functional.discussionboard.comments.create(
    connection,
    {
      body: {
        discussionboard_post_id: postA.id,
        discussionboard_member_id: memberB,
        body: "Top by B",
      },
    },
  );
  typia.assert(commentA1);
  typia.assert(commentA2);

  // 3. Create replies (children)
  const childA1 = await api.functional.discussionboard.comments.create(
    connection,
    {
      body: {
        discussionboard_post_id: postA.id,
        discussionboard_member_id: memberB,
        parent_id: commentA1.id,
        body: "Reply to Top by A (by B)",
      },
    },
  );
  const childA2 = await api.functional.discussionboard.comments.create(
    connection,
    {
      body: {
        discussionboard_post_id: postA.id,
        discussionboard_member_id: memberA,
        parent_id: commentA2.id,
        body: "Reply to Top by B (by A)",
      },
    },
  );
  typia.assert(childA1);
  typia.assert(childA2);

  // 4. No delete endpoint; can only test semantics of filter with 'deleted'.
  // 5a. List all comments for postA
  const allForPostA = await api.functional.discussionboard.comments.index(
    connection,
    { body: { discussionboard_post_id: postA.id } },
  );
  typia.assert(allForPostA);
  allForPostA.data.forEach((comment) => typia.assert(comment));
  allForPostA.data.forEach((c) =>
    TestValidator.equals("post id")(c.discussionboard_post_id)(postA.id),
  );

  // 5b. Filter by author (memberA)
  const byMemberA = await api.functional.discussionboard.comments.index(
    connection,
