import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";

/**
 * Validate creation of comments: root-level and reply with parent_id, plus error edge cases.
 *
 * This test covers end-to-end comment creation logic in a discussion board context:
 *
 * 1. Create a discussion board member (for comment authorship).
 * 2. Create a discussion board post (to attach comments to).
 * 3. Create a root-level comment under the post (with no parent_id).
 * 4. Create a reply comment referencing the previous root-level comment (parent_id).
 * 5. Attempt creation with an invalid/non-existent post_id (expect failure).
 * 6. Attempt creation with an invalid/non-existent member_id (expect failure).
 * 7. Attempt creation with an invalid/non-existent parent_id (expect failure).
 *
 * Expected result: All created comment entities match the schema. All failure scenarios raise errors. Root and reply comments reference correct post/member/parent. Foreign key and required field enforcement is properly handled by the system.
 */
export async function test_api_discussionboard_test_create_comment_with_and_without_parent_id(
  connection: api.IConnection,
) {
  // 1. Create a discussion board member
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create a discussion board post
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: member.id,
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 3. Create a root-level comment (no parent_id)
  const rootComment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
      body: RandomGenerator.paragraph()(),
    } satisfies IComment.ICreate,
  });
  typia.assert(rootComment);
  TestValidator.equals("Comment is top-level")(rootComment.parent_id)(null);
  TestValidator.equals("Comment references correct post")(rootComment.discussionboard_post_id)(post.id);
  TestValidator.equals("Comment authored by member")(rootComment.discussionboard_member_id)(member.id);

  // 4. Create a reply comment referencing the root comment (parent_id)
  const replyComment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
      parent_id: rootComment.id,
      body: RandomGenerator.paragraph()(),
    } satisfies IComment.ICreate,
  });
  typia.assert(replyComment);
  TestValidator.equals("Reply parent matches root comment")(replyComment.parent_id)(rootComment.id);
  TestValidator.equals("Reply references correct post")(replyComment.discussionboard_post_id)(post.id);
  TestValidator.equals("Reply authored by member")(replyComment.discussionboard_member_id)(member.id);

  // 5. Try to create a comment with an invalid post_id (should error)
  await TestValidator.error("Invalid post_id should fail")(() =>
    api.functional.discussionboard.comments.create(connection, {
      body: {
        discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(), // Nonexistent post id
        discussionboard_member_id: member.id,
        body: RandomGenerator.paragraph()(),
      } satisfies IComment.ICreate,
    })
  );

  // 6. Try to create a comment with an invalid member_id (should error)
  await TestValidator.error("Invalid member_id should fail")(() =>
    api.functional.discussionboard.comments.create(connection, {
      body: {
        discussionboard_post_id: post.id,
        discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(), // Nonexistent member id
        body: RandomGenerator.paragraph()(),
      } satisfies IComment.ICreate,
    })
  );

  // 7. Try to create a comment with invalid parent_id (should error)
  await TestValidator.error("Invalid parent_id should fail")(() =>
    api.functional.discussionboard.comments.create(connection, {
      body: {
        discussionboard_post_id: post.id,
        discussionboard_member_id: member.id,
        parent_id: typia.random<string & tags.Format<"uuid">>(), // Nonexistent comment id
        body: RandomGenerator.paragraph()(),
      } satisfies IComment.ICreate,
    })
  );
}

