import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";

/**
 * Validate comment update endpoint, including body change, parent_id re-assignment, forbidden moves, and error on invalid ids.
 *
 * This test covers:
 *  1. Creation of a member (author), and a valid post for comments.
 *  2. Creating several comments to form a comment tree.
 *  3. Successful update: modify body and parent_id to another valid comment on same post. Ensure response reflects changes.
 *  4. Forbidden update: set parent_id to non-existent comment UUID (expect error).
 *  5. Forbidden update: put body/parent_id (or only body) to a non-existent comment UUID (expect error).
 *
 * Steps:
 *  a. Create member (for authoring comments)
 *  b. Create post
 *  c. Create three comments:
 *      - commentA: top-level
 *      - commentB: reply-to commentA
 *      - commentC: top-level
 *  d. Update commentB:
 *      - Change body (verify)
 *      - Change parent_id to commentC (verify)
 *  e. Attempt to update commentB specifying parent_id as non-existent UUID (invalid parent), expect error
 *  f. Attempt to update with non-existent comment id (expect error)
 *
 * Assertions:
 *  - After successful update, commentB's updated body and parent_id point to new values and updated_at is set.
 *  - Error cases are properly caught with TestValidator.error().
 */
export async function test_api_discussionboard_test_update_comment_body_and_parent_id(connection: api.IConnection) {
  // 1. Create a discussion member (author)
  const memberInput = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphabets(16),
    role: "member",
    is_active: true,
  } satisfies IDiscussionboardMember.ICreate;
  const member = await api.functional.discussionboard.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create a discussion post (requires FKs for thread, board, member)
  // Generate dummy thread & board IDs (assuming pre-existence)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const postInput = {
    discussionboard_thread_id: threadId,
    discussionboard_member_id: member.id,
    discussionboard_board_id: boardId,
    title: RandomGenerator.alphabets(16),
    body: RandomGenerator.content()()(),
  } satisfies IDiscussionboardPost.ICreate;
  const post = await api.functional.discussionboard.posts.create(connection, { body: postInput });
  typia.assert(post);

  // 3. Create initial comment tree: commentA (top), commentC (top), commentB (reply to A)
  const commentA = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
      body: "Root-level comment A",
    } satisfies IComment.ICreate,
  });
  typia.assert(commentA);
  const commentC = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
      body: "Root-level comment C",
    } satisfies IComment.ICreate,
  });
  typia.assert(commentC);
  const commentB = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
      parent_id: commentA.id,
      body: "Reply to A - B",
    } satisfies IComment.ICreate,
  });
  typia.assert(commentB);

  // 4. Update commentB: change body and parent_id to commentC.id
  const newBody = "Updated body for B (now replies to C)";
  const updated = await api.functional.discussionboard.comments.update(connection, {
    id: commentB.id,
    body: {
      body: newBody,
      parent_id: commentC.id,
    } satisfies IComment.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("updated body for commentB")(updated.body)(newBody);
  TestValidator.equals("updated parent_id for commentB")(updated.parent_id)(commentC.id);
  TestValidator.predicate("updated_at is set for commentB")(
    typeof updated.updated_at === "string" && !!updated.updated_at,
  );

  // 5. Try to update parent_id to a non-existent comment (invalid parent_id) (should error)
  const fakeParentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("invalid parent_id reference")(() =>
    api.functional.discussionboard.comments.update(connection, {
      id: commentB.id,
      body: {
        parent_id: fakeParentId,
      },
    }),
  );
  // 6. Try to update a non-existent comment id (should error)
  const fakeCommentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("update with non-existent comment id")(() =>
    api.functional.discussionboard.comments.update(connection, {
      id: fakeCommentId,
      body: {
        body: "Should fail",
      },
    }),
  );
}

