import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";

/**
 * Test soft-deleting a discussion board comment (logical deletion).
 *
 * Validates soft-deletion on the comment API:
 *  - Success (deleted_at flag should be set, entity is not hard-deleted)
 *  - Idempotency (multiple deletions on same ID: should not error, deleted_at remains correct)
 *  - Deleting non-existent comment (should not hard error, best-effort with proper error handling)
 *  - Verifies entity not hard-deleted in system (to the extent allowed by available APIs)
 *
 * Steps:
 * 1. Create a discussion board member
 * 2. Create a post with that member as author
 * 3. Create a comment for that post as the member
 * 4. Soft-delete the comment (DELETE by its ID)
 * 5. Attempt to delete the comment again (idempotency check)
 * 6. Attempt to delete a random non-existent comment (system stability/error handling)
 *
 * Note: Since there is no GET-by-ID for comments, direct post-delete state verification isn't possible at the API level.
 */
export async function test_api_discussionboard_test_soft_delete_comment_and_idempotency(
  connection: api.IConnection,
) {
  // 1. Create a new member (author)
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create a new post
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: member.id,
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(1),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 3. Create a comment for the post
  const comment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
      parent_id: null,
      body: RandomGenerator.paragraph()(1),
    } satisfies IComment.ICreate,
  });
  typia.assert(comment);

  // 4. Soft-delete the comment (success case)
  await api.functional.discussionboard.comments.erase(connection, {
    id: comment.id,
  });

  // 5. Attempt to delete the comment again (idempotency check)
  await api.functional.discussionboard.comments.erase(connection, {
    id: comment.id,
  });

  // 6. Attempt to delete a non-existent comment (should error gracefully)
  TestValidator.error("delete non-existent comment")(() =>
    api.functional.discussionboard.comments.erase(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );
}

