import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBan";
import type { IPageIDiscussionboardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardBan";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 어드민/모더레이터가 밴(ban) 목록을 다양한 필터와 페이징 옵션으로 조회할 수 있는지 검증합니다.
 *
 * 본 테스트는 각종 필터(acting_moderator_id, banned_member_id, report_id, ban_type, reason substring, banned_at, expires_at)와
 * 페이지(page/limit)에 대한 다양한 조합으로, ban 목록 API가 정확히 동작함을 검증합니다.
 * 
 * [테스트 절차 및 검증 단계]
 * 1. 테스트용 회원 4명 생성(각각: admin, moderator, member1, member2)
 * 2. acting_moderator_id, banned_member_id, ban_type(temporary/permanent), report_id, reason, banned_at, expires_at 조합을 달리해 ban 4개 이상 생성
 * 3. 전체 조회: 필터 없이 요청 시 전체 ban 목록이 페이지네이션 메타와 함께 반환되는지 확인
 * 4. acting_moderator_id로 필터 시 해당 모더레이터가 생성한 ban만 반환됨을 확인
 * 5. banned_member_id로 필터 시 해당 멤버가 ban된 기록만 반환됨을 확인
 * 6. ban_type 필터(temporary/permanent)로 결과 정확성 검증
 * 7. reason substring filter로 해당 문자열이 포함된 ban만 필터링됨을 확인
 * 8. report_id 기준 필터로 정확히 ban2만 반환되는지 확인
 * 9. banned_at, expires_at 필드(범위 등)로 필터 시 올바른 ban 포함여부 검증
 * 10. 존재하지 않는 banned_member_id, ban_type 값으로 필터 시 데이터 없음 확인
 * 11. page/limit 페이징 파라미터 조합으로 결과개수 및 페이지네이션 메타 검증
 */
export async function test_api_discussionboard_test_list_bans_with_various_filters_and_pagination(connection: api.IConnection) {
  // 1. 테스트용 회원 4명 생성
  const admin = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "admin",
      is_active: true,
    },
  });
  typia.assert(admin);

  const moderator = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "moderator",
      is_active: true,
    },
  });
  typia.assert(moderator);

  const member1 = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(member1);

  const member2 = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(member2);

  // 2. 밴 레코드 생성 (조합 다양화)
  const now = new Date();
  const ban1 = await api.functional.discussionboard.bans.create(connection, {
    body: {
      banned_member_id: member1.id,
      acting_moderator_id: moderator.id,
      report_id: null,
      reason: "spam",
      ban_type: "temporary",
      banned_at: new Date(now.getTime() - 800000).toISOString(),
      expires_at: new Date(now.getTime() + 20000).toISOString(),
    },
  });
  typia.assert(ban1);

  const ban2ReportId = typia.random<string & tags.Format<"uuid">>();
  const ban2 = await api.functional.discussionboard.bans.create(connection, {
    body: {
      banned_member_id: member2.id,
      acting_moderator_id: admin.id,
      report_id: ban2ReportId,
      reason: "abuse report",
      ban_type: "permanent",
      banned_at: new Date(now.getTime() - 600000).toISOString(),
      expires_at: null,
    },
  });
  typia.assert(ban2);

  const ban3 = await api.functional.discussionboard.bans.create(connection, {
    body: {
      banned_member_id: member1.id,
      acting_moderator_id: moderator.id,
      report_id: null,
      reason: "foul language",
      ban_type: "temporary",
      banned_at: new Date(now.getTime() - 400000).toISOString(),
      expires_at: new Date(now.getTime() + 600000).toISOString(),
    },
  });
  typia.assert(ban3);

  const ban4 = await api.functional.discussionboard.bans.create(connection, {
    body: {
      banned_member_id: member2.id,
      acting_moderator_id: moderator.id,
      report_id: null,
      reason: "other case",
      ban_type: "temporary",
      banned_at: new Date(now.getTime() - 200000).toISOString(),
      expires_at: null,
    },
  });
  typia.assert(ban4);

  // 3. 전체 목록 조회 (필터 없이)
  const allBans = await api.functional.discussionboard.bans.index(connection, { body: {} });
  typia.assert(allBans);
  TestValidator.predicate("ban 레코드 총 4개 이상 반환됨")(allBans.data.length >= 4);

  // 4. acting_moderator_id 기준 조회
  const byModerator = await api.functional.discussionboard.bans.index(connection, {
    body: { acting_moderator_id: moderator.id },
  });
  typia.assert(byModerator);
  TestValidator.predicate("모더레이터별 필터링")(byModerator.data.every(b => b.acting_moderator_id === moderator.id));

  // 5. banned_member_id 기준 조회
  const byMember1 = await api.functional.discussionboard.bans.index(connection, {
    body: { banned_member_id: member1.id },
  });
  typia.assert(byMember1);
  TestValidator.predicate("멤버1 기준 필터링")(byMember1.data.every(b => b.banned_member_id === member1.id));

  // 6. ban_type='temporary' 필터
  const byTypeTemporary = await api.functional.discussionboard.bans.index(connection, {
    body: { ban_type: "temporary" },
  });
  typia.assert(byTypeTemporary);
  TestValidator.predicate("ban_type temporary only")(byTypeTemporary.data.every(b => b.ban_type === "temporary"));

  // 7. reason substring='spam' 필터
  const byReasonSpam = await api.functional.discussionboard.bans.index(connection, {
    body: { reason: "spam" },
  });
  typia.assert(byReasonSpam);
  TestValidator.predicate("reason 'spam' 포함 필터링")(byReasonSpam.data.every(b => b.reason.includes("spam")));

  // 8. report_id(ban2) 기준 필터
  const byReportId = await api.functional.discussionboard.bans.index(connection, {
    body: { report_id: ban2.report_id },
  });
  typia.assert(byReportId);
  TestValidator.predicate("ban2의 report_id로 필터링")(byReportId.data.every(b => b.report_id === ban2.report_id));

  // 9. expires_at(미래 만료) 기준 필터
  const byExpiresFuture = await api.functional.discussionboard.bans.index(connection, {
    body: { expires_at: new Date(now.getTime() + 100000).toISOString() },
  });
  typia.assert(byExpiresFuture);
  // 일부 ban에 대해 expires_at이 필터값 이상인지 포함 여부 검증
  TestValidator.predicate("expires_at(future) 내 포함 ban 존재")(byExpiresFuture.data.some(b => b.expires_at && new Date(b.expires_at) >= new Date(now.getTime() + 100000)));

  // 10. 없는 banned_member_id, ban_type 값으로 조회
  const byNonExistentMember = await api.functional.discussionboard.bans.index(connection, {
    body: { banned_member_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(byNonExistentMember);
  TestValidator.equals("존재하지 않는 멤버 필터 0건")(byNonExistentMember.data.length)(0);

  const byNonExistentType = await api.functional.discussionboard.bans.index(connection, {
    body: { ban_type: "nonexistent_type" },
  });
  typia.assert(byNonExistentType);
  TestValidator.equals("존재하지 않는 ban_type 필터 0건")(byNonExistentType.data.length)(0);

  // 11. 페이지/limit 조합
  const page1 = await api.functional.discussionboard.bans.index(connection, {
    body: { page: 1, limit: 2 },
  });
  typia.assert(page1);
  TestValidator.equals("1페이지, 2개 반환")(page1.data.length)(Math.min(2, allBans.data.length));

  const page2 = await api.functional.discussionboard.bans.index(connection, {
    body: { page: 2, limit: 2 },
  });
  typia.assert(page2);
  TestValidator.equals("2페이지, 2개 제외 이후 개수")(page2.data.length)(Math.max(0, allBans.data.length - 2));
}

