import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBan";

/**
 * Validate fetching the details of a single ban record by id.
 *
 * This test ensures that when a valid ban record exists, fetching it by its id returns the full details, and only the schema-defined fields are present:
 *   id, banned_member_id, acting_moderator_id, report_id, reason, ban_type, banned_at, expires_at.
 *
 * Business rationale:
 * Ban records in the discussion board must be retrievable by their unique id for audit, analytics, compliance, and moderation review workflows. It is critical that the returned object includes all required fields, the correct types/formats, and does not leak any extraneous or non-schema fields.
 *
 * Steps:
 * 1. Create a new ban record (retaining its id for use in detail query).
 * 2. Fetch the ban record by this id (GET /discussionboard/bans/{id}).
 * 3. Assert that:
 *    - All required and optional fields per schema are present.
 *    - Each field matches the creation payload and constraints.
 *    - No non-schema/extra fields are present.
 */
export async function test_api_discussionboard_bans_test_get_ban_detail_by_id_when_ban_exists(
  connection: api.IConnection,
) {
  // 1. Create a new ban record to ensure a valid id for fetch-by-id testing.
  const banPayload: IDiscussionboardBan.ICreate = {
    banned_member_id: typia.random<string & tags.Format<"uuid">>(),
    acting_moderator_id: typia.random<string & tags.Format<"uuid">>(),
    report_id: typia.random<(string & tags.Format<"uuid">) | null>(),
    reason: "Violation of board rules (test scenario)",
    ban_type: "temporary",
    banned_at: new Date().toISOString(),
    expires_at: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), // 7 days later
  };
  const created: IDiscussionboardBan = await api.functional.discussionboard.bans.create(connection, {
    body: banPayload,
  });
  typia.assert(created);

  // 2. Fetch the ban record by its id
  const output: IDiscussionboardBan = await api.functional.discussionboard.bans.at(connection, {
    id: created.id,
  });
  typia.assert(output);

  // 3. Schema and value assertions
  // Destructure the result and check for the presence of only allowed fields
  const {
    id,
    banned_member_id,
    acting_moderator_id,
    report_id,
    reason,
    ban_type,
    banned_at,
    expires_at,
    ...extra
  } = output;

  // No extra fields
  TestValidator.predicate("No extra fields in returned ban object")(Object.keys(extra).length === 0);

  // Field-by-field value assertions
  TestValidator.equals("Returned id matches created id")(output.id)(created.id);
  TestValidator.equals("banned_member_id matches")(output.banned_member_id)(banPayload.banned_member_id);
  TestValidator.equals("acting_moderator_id matches")(output.acting_moderator_id)(banPayload.acting_moderator_id);
  TestValidator.equals("reason matches")(output.reason)(banPayload.reason);
  TestValidator.equals("ban_type matches")(output.ban_type)(banPayload.ban_type);

  // Format and type validation for UUIDs and date-times is done implicitly by typia.assert.
}

