import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBan";

/**
 * Test creation of ban records (required and optional fields)
 *
 * Validates that a ban can be created with only required fields as well as with all optional fields (report_id, expires_at) set, confirms correct schema compliance of the returned record, and covers validation failure on missing required fields.
 *
 * Steps:
 * 1. Create a member to serve as the banned user.
 * 2. Create another member with moderator/admin role for acting_moderator_id.
 * 3. Attempt a ban creation using only required fields; verify response matches request and correctly stores the input.
 * 4. Attempt a ban creation using required and all optional fields; verify response stores all properties correctly.
 * 5. Negative test: try to create a ban missing a required field (e.g., reason), expecting a validation error.
 *
 * NOTE: Actual user restriction effects are enforced by surrounding application logic, not by the Ban creation API: only database record creation is asserted here.
 */
export async function test_api_discussionboard_test_create_ban_with_required_and_optional_fields(connection: api.IConnection) {
  // Step 1. Create the member to be banned
  const bannedMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true
    } satisfies IDiscussionboardMember.ICreate
  });
  typia.assert(bannedMember);

  // Step 2. Create an admin/moderator member
  const moderator = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: RandomGenerator.pick(["moderator", "admin"]),
      is_active: true
    } satisfies IDiscussionboardMember.ICreate
  });
  typia.assert(moderator);

  // Step 3. Create a required-only ban
  const now = new Date().toISOString();
  const banRequired = await api.functional.discussionboard.bans.create(connection, {
    body: {
      banned_member_id: bannedMember.id,
      acting_moderator_id: moderator.id,
      reason: "Violation of policy",
      ban_type: "temporary",
      banned_at: now
    } satisfies IDiscussionboardBan.ICreate
  });
  typia.assert(banRequired);
  TestValidator.equals("banned_member_id")(banRequired.banned_member_id)(bannedMember.id);
  TestValidator.equals("acting_moderator_id")(banRequired.acting_moderator_id)(moderator.id);
  TestValidator.equals("reason")(banRequired.reason)("Violation of policy");
  TestValidator.equals("ban_type")(banRequired.ban_type)("temporary");
  TestValidator.equals("banned_at")(banRequired.banned_at)(now);
  TestValidator.equals("report_id null")(banRequired.report_id)(null);
  TestValidator.equals("expires_at null")(banRequired.expires_at)(null);

  // Step 4. Create a ban with optional fields
  const expiresAt = new Date(Date.now() + 1000 * 60 * 60 * 24 * 3).toISOString();
  const reportId = typia.random<string & tags.Format<"uuid">>();
  const banWithOptional = await api.functional.discussionboard.bans.create(connection, {
    body: {
      banned_member_id: bannedMember.id,
      acting_moderator_id: moderator.id,
      reason: "Repeat offense",
      ban_type: "permanent",
      banned_at: now,
      report_id: reportId,
      expires_at: expiresAt
    } satisfies IDiscussionboardBan.ICreate
  });
  typia.assert(banWithOptional);
  TestValidator.equals("banned_member_id")(banWithOptional.banned_member_id)(bannedMember.id);
  TestValidator.equals("acting_moderator_id")(banWithOptional.acting_moderator_id)(moderator.id);
  TestValidator.equals("reason")(banWithOptional.reason)("Repeat offense");
  TestValidator.equals("ban_type")(banWithOptional.ban_type)("permanent");
  TestValidator.equals("banned_at")(banWithOptional.banned_at)(now);
  TestValidator.equals("report_id")(banWithOptional.report_id)(reportId);
  TestValidator.equals("expires_at")(banWithOptional.expires_at)(expiresAt);

  // Step 5. Validation error on missing required field
  await TestValidator.error("ban creation missing required reason should fail")(async () => {
    await api.functional.discussionboard.bans.create(connection, {
      body: {
        banned_member_id: bannedMember.id,
        acting_moderator_id: moderator.id,
        ban_type: "temporary",
        banned_at: now
        // reason is omitted => should trigger validation error
      } as any // as any: forced violation for test
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
