import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBan";

/**
 * Test updating an existing ban record and validate correct update behavior, as well as failure scenarios.
 *
 * Business context: Moderators or admins may need to update bans (e.g., adjust the ban period, change the type, update linkage to a moderation report, or correct the reason). The API should allow such updates, enforcing all referential and integrity constraints.
 *
 * Workflow:
 * 1. Create a member to be banned and a moderator/admin member for acting.
 * 2. Create a valid ban record using these members.
 * 3. Update the ban with new reason, ban_type, expires_at, report_id, and verify that all changes are accurately reflected in the updated entity.
 * 4. Attempt to update a ban record that does not exist (random UUID) and expect a not-found error.
 * 5. Attempt to update an existing ban record with invalid banned_member_id (random UUID not matching any member) and expect a foreign key or integrity error.
 * 6. Attempt to update using invalid acting_moderator_id (random UUID not matching any member) and expect a foreign key or integrity error.
 *
 * The test validates correct update operation, not-found errors, and referential integrity on foreign keys.
 */
export async function test_api_discussionboard_test_update_ban_details_success_and_failure(
  connection: api.IConnection,
) {
  // 1. Create two members: one as a ban target, one as moderator
  const bannedMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphabets(16),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(bannedMember);

  const moderatorMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphabets(16),
      role: "moderator",
      is_active: true,
    },
  });
  typia.assert(moderatorMember);

  // 2. Create an initial ban record
  const ban = await api.functional.discussionboard.bans.create(connection, {
    body: {
      banned_member_id: bannedMember.id,
      acting_moderator_id: moderatorMember.id,
      report_id: null,
      reason: "Initial ban for test",
      ban_type: "temporary",
      banned_at: new Date().toISOString(),
      expires_at: null,
    },
  });
  typia.assert(ban);

  // 3. Update the ban with new values
  const newReason = "Updated reason for audit purposes";
  const newBanType = "permanent";
  const newExpiresAt = new Date(Date.now() + 86400 * 1000).toISOString(); // +1 day
  const updatedBan = await api.functional.discussionboard.bans.update(connection, {
    id: ban.id,
    body: {
      banned_member_id: bannedMember.id,
      acting_moderator_id: moderatorMember.id,
      report_id: typia.random<string & tags.Format<"uuid">>(),
      reason: newReason,
      ban_type: newBanType,
      banned_at: ban.banned_at,
      expires_at: newExpiresAt,
    },
  });
  typia.assert(updatedBan);
  TestValidator.equals("ban id after update")(updatedBan.id)(ban.id);
  TestValidator.equals("banned_member_id")(updatedBan.banned_member_id)(ban.banned_member_id);
  TestValidator.equals("acting_moderator_id")(updatedBan.acting_moderator_id)(ban.acting_moderator_id);
  TestValidator.equals("reason updated")(updatedBan.reason)(newReason);
  TestValidator.equals("ban_type updated")(updatedBan.ban_type)(newBanType);
  TestValidator.equals("expires_at updated")(updatedBan.expires_at)(newExpiresAt);
  TestValidator.equals("report_id updated")(updatedBan.report_id !== null)(true);

  // 4. Attempt to update non-existent ban id (should result in not-found error)
  const nonExistentBanId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("Update non-existent ban should fail")(() => 
    api.functional.discussionboard.bans.update(connection, {
      id: nonExistentBanId,
      body: {
        banned_member_id: bannedMember.id,
        acting_moderator_id: moderatorMember.id,
        report_id: null,
        reason: "Try update non-existent ban",
        ban_type: "temporary",
        banned_at: ban.banned_at,
        expires_at: null,
      },
    }),
  );

  // 5. Update with invalid banned_member_id (should fail FK check)
  const fakeMemberUUID = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("Update with invalid banned_member_id should fail")(() =>
    api.functional.discussionboard.bans.update(connection, {
      id: ban.id,
      body: {
        banned_member_id: fakeMemberUUID,
        acting_moderator_id: moderatorMember.id,
        report_id: null,
        reason: "Change with bad banned_member_id",
        ban_type: "temporary",
        banned_at: ban.banned_at,
        expires_at: null,
      },
    }),
  );

  // 6. Update with invalid acting_moderator_id (should fail FK check)
  const fakeModeratorUUID = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("Update with invalid acting_moderator_id should fail")(() =>
    api.functional.discussionboard.bans.update(connection, {
      id: ban.id,
      body: {
        banned_member_id: bannedMember.id,
        acting_moderator_id: fakeModeratorUUID,
        report_id: null,
        reason: "Change with bad acting_moderator_id",
        ban_type: "temporary",
        banned_at: ban.banned_at,
        expires_at: null,
      },
    }),
  );
}

