/**
 * 테스트: 특정 ban(정지) 레코드의 삭제 성공 및 존재하지 않는 id에 대한 삭제 실패 검증
 *
 * 이 테스트는 아래 워크플로우를 검증합니다:
 * 1. 새 ban 레코드를 생성합니다.
 * 2. 해당 ban id로 삭제를 수행합니다(정상적으로 삭제되어야 함).
 * 3. 동일한 id로 한 번 더 삭제를 시도해, not-found 혹은 적절한 에러가 발생함을 확인합니다.
 * 4. 완전히 무작위(존재하지 않을) id로 삭제 시도 시에도 마찬가지로 에러가 발생함을 확인합니다.
 * 5. (주어진 API만으로는) 다른 역할/연관 엔터티에 영향이 없음을 코드상 증명할 수는 없으나, 이 ban 레코드만 조작됨을 보장합니다.
 *
 * 검증 요소:
 * - 정상적인 ban 레코드 삭제 흐름
 * - 동일/무작위 id 재삭제 시 올바른 에러 핸들링
 * - ban 이외 엔터티 영향 없음
 */
export async function test_api_discussionboard_test_delete_ban_success_and_nonexistent_id(
  connection: api.IConnection,
) {
  // 1. 새 ban 레코드를 생성 (삭제 테스트를 위해 필요)
  const banInput: IDiscussionboardBan.ICreate = {
    banned_member_id: typia.random<string & tags.Format<"uuid">>(),
    acting_moderator_id: typia.random<string & tags.Format<"uuid">>(),
    report_id: null,
    reason: "E2E 테스트용 ban 삭제 케이스",
    ban_type: "temporary",
    banned_at: new Date().toISOString(),
    expires_at: null,
  };
  const ban = await api.functional.discussionboard.bans.create(connection, {
    body: banInput,
  });
  typia.assert(ban);

  // 2. 해당 ban id로 삭제
  await api.functional.discussionboard.bans.erase(connection, {
    id: ban.id,
  });

  // 3. 동일 id 재삭제 시도 → 에러 발생
  await TestValidator.error("정지 레코드 두 번 삭제시 실패해야 함")(() =>
    api.functional.discussionboard.bans.erase(connection, {
      id: ban.id,
    })
  );

  // 4. 완전히 무작위(존재하지 않을) id로 삭제 시도 → 에러 발생
  const randomId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("없는 ban id 삭제시 에러 발생")(() =>
    api.functional.discussionboard.bans.erase(connection, {
      id: randomId,
    })
  );

  // 5. 다른 역할/연관 엔터티와는 무관하게 오직 ban 엔티티만 조작됨 (주어진 API 상에서 더 이상 코드 검증 불가)
