import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { Idiscussionboard_report_types } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_report_types";
import type { IPageIdiscussionboard_report_types } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIdiscussionboard_report_types";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate report type listing with pagination, filtering, and edge case handling for moderation dashboard use.
 *
 * An admin needs to load the list of report types for use in a dashboard select box. Only report types that are active should appear by default, sorted by newest first. The response must have correct pagination fields and all entity data must match the schema. We also verify filtering for inactive report types. Finally, we check the edge case where a search by display_name uses a string unlikely to match anything; response must be handled gracefully and return an empty array as data.
 *
 * Step-by-step:
 * 1. Request paginated active report types (active=true), with descending created_at sorting
 * 2. Check each returned entity matches schema fields, active is true, and pagination info makes sense
 * 3. Request paginated inactive report types (active=false), verify only inactive rows are returned
 * 4. Search using display_name unlikely to match any record, validate empty result set and correct pagination
 */
export async function test_api_discussionboard_reportTypes_index(
  connection: api.IConnection,
) {
  // 1. List active report types, sorted by created_at desc (assume default page 1, limit 10)
  const activeList = await api.functional.discussionboard.reportTypes.index(connection, {
    body: {
      active: true,
    },
  });
  typia.assert(activeList);
  // Validate only active report types were returned
  for (const item of activeList.data) {
    TestValidator.equals("All results should be active")(item.active)(true);
  }
  // Pagination fields check (should be on first page)
  TestValidator.equals("current page")(activeList.pagination.current)(1);
  TestValidator.predicate("limit positive")(activeList.pagination.limit > 0);
  // Data fields check (required: id uuid, code string, display_name string, [description?], active bool, created_at iso8601)
  for (const item of activeList.data) {
    TestValidator.predicate("id format")(/^[0-9a-f\-]{36}$/.test(item.id));
    TestValidator.equals("active field is boolean")(typeof item.active)("boolean");
  }

  // 2. List inactive report types
  const inactiveList = await api.functional.discussionboard.reportTypes.index(connection, {
    body: {
      active: false,
    },
  });
  typia.assert(inactiveList);
  for (const item of inactiveList.data) {
    TestValidator.equals("All results should be inactive")(item.active)(false);
  }

  // 3. Search by display_name with rare string
  const rareString = "unlikelystring-" + Math.random().toString(36).slice(2);
  const emptyResult = await api.functional.discussionboard.reportTypes.index(connection, {
    body: {
      display_name: rareString,
    },
  });
  typia.assert(emptyResult);
  TestValidator.equals("data array is empty")(emptyResult.data.length)(0);
  // Pagination for empty result
  TestValidator.equals("zero records for rare string")(emptyResult.pagination.records)(0);
}

