import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardThreadTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreadTag";
import type { IPageDiscussionboardThreadTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardThreadTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E: Test list endpoint for paginated/filtered thread tag assignments (discussionboard_thread_tags)
 *
 * Purpose: To validate the /discussionboard/threadTags PATCH endpoint provides correct, paginated, and filtered results according to a variety of filter and pagination parameters, and strictly adheres to the schema.
 *
 * Business Context:
 * - Thread tag assignment records (discussionboard_thread_tags) must be retrievable by thread id, assignment date window, and by activity status (removed_at null or not).
 * - Pagination (page, limit) is used for UI and analytics, handling potentially large records.
 *
 * Test Steps:
 * 1. Create a thread to serve as a target for tag assignment and filtering
 * 2. Assign multiple (3+) tags to the created thread, with varied assigned_at and removed_at values (simulate historical and active tags)
 * 3. Call the PATCH /discussionboard/threadTags endpoint with different filters:
 *   a. By thread_id only (should return all tag assignments for the thread)
 *   b. With removed_at_null_only=true (should show only active tag assignments)
 *   c. With assigned_at_from/assigned_at_to window to select specific tags (cover window boundaries)
 *   d. With pagination (page=1, limit=<N>, and with page >1)
 *   e. With limit set to max allowed value (200)
 *   f. With filter that should produce empty results (thread_id that does not exist)
 * 4. For each case, verify that:
 *   - Only schema-compliant fields are present in the response
 *   - Pagination info is correct (current, limit, pages, records)
 *   - The tag assignment records match the intended filter (thread_id, removed_at, assignment window)
 *   - Result is empty when filter does not match (edge case)
 *   - Results are correct for paging (split over multiple pages as needed)
 *   - (Negative test) With invalid pagination (page=0, limit=0 or limit>200), API responds with error (if enforced)
 *
 * Notes:
 * - No explicit sorting parameter exists; sorting is assumed default or API controlled (usually newest assigned_at first)
 * - All result fields must match IDiscussionboardThreadTag schema; no extras
 * - Clean up not necessary; record creation is isolated by test thread_id
 */
export async function test_api_discussionboard_test_list_thread_tags_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create a thread
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: typia.random<string & tags.Format<"uuid">>(),
      author_member_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);

  // 2. Assign multiple tags with varied assigned_at and removed_at (simulate historical/active tags)
  const baseTime: string & tags.Format<"date-time"> = new Date().toISOString() as any;
  const oneHourAgo: string & tags.Format<"date-time"> = new Date(Date.now() - 1000 * 60 * 60).toISOString() as any;
  const twoHoursAgo: string & tags.Format<"date-time"> = new Date(Date.now() - 2 * 1000 * 60 * 60).toISOString() as any;
  // a) Active tag 1
  const tagActive1 = await api.functional.discussionboard.threadTags.create(connection, {
    body: {
      thread_id: thread.id,
      assigned_at: baseTime,
    } satisfies IDiscussionboardThreadTag.ICreate,
  });
  typia.assert(tagActive1);
  // b) Active tag 2
  const tagActive2 = await api.functional.discussionboard.threadTags.create(connection, {
    body: {
      thread_id: thread.id,
      assigned_at: oneHourAgo,
    } satisfies IDiscussionboardThreadTag.ICreate,
  });
  typia.assert(tagActive2);
  // c) Historical (removed) tag
  const tagHistorical = await api.functional.discussionboard.threadTags.create(connection, {
    body: {
      thread_id: thread.id,
      assigned_at: twoHoursAgo,
    } satisfies IDiscussionboardThreadTag.ICreate,
  });
  typia.assert(tagHistorical);

  // Simulate historical state by directly setting removed_at if possible (placeholder, not exposed by API)
  // So we will just simulate by filtering in retrieval.

  // 3a. Retrieve all tag assignments for the thread
  const allTagsPage = await api.functional.discussionboard.threadTags.index(connection, {
    body: {
      thread_id: thread.id,
    } satisfies IDiscussionboardThreadTag.IRequest,
  });
  typia.assert(allTagsPage);
  allTagsPage.data.forEach(tag => {
    TestValidator.equals("thread id matches")(tag.thread_id)(thread.id);
  });

  // 3b. Retrieve only active tags (removed_at_null_only: true)
  const activeTagsPage = await api.functional.discussionboard.threadTags.index(connection, {
    body: {
      thread_id: thread.id,
      removed_at_null_only: true,
    } satisfies IDiscussionboardThreadTag.IRequest,
  });
  typia.assert(activeTagsPage);
  activeTagsPage.data.forEach(tag => {
    TestValidator.equals("should be active")(tag.removed_at)(null);
    TestValidator.equals("thread id matches")(tag.thread_id)(thread.id);
  });

  // 3c. Retrieve by assigned_at window (from twoHoursAgo to baseTime)
  const windowTagsPage = await api.functional.discussionboard.threadTags.index(connection, {
    body: {
      thread_id: thread.id,
      assigned_at_from: twoHoursAgo,
      assigned_at_to: baseTime,
    } satisfies IDiscussionboardThreadTag.IRequest,
  });
  typia.assert(windowTagsPage);
  windowTagsPage.data.forEach(tag => {
    TestValidator.equals("thread id matches")(tag.thread_id)(thread.id);
    TestValidator.predicate("assigned_at in range")(
      tag.assigned_at >= twoHoursAgo && tag.assigned_at <= baseTime
    );
  });

  // 3d. Retrieve with pagination (page=1, limit=2)
  const pagedTagsPage1 = await api.functional.discussionboard.threadTags.index(connection, {
    body: {
      thread_id: thread.id,
      page: 1,
      limit: 2,
    } satisfies IDiscussionboardThreadTag.IRequest,
  });
  typia.assert(pagedTagsPage1);
  TestValidator.equals("pagination current")(pagedTagsPage1.pagination.current)(1);
  TestValidator.equals("pagination limit")(pagedTagsPage1.pagination.limit)(2);
  TestValidator.predicate("page size")(pagedTagsPage1.data.length <= 2);

  // Optionally, fetch next page if records > 2
  if (pagedTagsPage1.pagination.records > 2 && pagedTagsPage1.pagination.pages > 1) {
    const pagedTagsPage2 = await api.functional.discussionboard.threadTags.index(connection, {
      body: {
        thread_id: thread.id,
        page: 2,
        limit: 2,
      } satisfies IDiscussionboardThreadTag.IRequest,
    });
    typia.assert(pagedTagsPage2);
    TestValidator.equals("pagination current")(pagedTagsPage2.pagination.current)(2);
    TestValidator.equals("pagination limit")(pagedTagsPage2.pagination.limit)(2);
    // Data on page 2 may be nonempty only if total records > 2
    TestValidator.predicate("page size OK")(pagedTagsPage2.data.length <= 2);
  }

  // 3e. Retrieve with maximum allowed page size
  const maxLimitTagsPage = await api.functional.discussionboard.threadTags.index(connection, {
    body: {
      thread_id: thread.id,
      limit: 200,
    } satisfies IDiscussionboardThreadTag.IRequest,
  });
  typia.assert(maxLimitTagsPage);
  TestValidator.equals("pagination limit")(maxLimitTagsPage.pagination.limit)(200);
  TestValidator.predicate("max limit respected")(maxLimitTagsPage.data.length <= 200);

  // 3f. Filter that should produce empty results (random uuid as thread_id)
  const emptyTagsPage = await api.functional.discussionboard.threadTags.index(connection, {
    body: {
      thread_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IDiscussionboardThreadTag.IRequest,
  });
  typia.assert(emptyTagsPage);
  TestValidator.equals("empty list")(emptyTagsPage.data.length)(0);

  // 4. Negative case(s): invalid pagination (page=0, limit=0, limit>200)
  // - These should result in API errors if properly enforced
  await TestValidator.error("page=0 should fail")(async () => {
    await api.functional.discussionboard.threadTags.index(connection, {
      body: {
        thread_id: thread.id,
        page: 0 as any,
        limit: 2,
      } as any,
    });
  });
  await TestValidator.error("limit=0 should fail")(async () => {
    await api.functional.discussionboard.threadTags.index(connection, {
      body: {
        thread_id: thread.id,
        limit: 0 as any,
      } as any,
    });
  });
  await TestValidator.error("limit>200 should fail")(async () => {
    await api.functional.discussionboard.threadTags.index(connection, {
      body: {
        thread_id: thread.id,
        limit: 201 as any,
      } as any,
    });
  });
}

