 * 2. Attempt to create another privacy policy record with exactly the same version and different content/title/effective_date (to isolate the version uniqueness constraint).
 * 3. Expect a validation error (uniqueness violation) in the second creation attempt, verifying that only version uniqueness causes the failure.
 */
export async function test_api_discussionboard_privacyPolicies_create_test_create_privacy_policy_with_duplicate_version(
  connection: api.IConnection,
) {
