import type { IDiscussionboardPrivacyPolicies } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPrivacyPolicies";

/**
 * Test updating a privacy policy with valid data.
 *
 * This test ensures that an existing privacy policy can be updated with valid new fields and that the API returns updated data correctly. The test follows this workflow:
 *
 * 1. Create a new privacy policy with valid fields (version, effective_date, title, content).
 * 2. Update the created privacy policy using new values for all editable fields.
 * 3. Verify that the updated policy reflects the new values for editable fields (version, effective_date, title, content), and that other fields (id, created_at) remain unchanged.
 * 4. Confirm that the updated_at field is updated to a later value than before the update.
 */
export async function test_api_discussionboard_privacypolicies_test_update_privacy_policy_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create an initial privacy policy for update testing
  const input: IDiscussionboardPrivacyPolicies.ICreate = {
    version: `v${new Date().getFullYear()}.${String(new Date().getMonth() + 1).padStart(2, "0")}`,
    effective_date: new Date().toISOString(),
    title: "Initial Privacy Policy Title",
    content: "Initial full legal content of the privacy policy.",
  };
  const original = await api.functional.discussionboard.privacyPolicies.create(connection, { body: input });
  typia.assert(original);

  // 2. Prepare updated values for all editable fields
  const updateInput: IDiscussionboardPrivacyPolicies.IUpdate = {
    version: `${input.version}-rev1`,
    effective_date: new Date(Date.now() + 86400000).toISOString(), // Next day effective date
    title: "Updated Privacy Policy Title",
    content: "Updated full legal content of the privacy policy.",
  };

  // 3. Update the privacy policy by its id
  const updated = await api.functional.discussionboard.privacyPolicies.update(connection, {
    id: original.id,
    body: updateInput,
  });
  typia.assert(updated);

  // 4. Verify the fields are updated as expected
  TestValidator.equals("id unchanged")(updated.id)(original.id);
  TestValidator.equals("created_at unchanged")(updated.created_at)(original.created_at);
  TestValidator.notEquals("updated_at changed")(updated.updated_at)(original.updated_at);
  TestValidator.equals("version updated")(updated.version)(updateInput.version);
  TestValidator.equals("effective_date updated")(updated.effective_date)(updateInput.effective_date);
  TestValidator.equals("title updated")(updated.title)(updateInput.title);
  TestValidator.equals("content updated")(updated.content)(updateInput.content);
}

