/**
 * Validate that updating a privacy policy with a duplicate version is rejected.
 *
 * This test ensures that the API enforces version uniqueness for privacy policy records.
 * It simulates a situation where two policies exist with different version strings, and then an
 * attempt is made to update one to use the other's version (i.e., forcing a collision).
 *
 * Steps:
 * 1. Create privacy policy A with a unique version (vA)
 * 2. Create privacy policy B with a different unique version (vB)
 * 3. Attempt to update policy B to have version vA (same as A)
 * 4. Confirm that the update is rejected with a uniqueness error on version.
 */
export async function test_api_discussionboard_test_update_privacy_policy_with_duplicate_version(
  connection: api.IConnection,
) {
  // Step 1: Create privacy policy A with unique version vA
  const uniqueVersionA =
    `v${typia.random<number & tags.Type<"uint32">>()}_${typia.random<number & tags.Type<"uint32">>()}`;
  const policyA = await api.functional.discussionboard.privacyPolicies.create(
    connection,
    {
      body: {
        version: uniqueVersionA,
        effective_date: new Date(Date.now() + 1000 * 60 * 60 * 24).toISOString(), // tomorrow
        title: `Test Privacy Policy A ${RandomGenerator.alphaNumeric(6)}`,
        content: `Policy A Content ${RandomGenerator.alphabets(10)}`,
      } satisfies IDiscussionboardPrivacyPolicies.ICreate,
    },
  );
  typia.assert(policyA);

  // Step 2: Create privacy policy B with another unique version vB
  const uniqueVersionB =
    `v${typia.random<number & tags.Type<"uint32">>()}_${typia.random<number & tags.Type<"uint32">>()}`;
  const policyB = await api.functional.discussionboard.privacyPolicies.create(
    connection,
    {
      body: {
        version: uniqueVersionB,
        effective_date: new Date(Date.now() + 1000 * 60 * 60 * 48).toISOString(), // day after tomorrow
        title: `Test Privacy Policy B ${RandomGenerator.alphaNumeric(6)}`,
        content: `Policy B Content ${RandomGenerator.alphabets(10)}`,
      } satisfies IDiscussionboardPrivacyPolicies.ICreate,
    },
  );
  typia.assert(policyB);

  // Step 3: Attempt to update policy B to duplicate version of policy A
  await TestValidator.error("updating to duplicate version should fail")(
    async () => {
      await api.functional.discussionboard.privacyPolicies.update(
        connection,
        {
          id: policyB.id,
          body: {
            version: uniqueVersionA, // duplicate version
            effective_date: policyB.effective_date,
            title: policyB.title,
            content: policyB.content,
          } satisfies IDiscussionboardPrivacyPolicies.IUpdate,
        },
      );
    },
  );
}

