import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IModeratorAssignment } from "@ORGANIZATION/PROJECT-api/lib/structures/IModeratorAssignment";
import type { IBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoard";
import type { IDiscussionboardBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardModerator";
import type { IPageDiscussionboardBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionboardBoardModerators } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardModerators";

/**
 * Test listing board-moderator assignments with a variety of filter and pagination options.
 *
 * This test constructs a full workflow for assigning moderators to boards, then validates
 * the query/list endpoint for moderator-board assignments (PATCH /discussionboard/boardModerators)
 * with multiple realistic filters and pagination. Both positive and negative (empty result)
 * cases are tested.
 *
 * 1. Create two boards (different categories/sections).
 * 2. Create two moderators (simulate as unique members/admins).
 * 3. Assign Board 1 to Moderator 1 as primary; Board 2 to Moderator 2 as non-primary; Board 2 to Moderator 1 as secondary.
 * 4. Filter on moderator or board, filter on is_primary, test date filtering, and various page/limit settings.
 * 5. Validate pagination (e.g., page=2 with limit=1 yields second result).
 * 6. Edge case: Query for a random UUID that should return no results.
 */
export async function test_api_discussionboard_test_list_board_moderator_assignments_with_filters(connection: api.IConnection) {
  // 1. Create two boards
  const boardA = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.alphabets(10),
      code: RandomGenerator.alphabets(6),
      description: RandomGenerator.alphabets(15),
      is_active: true,
      is_visible: true,
    },
  });
  typia.assert(boardA);

  const boardB = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.alphabets(10),
      code: RandomGenerator.alphabets(6),
      description: RandomGenerator.alphabets(15),
      is_active: true,
      is_visible: true,
    },
  });
  typia.assert(boardB);

  // 2. Create two moderators
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const mod1 = await api.functional.discussionboard.moderators.create(connection, {
    body: {
      member_id: typia.random<string & tags.Format<"uuid">>(),
      assigned_by_admin_id: adminId,
      assigned_at: new Date().toISOString(),
      expires_at: null,
    }
  });
  typia.assert(mod1);

  const mod2 = await api.functional.discussionboard.moderators.create(connection, {
    body: {
      member_id: typia.random<string & tags.Format<"uuid">>(),
      assigned_by_admin_id: adminId,
      assigned_at: new Date(Date.now() + 1000).toISOString(),
      expires_at: null,
    }
  });
  typia.assert(mod2);

  // 3. Assign board-moderator relationships
  const joinedNow = new Date().toISOString();
  const assignA1 = await api.functional.discussionboard.boardModerators.create(connection, {
    body: {
      discussionboard_board_id: boardA.id,
      discussionboard_moderator_id: mod1.id,
      is_primary: true,
      joined_at: joinedNow,
    },
  });
  typia.assert(assignA1);

  const assignB2 = await api.functional.discussionboard.boardModerators.create(connection, {
    body: {
      discussionboard_board_id: boardB.id,
      discussionboard_moderator_id: mod2.id,
      is_primary: false,
      joined_at: new Date(Date.now() + 3000).toISOString(),
    },
  });
  typia.assert(assignB2);

  const assignB1 = await api.functional.discussionboard.boardModerators.create(connection, {
    body: {
      discussionboard_board_id: boardB.id,
      discussionboard_moderator_id: mod1.id,
      is_primary: false,
      joined_at: new Date(Date.now() + 4000).toISOString(),
    },
  });
  typia.assert(assignB1);

  // 4. Filtering - by moderator, board, is_primary, joined_at_from, joined_at_to
  // List all assignments for moderator 1
  let result = await api.functional.discussionboard.boardModerators.index(connection, {
    body: { discussionboard_moderator_id: mod1.id },
  });
  typia.assert(result);
  TestValidator.predicate('All returned assignments for mod1')(
    result.data.every(row => row.discussionboard_moderator_id === mod1.id)
  );

  // List all assignments for board B
  result = await api.functional.discussionboard.boardModerators.index(connection, {
    body: { discussionboard_board_id: boardB.id },
  });
  typia.assert(result);
  TestValidator.predicate('All returned assignments for boardB')(
    result.data.every(row => row.discussionboard_board_id === boardB.id)
  );

  // Filter by primary assignment
  result = await api.functional.discussionboard.boardModerators.index(connection, {
    body: { is_primary: true },
  });
  typia.assert(result);
  TestValidator.predicate('All primary assignments')(
    result.data.every(row => row.is_primary === true)
  );

  // Filter by non-primary assignment
  result = await api.functional.discussionboard.boardModerators.index(connection, {
    body: { is_primary: false },
  });
  typia.assert(result);
  TestValidator.predicate('All non-primary assignments')(
    result.data.every(row => row.is_primary === false)
  );

  // Filter by joined_at_from
  result = await api.functional.discussionboard.boardModerators.index(connection, {
    body: { joined_at_from: joinedNow },
  });
  typia.assert(result);
  TestValidator.predicate('All assignments joined at or after filter')(
    result.data.every(row => row.joined_at >= joinedNow)
  );

  // Pagination (limit 1, get first page)
  result = await api.functional.discussionboard.boardModerators.index(connection, {
    body: { limit: 1, page: 1 },
  });
  typia.assert(result);
  TestValidator.equals('One record only')(result.data.length)(1);
  TestValidator.equals('Correct pagination current')(result.pagination.current)(1);
  TestValidator.equals('Correct limit')(result.pagination.limit)(1);

  // Pagination (page 2, limit 1)
  result = await api.functional.discussionboard.boardModerators.index(connection, {
    body: { limit: 1, page: 2 },
  });
  typia.assert(result);
  TestValidator.equals('One record on page 2')(result.data.length)(1);
  TestValidator.equals('Page two')(result.pagination.current)(2);

  // Large page size (limit=100)
  result = await api.functional.discussionboard.boardModerators.index(connection, {
    body: { limit: 100, page: 1 },
  });
  typia.assert(result);
  TestValidator.predicate('At most 100 records')(result.data.length <= 100);

  // Edge case: Query for random UUID, expect zero results.
  result = await api.functional.discussionboard.boardModerators.index(connection, {
    body: { discussionboard_board_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(result);
  TestValidator.equals('No assignments for random UUID')(result.data.length)(0);
}

