 * This test verifies that the API correctly updates the primary status of a moderator assignment for a board.
 * The workflow ensures the required board and moderator exist, makes the assignment, toggles its primary flag,
 * and checks the update is persisted and reflected in the API response.
 *
 * Steps:
 * 1. Create a board (for assignment)
 * 2. Create a moderator assignment (providing a moderator record)
 * 3. Assign the moderator to the board with is_primary = false
 * 4. Update the assignment to is_primary = true (toggle)
 * 5. Assert that the update succeeded and only the is_primary flag changed
 */
export async function test_api_discussionboard_test_update_board_moderator_assignment_is_primary(
  connection: api.IConnection,
) {
  // 1. Create a board to assign the moderator to
  const boardCreate: IBoard.ICreate = {
    discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
    name: RandomGenerator.alphabets(8),
    code: `board_${RandomGenerator.alphaNumeric(6)}`,
    description: RandomGenerator.paragraph()(),
    is_active: true,
    is_visible: true,
  };
  const board = await api.functional.discussionboard.boards.create(connection, { body: boardCreate });
  typia.assert(board);

  // 2. Create a moderator assignment, which also gives us a moderator id
  const moderatorCreate: IModeratorAssignment.ICreate = {
    member_id: typia.random<string & tags.Format<"uuid">>(),
    assigned_by_admin_id: typia.random<string & tags.Format<"uuid">>(),
    assigned_at: new Date().toISOString(),
    expires_at: null,
  };
  const moderator = await api.functional.discussionboard.moderators.create(connection, { body: moderatorCreate });
  typia.assert(moderator);

  // 3. Create the board-moderator assignment with is_primary false
  const initialIsPrimary = false;
  const assignmentCreate: IDiscussionboardBoardModerators.ICreate = {
    discussionboard_board_id: board.id,
    discussionboard_moderator_id: moderator.id,
    is_primary: initialIsPrimary,
    joined_at: new Date().toISOString(),
  };
  const assignment = await api.functional.discussionboard.boardModerators.create(connection, { body: assignmentCreate });
  typia.assert(assignment);
  TestValidator.equals("is_primary set initially")(assignment.is_primary)(initialIsPrimary);

  // 4. Toggle is_primary to true and update via PUT
  const toggledIsPrimary = !initialIsPrimary;
  const updateInput: IDiscussionboardBoardModerators.IUpdate = {
    is_primary: toggledIsPrimary,
  };
  const updated = await api.functional.discussionboard.boardModerators.update(connection, {
    id: assignment.id,
    body: updateInput,
  });
  typia.assert(updated);

  // 5. Assert the change is correct and rest are unchanged
  TestValidator.equals("is_primary updated")(updated.is_primary)(toggledIsPrimary);
  TestValidator.equals("id constant")(updated.id)(assignment.id);
  TestValidator.equals("moderator constant")(updated.discussionboard_moderator_id)(assignment.discussionboard_moderator_id);
  TestValidator.equals("board constant")(updated.discussionboard_board_id)(assignment.discussionboard_board_id);
  TestValidator.equals("joined_at constant")(updated.joined_at)(assignment.joined_at);
}

