import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IMemberPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberPreference";

/**
 * Validate that the member preferences creation API enforces required fields and fails on omission.
 *
 * This test ensures the system properly rejects create requests for member preferences without required fields. It covers these cases:
 * 1. Omit `member_id` entirely (required, FK to members)
 * 2. Omit the entire request body (should trigger a top-level violation)
 * 3. Provide request with only optional fields, but no `member_id`
 * 4. Provide explicit `null` for `member_id`
 *
 * Steps:
 * 1. Create a valid member using the members API
 * 2. Attempt to create memberPreference without `member_id` and expect error
 * 3. Attempt POST with empty body and expect error
 * 4. Attempt POST with all optional fields but no `member_id` and expect error
 * 5. Attempt POST with member_id: null and expect error
 * 6. (By design, all cases above are validation failures and create no record)
 *
 * The test does NOT check for TypeScript-level compilation errors, only runtime business logic validation on the backend.
 */
export async function test_api_discussionboard_test_create_member_preference_with_missing_required_fields(
  connection: api.IConnection,
) {
  // 1. Create a valid member for use in attempted preferences creates
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Omit member_id entirely
  await TestValidator.error("missing member_id should fail")(() =>
    api.functional.discussionboard.memberPreferences.create(connection, {
      body: {
        // member_id is missing
        receive_email_notifications: true,
      } as any,
    })
  );

  // 3. Omit entire request body (empty object)
  await TestValidator.error("completely empty body should fail")(() =>
    api.functional.discussionboard.memberPreferences.create(connection, {
      body: {} as any,
    })
  );

  // 4. Provide only optional fields with no member_id
  await TestValidator.error("no member_id among only optional fields should fail")(() =>
    api.functional.discussionboard.memberPreferences.create(connection, {
      body: {
        receive_email_notifications: true,
        receive_push_notifications: false,
        preferred_language: "ko",
        dark_mode_enabled: null,
      } as any,
    })
  );

  // 5. Explicitly set member_id: null
  await TestValidator.error("explicit null member_id should fail")(() =>
    api.functional.discussionboard.memberPreferences.create(connection, {
      body: {
        member_id: null,
        receive_email_notifications: false,
      } as any,
    })
  );
}

