/**
 * Test that member preference creation enforces uniqueness per member.
 *
 * Validates that a member cannot have more than one preference record:
 * 1. Creates a new discussion board member with unique credentials.
 * 2. Successfully creates the member's preference record.
 * 3. Attempts to create another preference record for the same member (same member_id), expecting a unique constraint violation.
 *
 * Business impact: This ensures each member can only have one preference record, preventing data duplication and enforcing model invariants. This validation is critical for correct notification and UI behavior.
 *
 * Steps:
 * 1. Create a discussionboard member.
 * 2. Create a preference record for the member.
 * 3. Attempt to create a duplicate preference record for the same member_id. Assert that the API throws an error (unique constraint).
 * 4. Confirm, by business design, that no duplicate preference record can exist after the failure (cannot check via API directly, but the API contract is enforced).
 */
export async function test_api_discussionboard_memberPreferences_test_create_member_preference_when_preference_already_exists_for_member(connection: api.IConnection) {
  // 1. Create a new discussionboard member
  const memberCreateInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    role: "member",
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, { body: memberCreateInput });
  typia.assert(member);

  // 2. Create the member's initial preference record
  const preferenceCreateInput: IMemberPreference.ICreate = {
    member_id: member.id,
    receive_email_notifications: true,
    receive_push_notifications: false,
    preferred_language: "en",
    dark_mode_enabled: true,
  };
  const preference = await api.functional.discussionboard.memberPreferences.create(connection, { body: preferenceCreateInput });
  typia.assert(preference);

  // 3. Attempt to create another preference record (should fail with unique constraint)
  await TestValidator.error("cannot create duplicate member preference")(
    () => api.functional.discussionboard.memberPreferences.create(connection, { body: preferenceCreateInput })
  );
  // 4. By API contract, no duplicate record is created (not directly verifiable, but business rule is enforced).
}

