import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IPostReference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostReference";
import type { IPageIPostReference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPostReference";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Advanced analytics/admin retrieval of post reference records with filtering & pagination.
 *
 * Validates that advanced filters and pagination in the /discussionboard/postReferences PATCH endpoint function as intended:
 * 1. Prepares test data: creates two posts (source & target) and a reference between them.
 * 2. Filters by source_post_id: Only reference(s) pointing from the specified source_post_id must appear.
 * 3. Filters by target_post_id: Only reference(s) pointing to the specified target_post_id must appear.
 * 4. Filters by reference_type: Only reference(s) of matching type should be returned.
 * 5. Pagination (limit): Setting a low limit yields correct number of results and the pagination reflects properly.
 * 6. Filtering with a non-existent value returns empty data array.
 *
 * Note: Member and thread entities are referenced by random UUIDs, as member/thread creation APIs are not available in test context.
 */
export async function test_api_discussionboard_test_list_post_references_with_advanced_filters(
  connection: api.IConnection,
) {
  // 1. Prepare two posts and the reference.
  // Member and thread creation not available; use random UUIDs for foreign keys.
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const memberId = typia.random<string & tags.Format<"uuid">>();

  // Create source post
  const sourcePost = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_member_id: memberId,
      discussionboard_board_id: boardId,
      title: "Source Post",
      body: "This is the source post for reference testing.",
    },
  });
  typia.assert(sourcePost);

  // Create target post
  const targetPost = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_member_id: memberId,
      discussionboard_board_id: boardId,
      title: "Target Post",
      body: "This is the target post for reference testing.",
    },
  });
  typia.assert(targetPost);

  // Create post reference between the two posts
  const refType = "post";
  const postReference = await api.functional.discussionboard.postReferences.create(connection, {
    body: {
      source_post_id: sourcePost.id,
      target_post_id: targetPost.id,
      reference_type: refType,
    },
  });
  typia.assert(postReference);

  // 2. Retrieve by source_post_id; validate only correct references are returned
  const bySource = await api.functional.discussionboard.postReferences.index(connection, {
    body: { source_post_id: sourcePost.id },
  });
  typia.assert(bySource);
  TestValidator.predicate("references filtered by source_post_id")(bySource.data.length > 0);
  TestValidator.predicate("all source_post_id matches")(bySource.data.every(x => x.source_post_id === sourcePost.id));

  // 3. Retrieve by target_post_id; validate only correct references are returned
  const byTarget = await api.functional.discussionboard.postReferences.index(connection, {
    body: { target_post_id: targetPost.id },
  });
  typia.assert(byTarget);
  TestValidator.predicate("references filtered by target_post_id")(byTarget.data.length > 0);
  TestValidator.predicate("all target_post_id matches")(byTarget.data.every(x => x.target_post_id === targetPost.id));

  // 4. Filter by reference_type
  const byType = await api.functional.discussionboard.postReferences.index(connection, {
    body: { reference_type: refType },
  });
  typia.assert(byType);
  TestValidator.predicate("references filtered by reference_type")(byType.data.length > 0);
  TestValidator.predicate("all reference_type matches")(byType.data.every(x => x.reference_type === refType));

  // 5. Pagination - limit
  const byLimit = await api.functional.discussionboard.postReferences.index(connection, {
    body: { limit: 1 },
  });
  typia.assert(byLimit);
  TestValidator.equals("pagination limit")(byLimit.data.length)(1);
  TestValidator.equals("pagination meta")(byLimit.pagination.limit)(1);

  // 6. Non-existent filter value yields empty data
  const byFakeSource = await api.functional.discussionboard.postReferences.index(connection, {
    body: { source_post_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(byFakeSource);
  TestValidator.equals("no results for unknown source_post_id")(byFakeSource.data.length)(0);
}

