/**
 * Validate hard deletion (erase) of a post reference by its id and error/idempotency rules.
 *
 * This function tests the following behaviors:
 * 1. Set up: Create two posts (to be used as source and target of the post reference).
 * 2. Set up: Create a post reference pointing from source -> target.
 * 3. Action: Delete the post reference by its id via hard-delete.
 * 4. Validation: Attempt deleting the same id again; assert API returns a not found or similar error, confirming idempotent delete semantics.
 * 5. Validation: Attempt to delete a random (non-existent) UUID; assert proper error is thrown and no side effect occurs.
 *
 * Additional verification is not possible (no list/read endpoint), so deletion is only verified via (lack of) errors and contract compliance.
 */
export async function test_api_discussionboard_test_delete_post_reference_and_handle_idempotency(
  connection: api.IConnection,
) {
  // 1. Create source post
  const sourcePost = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(8),
      body: RandomGenerator.content()()(20, 50),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(sourcePost);

  // 2. Create target post
  const targetPost = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(8),
      body: RandomGenerator.content()()(20, 50),
