import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { Idiscussionboard_post_reports } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_post_reports";
import type { IPageIdiscussionboard_post_reports } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIdiscussionboard_post_reports";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate filtering and pagination for the post report listing endpoint.
 *
 * This test ensures that the PATCH /discussionboard/postReports endpoint correctly supports all documented filters—by reporter, post, report_type_id, and created_at date range—and supports pagination. It covers positive and negative (empty results) scenarios.
 *
 * Business context: Moderators or analytics tools use this endpoint to triage, survey, or analyze post reports. Real-world queries often involve combinations of filters, and the paging controls are essential for large data sets.
 *
 * Steps:
 * 1. Create several discussion posts to serve as possible report targets.
 * 2. Use at least two different reporter_member_ids and at least two report_type_ids for variety.
 * 3. File several post reports using different combinations of (post, reporter, report_type), spacing out created_at values to test date range filtering.
 * 4. Call the PATCH /discussionboard/postReports endpoint with various filters:
 *    a. By specific discussionboard_post_id
 *    b. By specific reporter_member_id
 *    c. By specific report_type_id
 *    d. By created_at date range inclusions/exclusions
 *    e. Combination of filters (AND logic)
 *    f. Pagination: set limit=2 and page=1,2,3 to validate paging works as expected
 *    g. Negative case: filter by post_id and reporter_member_id that do not overlap (expect empty results)
 * 5. For each query, assert that all returned report rows match the filter(s) and that pagination info reflects the query parameters and data set size. For the empty-result search, verify the result set is empty and pagination reflects zero records.
 *
 * This test covers realistic moderator dashboard or back-office analytics workflows, ensuring that all critical combinations are handled and the data structure remains consistent across filter and paging conditions.
 */
export async function test_api_discussionboard_postReports_test_list_post_reports_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // Helpers for later assertions
  function check_all<T>(arr: T[], pred: (t: T) => boolean, message: string) {
    for (const x of arr) {
      TestValidator.predicate(message)(pred(x));
    }
  }

  // 1. Create some discussion posts for reporting.
  const postA = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: `Test post A ${RandomGenerator.alphaNumeric(6)}`,
      body: `Body for post A ${RandomGenerator.alphaNumeric(12)}`,
    },
  });
  typia.assert(postA);
  const postB = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: `Test post B ${RandomGenerator.alphaNumeric(6)}`,
      body: `Body for post B ${RandomGenerator.alphaNumeric(12)}`,
    },
  });
  typia.assert(postB);

  // 2. Generate some members to use as reporters
  const reporter1_id = typia.random<string & tags.Format<"uuid">>();
  const reporter2_id = typia.random<string & tags.Format<"uuid">>();

  // 3. Pick some report_type_ids
  const reportTypeSpam = typia.random<string & tags.Format<"uuid">>();
  const reportTypeAbuse = typia.random<string & tags.Format<"uuid">>();

  // 4. Timestamps for testing date range
  const now = new Date();
  const past = new Date(now.getTime() - 1000 * 60 * 60 * 24 * 2); // 2 days ago
  const future = new Date(now.getTime() + 1000 * 60 * 60 * 24 * 2); // 2 days ahead
  const isoNow = now.toISOString();
  const isoPast = past.toISOString();
  const isoFuture = future.toISOString();

  // 5. Reports: variegate reporter/post/type/created_at combinations
  //   R1: [postA, reporter1, spam, past]
  //   R2: [postA, reporter2, abuse, now]
  //   R3: [postB, reporter1, abuse, future]
  //   R4: [postB, reporter2, spam, now]
  const reports = [
    {
      discussionboard_post_id: postA.id,
      reporter_member_id: reporter1_id,
      report_type_id: reportTypeSpam,
      description: "Spam in post A (r1)",
      created_at: isoPast,
    },
    {
      discussionboard_post_id: postA.id,
      reporter_member_id: reporter2_id,
      report_type_id: reportTypeAbuse,
      description: "Abuse in post A (r2)",
      created_at: isoNow,
    },
    {
      discussionboard_post_id: postB.id,
      reporter_member_id: reporter1_id,
      report_type_id: reportTypeAbuse,
      description: "Abuse in post B (r3)",
      created_at: isoFuture,
    },
    {
      discussionboard_post_id: postB.id,
      reporter_member_id: reporter2_id,
      report_type_id: reportTypeSpam,
      description: "Spam in post B (r4)",
      created_at: isoNow,
    },
  ];
  const createdReports = [] as Idiscussionboard_post_reports[];
  for (const r of reports) {
    const out = await api.functional.discussionboard.postReports.create(connection, {
      body: r,
    });
    typia.assert(out);
    createdReports.push(out);
  }

  // Helper for fetching and asserting report list
  async function queryAndAssert(
    filter: Partial<Idiscussionboard_post_reports.IRequest> & { page?: number; limit?: number },
    expectPred: (r: Idiscussionboard_post_reports) => boolean,
    expectCount: number | null = null,
    msgSuffix: string = "",
  ) {
    const result = await api.functional.discussionboard.postReports.index(connection, {
      body: filter as Idiscussionboard_post_reports.IRequest,
    });
    typia.assert(result);
    // Validate every item matches filter predicate
    check_all(
      result.data,
      expectPred,
      `report matches filter${msgSuffix ? ": " + msgSuffix : ""}`,
    );
    // If an expected count is given, validate
    if (expectCount !== null) {
      TestValidator.equals(`expected report count${msgSuffix ? ": " + msgSuffix : ""}`)(result.data.length)(expectCount);
    }
    // Type-safe: check pagination info. Pages >= 1 if there are records; pages === 0 if none.
    TestValidator.predicate(`pagination object${msgSuffix}`)(typeof result.pagination === "object");
    if (expectCount !== null) {
      const expectedPages = Math.ceil(expectCount / (filter.limit ?? result.pagination.limit));
      TestValidator.equals(`pagination.pages${msgSuffix}`)(result.pagination.pages)(expectedPages);
      TestValidator.equals(`pagination.records${msgSuffix}`)(result.pagination.records)(expectCount);
    }
    return result;
  }

  // 6. Now, filter by each field in turn

  // a. By discussionboard_post_id (postA)
  await queryAndAssert(
    { discussionboard_post_id: postA.id },
    (r) => r.discussionboard_post_id === postA.id,
    2,
    "filter by postA",
  );

  // b. By reporter_member_id (reporter1)
  await queryAndAssert(
    { reporter_member_id: reporter1_id },
    (r) => r.reporter_member_id === reporter1_id,
    2,
    "filter by reporter1",
  );

  // c. By report_type_id (abuse)
  await queryAndAssert(
    { report_type_id: reportTypeAbuse },
    (r) => r.report_type_id === reportTypeAbuse,
    2,
    "filter by reportTypeAbuse",
  );

  // d. By created_at date range (gte: now, should catch R2, R3, R4)
  await queryAndAssert(
    { created_at_gte: isoNow },
    (r) => new Date(r.created_at) >= new Date(isoNow),
    3,
    "created_at >= now",
  );
  //    ... and lte: now (should catch R1, R2, R4)
  await queryAndAssert(
    { created_at_lte: isoNow },
    (r) => new Date(r.created_at) <= new Date(isoNow),
    3,
    "created_at <= now",
  );

  // e. Combination: postB + report_type_id: abuse (should be one: R3)
  await queryAndAssert(
    { discussionboard_post_id: postB.id, report_type_id: reportTypeAbuse },
    (r) => r.discussionboard_post_id === postB.id && r.report_type_id === reportTypeAbuse,
    1,
    "postB + reportTypeAbuse",
  );

  // f. Pagination: limit=2; page=1 (should be first two by order?), page=2 (second 2)
  const result1 = await api.functional.discussionboard.postReports.index(connection, {
    body: { limit: 2, page: 1 },
  });
  typia.assert(result1);
  TestValidator.equals("pagination current=1")(result1.pagination.current)(1);
  TestValidator.equals("pagination limit=2")(result1.pagination.limit)(2);
  TestValidator.equals("first page count")(result1.data.length)(2);

  const result2 = await api.functional.discussionboard.postReports.index(connection, {
    body: { limit: 2, page: 2 },
  });
  typia.assert(result2);
  TestValidator.equals("pagination current=2")(result2.pagination.current)(2);
  TestValidator.equals("second page count")(result2.data.length)(2);

  //   page 3 should be empty since only 4 reports
  const result3 = await api.functional.discussionboard.postReports.index(connection, {
    body: { limit: 2, page: 3 },
  });
  typia.assert(result3);
  TestValidator.equals("pagination current=3")(result3.pagination.current)(3);
  TestValidator.equals("third page empty")(result3.data.length)(0);

  // g. Negative: postA + report_type_id: spam + reporter2_id (no match)
  await queryAndAssert(
    {
      discussionboard_post_id: postA.id,
      report_type_id: reportTypeSpam,
      reporter_member_id: reporter2_id,
    },
    () => false, // No result must match
    0,
    "negative empty filter",
  );
}

