 *
 * Steps:
 * 1. Create a new board to be associated with board settings, supplying valid identifiers and display data.
 * 2. Create a settings record for that board, providing explicit field values for every setting required by the schema.
 * 3. Fetch those board settings using their ID.
 * 4. Assert that every field is present and matches the creation input (exact match for all non-datetime fields).
 * 5. Predicate-check the timestamps are defined.
 */
export async function test_api_discussionboard_boardSettings_test_get_board_setting_by_valid_id(
  connection: api.IConnection
) {
  // 1. Create a new board to associate with settings
  const boardInput: IBoard.ICreate = {
