  // 3. Fetch the settings by ID
  const fetched = await api.functional.discussionboard.boardSettings.at(connection, {
    id: createdSetting.id,
  });
  typia.assert(fetched);

  // 4. Assert values match input exactly for all business fields
  TestValidator.equals("id")(fetched.id)(createdSetting.id);
  TestValidator.equals("discussionboard_board_id")(fetched.discussionboard_board_id)(settingInput.discussionboard_board_id);
  TestValidator.equals("is_locked")(fetched.is_locked)(settingInput.is_locked);
  TestValidator.equals("require_approval_for_posting")(fetched.require_approval_for_posting)(settingInput.require_approval_for_posting);
  TestValidator.equals("max_posts_per_hour")(fetched.max_posts_per_hour)(settingInput.max_posts_per_hour);
