/**
 * Test deleting an existing board settings record by id.
 *
 * This test ensures that a board settings record can be hard-deleted by its unique id,
 * and that the deletion is reflected in persistent storage (i.e., subsequent delete attempts fail).
 *
 * Business Context:
 * - Board settings entities are system configuration records attached to boards
 * - Hard delete is required (no soft-delete fields in schema)
 *
 * Steps:
 * 1. Create a board (required to create a valid board settings record)
 * 2. Create a board settings record referencing the created board
 * 3. Delete the board settings record by id and validate the response
 * 4. Attempt to delete the same record again and verify correct handling (should fail)
 *
 * Note: The scenario requests validation that a get-by-id fetch returns not-found after deletion,
 * but such a fetch API is not available, so only deletion mechanics are tested.
 */
export async function test_api_discussionboard_boardSettings_test_delete_board_setting_by_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a board (dependency for settings)
  const board: IBoard = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.paragraph()(),
      code: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(),
      is_active: true,
      is_visible: true,
    } satisfies IBoard.ICreate,
  });
  typia.assert(board);

  // 2. Create a board settings record referencing the above board
  const boardSetting: IDiscussionboardBoardSetting =
    await api.functional.discussionboard.boardSettings.create(connection, {
      body: {
        discussionboard_board_id: board.id,
        is_locked: false,
        require_approval_for_posting: false,
        max_posts_per_hour: 100,
        allow_anonymous_viewing: true,
        allow_file_uploads: true,
      } satisfies IDiscussionboardBoardSetting.ICreate,
    });
  typia.assert(boardSetting);

  // 3. Delete the board settings record by id
  const delResult: IDiscussionboardBoardSetting.IDeleteResult =
    await api.functional.discussionboard.boardSettings.erase(connection, {
      id: boardSetting.id,
    });
  typia.assert(delResult);
  TestValidator.equals("deletion succeeded")(delResult.success)(true);
  TestValidator.equals("deleted_id matches")(delResult.deleted_id)(boardSetting.id);

  // 4. Attempt to delete again - should return success false (already deleted)
  const delResult2: IDiscussionboardBoardSetting.IDeleteResult =
    await api.functional.discussionboard.boardSettings.erase(connection, {
      id: boardSetting.id,
    });
  typia.assert(delResult2);
  TestValidator.equals("delete returns false since already deleted")(delResult2.success)(false);
}

