 * Business context: Verifies the PUT /discussionboard/sections/{id} endpoint updates a section's metadata appropriately when provided with valid new values. This test ensures that admins or managers can modify section details (like name, code, description, order, active flag, or even change its parent channel) as expected, reflecting accurate updates in the returned object.
 *
 * Step-by-step process:
 * 1. Create a discussion board channel (needed for section linkage)
 * 2. Create an initial section, attached to the created channel
 * 3. Create another channel (to test moving the section to a new channel via update)
 * 4. Prepare new values: change the channel linkage, update code, name, description, position, and active status
 * 5. Call the update endpoint with the new values
 * 6. Validate that the returned section object reflects the changes,
 *    and that only recognized fields were updated.
 */
export async function test_api_discussionboard_sections_test_update_section_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create the first channel
  const channel1 = await api.functional.discussionboard.channels.create(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(6),
      name: RandomGenerator.paragraph()(2),
      description: RandomGenerator.paragraph()(1),
      position: 1,
      active: true,
    } satisfies IDiscussionboardChannel.ICreate,
  });
  typia.assert(channel1);

  // 2. Create the section linked to channel1
  const section = await api.functional.discussionboard.sections.create(connection, {
    body: {
      discussionboard_channel_id: channel1.id,
      code: RandomGenerator.alphaNumeric(5),
      name: RandomGenerator.paragraph()(2),
      description: RandomGenerator.paragraph()(1),
      position: 1,
      active: true,
    } satisfies IDiscussionboardSection.ICreate,
  });
  typia.assert(section);

  // 3. Create a second channel for move-to-channel test
  const channel2 = await api.functional.discussionboard.channels.create(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(6),
      name: RandomGenerator.paragraph()(2),
      description: RandomGenerator.paragraph()(1),
      position: 2,
      active: true,
    } satisfies IDiscussionboardChannel.ICreate,
  });
