  const updateInput: IDiscussionboardSection.IUpdate = {
    discussionboard_channel_id: section.discussionboard_channel_id,
    code: section.code + "_edit",
    name: section.name + "_edited",
    position: section.position,
    active: !section.active,
    description: section.description ? section.description + "_updated" : "temp updated desc",
  };
  // 인증 없이 호출: Authorization 헤더 명시적으로 삭제
  const unauthConn = { ...connection, headers: { ...connection.headers } };
  if (unauthConn.headers) delete unauthConn.headers["Authorization"];
  await TestValidator.error("권한 없는 update 요청은 반드시 거절되어야 함")(async () => {
    await api.functional.discussionboard.sections.update(unauthConn, {
      id: section.id,
      body: updateInput,
