export async function test_api_discussionboard_test_create_board_category_with_valid_data(
  connection: api.IConnection,
) {
  // 1. 고유하면서도 유효한 카테고리 입력 데이터 생성
  const payload: IDiscussionboardBoardCategory.ICreate = {
    name: `카테고리_${RandomGenerator.alphaNumeric(8)}`,
    code: `cat_${RandomGenerator.alphaNumeric(5)}`,
    description: RandomGenerator.paragraph()(),
    position: typia.random<number & tags.Type<"int32">>(),
  };

  // 2. 카테고리 생성 API 호출
  const created = await api.functional.discussionboard.boardCategories.create(
    connection,
    {
      body: payload,
    },
  );
  typia.assert(created);

