import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardCategory";

/**
 * Test successful hard deletion of a board category (irreversible removal).
 *
 * This test verifies that a board category can be hard deleted, ensuring its permanent
 * removal from the system. It simulates a typical admin workflow:
 *
 * 1. Create a new board category using valid random data (ensuring unique code and name)
 * 2. Delete the newly created board category using its id
 * 3. Confirm the deletion response contains success: true and correct deleted_id
 * 4. Attempt to delete the same id again; assert that the deletion fails (success: false),
 *    confirming that the entity no longer exists (serves as proxy for 404 since GET by id does not exist)
 */
export async function test_api_discussionboard_boardCategories_test_delete_board_category_successfully(
  connection: api.IConnection,
) {
  // 1. Create a new board category (setup)
  const category = await api.functional.discussionboard.boardCategories.create(connection, {
    body: {
      name: RandomGenerator.paragraph()(1),
      code: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.content()()(),
      position: typia.random<number & tags.Type<"int32">>(),
    } satisfies IDiscussionboardBoardCategory.ICreate,
  });
  typia.assert(category);

  // 2. Hard delete the board category by id
  const delResult = await api.functional.discussionboard.boardCategories.erase(connection, {
    id: category.id,
  });
  typia.assert(delResult);
  TestValidator.predicate("deletion must succeed")(delResult.success === true);
  TestValidator.equals("deleted id matches")(delResult.deleted_id)(category.id);

  // 3. Confirm subsequent deletion fails (proxy for not found)
  const delAgain = await api.functional.discussionboard.boardCategories.erase(connection, {
    id: category.id,
  });
  typia.assert(delAgain);
  TestValidator.equals("second delete should fail")(delAgain.success)(false);
  TestValidator.predicate("reason should indicate missing or already deleted")(
    typeof delAgain.reason === "string" && !!delAgain.reason,
  );
}

