import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardWarning";
import type { IPageIDiscussionboardWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardWarning";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test retrieving a paginated and filtered list of member warning records from the discussionboard_warnings table.
 *
 * Validates the /discussionboard/warnings PATCH API which lists warnings with support for filtering (acting_moderator_id, warned_member_id, warned_at date range), combination filters, and pagination. Also confirms that response objects only contain actual schema-defined fields. Ensures that unauthorized users (non-moderators/admins) cannot access results. Checks validation error handling for invalid filter fields and values, and tests scenarios for large datasets, paging bounds, and empty result sets.
 *
 * Steps:
 * 1. Create multiple members with various roles (member, moderator, admin)
 * 2. Issue several warnings using moderator/admin accounts -- vary attributes for warning diversity
 * 3. As moderator or admin, retrieve full, paginated warning lists without filters and confirm paging works with correct records/metadata
 * 4. Query with acting_moderator_id, warned_member_id, and warned_at filters 
 * 5. Run combination filter queries and verify accuracy of returned results
 * 6. Try to access with a normal member account (should be restricted/return error — SKIPPED: user role switching API not present)
 * 7. Provide invalid/unsupported fields in body and expect validation errors
 * 8. Test boundary: request pages beyond available records, and empty filters (should return empty result set with paginated metadata)
 * 9. Confirm no extra fields are present in response objects
 */
export async function test_api_discussionboard_warnings_test_list_warnings_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create users: 1 admin, 2 moderators, 3 normal members
  const users = await Promise.all([
    api.functional.discussionboard.members.create(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(16),
        role: "admin",
        is_active: true,
      } satisfies IDiscussionboardMember.ICreate,
    }),
    api.functional.discussionboard.members.create(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(16),
        role: "moderator",
        is_active: true,
      } satisfies IDiscussionboardMember.ICreate,
    }),
    api.functional.discussionboard.members.create(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(16),
        role: "moderator",
        is_active: true,
      } satisfies IDiscussionboardMember.ICreate,
    }),
    api.functional.discussionboard.members.create(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(16),
        role: "member",
        is_active: true,
      } satisfies IDiscussionboardMember.ICreate,
    }),
    api.functional.discussionboard.members.create(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(16),
        role: "member",
        is_active: true,
      } satisfies IDiscussionboardMember.ICreate,
    }),
    api.functional.discussionboard.members.create(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(16),
        role: "member",
        is_active: true,
      } satisfies IDiscussionboardMember.ICreate,
    }),
  ]);

  // 2. Issue warnings as moderators/admins; diversify attributes
  const mod1 = users[1];
  const mod2 = users[2];
  const admin = users[0];
  const member1 = users[3];
  const member2 = users[4];
  const member3 = users[5];

  // Different warnings: alternate moderators, members, timestamps, reasons
  const warnings: IDiscussionboardWarning[] = [];
  for (let i = 0; i < 12; ++i) {
    const moderator = i % 2 === 0 ? mod1 : mod2;
    const warned_member = i % 3 === 0 ? member1 : i % 3 === 1 ? member2 : member3;
    const warned_at = new Date(Date.now() - i * 1000 * 60 * 60).toISOString();
    const warning = await api.functional.discussionboard.warnings.create(connection, {
      body: {
        warned_member_id: warned_member.id,
        acting_moderator_id: moderator.id,
        reason: `Test warning ${i}`,
        warned_at,
      } satisfies IDiscussionboardWarning.ICreate,
    });
    warnings.push(warning);
  }

  // 3. As moderator, get paginated warning list with no filters
  let page = 1,
    perPage = 5;
  let resultPage = await api.functional.discussionboard.warnings.index(connection, {
    body: {
      page,
      limit: perPage,
    },
  });
  typia.assert(resultPage);
  TestValidator.equals("page count")(resultPage.pagination.current)(page);
  TestValidator.equals("per page")(resultPage.pagination.limit)(perPage);

  // 4. Filter by acting_moderator_id
  let filterByMod1 = await api.functional.discussionboard.warnings.index(connection, {
    body: { acting_moderator_id: mod1.id },
  });
  typia.assert(filterByMod1);
  for (let w of filterByMod1.data)
    TestValidator.equals("mod id")(w.acting_moderator_id)(mod1.id);

  // 5. Filter by warned_member_id
  let filterByMember2 = await api.functional.discussionboard.warnings.index(connection, {
    body: { warned_member_id: member2.id },
  });
  typia.assert(filterByMember2);
  for (let w of filterByMember2.data)
    TestValidator.equals("member id")(w.warned_member_id)(member2.id);

  // 6. Filter by warned_at (use existing warning date)
  let warnedAtDate = warnings[6].warned_at;
  let filterByWarnedAt = await api.functional.discussionboard.warnings.index(connection, {
    body: { warned_at: warnedAtDate },
  });
  typia.assert(filterByWarnedAt);
  for (let w of filterByWarnedAt.data)
    TestValidator.equals("warned_at time")(w.warned_at)(warnedAtDate);

  // 7. Combined filter
  let combined = await api.functional.discussionboard.warnings.index(connection, {
    body: {
      acting_moderator_id: mod2.id,
      warned_member_id: member3.id,
    },
  });
  typia.assert(combined);
  for (let w of combined.data) {
    TestValidator.equals("mod id")(w.acting_moderator_id)(mod2.id);
    TestValidator.equals("member id")(w.warned_member_id)(member3.id);
  }

  // 8. Empty results for non-matching filter
  let emptyRes = await api.functional.discussionboard.warnings.index(connection, {
    body: { acting_moderator_id: admin.id, warned_member_id: member1.id },
  });
  typia.assert(emptyRes);
  TestValidator.equals("no records")(emptyRes.data.length)(0);

  // 9. Very large page (test limit)
  let largePage = await api.functional.discussionboard.warnings.index(connection, {
    body: { page: 1, limit: 1000 },
  });
  typia.assert(largePage);
  TestValidator.predicate("large data: has all records")(largePage.data.length >= warnings.length);

  // 10. Out of bounds page
  let lastPageNum = Math.max(2, Math.ceil(largePage.pagination.records / perPage) + 1);
  let outOfBounds = await api.functional.discussionboard.warnings.index(connection, {
    body: {
      page: lastPageNum,
      limit: perPage,
    },
  });
  typia.assert(outOfBounds);
  TestValidator.equals("empty out of bounds")(outOfBounds.data.length)(0);

  // 11. Check only schema fields are present in warnings
  if (resultPage.data.length) {
    for (let w of resultPage.data) {
      const keys = Object.keys(w).sort();
      const expected = [
        "id",
        "warned_member_id",
        "acting_moderator_id",
        "report_id",
        "reason",
        "warned_at",
      ].sort();
      TestValidator.equals("schema fields match")(keys)(expected);
    }
  }

  // 12. SKIPPED: Cannot test as a normal member due to lack of user session switching API.

  // 13. Send invalid field (should get validation error)
  await TestValidator.error("rejects unknown fields")(
    async () => {
      await api.functional.discussionboard.warnings.index(connection, {
        body: {
          acting_moderator_id: mod1.id,
          some_invalid_field: "invalid",
        } as any,
      });
    },
  );

  // 14. Send invalid value (bad uuid format)
  await TestValidator.error("rejects bad uuid")(
    async () => {
      await api.functional.discussionboard.warnings.index(connection, {
        body: {
          acting_moderator_id: "not-a-uuid" as any,
        },
      });
    },
  );
}

