import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardWarning";

/**
 * 특정 경고(warning) 레코드의 상세 조회(GET) 기능을 정상/오류 경로로 검증합니다.
 *
 * 1. 임의 member(경고 대상) 생성
 * 2. 임의 admin(경고 발급자) 생성
 * 3. 위 멤버에게 warning 발급 및 해당 warning id 획득
 * 4. 해당 warning id로 상세 조회 - 모든 스키마 정의 필드가 정확하게 반환되는지, 추가/민감 정보 노출 없음 확인
 * 5. 존재하지 않는 warning id로 조회 시 404 오류 등 적절한 예외처리 발생 확인
 *
 * - 스키마 필드 외 값 노출 여부 검증: 반환키 Object.keys 정렬로 strict 체크
 * - 관리자 권한 인증 API가 없으므로, acting_moderator_id는 직접 생성한 admin member id를 사용
 *
 *
 * @author Wrtn AutoBE
 */
export async function test_api_discussionboard_test_retrieve_warning_by_id_with_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. 테스트용 멤버 생성(경고 받을 멤버)
  const memberReq: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphabets(12),
    role: "member",
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, { body: memberReq });
  typia.assert(member);

  // 2. 테스트용 관리자 생성(acting_moderator_id 부여 목적)
  const moderatorReq: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphabets(14),
    role: "admin",
    is_active: true,
  };
  const moderator = await api.functional.discussionboard.members.create(connection, { body: moderatorReq });
  typia.assert(moderator);

  // 3. 경고(warning) 발급 (report_id=null: 인시던트 미연결)
  const now = new Date().toISOString();
  const warningReq: IDiscussionboardWarning.ICreate = {
    warned_member_id: member.id,
    acting_moderator_id: moderator.id,
    report_id: null,
    reason: "테스트 경고 사유: 정책 위반",
    warned_at: now,
  };
  const warning = await api.functional.discussionboard.warnings.create(connection, { body: warningReq });
  typia.assert(warning);

  // 4. 정상 id 상세조회: 모든 필드 일치 및 스키마 외 값 없음 보장
  const detail = await api.functional.discussionboard.warnings.at(connection, { id: warning.id });
  typia.assert(detail);
  TestValidator.equals("id 일치")(detail.id)(warning.id);
  TestValidator.equals("warned_member_id 일치")(detail.warned_member_id)(warningReq.warned_member_id);
  TestValidator.equals("acting_moderator_id 일치")(detail.acting_moderator_id)(warningReq.acting_moderator_id);
  TestValidator.equals("report_id 일치")(detail.report_id)(warningReq.report_id);
  TestValidator.equals("reason 일치")(detail.reason)(warningReq.reason);
  TestValidator.equals("warned_at 일치")(detail.warned_at)(warningReq.warned_at);
  TestValidator.predicate("스키마 외 필드 없음")(Object.keys(detail).sort().join(",") === Object.keys(warning).sort().join(","));

  // 5. 존재하지 않는 id로 조회하면 오류 발생(404 등)
  await TestValidator.error("존재하지 않는 warning id 오류")(
    async () => {
      await api.functional.discussionboard.warnings.at(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );
}

