import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardWarning";

/**
 * 관리자/모더레이터 권한 접근 및 경고 레코드 접근 제어 테스트
 *
 * 토론 게시판 경고 레코드 단건 조회 API의 접근 제어를 검증한다. 이 테스트는 다음 기술적, 비즈니스 시나리오를 검증한다:
 *
 * 1. 권한이 있는 관리자(혹은 모더레이터)로 경고 레코드를 생성하고 해당 ID로 정상 조회가 가능해야 한다.
 * 2. 인증이 해제된 상태(Authorization 헤더 미포함)에서는 같은 레코드 단건 조회 시 반드시 접근 거부 에러가 발생해야 한다.
 * 3. (실제 프로젝트에 member 인증 API가 제공된다면) 권한 없는 일반 멤버로 로그인 후 동일 액세스 시도는 반드시 접근 거부되어야 한다.
 *
 * [구현 세부]
 * - 테스트 기본 connection은 최고 관리자 권한이 부여된 것으로 간주한다.
 * - 인증 해제(비로그인) context는 Authorization 헤더만 제거하여 검증한다.
 * - 일반 member 권한 context는 실제 멤버 인증 API 제공 여부에 따라 확장/주석 처리한다.
 * - 테스트 경고 레코드는 직접 생성후, 이후 액세스 시험에 활용한다.
 *
 * [시나리오 순서]
 * 1. 최고 관리자/모더레이터 권한 상태에서 warning 생성 후 반환 ID 획득
 * 2. 정상 상태에서 단일 경고 상세 조회 성공 및 데이터 구조/내용 일치 검증
 * 3. 인증 해제 상태에서 단일 조회 시 접근 거부(에러) 검증
 * 4. (미제공시 주석) 일반 member 컨텍스트에서 단일 조회 시 접근 거부(에러) 검증
 */
export async function test_api_discussionboard_test_get_warning_access_control(
  connection: api.IConnection,
) {
  // 1. 최고 관리자/모더레이터 권한 상태에서 warning 생성
  const warning = await api.functional.discussionboard.warnings.create(connection, {
    body: typia.random<IDiscussionboardWarning.ICreate>(),
  });
  typia.assert(warning);

  // 2. 정상적인 관리자/모더레이터 인증상태에서 warning 상세 단일조회
  const fetched = await api.functional.discussionboard.warnings.at(connection, { id: warning.id });
  typia.assert(fetched);
  TestValidator.equals("admin or mod fetched data matches created record")(fetched)(warning);

  // 3. 인증 해제(비로그인) context: Authorization 헤더 제거 후 접근 거부 확인
  const noAuthConnection = { ...connection, headers: { ...connection.headers } };
  delete noAuthConnection.headers.Authorization;
  await TestValidator.error("unauthenticated user must be rejected")(
    async () => {
      await api.functional.discussionboard.warnings.at(noAuthConnection, { id: warning.id });
    }
  );

  // 4. (Optional: 실제 member 인증 API가 있다면 확장)
  // 권한 없는 일반 멤버 인증 context로 시도할 때 반드시 거부되어야 함
  // 다음 코드는 member 인증 API가 제공될 경우에만 구현 필요:
  // const memberConnection = ... (권한 없는 멤버 로그인 후 컨텍스트)
  // await TestValidator.error("unauthorized member must be rejected")(
  //   async () => {
  //     await api.functional.discussionboard.warnings.at(memberConnection, { id: warning.id });
  //   }
  // );
}

