import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardWarning";

/**
 * Verify creation of a warning record for a member by a moderator or admin in the discussion board system.
 *
 * Business Context:
 * Warnings are atomic, discipline-escalation records issued by moderators/admins against regular members, possibly tied to a specific moderation incident (by report_id or null if not).
 * Warnings are critical for audit trails, compliance, and enable correct linking between warned members and moderators in system UIs and logs.
 *
 * Test Process:
 * 1. Create a new member to be warned (regular user, active, unique email/username).
 * 2. Create a new member as the moderator/acting admin to issue the warning (role=moderator or role=admin, active, unique email/username).
 * 3. As an authorized actor (simulated; authentication not in API), create a warning with valid warned_member_id, acting_moderator_id, null report_id (case: warning not tied to an incident), proper reason, correctly formatted ISO timestamp.
 * 4. Assert that all returned fields from warning creation are correct:
 *    - warned_member_id and acting_moderator_id match the created users
 *    - report_id is null as specified
 *    - reason matches input
 *    - warned_at field matches input within tolerable delta
 *    - id is a valid UUID
 * 5. (Persistence/audit check) Since retrieval APIs are not provided, we rely on the response and correct typing via typia.assert.
 */
export async function test_api_discussionboard_test_create_warning_for_member_with_valid_data(
  connection: api.IConnection,
) {
  // Step 1: Create the member who will receive the warning
  const warnedMemberInput = {
    username: RandomGenerator.alphaNumeric(12),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(20),
    role: "member",
    is_active: true,
  } satisfies IDiscussionboardMember.ICreate;
  const warnedMember = await api.functional.discussionboard.members.create(connection, { body: warnedMemberInput });
  typia.assert(warnedMember);

  // Step 2: Create the moderator/admin issuing the warning
  const moderatorRole = RandomGenerator.pick(["admin", "moderator"]);
  const moderatorInput = {
    username: RandomGenerator.alphaNumeric(12),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(20),
    role: moderatorRole,
    is_active: true,
  } satisfies IDiscussionboardMember.ICreate;
  const moderator = await api.functional.discussionboard.members.create(connection, { body: moderatorInput });
  typia.assert(moderator);

  // Step 3: Create the warning record with null report_id
  const now = new Date().toISOString();
  const reasonText = "Violation of forum guidelines: inappropriate language.";
  const warningInput = {
    warned_member_id: warnedMember.id,
    acting_moderator_id: moderator.id,
    report_id: null,
    reason: reasonText,
    warned_at: now,
  } satisfies IDiscussionboardWarning.ICreate;
  const warning = await api.functional.discussionboard.warnings.create(connection, { body: warningInput });
  typia.assert(warning);

  // Step 4: Validate returned fields
  // Ensure warned_member_id matches
  TestValidator.equals("warned_member_id matches")(warning.warned_member_id)(warnedMember.id);
  // Ensure acting_moderator_id matches
  TestValidator.equals("acting_moderator_id matches")(warning.acting_moderator_id)(moderator.id);
  // Ensure report_id is null
  TestValidator.equals("report_id is null")(warning.report_id)(null);
  // Ensure reason matches input
  TestValidator.equals("reason matches")(warning.reason)(reasonText);
  // Ensure warned_at matches (within 1 second tolerance)
  TestValidator.equals("warned_at matches within 1 second")(Math.abs(Date.parse(warning.warned_at) - Date.parse(now)) < 1000)(true);
  // typia.assert also validates id is a proper UUID, so no additional id validation needed
}

