import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSetting";
import type { IPageIDiscussionboardSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardSetting";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing of discussion board settings with pagination and various filters.
 *
 * This test simulates an admin using a management UI to audit or search feature/configuration toggles in the system with complex filters. It covers multi-dimensional queries:
 *   - Filter by scope_type (e.g. 'feature_flag', 'channel')
 *   - Filter by key (e.g. partial or exact)
 *   - Filter for specific value(s) (if relevant)
 *   - Filter by active status (simulate by value or description, as there is no explicit 'active' column)
 *   - Paginate (limit, page)
 *   - Order results (orderBy and orderDirection)
 *
 * Steps:
 * 1. Create at least three settings records differing in scope_type, key, value, and description: one with scope_type 'feature_flag' & key 'dark_mode', one with 'feature_flag' & 'beta_access', one with 'channel' & 'max_post_length', using different values & description/null.
 * 2. Run multiple list queries:
 *    - Query by scope_type = 'feature_flag' and key = 'dark_mode' (should return only matching one)
 *    - Paginate with limit = 2 (should return only 2 records, and check meta)
 *    - Query by partial key (q='max') returns only expected one
 *    - Query with sorting (orderBy and orderDirection)
 *    - Query for non-existent value, assert empty results
 * 3. For each query, assert all returned data match filter criteria, all schema fields are present, and pagination meta is correct.
 */
export async function test_api_discussionboard_test_list_settings_with_pagination_and_filtering(
  connection: api.IConnection,
) {
  // 1. Diverse settings record 생성
  const s1 = await api.functional.discussionboard.settings.create(connection, {
    body: {
      scope_type: "feature_flag",
      key: "dark_mode",
      value: "true",
      description: "Dark mode feature toggle",
    },
  });
  typia.assert(s1);
  const s2 = await api.functional.discussionboard.settings.create(connection, {
    body: {
      scope_type: "feature_flag",
      key: "beta_access",
      value: "false",
      description: "Closed beta access",
    },
  });
  typia.assert(s2);
  const s3 = await api.functional.discussionboard.settings.create(connection, {
    body: {
      scope_type: "channel",
      key: "max_post_length",
      value: "1024",
      description: null,
    },
  });
  typia.assert(s3);

  // 2a. scope_type/key 필터로 조회 (s1만 반환)
  let out = await api.functional.discussionboard.settings.index(connection, {
    body: {
      scope_type: "feature_flag",
      key: "dark_mode",
    },
  });
  typia.assert(out);
  TestValidator.equals("Filter scope_type+key count")(out.data.length)(1);
  TestValidator.equals("Returned record is s1")(out.data[0].id)(s1.id);

  // 2b. limit=2 페이지네이션
  out = await api.functional.discussionboard.settings.index(connection, {
    body: {
      limit: 2,
      orderBy: "key",
      orderDirection: "asc",
    },
  });
  typia.assert(out);
  TestValidator.equals("Page limit")(out.data.length)(2);
  TestValidator.equals("Pagination meta limit")(out.pagination.limit)(2);
  TestValidator.equals("First returned sorted key")(out.data[0].key)([s2, s1, s3].sort((a, b) => a.key.localeCompare(b.key))[0].key);

  // 2c. Partial key (q='max') → s3만 반환
  out = await api.functional.discussionboard.settings.index(connection, {
    body: {
      q: "max",
    },
  });
  typia.assert(out);
  TestValidator.equals("Partial-key (q='max') count")(out.data.length)(1);
  TestValidator.equals("Partial-key is s3")(out.data[0].id)(s3.id);

  // 2d. 내림차순 정렬
  out = await api.functional.discussionboard.settings.index(connection, {
    body: {
      orderBy: "key",
      orderDirection: "desc",
    },
  });
  typia.assert(out);
  const allRecs = [s1, s2, s3].sort((a, b) => b.key.localeCompare(a.key));
  TestValidator.equals("Descending key order")(out.data.map((x) => x.key))([
    allRecs[0].key,
    allRecs[1].key,
    allRecs[2].key,
  ]);

  // 2e. No matching (value= '__does_not_exist__')
  out = await api.functional.discussionboard.settings.index(connection, {
    body: {
      value: "__does_not_exist__",
    },
  });
  typia.assert(out);
  TestValidator.equals("No results on nonsense filter")(out.data.length)(0);
  TestValidator.equals("No results pagination records")(out.pagination.records)(0);
}

