/**
 * 게시판 설정 레코드 신규 생성(e2e) 테스트
 *
 * 운영자(admin)가 새로운 게시판 기능 토글 또는 컨텍스트별 규칙(예: 채널별 정책, feature_flag 등)을 추가하는 use-case를 검증합니다.
 * 모든 비즈니스 주요 필드(scope_type, key, value, description 등)를 유효값으로 채워 신규 레코드를 생성한 뒤,
 * 응답 데이터의 스키마 구조와 값 매칭을 확인합니다. NULL 허용 필드는 명시적으로 null 시나리오도 함께 테스트합니다.
 *
 * 단계별 절차:
 * 1. 랜덤(유효성 준수) 데이터로 IDiscussionboardSetting.ICreate를 구성
 * 2. api.functional.discussionboard.settings.create로 신규 레코드 생성
 * 3. 반환 객체가 IDiscussionboardSetting 전체 스키마와 일치하는지 typia.assert로 확인
 * 4. 입력값(key 필드 등)이 응답 속성과 일치하는지 assert
 * 5. (명시적 null 입력 시) 응답 값도 null로 반영되는지 확인
 */
export async function test_api_discussionboard_test_create_setting_with_valid_data(
  connection: api.IConnection,
) {
  // 1. 유효한 신규 설정 데이터 생성
  const createInput: IDiscussionboardSetting.ICreate = {
    scope_id: typia.random<string & tags.Format<"uuid">>(),
    scope_type: "feature_flag",
    key: "auto_approval_enabled",
    value: "true",
    description: "자동 승인 기능 활성 토글",
  };

  // 2. 신규 설정 생성
  const result = await api.functional.discussionboard.settings.create(connection, {
