  // 3. Cast an initial vote ("up")
  const vote = await api.functional.discussionboard.commentVotes.create(connection, {
    body: {
      discussionboard_comment_id: comment.id,
      discussionboard_member_id: member.id,
      vote_type: "up",
    } satisfies IDiscussionboardCommentVote.ICreate,
  });
