import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IDiscussionboardCommentVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentVote";

/**
 * Permanently delete a comment vote by its ID and validate the deletion.
 *
 * This end-to-end scenario validates the following business behaviors:
 *   1. Creation of a discussionboard member (used as voter)
 *   2. Creation of a comment to be voted on
 *   3. Creation of a vote (up/down) on the comment by the member
 *   4. Deletion of the vote using its ID (API: DELETE /discussionboard/commentVotes/:id)
 *   5. Attempting to delete a non-existent vote to ensure a 404 or error is thrown
 *   6. Business edge-case: After deletion, re-create a vote with the same (comment, member, vote_type) tuple to ensure unique constraint is freed
 *
 * Steps:
 *   - Step 1: Create a member using discussionboard.members.create (POST /discussionboard/members)
 *   - Step 2: Create a comment using discussionboard.comments.create (POST /discussionboard/comments)
 *   - Step 3: Create a comment vote using discussionboard.commentVotes.create (POST /discussionboard/commentVotes)
 *   - Step 4: Delete the vote by ID (discussionboard.commentVotes.erase)
 *   - Step 5: Confirm deletion by attempting another delete (discussionboard.commentVotes.erase, expect error)
 *   - Step 6: Re-create the vote with the same (comment, member, vote_type) using discussionboard.commentVotes.create again, expect success
 */
export async function test_api_discussionboard_test_delete_comment_vote_success_and_not_found(
  connection: api.IConnection,
) {
  // Step 1: Create a member (used as the voter)
  const memberInput = {
    username: RandomGenerator.alphaNumeric(10),
    email: RandomGenerator.alphaNumeric(8) + "@example.com",
    hashed_password: RandomGenerator.alphaNumeric(24),
    role: "member",
    is_active: true,
  } satisfies IDiscussionboardMember.ICreate;
  const member = await api.functional.discussionboard.members.create(connection, { body: memberInput });
  typia.assert(member);

  // Step 2: Create a comment (target of the vote)
  const commentInput = {
    discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_member_id: member.id,
    body: RandomGenerator.paragraph()(),
  } satisfies IComment.ICreate;
  const comment = await api.functional.discussionboard.comments.create(connection, { body: commentInput });
  typia.assert(comment);

  // Step 3: Create a vote
  const voteType = "up";
  const voteInput = {
    discussionboard_comment_id: comment.id,
    discussionboard_member_id: member.id,
    vote_type: voteType,
  } satisfies IDiscussionboardCommentVote.ICreate;
  const vote = await api.functional.discussionboard.commentVotes.create(connection, { body: voteInput });
  typia.assert(vote);

  // Step 4: Delete the vote by ID
  const deleted = await api.functional.discussionboard.commentVotes.erase(connection, { id: vote.id });
  typia.assert(deleted);
  TestValidator.equals("vote deleted")(deleted.id)(vote.id);

  // Step 5: Attempt to delete again (should throw)
  await TestValidator.error("deleting already-deleted vote should fail")(
    async () => await api.functional.discussionboard.commentVotes.erase(connection, { id: vote.id })
  );

  // Step 6: Re-create the vote, expect success (unique constraint cleared)
  const reVote = await api.functional.discussionboard.commentVotes.create(connection, { body: voteInput });
  typia.assert(reVote);
  TestValidator.equals("recreated vote should match input")(
    {
      discussionboard_comment_id: reVote.discussionboard_comment_id,
      discussionboard_member_id: reVote.discussionboard_member_id,
      vote_type: reVote.vote_type,
    }
  )(
    voteInput
  );
}

