 *
 * 단계:
 * 1. 신규 멤버 계정 생성
 * 2. 관리자 계정 생성
 * 3. 멤버에 대한 모더레이터 할당 생성
 * 4. 해당 id로 상세정보 조회 & 모든 필드 일치 검증
 * 5. 존재하지 않는 id 조회 시 404 예외 검증
 */
export async function test_api_discussionboard_moderators_test_get_moderator_assignment_detail_success_and_not_found(
  connection: api.IConnection,
) {
  // 1. 신규 멤버 계정 생성
  const member = await api.functional.discussionboard.members.create(
    connection,
    {
      body: {
        username: RandomGenerator.alphaNumeric(10),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(16),
        role: "member",
        is_active: true,
      } satisfies IDiscussionboardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. 관리자 계정 생성
  const admin = await api.functional.discussionboard.members.create(
    connection,
    {
      body: {
        username: RandomGenerator.alphaNumeric(10),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(16),
        role: "admin",
        is_active: true,
      } satisfies IDiscussionboardMember.ICreate,
    },
  );
  typia.assert(admin);

  // 3. 멤버를 모더레이터로 할당 (만료일 없음)
