import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardThreadSnapshots } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreadSnapshots";
import type { IPageIDiscussionboardThreadSnapshots } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardThreadSnapshots";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test paginated, filtered retrieval of thread snapshots (audit/version history).
 *
 * This E2E test ensures that thread snapshot search with different filters (thread_id,
 * actor_id, title substring, creation window, pagination) works as expected, supporting
 * moderation and version audit use-cases.
 *
 * Workflow:
 * 1. Create a thread with a random board_id and author_member_id.
 * 2. Generate several snapshots for the thread, changing titles/content and optionally
 *    using different actor IDs for edits.
 * 3. Query snapshots by thread_id, validating pagination (e.g., limit=2, first/second page).
 * 4. Check filter by actor_id returns only snapshots by that actor.
 * 5. Check filter by title substring matches only correct snapshots.
 * 6. Check filter by creation time returns snapshots in expected window.
 * 7. Edge: search with a non-existent actor or page beyond available results yields empty data.
 *
 * At each step, verify the search results exactly match expected snapshots.
 */
export async function test_api_discussionboard_test_list_thread_snapshots_with_filter_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create a thread
  const board_id = typia.random<string & tags.Format<"uuid">>();
  const author_member_id = typia.random<string & tags.Format<"uuid">>();
  const thread_title = RandomGenerator.paragraph()(3);
  const thread_body = RandomGenerator.content()(1)();
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id,
      author_member_id,
      title: thread_title,
      body: thread_body,
    },
  });
  typia.assert(thread);

  // 2. Generate snapshots (distinct edits/actors/titles/bodies)
  const base_time = new Date();
  const actorA = author_member_id;
  const actorB = typia.random<string & tags.Format<"uuid">>();
  const snap1 = await api.functional.discussionboard.threadSnapshots.create(connection, {
    body: {
      thread_id: thread.id,
      actor_id: actorA,
      title: thread_title,
      body: thread_body,
      reason: "Initial submission",
    },
  });
  typia.assert(snap1);
  await sleep(1000); // ensure different timestamps
  const snap2 = await api.functional.discussionboard.threadSnapshots.create(connection, {
    body: {
      thread_id: thread.id,
      actor_id: actorB,
      title: thread_title + " [edited 1]",
      body: thread_body + "\nEdited once.",
      reason: "First edit by actorB",
    },
  });
  typia.assert(snap2);
  await sleep(1000);
  const snap3 = await api.functional.discussionboard.threadSnapshots.create(connection, {
    body: {
      thread_id: thread.id,
      actor_id: actorA,
      title: thread_title + " [final]",
      body: thread_body + "\nFinal revision.",
      reason: "Final revision by original author",
    },
  });
  typia.assert(snap3);

  // List of snapshots in creation order
  const snapshots = [snap1, snap2, snap3];

  // 3. Query by thread_id, limit=2 (first page)
  const page1 = await api.functional.discussionboard.threadSnapshots.index(connection, {
    body: { thread_id: thread.id, limit: 2, page: 1 },
  });
  typia.assert(page1);
  TestValidator.equals("pagination limit 2")(page1.pagination.limit)(2);
  TestValidator.equals("pagination page 1")(page1.pagination.current)(1);
  TestValidator.equals("records in data")(page1.data.length)(2);
  TestValidator.equals("first snapshot matches")(page1.data[0].id)(snap1.id);
  TestValidator.equals("second snapshot matches")(page1.data[1].id)(snap2.id);

  // 4. Query page=2
  const page2 = await api.functional.discussionboard.threadSnapshots.index(connection, {
    body: { thread_id: thread.id, limit: 2, page: 2 },
  });
  typia.assert(page2);
  TestValidator.equals("pagination page 2")(page2.pagination.current)(2);
  TestValidator.equals("page 2 should have 1 result")(page2.data.length)(1);
  TestValidator.equals("third snapshot matches")(page2.data[0].id)(snap3.id);

  // 5. Filter by actor_id (actorB)
  const byActorB = await api.functional.discussionboard.threadSnapshots.index(connection, {
    body: { thread_id: thread.id, actor_id: actorB },
  });
  typia.assert(byActorB);
  TestValidator.equals("only snap2 by actorB")([snap2.id])(byActorB.data.map(x => x.id));

  // 6. Filter by title substring
  const byTitle = await api.functional.discussionboard.threadSnapshots.index(connection, {
    body: { thread_id: thread.id, title: "final" },
  });
  typia.assert(byTitle);
  TestValidator.predicate("finds snap3 by 'final'")(byTitle.data.some(x => x.id === snap3.id));

  // 7. Filter by creation time (from snap2.created_at)
  const byCreated = await api.functional.discussionboard.threadSnapshots.index(connection, {
    body: { thread_id: thread.id, created_at_from: snap2.created_at },
  });
  typia.assert(byCreated);
  TestValidator.equals("snap2 and snap3 included")(
    new Set(byCreated.data.map(x => x.id))
  )(new Set([snap2.id, snap3.id]));

  // 8. Edge case: non-existent actor, should be empty
  const byMissingActor = await api.functional.discussionboard.threadSnapshots.index(connection, {
    body: { thread_id: thread.id, actor_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(byMissingActor);
  TestValidator.equals("no data for random actor")(byMissingActor.data.length)(0);

  // 9. Edge case: page beyond available results, should be empty
  const pageBeyond = await api.functional.discussionboard.threadSnapshots.index(connection, {
    body: { thread_id: thread.id, page: 10, limit: 3 },
  });
  typia.assert(pageBeyond);
  TestValidator.equals("empty data for far page")(pageBeyond.data.length)(0);
}
function sleep(ms: number) {
  return new Promise(res => setTimeout(res, ms));
}

