 * 2. 신규 member를 author로 하여 실제 thread를 생성한다.
 * 3. (정상) actor_id, title, body, reason 등 전체 필드가 채워진 스냅샷 생성 및 반환값 검증
 * 4. (정상) 최소 필수(thread_id, title), actor_id=null, 옵션(body, reason) 없음 케이스 생성 및 반환값 검증
 * 5. (오류) 필수 필드(thread_id 또는 title) 누락 후 API 호출 → 스키마 validation 오류 발생 확인
 * 6. (오류) 존재하지 않는 thread_id/actor_id 입력 → 관계 무결성/외래키 오류 확인
 */
export async function test_api_discussionboard_test_create_thread_snapshot_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. 스냅샷 actor/author로 사용할 member 생성
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. 위 member를 author로 해서 thread 생성
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: typia.random<string & tags.Format<"uuid">>(),
      author_member_id: member.id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);

  // 3. (정상) 모든 필드 입력 & actor_id 지정
  const snapshotPayloadFull: IDiscussionboardThreadSnapshots.ICreate = {
    thread_id: thread.id,
    actor_id: member.id,
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
    reason: "Initial version for testing.",
  };
  const snapshotFull = await api.functional.discussionboard.threadSnapshots.create(connection, { body: snapshotPayloadFull });
  typia.assert(snapshotFull);
  TestValidator.equals("thread_id matches")(snapshotFull.thread_id)(thread.id);
  TestValidator.equals("actor_id matches")(snapshotFull.actor_id)(member.id);
  TestValidator.equals("title matches")(snapshotFull.title)(snapshotPayloadFull.title);
  TestValidator.equals("body matches")(snapshotFull.body)(snapshotPayloadFull.body);
  TestValidator.equals("reason matches")(snapshotFull.reason)(snapshotPayloadFull.reason);

  // 4. (정상) 최소 필수만 입력 (actor_id: null, body/reason 없음)
  const snapshotPayloadMinimal: IDiscussionboardThreadSnapshots.ICreate = {
    thread_id: thread.id,
    actor_id: null,
    title: RandomGenerator.paragraph()(),
    // body, reason 생략
  };
  const snapshotMinimal = await api.functional.discussionboard.threadSnapshots.create(connection, { body: snapshotPayloadMinimal });
  typia.assert(snapshotMinimal);
  TestValidator.equals("actor_id is null")(snapshotMinimal.actor_id)(null);
  TestValidator.equals("title matches")(snapshotMinimal.title)(snapshotPayloadMinimal.title);
  TestValidator.equals("body omitted")(snapshotMinimal.body)(undefined);
  TestValidator.equals("reason omitted")(snapshotMinimal.reason)(undefined);

  // 5. (오류) 필수 필드(thread_id, title) 누락 시 validation 에러 발생해야 한다.
  await TestValidator.error("missing thread_id")(async () => {
    await api.functional.discussionboard.threadSnapshots.create(connection, {
      body: {
        actor_id: member.id,
        title: RandomGenerator.paragraph()(),
      } as any,
    });
  });
  await TestValidator.error("missing title")(async () => {
    await api.functional.discussionboard.threadSnapshots.create(connection, {
      body: {
        thread_id: thread.id,
        actor_id: member.id,
      } as any,
    });
  });

  // 6. (오류) 유효하지 않은 thread_id / actor_id 입력 시 무결성 에러 발생 확인
  await TestValidator.error("non-existent thread_id")(async () => {
    await api.functional.discussionboard.threadSnapshots.create(connection, {
      body: {
        thread_id: typia.random<string & tags.Format<"uuid">>(), // 존재하지 않을 UUID
        actor_id: member.id,
        title: RandomGenerator.paragraph()(),
      },
    });
  });
  await TestValidator.error("non-existent actor_id")(async () => {
    await api.functional.discussionboard.threadSnapshots.create(connection, {
      body: {
        thread_id: thread.id,
        actor_id: typia.random<string & tags.Format<"uuid">>(), // 존재하지 않을 UUID
        title: RandomGenerator.paragraph()(),
      },
    });
  });
}

