import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardThreadSnapshots } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreadSnapshots";

/**
 * Updates a discussion thread snapshot with various field changes, and validates all crucial success and error cases.
 *
 * Business context:
 * Each thread edit/action is versioned via a thread snapshot. This test ensures that updating a snapshot (title/body/reason/actor_id) works as specified, and that errors for non-existent IDs or schema violations are returned as intended.
 *
 * Steps:
 * 1. Create a discussionboard_member (actor).
 * 2. Create a discussionboard_thread, authored by the member.
 * 3. Create an initial thread snapshot referencing the thread/actor.
 * 4. Update snapshot with new title, body, reason (using PUT), and verify the changes took effect.
 * 5. If schema allows, also update actor_id, verify in response.
 * 6. Try PUT update to a non-existent snapshot id, confirm a 404 (TestValidator.error).
 * 7. Try invalid update payloads (missing/invalid title), confirm 400 validation errors.
 */
export async function test_api_discussionboard_threadSnapshots_test_update_thread_snapshot_title_body_reason(
  connection: api.IConnection,
) {
  // 1. Create actor (member)
  const actor: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<'email'>>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(actor);

  // 2. Create a thread, authored by this member
  const thread: IDiscussionboardThreads = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: typia.random<string & tags.Format<'uuid'>>(),
      author_member_id: actor.id,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()(1)(1),
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);

  // 3. Create thread snapshot referencing thread and actor
  const initialSnapshot: IDiscussionboardThreadSnapshots = await api.functional.discussionboard.threadSnapshots.create(connection, {
    body: {
      thread_id: thread.id,
      actor_id: actor.id,
      title: thread.title,
      body: thread.body,
      reason: "Initial creation",
    } satisfies IDiscussionboardThreadSnapshots.ICreate,
  });
  typia.assert(initialSnapshot);

  // 4. Update: change title, body, reason
  const updateInput: IDiscussionboardThreadSnapshots.IUpdate = {
    title: RandomGenerator.paragraph()(1) + " (updated)",
    body: RandomGenerator.content()(1)(1) + " (updated)",
    reason: "Correction - typo fix",
  };
  const updatedSnapshot: IDiscussionboardThreadSnapshots = await api.functional.discussionboard.threadSnapshots.update(connection, {
    id: initialSnapshot.id,
    body: updateInput,
  });
  typia.assert(updatedSnapshot);
  TestValidator.equals("updated title")(updatedSnapshot.title)(updateInput.title);
  TestValidator.equals("updated body")(updatedSnapshot.body)(updateInput.body);
  TestValidator.equals("updated reason")(updatedSnapshot.reason)(updateInput.reason);
  TestValidator.equals("thread_id unchanged")(updatedSnapshot.thread_id)(initialSnapshot.thread_id);

  // 5. If allowed by schema, update actor_id
  const actor2: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<'email'>>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(actor2);

  const actorUpdateInput: IDiscussionboardThreadSnapshots.IUpdate = { actor_id: actor2.id };
  const updatedWithActor: IDiscussionboardThreadSnapshots = await api.functional.discussionboard.threadSnapshots.update(connection, {
    id: initialSnapshot.id,
    body: actorUpdateInput,
  });
  typia.assert(updatedWithActor);
  TestValidator.equals("actor_id updated")(updatedWithActor.actor_id)(actor2.id);

  // 6. Try updating non-existent snapshot (should 404/error)
  await TestValidator.error("404 on non-existent snapshot id")(
    () => api.functional.discussionboard.threadSnapshots.update(connection, {
      id: typia.random<string & tags.Format<'uuid'>>(),
      body: {
        title: "Won't matter",
        body: "Some body",
      },
    })
  );

  // 7. Try invalid update: title null (should error 400)
  await TestValidator.error("schema validation fail: title=null")(
    () => api.functional.discussionboard.threadSnapshots.update(connection, {
      id: initialSnapshot.id,
      body: { title: null as unknown as string }, // forcibly wrong
    })
  );

  // 7b. Try invalid update: title empty string (should error 400 if not allowed)
  await TestValidator.error("schema validation fail: title empty string")(
    () => api.functional.discussionboard.threadSnapshots.update(connection, {
      id: initialSnapshot.id,
      body: { title: "" },
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardThreadSnapshots } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreadSnapshots";

/**
 * E2E test for the permanent deletion of a thread snapshot.
 *
 * This test verifies that after hard-deleting a thread snapshot using DELETE /discussionboard/threadSnapshots/{id},
 * all further attempts to erase the same snapshot or to erase a completely unknown id result in error.
 *
 * Steps:
 * 1. Create a thread for the context
 * 2. Create a snapshot tied to the thread
 * 3. Hard-delete the snapshot
 * 4. Attempt to delete the same snapshot again (should fail)
 * 5. Attempt to delete a completely unknown id (should fail)
 *
 * Retrieval of a snapshot by id for post-delete validation is not possible (no such API),
 * so error testing focuses on delete endpoints exclusively.
 * No soft-delete nor snapshot recovery is possible or tested.
 */
export async function test_api_discussionboard_threadSnapshots_test_delete_thread_snapshot_and_fetch_after_deletion(
  connection: api.IConnection,
) {
  // 1. Create a thread for the snapshot context
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: typia.random<string & tags.Format<"uuid">>(),
      author_member_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()() as string, // thread body (optional)
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);

  // 2. Create a snapshot for the thread
  const snapshot = await api.functional.discussionboard.threadSnapshots.create(connection, {
    body: {
      thread_id: thread.id,
      actor_id: thread.author_member_id,
      title: thread.title + ' SNAPSHOT v1',
      body: thread.body ?? null,
      reason: 'Initial version',
    } satisfies IDiscussionboardThreadSnapshots.ICreate,
  });
  typia.assert(snapshot);

  // 3. Hard delete the snapshot by its id
  await api.functional.discussionboard.threadSnapshots.erase(connection, {
    id: snapshot.id,
  });

  // 4. Attempt to delete the same snapshot again (should error)
  await TestValidator.error("double delete must fail")(
    async () => {
      await api.functional.discussionboard.threadSnapshots.erase(connection, {
        id: snapshot.id,
      });
    },
  );

  // 5. Attempt to delete a completely unknown random id (should error)
  await TestValidator.error("delete unknown id must fail")(
    async () => {
      await api.functional.discussionboard.threadSnapshots.erase(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );
}

