import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IPageIDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate parameter value/type validation for listing members with invalid filters.
 *
 * This test ensures the API properly validates parameter types/values and rejects malformed filter criteria.
 * Specifically, it checks that attempts to pass invalid values for allowed filter fields (such as wrong types)
 * are rejected with validation/runtime errors, while correct filters still function.
 *
 * Steps:
 * 1. Attempt to search members with invalid type for is_active (string instead of boolean).
 *    Expect a validation error (TestValidator.error).
 * 2. Attempt to search members with an invalid type for page (string instead of integer >=1).
 *    Expect a validation error.
 * 3. Perform a normal search with a supported filter to ensure successful operation as positive control.
 */
export async function test_api_discussionboard_test_list_members_with_invalid_filter_parameters(
  connection: api.IConnection,
) {
