 *
 * Step-by-step process:
 * 1. Create two distinct members (memberA, memberB), each with unique username/email.
 * 2. Attempt to update memberA's username to memberB's username: expect constraint violation (error should be thrown).
 * 3. Attempt to update memberA's email to memberB's email: expect constraint violation (error should be thrown).
 * 4. Confirm memberA remains unchanged after failed updates.
 */
export async function test_api_discussionboard_members_test_update_member_with_duplicate_email_or_username(
  connection: api.IConnection,
) {
  // 1. Create memberA
  const usernameA = RandomGenerator.alphaNumeric(8);
  const emailA = typia.random<string & tags.Format<"email">>();
  const memberA = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: usernameA,
      email: emailA,
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(memberA);

  // 2. Create memberB
  const usernameB = RandomGenerator.alphaNumeric(8);
  const emailB = typia.random<string & tags.Format<"email">>();
  const memberB = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: usernameB,
      email: emailB,
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(memberB);

  // 3. Attempt to update memberA's username to memberB's username (should fail)
  await TestValidator.error("duplicate username should be rejected")(async () => {
    await api.functional.discussionboard.members.update(connection, {
      id: memberA.id,
      body: {
        username: memberB.username,
      },
    });
  });

  // 4. Attempt to update memberA's email to memberB's email (should fail)
  await TestValidator.error("duplicate email should be rejected")(async () => {
    await api.functional.discussionboard.members.update(connection, {
      id: memberA.id,
      body: {
        email: memberB.email,
      },
    });
  });

  // 5. Confirm memberA's username and email are unchanged
  const reloadedA = await api.functional.discussionboard.members.update(connection, {
    id: memberA.id,
    body: {}, // No changes
  });
  typia.assert(reloadedA);
  TestValidator.equals("username unchanged")(reloadedA.username)(usernameA);
  TestValidator.equals("email unchanged")(reloadedA.email)(emailA);
}

