import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";

/**
 * Test soft-delete (compliance removal) of a discussion board member account, verifying auditability & access prevention.
 *
 * 이 테스트는 discussionboard_members의 소프트 삭제(탈퇴) API를 검증합니다.
 * 삭제 시 실제 데이터가 물리적으로 삭제되지 않고(deleted_at 필드가 현재 시각으로 세팅),
 * 계정은 로그인·검색 등 주요 기능에서 제외되며, id로는 감사/컴플라이언스 용도로 열람 가능해야 합니다.
 *
 * 주요 테스트 단계:
 * 1. 회원 계정 신규 생성
 * 2. 소프트 삭제 API 호출 (deleted_at 세팅)
 * 3. 동일 id에 중복 삭제 시도(오류 확인)
 * 4. 존재하지 않는 id로 삭제 시도(오류 확인)
 * (※ 계정 검색/리스트·id직접조회·로그인불가 검증은 실 구현 API가 미존재하므로 누락)
 */
export async function test_api_discussionboard_test_soft_delete_member_account(
  connection: api.IConnection,
) {
  // 1. 테스트용 회원 계정 신규 생성
  const reg = await api.functional.discussionboard.members.create(
    connection,
    {
      body: {
        username: RandomGenerator.alphabets(8),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphabets(16),
        role: "member",
        is_active: true,
      },
    },
  );
  typia.assert(reg);

  // 2. 소프트 삭제(탈퇴) API 호출 - deleted_at 업데이트
  await api.functional.discussionboard.members.erase(
    connection,
    {
      id: reg.id,
    },
  );

  // 3. 동일 id 재삭제 시도(오류 확인)
  await TestValidator.error("중복 soft-delete 시 오류 반환")(
    () => api.functional.discussionboard.members.erase(
      connection,
      { id: reg.id },
    )
