/**
 * Validate error handling for thread creation with nonexistent board or author.
 *
 * This test ensures that the POST /discussionboard/threads endpoint enforces referential integrity
 * by rejecting attempts to create threads that reference nonexistent boards or authors. The test simulates
 * three scenarios:
 *   1. Both board_id and author_member_id are nonexistent
 *   2. Only board_id is nonexistent
 *   3. Only author_member_id is nonexistent
 *
 * Step-by-step process:
 * 1. Generate random UUIDs for board_id and author_member_id, which are almost certainly not present in the database.
 * 2. Attempt to create a thread with both bad board_id and author_member_id, expect an error.
 * 3. Attempt to create a thread with a bad board_id and a random (but equally nonexistent) author_member_id, expect an error.
 * 4. Attempt to create a thread with a random (but equally nonexistent) board_id and bad author_member_id, expect an error.
 * 5. For all cases, assert that an error is thrown and no thread is created.
 *
 * This guarantees that the API prevents orphaned thread records and strictly enforces foreign key integrity.
 */
export async function test_api_discussionboard_test_create_thread_with_nonexistent_board_or_author(
  connection: api.IConnection,
) {
  // 1. Generate random UUIDs to represent nonexistent board and author
  const badBoardId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const badAuthorId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();

  // 2. Attempt to create a thread with both bad board_id and author_member_id
  await TestValidator.error("should fail with both bad board_id and author_member_id")(
    async () => {
      await api.functional.discussionboard.threads.create(connection, {
        body: {
          board_id: badBoardId,
          author_member_id: badAuthorId,
          title: "Should Fail: Nonexistent Board & Author",
          body: "Creating with both board_id and author_member_id invalid.",
        } satisfies IDiscussionboardThreads.ICreate,
      });
    },
  );

  // 3. Attempt to create a thread with a bad board_id (likely) and new random author_member_id
  await TestValidator.error("should fail with bad board_id only")(
    async () => {
      await api.functional.discussionboard.threads.create(connection, {
        body: {
          board_id: badBoardId,
          author_member_id: typia.random<string & tags.Format<"uuid">>(),
          title: "Should Fail: Nonexistent Board",
        } satisfies IDiscussionboardThreads.ICreate,
      });
    },
  );

  // 4. Attempt to create a thread with new random board_id and bad author_member_id
  await TestValidator.error("should fail with bad author_member_id only")(
    async () => {
      await api.functional.discussionboard.threads.create(connection, {
        body: {
          board_id: typia.random<string & tags.Format<"uuid">>(),
          author_member_id: badAuthorId,
          title: "Should Fail: Nonexistent Author",
        } satisfies IDiscussionboardThreads.ICreate,
      });
    },
  );
