/**
 * 테스트 목적: 필수 필드 누락 시 스레드 생성 실패 검증
 *
 * 비즈니스 목적 및 필요성:
 * 게시판 스레드 생성 시 board_id, author_member_id, title은 모두 필수 항목이다. 서버에서 누락 시 유효성 에러(400, 422 등)가 발생해야 하며, 올바른 검증 동작 여부를 테스트한다. 이 기능은 API의 견고한 데이터 무결성과 클라이언트 입력 실수에 대한 방어를 검증한다.
 *
 * 테스트 단계:
 * 1. 정상 컨트롤 생성 위해 discussionboard/boards 및 discussionboard/members에 대한 데이터를 각각 1건씩 생성
 * 2. 3개의 필수 필드(board_id, author_member_id, title)를 각기 빠뜨린 3종 요청을 전송
 *     a. board_id 누락 요청 → 실패 검증
 *     b. author_member_id 누락 요청 → 실패 검증
 *     c. title 누락 요청 → 실패 검증
 * 3. 각 케이스별로 유효성 실패(에러) 발생 여부를 TestValidator.error로 검증
 */
export async function test_api_discussionboard_test_create_thread_missing_required_fields(
  connection: api.IConnection,
) {
  // [1] 사전 데이터 생성: 게시판과 회원은 정상 플로우로 한 번씩 생성한다.
  const board = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.name(),
      code: RandomGenerator.alphaNumeric(10),
      description: RandomGenerator.paragraph()(),
      is_active: true,
      is_visible: true,
    } satisfies IBoard.ICreate,
  });
  typia.assert(board);

  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(12),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(50),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // [2a] board_id 누락 요청: 필드 미포함
  TestValidator.error("board_id 누락시 생성 실패")(() =>
    api.functional.discussionboard.threads.create(connection, {
      body: {
        // board_id: deliberately omitted
        author_member_id: member.id,
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } as any, // 타입 위반 허용 (유효성 검증 목적)
    })
  );

  // [2b] author_member_id 누락 요청
  TestValidator.error("author_member_id 누락시 생성 실패")(() =>
    api.functional.discussionboard.threads.create(connection, {
      body: {
        board_id: board.id,
        // author_member_id: deliberately omitted
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } as any,
    })
  );

  // [2c] title 누락 요청
  TestValidator.error("title 누락시 생성 실패")(() =>
    api.functional.discussionboard.threads.create(connection, {
      body: {
        board_id: board.id,
        author_member_id: member.id,
        // title: deliberately omitted
        body: RandomGenerator.content()()(),
      } as any,
    })
  );
}

