/**
 * Test updating the title and body of a discussion thread.
 *
 * This test validates that when a thread is updated via the PUT endpoint, both the title and body fields are properly changed.
 * It also confirms that the updated_at timestamp is modified accordingly to reflect this action.
 *
 * Business context: Editing a thread is a fundamental forum/discussion board capability and must guarantee both data integrity and auditability (via timestamps).
 *
 * Process:
 * 1. Create a Board (dependency for thread's board_id).
 * 2. Create a Member (dependency for thread's author_member_id).
 * 3. Create a Thread using the board and member.
 * 4. Update the thread's title and body using the PUT endpoint.
 * 5. Validate that the changes are correctly reflected in the response object.
 * 6. Validate that updated_at has been changed to a new value (is later than the original).
 */
export async function test_api_discussionboard_test_update_thread_title_and_body(
  connection: api.IConnection,
) {
  // Step 1. Create a Board
  const boardCategoryId = typia.random<string & tags.Format<"uuid">>();
  const sectionId = typia.random<string & tags.Format<"uuid">>();
  const board = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: boardCategoryId,
      discussionboard_section_id: sectionId,
      name: RandomGenerator.paragraph()(2),
      code: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(1),
      is_active: true,
      is_visible: true,
    } satisfies IBoard.ICreate,
  });
  typia.assert(board);

  // Step 2. Create a Member
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // Step 3. Create a Thread
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: board.id,
      author_member_id: member.id,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.paragraph()(2),
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);
  const originalUpdatedAt = thread.updated_at;

  // Step 4. Update the thread's title and body
  const newTitle = RandomGenerator.paragraph()(1);
  const newBody = RandomGenerator.paragraph()(2);
  const updatedThread = await api.functional.discussionboard.threads.update(connection, {
    id: thread.id,
    body: {
      title: newTitle,
      body: newBody,
    } satisfies IDiscussionboardThreads.IUpdate,
  });
  typia.assert(updatedThread);

  // Step 5. Validate changes
  TestValidator.equals("updated title")(updatedThread.title)(newTitle);
  TestValidator.equals("updated body")(updatedThread.body)(newBody);

  // Step 6. Validate updated_at changed
  TestValidator.predicate("updated_at should be changed")(
    updatedThread.updated_at > originalUpdatedAt,
  );
}

