 *
 * 1. Create required board and member.
 * 2. Create a thread in the board.
 * 3. Soft-delete the thread by setting deleted_at (via update PUT).
 * 4. Confirm deleted_at is set.
 * 5. Restore by setting deleted_at to null (PUT).
 * 6. Confirm deleted_at is null again.
 *
 * (Thread listing visibility confirmation is omitted,
 * as list/search API is not available in the provided SDK functions.)
 */
export async function test_api_discussionboard_test_update_thread_soft_delete_and_restore(
  connection: api.IConnection,
) {
  // 1. Create a board
  const board: IBoard = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.paragraph()(),
      code: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(),
      is_active: true,
      is_visible: true,
    } satisfies IBoard.ICreate,
  });
  typia.assert(board);

  // 2. Create a member (thread author)
  const uniqueEmail: string = typia.random<string & tags.Format<"email">>();
  const member: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: uniqueEmail,
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 3. Create a thread
  const thread: IDiscussionboardThreads = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: board.id,
      author_member_id: member.id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.paragraph()(),
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);

  // 4. Soft-delete the thread (set deleted_at)
  const deletedAt = new Date().toISOString();
  const softDeleted: IDiscussionboardThreads = await api.functional.discussionboard.threads.update(connection, {
    id: thread.id,
    body: {
      deleted_at: deletedAt,
    } satisfies IDiscussionboardThreads.IUpdate,
  });
  typia.assert(softDeleted);
  TestValidator.equals("deleted_at is set")(softDeleted.deleted_at)(deletedAt);

  // 5. Restore the thread (set deleted_at to null)
  const restored: IDiscussionboardThreads = await api.functional.discussionboard.threads.update(connection, {
    id: thread.id,
    body: {
      deleted_at: null,
    } satisfies IDiscussionboardThreads.IUpdate,
  });
  typia.assert(restored);
  TestValidator.equals("deleted_at is null after restore")(restored.deleted_at)(null);
}

