 *   2. Create a Member (thread author)
 *   3. Create a Thread (valid data under valid Board/Member)
 *   4. Attempt to update the thread with:
 *      - Empty title string (should fail)
 *      - Excessively long title string (should fail)
 *      - Excessively long body string (should fail)
 *   5. Confirm that after invalid updates, thread content is unchanged.
 */
export async function test_api_discussionboard_test_update_thread_with_invalid_fields(
  connection: api.IConnection,
) {
  // 1. Create board (for thread)
  const board = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.alphabets(8),
      code: RandomGenerator.alphaNumeric(12),
      description: RandomGenerator.paragraph()(),
      is_active: true,
      is_visible: true,
    },
  });
  typia.assert(board);

  // 2. Create thread author (member)
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(64),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(member);

  // 3. Create thread (valid content)
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: board.id,
      author_member_id: member.id,
      title: RandomGenerator.paragraph()(1, 1),
      body: RandomGenerator.paragraph()(3, 10),
    },
  });
  typia.assert(thread);

  // 4a. Attempt update with empty title (invalid, should error)
  await TestValidator.error("empty title is not allowed")(() =>
    api.functional.discussionboard.threads.update(connection, {
      id: thread.id,
      body: {
        title: ""
      } satisfies IDiscussionboardThreads.IUpdate,
    })
  );

  // 4b. Attempt update with excessively long title (invalid, should error)
  await TestValidator.error("excessively long title is not allowed")(() =>
    api.functional.discussionboard.threads.update(connection, {
      id: thread.id,
      body: {
        title: "T".repeat(10000),
      } satisfies IDiscussionboardThreads.IUpdate,
