      id: thread.id,
      body: {
        body: "B".repeat(100000),
      } satisfies IDiscussionboardThreads.IUpdate,
    })
  );

  // 5. Confirm thread remains unchanged (should still have original values)
  // (Since no GET API, use update with empty body as a no-op to receive latest thread)
  const reloaded = await api.functional.discussionboard.threads.update(connection, {
    id: thread.id,
    body: {} as IDiscussionboardThreads.IUpdate,
  });
  typia.assert(reloaded);
  TestValidator.equals("thread title unchanged after invalid updates")(reloaded.title)(thread.title);
  TestValidator.equals("thread body unchanged after invalid updates")(reloaded.body)(thread.body);
}

