import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoard";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { ISoftDeleteConfirmation } from "@ORGANIZATION/PROJECT-api/lib/structures/ISoftDeleteConfirmation";

/**
 * Validate soft-deleting a thread by its id.
 *
 * Business context:
 * Soft-deletion means marking the thread as deleted by setting its deleted_at timestamp, instead of actually erasing it from the database. This ensures data auditability and potential restoration, which is important for compliance and history in community forums.
 *
 * Test Process:
 * 1. Create a board (required for thread creation)
 * 2. Create a member (author of the thread)
 * 3. Create a thread under the board, authored by the member
 * 4. Call DELETE /discussionboard/threads/{id} to soft-delete the thread
 * 5. Confirm that the response returns the correct id and soft_deleted: true
 * 6. (Post-delete check logic omitted: no GET API is present to fetch the thread and inspect deleted_at)
 */
export async function test_api_discussionboard_test_soft_delete_thread_success(
  connection: api.IConnection,
) {
  // 1. Create a board
  const board = await api.functional.discussionboard.boards.create(
    connection,
    {
      body: {
        discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
        name: RandomGenerator.paragraph()(2),
        code: RandomGenerator.alphaNumeric(8),
        description: RandomGenerator.paragraph()(1),
        is_active: true,
        is_visible: true,
      } satisfies IBoard.ICreate,
    },
  );
  typia.assert(board);

  // 2. Create a member (author)
  const member = await api.functional.discussionboard.members.create(
    connection,
    {
      body: {
        username: RandomGenerator.alphaNumeric(10),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(32),
        role: "member",
        is_active: true,
      } satisfies IDiscussionboardMember.ICreate,
    },
  );
  typia.assert(member);

  // 3. Create a thread authored by the member in the board
  const thread = await api.functional.discussionboard.threads.create(
    connection,
    {
      body: {
        board_id: board.id,
        author_member_id: member.id,
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()(1)(3),
      } satisfies IDiscussionboardThreads.ICreate,
    },
  );
  typia.assert(thread);

  // 4. Soft-delete the thread by id
  const deletion = await api.functional.discussionboard.threads.erase(
    connection,
    { id: thread.id },
