import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IMemberProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberProfile";

/**
 * Validate retrieving a member profile by id.
 *
 * This test creates a discussionboard member and then creates a profile for that member. It then retrieves the newly created member profile by its id using the GET endpoint. The response is checked to ensure that all required public fields (id, member_id, display_name) are present, optional fields (bio, avatar_url, location, website_url) are properly formatted or null, and that no sensitive information from the member account (such as email, username, system role, or deleted_at) is present in the profile response. All UUID fields and format constraints are also asserted.
 *
 * Steps:
 * 1. Create a new member account using the registration endpoint.
 * 2. Create a new profile for the member with a display name and some optional fields filled.
 * 3. Retrieve the created profile by its id.
 * 4. Assert all fields on the profile are correct, match schema, and only public information is included.
 */
export async function test_api_discussionboard_test_retrieve_member_profile_by_id_success(connection: api.IConnection) {
  // 1. Create a new discussionboard member
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create a new member profile for that member
  const profileInput: IMemberProfile.ICreate = {
    member_id: member.id,
    display_name: RandomGenerator.name(),
    bio: RandomGenerator.paragraph()(),
    avatar_url: typia.random<string & tags.Format<"uri">>(),
    location: RandomGenerator.name(),
    website_url: typia.random<string & tags.Format<"uri">>(),
  };
  const profile = await api.functional.discussionboard.memberProfiles.create(connection, {
    body: profileInput,
  });
  typia.assert(profile);

  // 3. Retrieve the member profile by id
  const output = await api.functional.discussionboard.memberProfiles.at(connection, {
    id: profile.id,
  });
  typia.assert(output);

  // 4. Validate the response fields
  TestValidator.equals("id matches")(output.id)(profile.id);
  TestValidator.equals("member_id matches")(output.member_id)(member.id);
  TestValidator.equals("display_name matches")(output.display_name)(profileInput.display_name);
  TestValidator.equals("bio matches")(output.bio)(profileInput.bio);
  TestValidator.equals("avatar_url matches")(output.avatar_url)(profileInput.avatar_url);
  TestValidator.equals("location matches")(output.location)(profileInput.location);
  TestValidator.equals("website_url matches")(output.website_url)(profileInput.website_url);

  // Assert no sensitive fields from member are present in the profile response
  if (
    (output as any).email !== undefined ||
    (output as any).username !== undefined ||
    (output as any).role !== undefined ||
    (output as any).is_active !== undefined ||
    (output as any).deleted_at !== undefined
  ) {
    throw new Error("Sensitive discussionboard_members fields should not be present in the profile response");
  }
}

