 *
 * - 회원(member)을 1명 생성한다.
 * - 해당 member의 id로 profile을 1회 정상 생성한다.
 * - 같은 member_id로 profile을 한 번 더 생성 시도 시 에러가 발생하고, 기존 데이터에 side effect가 없는지 확인한다.
 *
 * [절차]
 * 1. discussionboard_members에 회원을 생성 (username/email/role 등)
 * 2. member_id로 memberProfiles 1번째 생성 (성공)
 * 3. 동일 member_id로 memberProfiles 2번째 생성(실패 예상, UNIQUE 위반)
 *    - 올바르게 에러가 발생하는지 TestValidator.error로 확인
 *    - 추가 side effect 또는 불필요한 데이터 없이 오류만 발생하는지만 체크(조회 API 없음)
 */
export async function test_api_discussionboard_test_create_member_profile_duplicate_for_same_member(
  connection: api.IConnection,
) {
  // 1. 회원 생성
  const memberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
