import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IMemberProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberProfile";

/**
 * Validates successful update of a discussion board member profile by ID.
 *
 * This test ensures that an existing member profile can be updated, and only fields
 * allowed by the business schema are mutable. It confirms that:
 * - The update process works and only fields in the IUpdate schema are accepted
 * - Mutable fields reflect changes; immutable ones remain unchanged
 * - Optional/null-able fields are updated or retain values as expected
 * - All response properties conform to the IMemberProfile schema
 *
 * Workflow:
 * 1. Create a member (for reference by the profile)
 * 2. Create a profile with all fields set (including optional fields)
 * 3. Update the profile: change display_name, bio, website_url; others unchanged
 * 4. Confirm:
 *      - updated fields reflect changes
 *      - unchanged fields remain the same
 *      - nulls/defaults behave as expected
 *      - schema constraints are maintained
 */
export async function test_api_discussionboard_memberProfiles_test_update_member_profile_successful_update(
  connection: api.IConnection,
) {
  // 1. Create a member for test
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create an initial member profile
  const initialProfile = await api.functional.discussionboard.memberProfiles.create(connection, {
    body: {
      member_id: member.id,
      display_name: RandomGenerator.name(),
      bio: RandomGenerator.paragraph()(),
      avatar_url: "https://img.example.com/avatar.png",
      location: "Seoul, South Korea",
      website_url: "https://www.init-example.com",
    } satisfies IMemberProfile.ICreate,
  });
  typia.assert(initialProfile);

  // 3. Prepare update payload
  const updatePayload = {
    display_name: initialProfile.display_name + "_updated",
    bio: (initialProfile.bio ? initialProfile.bio + " UPDATED" : "Updated bio"),
    website_url: "https://www.new-profile.com",
    // avatar_url and location are omitted (remain unchanged)
  } satisfies IMemberProfile.IUpdate;

  const updatedProfile = await api.functional.discussionboard.memberProfiles.update(connection, {
    id: initialProfile.id,
    body: updatePayload,
  });
  typia.assert(updatedProfile);

  // 4. Assert updated/unchanged fields
  TestValidator.equals("id unchanged")(updatedProfile.id)(initialProfile.id);
  TestValidator.equals("member_id unchanged")(updatedProfile.member_id)(initialProfile.member_id);
  TestValidator.equals("display_name updated")(updatedProfile.display_name)(updatePayload.display_name);
  TestValidator.equals("bio updated")(updatedProfile.bio)(updatePayload.bio);
  TestValidator.equals("avatar_url unchanged")(updatedProfile.avatar_url)(initialProfile.avatar_url);
  TestValidator.equals("location unchanged")(updatedProfile.location)(initialProfile.location);
  TestValidator.equals("website_url updated")(updatedProfile.website_url)(updatePayload.website_url);
}

