  };
  const created: IBoard = await api.functional.discussionboard.boards.create(
    connection,
    { body: input }
  );
  typia.assert(created);

  // 2. Fetch board by ID
  const fetched: IBoard = await api.functional.discussionboard.boards.at(
    connection,
    { id: created.id }
  );
  typia.assert(fetched);

  // 3. Assert all fields match those submitted/generated
  TestValidator.equals("discussionboard_board_category_id")(fetched.discussionboard_board_category_id)(input.discussionboard_board_category_id);
