import api from "@ORGANIZATION/PROJECT-api";
import type { IBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoard";

/**
 * Test the hard delete of a board in the discussion board system.
 *
 * This test ensures that when a board is created and then deleted by its unique ID, the deletion is permanent and does not affect other boards.
 *
 * Steps:
 * 1. Create two distinct board records (A and B) with different category and section IDs, codes, etc.
 * 2. Delete board A using its ID via the hard delete endpoint.
 * 3. Confirm that:
 *    a. Board A cannot be retrieved by GET (if GET existed), or is not in the list (if list existed).
 *    b. Board B is still present and unaffected.
 *    c. No error is thrown on successful deletion, and response matches documentation (void result for delete).
 *
 * Edge cases not directly testable as there are no GET or list endpoints exposed, so the test focuses on correct workflow, type assertions, and non-affection of unrelated resources.
 */
export async function test_api_discussionboard_test_delete_board_success(
  connection: api.IConnection,
) {
  // 1. Create board A
  const boardA = await api.functional.discussionboard.boards.create(
    connection,
    {
      body: {
        discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
        name: "Test Board A",
        code: `test_board_a_${typia.random<string>()}`,
        description: "This board is created for hard delete E2E test.",
        is_active: true,
        is_visible: true,
      } satisfies IBoard.ICreate,
    },
  );
  typia.assert(boardA);

  // 2. Create board B (should not be affected by A's deletion)
  const boardB = await api.functional.discussionboard.boards.create(
    connection,
    {
      body: {
        discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
        name: "Test Board B",
        code: `test_board_b_${typia.random<string>()}`,
        description: "This board should persist after A is deleted.",
        is_active: true,
        is_visible: true,
      } satisfies IBoard.ICreate,
    },
  );
  typia.assert(boardB);

  // 3. Hard delete board A by ID
  await api.functional.discussionboard.boards.erase(
    connection,
    {
      id: boardA.id,
    },
  );
  // No assertion required for void return.

  // Since there are no GET or list endpoints available,
  // we indirectly confirm that unrelated board B can still be operated on.
  // Attempting to delete B confirms its independent existence after A's deletion.
  await api.functional.discussionboard.boards.erase(
    connection,
    {
      id: boardB.id,
    },
  );
  // Both deletions should succeed without errors if board independence is preserved.
}

