import type { IDiscussionboardDataErasureRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardDataErasureRequest";

/**
 * 데이터 삭제 요청 목록 필터, 페이징, 전체 반환 및 예외값을 검증하는 테스트
 *
 * 관리자가 논객 데이터 삭제 요청을 심사하는 상황을 가정하여,
 * 다양한 status(pending 등), discussionboard_member_id, 페이지네이션(page, limit), 전체조회(빈body),
 * 잘못된 필터(존재하지 않는 status/멤버)에 대해 정밀하게 동작 및 스키마 적합성을 확인합니다.
 *
 * 1. 테스트용 멤버 생성
 * 2. 데이터 삭제 요청 1~2건 생성 (중복 불가 정책이면 1건만 긴급 생성)
 * 3. status별(pending 등) 필터링 검색, 상태 검증
 * 4. 멤버 id별로 필터, 반환값 논리적 일치 확인
 * 5. 페이지네이션(limit=1, page=1/2) 실제 데이터 분리 확인
 * 6. 전체조회 케이스, 테스트 데이터가 반드시 포함되는지 검증
 * 7. 결과 모든 데이터가 API 스키마만 따르는지 typia.assert
 * 8. 잘못된 status/멤버 아이디로 검색 시 빈결과 반환되는지 체크
 */
export async function test_api_discussionboard_test_list_data_erasure_requests_with_filter_and_pagination(
  connection: api.IConnection,
) {
  // 1. 테스트 멤버 생성
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: memberEmail,
      hashed_password: RandomGenerator.alphaNumeric(30),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(member);

  // 2. 테스트 멤버로 데이터 삭제 요청 1~2건 생성
  const request1 = await api.functional.discussionboard.dataErasureRequests.create(connection, {
    body: { discussionboard_member_id: member.id },
  });
  typia.assert(request1);
  // 중복 제출 정책 대응: 2번째 요청이 불가(exp예외)해도 이후 테스트 연결
  let request2;
  try {
    request2 = await api.functional.discussionboard.dataErasureRequests.create(connection, {
      body: { discussionboard_member_id: member.id },
    });
    typia.assert(request2);
  } catch {
    request2 = null;
  }

  // 3. status별(pending)로 필터 검색
  const byStatusPending = await api.functional.discussionboard.dataErasureRequests.index(connection, {
    body: { status: "pending" },
  });
  typia.assert(byStatusPending);
  TestValidator.predicate("status가 모두 pending인지 확인")(
    byStatusPending.data.every((r) => r.status === "pending"),
  );

  // 4. 해당 멤버 ID로 검색, 반드시 모두 그 ID만 반환
  const byMember = await api.functional.discussionboard.dataErasureRequests.index(connection, {
    body: { discussionboard_member_id: member.id },
  });
  typia.assert(byMember);
  TestValidator.predicate("멤버ID 동일성")(
    byMember.data.every((r) => r.discussionboard_member_id === member.id),
  );

  // 5. 페이지네이션 limit=1, page=1
  const page1 = await api.functional.discussionboard.dataErasureRequests.index(connection, {
    body: { discussionboard_member_id: member.id, limit: 1, page: 1 },
  });
  typia.assert(page1);
  TestValidator.equals("페이지1-번호")(page1.pagination.current)(1);
  TestValidator.equals("limit=1")(page1.pagination.limit)(1);
  TestValidator.predicate("데이터1개")(page1.data.length === 1);
  // page=2
  const page2 = await api.functional.discussionboard.dataErasureRequests.index(connection, {
    body: { discussionboard_member_id: member.id, limit: 1, page: 2 },
  });
  typia.assert(page2);
  TestValidator.equals("페이지2-번호")(page2.pagination.current)(2);
  TestValidator.equals("limit=1")(page2.pagination.limit)(1);

  // 6. 전체조회(body 비움)
  const all = await api.functional.discussionboard.dataErasureRequests.index(connection, {
    body: {},
  });
  typia.assert(all);
  TestValidator.predicate("테스트멤버id 포함")(
    all.data.some((r) => r.discussionboard_member_id === member.id),
  );
  all.data.forEach((d) => typia.assert(d));

  // 7. 잘못된 status(존재하지 않는) 필터시 결과0
  const byFakeStatus = await api.functional.discussionboard.dataErasureRequests.index(connection, {
    body: { status: "nonexistent_status_value_for_test" },
  });
  typia.assert(byFakeStatus);
  TestValidator.equals("비정상status-빈목록")(byFakeStatus.data.length)(0);

  // 8. 잘못된 멤버ID 필터시 결과0
  const byFakeMember = await api.functional.discussionboard.dataErasureRequests.index(connection, {
    body: { discussionboard_member_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(byFakeMember);
  TestValidator.equals("비멤버id-빈목록")(byFakeMember.data.length)(0);
}

