 * 1. Create a member account (dependency for generating a legitimate data erasure request)
 * 2. Create a data erasure request as that member
 * 3. Fetch (GET) the data erasure request by its unique id
 * 4. Confirm all schema-defined fields are present, correctly populated, and match the original request
 */
export async function test_api_discussionboard_dataErasureRequests_test_get_data_erasure_request_with_valid_id(
