/**
 * Test data erasure request update workflow by admin.
 *
 * Tests the ability of an admin to update 'status', 'reviewed_at', 'completed_at', and 'admin_remark' on a data erasure request,
 * following strict workflow transitions.
 *
 * Steps:
 * 1. Create a test member
 * 2. Submit a data erasure request (should default to 'pending')
 * 3. Approve the request as admin (status → 'approved', set reviewed_at, admin_remark)
 * 4. Mark the request as completed (status → 'completed', set completed_at, update admin_remark)
 * 5. Assert that only schema fields changed, immutable fields remain fixed
 *
 * Business context:
 * - Ensures that the update API enforces schema constraints (only updatable fields modifiable)
 * - Validates transition rules for status and timestamps (no skipping or reversal)
 * - Ensures auditability (timestamps and remarks reflect proper workflow)
 * - Ensures compliance with privacy/audit requirements (no unauthorized/untracked actions)
 */
export async function test_api_discussionboard_dataErasureRequests_test_update_data_erasure_request_status_by_admin(connection: api.IConnection) {
  // 1. Create a test member who will request data erasure
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<'email'>>(),
      hashed_password: RandomGenerator.alphabets(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create a data erasure request for that member
  const erasure = await api.functional.discussionboard.dataErasureRequests.create(connection, {
    body: {
      discussionboard_member_id: member.id,
    } satisfies IDiscussionboardDataErasureRequest.ICreate,
  });
  typia.assert(erasure);
  TestValidator.equals("Initial status should be pending")(erasure.status)("pending");
  TestValidator.equals("Correct member referenced")(erasure.discussionboard_member_id)(member.id);
  TestValidator.predicate("No reviewed_at at creation")(erasure.reviewed_at === null || erasure.reviewed_at === undefined);
  TestValidator.predicate("No completed_at at creation")(erasure.completed_at === null || erasure.completed_at === undefined);
  TestValidator.predicate("No admin_remark at creation")(erasure.admin_remark === null || erasure.admin_remark === undefined);

  // 3. Approve the request: update status to 'approved', set reviewed_at and admin_remark
  const reviewedAt = new Date().toISOString();
  const remark1 = "Request reviewed and approved.";
  const approved = await api.functional.discussionboard.dataErasureRequests.update(connection, {
    id: erasure.id,
    body: {
      status: "approved",
      reviewed_at: reviewedAt,
      admin_remark: remark1,
    } satisfies IDiscussionboardDataErasureRequest.IUpdate,
  });
  typia.assert(approved);
  TestValidator.equals("Status updated to approved")(approved.status)("approved");
  TestValidator.equals("reviewed_at set")(approved.reviewed_at)(reviewedAt);
  TestValidator.equals("admin_remark set")(approved.admin_remark)(remark1);

  // 4. Mark as completed: status to 'completed', completed_at timestamp, update admin_remark
  const completedAt = new Date(Date.now() + 60 * 1000).toISOString(); // +1 minute
  const remark2 = "Erasure process finalized.";
  const completed = await api.functional.discussionboard.dataErasureRequests.update(connection, {
    id: erasure.id,
    body: {
      status: "completed",
      completed_at: completedAt,
      admin_remark: remark2,
    } satisfies IDiscussionboardDataErasureRequest.IUpdate,
  });
  typia.assert(completed);
  TestValidator.equals("Status updated to completed")(completed.status)("completed");
  TestValidator.equals("completed_at set")(completed.completed_at)(completedAt);
  TestValidator.equals("admin_remark updated")(completed.admin_remark)(remark2);

  // 5. Immutable fields unchanged
  TestValidator.equals("Request id unchanged")(completed.id)(erasure.id);
  TestValidator.equals("Member id unchanged")(completed.discussionboard_member_id)(member.id);
  TestValidator.equals("requested_at unchanged")(completed.requested_at)(erasure.requested_at);

  // Edge Case: If testing reversion or invalid transitions was supported by API, attempt here (currently not implemented).
}

