import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardActivityLog";

/**
 * 테스트 목적: activity log 레코드 생성 및 유효성 검증
 *
 * - 정상 케이스: 모든 필수 필드와 유효값으로 activity log를 생성하고, 반환되는 log의 id와 필드값을 검증합니다.
 * - 오류 케이스1: 필수 필드를 누락한 경우 생성이 거부되어야 함을 검증합니다.
 * - 오류 케이스2: 잘못된 값(예: 이벤트 타임스탬프 형식 오류) 전달 시 유효성 오류가 반환되는지 확인합니다.
 * - 오류 케이스3: 허용되지 않은(스키마에 없는) 필드가 포함된 경우, 거부되어야 함을 검증합니다.
 *
 * [테스트 시나리오 단계]
 * 1. 모든 필드를 포함한 유효 payload로 activity log 생성 및 값 검증
 * 2. 필수 필드(event_type) 누락 후 생성 실패 검증
 * 3. 필수 필드 잘못된 값(event_timestamp) 전달 시 실패 검증
 * 4. 스키마에 없는 필드(extra_field) 포함 시 실패 검증
 */
export async function test_api_discussionboard_test_create_activity_log_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. 모든 필드를 통한 정상 생성 및 결과 검증
  const validPayload: IDiscussionboardActivityLog.ICreate = {
    discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_comment_id: typia.random<string & tags.Format<"uuid">>(),
    event_timestamp: new Date().toISOString(),
    event_type: "post_create",
    event_metadata: JSON.stringify({ device: "web", ip: "192.168.0.1" }),
  };
  const log = await api.functional.discussionboard.activityLogs.create(connection, {
    body: validPayload,
  });
  typia.assert(log);
  TestValidator.equals("event_type 일치")(log.event_type)(validPayload.event_type);
  TestValidator.equals("event_timestamp 일치")(log.event_timestamp)(validPayload.event_timestamp);

  // 2. 필수 필드 누락( event_type ) - 실패해야 함
  const missingEventType: IDiscussionboardActivityLog.ICreate = {
    ...validPayload,
  };
  delete (missingEventType as any).event_type;
  await TestValidator.error("event_type 누락 오류 발생해야 함")(() =>
    api.functional.discussionboard.activityLogs.create(connection, {
      body: missingEventType,
    }),
  );

  // 3. 잘못된 값 (event_timestamp: 형식 오류) - 실패해야 함
  const malformedTimestamp: IDiscussionboardActivityLog.ICreate = {
    ...validPayload,
    event_timestamp: "not-a-date" as any,
  };
  await TestValidator.error("event_timestamp 형식 오류 발생해야 함")(() =>
    api.functional.discussionboard.activityLogs.create(connection, {
      body: malformedTimestamp,
    }),
