import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ITrendingTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/ITrendingTopic";
import type { IPageITrendingTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITrendingTopic";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for listing trending topics via PATCH /discussionboard/trendingTopics.
 *
 * This test covers retrieving a paginated and filtered list of trending topics for management or analytics purposes. It covers:
 * 1. Default retrieval (all without filters, default page/limit)
 * 2. Filtering by ranking_period_date
 * 3. Filtering by board/thread ID
 * 4. Custom pagination (different page/limit)
 * 5. Edge case: query with filters that match no records – should return empty result array
 * Each test checks that:
 * - The result fields conform to the expected schema
 * - Returned results' data matches the applied filters
 * - The pagination structure is correct
 */
export async function test_api_discussionboard_test_list_trending_topics_with_basic_filter_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Default query (no filters, default page/limit)
  const defaultInput = {
    page: 1,
    limit: 20,
  } satisfies ITrendingTopic.IRequest;
  const res1 = await api.functional.discussionboard.trendingTopics.index(connection, { body: defaultInput });
  typia.assert(res1);
  TestValidator.equals("default pagination page")(res1.pagination.current)(1);
  TestValidator.equals("default pagination limit")(res1.pagination.limit)(20);
  res1.data.forEach(topic => typia.assert(topic));

  // 2. Filter by ranking_period_date
  if (res1.data.length > 0) {
    const filterDate = res1.data[0].ranking_period_date;
    const dateInput = {
      page: 1,
      limit: 20,
      ranking_period_date: filterDate,
    } satisfies ITrendingTopic.IRequest;
    const res2 = await api.functional.discussionboard.trendingTopics.index(connection, { body: dateInput });
    typia.assert(res2);
    res2.data.forEach(topic => {
      typia.assert(topic);
      TestValidator.equals("ranking_period_date matches")(topic.ranking_period_date)(filterDate);
    });
  }

  // 3. Filter by board and thread ID
  if (res1.data.length > 0) {
    const filterBoardId = res1.data[0].discussionboard_board_id;
    const filterThreadId = res1.data[0].discussionboard_thread_id;
    const filterInput = {
      page: 1,
      limit: 20,
      discussionboard_board_id: filterBoardId,
      discussionboard_thread_id: filterThreadId,
    } satisfies ITrendingTopic.IRequest;
    const res3 = await api.functional.discussionboard.trendingTopics.index(connection, { body: filterInput });
    typia.assert(res3);
    res3.data.forEach(topic => {
      typia.assert(topic);
      TestValidator.equals("board_id matches")(topic.discussionboard_board_id)(filterBoardId);
      TestValidator.equals("thread_id matches")(topic.discussionboard_thread_id)(filterThreadId);
    });
  }

  // 4. Custom pagination (second page, custom limit)
  const customInput = {
    page: 2,
    limit: 5,
  } satisfies ITrendingTopic.IRequest;
  const res4 = await api.functional.discussionboard.trendingTopics.index(connection, { body: customInput });
  typia.assert(res4);
  TestValidator.equals("custom pagination page")(res4.pagination.current)(2);
  TestValidator.equals("custom pagination limit")(res4.pagination.limit)(5);

  // 5. Edge case: filter by thread_id + period_date that should not exist
  const impossibleInput = {
    page: 1,
    limit: 10,
    discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
    ranking_period_date: "2099-01-01T00:00:00Z",
  } satisfies ITrendingTopic.IRequest;
  const res5 = await api.functional.discussionboard.trendingTopics.index(connection, { body: impossibleInput });
  typia.assert(res5);
  TestValidator.equals("no data on impossible filter")(res5.data.length)(0);
}

