/**
 * 넘치는 페이지 번호로 Trending Topics 조회 (페이지 오버플로우 페이징 API 테스트)
 *
 * - 실제 존재하는 페이지 수보다 큰 page 번호로 trending topics 조회를 시도할 때,
 *   API가 빈 data 배열([])과 올바른 pagination 메타데이터를 반환하는지 검증합니다.
 * - 예외나 에러 없이, 정상적인 포맷/구조로 응답하는지 반드시 확인합니다.
 *
 * 테스트 순서:
 * 1. 정상적으로 trending topic을 1페이지(limit=10) 조회하여 전체 페이지 수, 전체 레코드 수를 확인합니다.
 * 2. 존재하지 않는(overflow) 페이지 번호(page=20 또는 최대 페이지+1)로 다시 요청합니다.
 * 3. 반환된 data가 빈 배열이고, pagination 메타데이터가 일관되며, API가 예외 없이 동작함을 검증합니다.
 *
 * 이 테스트는 페이징 방어코드(오버플로우 페이지 요청시 빈 데이터 및 일관된 메타 제공)에 대한 회귀/경계값 검증입니다.
 */
export async function test_api_discussionboard_test_list_trending_topics_pagination_overflow(
  connection: api.IConnection
) {
  // 1. 우선 정상 페이지(1페이지, limit=10)로 trending topics 조회 (실제 데이터 존재 가정)
  const normalResponse = await api.functional.discussionboard.trendingTopics.index(connection, {
    body: {
      page: 1,
      limit: 10
    } satisfies ITrendingTopic.IRequest
  });
  typia.assert(normalResponse);
  const totalPages = normalResponse.pagination.pages;
  const totalRecords = normalResponse.pagination.records;

  // 2. 존재하지 않는 page 번호로 overflow/오버페이징 요청(page=20 또는 totalPages+1)
  const overflowPageNumber = totalPages + 10 > 20 ? totalPages + 1 : 20;
  const overflowResponse = await api.functional.discussionboard.trendingTopics.index(connection, {
    body: {
      page: overflowPageNumber,
      limit: 10
    } satisfies ITrendingTopic.IRequest
  });
  typia.assert(overflowResponse);

  // 3. data가 빈 배열([])임을 검증
  TestValidator.equals("overflow data empty array")(overflowResponse.data)([]);

  // 4. pagination 메타데이터 논리 체크
  TestValidator.equals("pagination current matches requested")(overflowResponse.pagination.current)(overflowPageNumber);
  TestValidator.equals("pagination limit matches")(overflowResponse.pagination.limit)(10);
  TestValidator.equals("pagination pages matches real page count")(overflowResponse.pagination.pages)(totalPages);
  TestValidator.equals("pagination records matches real count")(overflowResponse.pagination.records)(totalRecords);
}

