/**
 * Comprehensive test for updating discussion board engagement metrics.
 *
 * This E2E test validates the correct behavior and robustness of the engagement metric update API. It ensures not only successful full-field updates but also robustness against invalid operations and proper enforcement of business rules for the model. Steps:
 *
 * 1. Create a baseline engagement metric to update.
 * 2. Update all updatable fields (counts and associations) with new valid data and confirm changes.
 * 3. Edge: update associations to null, and verify nullability is respected.
 * 4. Try updating a non-existent id; verify not-found handling.
 * 5. Attempt updates with business-logic invalid negative counts and check they are rejected.
 */
export async function test_api_discussionboard_engagementMetrics_test_update_engagement_metric_fields_and_handle_errors(
  connection: api.IConnection,
) {
  // 1. Create a metric for update test
  const created = await api.functional.discussionboard.engagementMetrics.create(
    connection,
    {
      body: {
        discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
        engagement_date: typia.random<string & tags.Format<"date-time">>(),
        posts_created_count: 2,
        comments_created_count: 5,
        votes_cast_count: 3,
      } satisfies IDiscussionboardEngagementMetric.ICreate,
    },
  );
  typia.assert(created);

  // 2. Update all updatable fields with new valid replacements
  const updated = await api.functional.discussionboard.engagementMetrics.update(
    connection,
    {
      id: created.id,
      body: {
        discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
        engagement_date: typia.random<string & tags.Format<"date-time">>(),
        posts_created_count: 20,
        comments_created_count: 8,
        votes_cast_count: 4,
      } satisfies IDiscussionboardEngagementMetric.IUpdate,
    },
  );
  typia.assert(updated);
  TestValidator.equals("update applied: post count")(updated.posts_created_count)(20);
  TestValidator.equals("update applied: comments")(updated.comments_created_count)(8);
  TestValidator.equals("update applied: votes")(updated.votes_cast_count)(4);

  // 3. Edge: update associations to null and verify API accepts nulls
  const nullFields = await api.functional.discussionboard.engagementMetrics.update(
    connection,
    {
      id: created.id,
      body: {
        discussionboard_member_id: null,
        discussionboard_board_id: null,
        engagement_date: typia.random<string & tags.Format<"date-time">>(),
        posts_created_count: 7,
        comments_created_count: 2,
        votes_cast_count: 1,
      } satisfies IDiscussionboardEngagementMetric.IUpdate,
    },
  );
  typia.assert(nullFields);
  TestValidator.equals("member is null")(nullFields.discussionboard_member_id)(null);
  TestValidator.equals("board is null")(nullFields.discussionboard_board_id)(null);

  // 4. Update to a non-existent id (not found)
  await TestValidator.error("update not found")(() =>
    api.functional.discussionboard.engagementMetrics.update(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
        engagement_date: typia.random<string & tags.Format<"date-time">>(),
        posts_created_count: 22,
        comments_created_count: 3,
        votes_cast_count: 5,
      } satisfies IDiscussionboardEngagementMetric.IUpdate,
    })
  );

  // 5. Updates with business logic invalid negative counts
  for (const field of [
    "posts_created_count",
    "comments_created_count",
    "votes_cast_count",
  ]) {
    const next: IDiscussionboardEngagementMetric.IUpdate = {
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      engagement_date: typia.random<string & tags.Format<"date-time">>(),
      posts_created_count: 1,
      comments_created_count: 2,
      votes_cast_count: 3,
    };
    (next as any)[field] = -123;
    await TestValidator.error(`negative value - ${field}`)(() =>
      api.functional.discussionboard.engagementMetrics.update(connection, {
        id: created.id,
        body: next,
      })
    );
  }
}

