 * 3. Create a board required for thread and post creation
 * 4. Create a thread under that board, authored by the test member
 * 5. Create a normal post (is_deleted=false), authored by the test member
 * 6. Create a soft-deleted post (simulate is_deleted=true via DB or patch, or direct if possible)
 *    - Note: The POST /posts endpoint only handles is_deleted=false on creation, so explicitly test normal creation + post-update for deletion if possible, else simulate/fake
 * 7. Retrieve the normal post by ID (as regular member): assert response includes all fields, is_deleted=false, matches create data
 * 8. Retrieve the soft-deleted post by ID (as regular member): assert response includes all fields, is_deleted=true
 * 9. Retrieve the same posts by ID as moderator: assert same field visibility/content
 * 10. Attempt to retrieve a post with a random (non-existent) UUID: confirm a 404 error is thrown
 */
export async function test_api_discussionboard_test_get_single_post_success_and_soft_delete_visibility(
  connection: api.IConnection,
) {
  // 1. Create a test regular member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: memberEmail,
      hashed_password: RandomGenerator.alphaNumeric(32),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create a test moderator member
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: moderatorEmail,
      hashed_password: RandomGenerator.alphaNumeric(32),
      role: "moderator",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(moderator);

  // 3. Create a board
  const board: IBoard = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.alphaNumeric(10),
      code: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(),
      is_active: true,
      is_visible: true,
    } satisfies IBoard.ICreate,
  });
  typia.assert(board);

  // 4. Create a thread under the board, authored by the regular member
  const thread: IDiscussionboardThreads = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: board.id,
      author_member_id: member.id,
      title: RandomGenerator.alphaNumeric(20),
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);

  // 5. Create a normal post under the thread
  const normalPost: IDiscussionboardPost = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      discussionboard_member_id: member.id,
      discussionboard_board_id: board.id,
      title: RandomGenerator.alphaNumeric(24),
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(normalPost);
  TestValidator.equals("is_deleted for normal post")(normalPost.is_deleted)(false);

  // 6. Create a soft-deleted post (simulate deletion if direct creation not supported)
  const deletedPost: IDiscussionboardPost = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      discussionboard_member_id: member.id,
      discussionboard_board_id: board.id,
      title: RandomGenerator.alphaNumeric(22),
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(deletedPost);
  // Simulate soft-delete: if no patch/delete support, fake by setting is_deleted to true in memory for test assertion purposes only
  const deletedPostId = deletedPost.id;

  // 7. Retrieve the normal post by ID (as regular member)
  let retrieved: IDiscussionboardPost = await api.functional.discussionboard.posts.at(connection, { id: normalPost.id });
  typia.assert(retrieved);
  TestValidator.equals("post id matches")(retrieved.id)(normalPost.id);
  TestValidator.equals("thread id matches")(retrieved.discussionboard_thread_id)(thread.id);
  TestValidator.equals("title matches")(retrieved.title)(normalPost.title);
  TestValidator.equals("is_deleted false")(retrieved.is_deleted)(false);

  // 8. Retrieve the deleted post by ID (as regular member)
  // Since we cannot really soft-delete via API, we check actual field which is false
  retrieved = await api.functional.discussionboard.posts.at(connection, { id: deletedPostId });
  typia.assert(retrieved);
  // TestValidator.equals("is_deleted true")(retrieved.is_deleted)(true); // Would require patch/delete support

  // 9. Retrieve posts as moderator - here, result should be identical and test field presence, as API does not specify role filtering
  // Simulate as moderator: nothing to do, as current API has no per-role auth context or field filtering
  retrieved = await api.functional.discussionboard.posts.at(connection, { id: normalPost.id });
  typia.assert(retrieved);
  TestValidator.equals("post id matches - moderator")(retrieved.id)(normalPost.id);
