  typia.assert(retrieved);
  // TestValidator.equals("is_deleted true - moderator")(retrieved.is_deleted)(true); // Would require patch/delete support

  // 10. Try retrieving a random (non-existent) post id (should 404)
  await TestValidator.error("404 on missing post")(() =>
    api.functional.discussionboard.posts.at(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
