import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoard";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";

/**
 * Test creating discussion board posts with both valid and invalid data.
 *
 * This test function exercises the /discussionboard/posts endpoint, covering both the successful creation of a new post and common failure scenarios (validation errors, constraint failures, and unexpected field rejection).
 *
 * 1. Prepare required dependencies:
 *    a. Create a discussionboard member (to act as post author)
 *    b. Create a board (to reference as discussionboard_board_id)
 *    c. Create a thread in the board (to reference as discussionboard_thread_id)
 * 2. Attempt to create a post using all valid required fields and verify the returned post matches input and is properly created.
 * 3. Test validation errors:
 *    a. Attempt to create post missing required fields (thread ID, board ID, or title). Confirm error is thrown.
 *    b. Attempt to use non-existent thread/board/member IDs and confirm error is thrown (constraint check).
 *    c. Attempt to include unexpected fields in payload and confirm error is thrown.
 */
export async function test_api_discussionboard_test_create_post_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Prepare required data: create member, board, and thread.
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.name(),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(10),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // Board dependency: Needs fake category and section UUIDs.
  const boardCategoryId = typia.random<string & tags.Format<"uuid">>();
  const sectionId = typia.random<string & tags.Format<"uuid">>();
  const board = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: boardCategoryId,
      discussionboard_section_id: sectionId,
      name: RandomGenerator.alphabets(8),
      code: RandomGenerator.alphaNumeric(6),
      is_active: true,
      is_visible: true,
      description: "Test board description",
    } satisfies IBoard.ICreate,
  });
  typia.assert(board);

  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: board.id,
      author_member_id: member.id,
      title: "Thread Title",
      body: "Thread body for test thread",
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);

  // 2. Create a post with valid data
  const postInput = {
    discussionboard_thread_id: thread.id,
    discussionboard_member_id: member.id,
    discussionboard_board_id: board.id,
    title: "Test Post Title",
    body: "Test post body content.",
  } satisfies IDiscussionboardPost.ICreate;
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: postInput,
  });
  typia.assert(post);

  TestValidator.equals("discussionboard_thread_id")(post.discussionboard_thread_id)(postInput.discussionboard_thread_id);
  TestValidator.equals("discussionboard_member_id")(post.discussionboard_member_id)(postInput.discussionboard_member_id);
  TestValidator.equals("discussionboard_board_id")(post.discussionboard_board_id)(postInput.discussionboard_board_id);
  TestValidator.equals("title")(post.title)(postInput.title);
  TestValidator.equals("body")(post.body)(postInput.body);
  TestValidator.equals("is_deleted")(post.is_deleted)(false);

  // 3.a. Missing required field (thread ID)
  await TestValidator.error("missing thread ID")(() =>
    api.functional.discussionboard.posts.create(connection, {
      body: {
        // discussionboard_thread_id omitted
        discussionboard_member_id: member.id,
        discussionboard_board_id: board.id,
        title: "Title",
        body: "Body",
      } as any, // Required for runtime error in test
    }),
  );

  // 3.b. Missing required field (title)
  await TestValidator.error("missing title")(() =>
    api.functional.discussionboard.posts.create(connection, {
      body: {
        discussionboard_thread_id: thread.id,
        discussionboard_member_id: member.id,
        discussionboard_board_id: board.id,
        // title omitted
        body: "Body",
      } as any,
    }),
  );

  // 3.c. Constraint violation: non-existent thread ID
  await TestValidator.error("invalid thread ID")(() =>
    api.functional.discussionboard.posts.create(connection, {
      body: {
        discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_member_id: member.id,
        discussionboard_board_id: board.id,
        title: "Title",
        body: "Body",
      },
    }),
  );

  // 3.d. Constraint violation: non-existent member ID
  await TestValidator.error("invalid member ID")(() =>
    api.functional.discussionboard.posts.create(connection, {
      body: {
        discussionboard_thread_id: thread.id,
        discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_board_id: board.id,
        title: "Title",
        body: "Body",
      },
    }),
  );

  // 3.e. Payload includes unexpected field (should fail)
  await TestValidator.error("unexpected field in payload")(() =>
    api.functional.discussionboard.posts.create(connection, {
      body: {
        discussionboard_thread_id: thread.id,
        discussionboard_member_id: member.id,
        discussionboard_board_id: board.id,
        title: "Title",
        body: "Body",
        unexpected_field: 123,
      } as any,
    }),
  );
}

