import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoard";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";

/**
 * Tests updating a discussion board post: edit of title, body, and soft delete.
 *
 * This scenario validates both normal and error update operations:
 *
 * 1. Creates all dependencies: board, member, thread, post.
 * 2. Updates post title/body. Verifies updated fields and updated_at field.
 * 3. Performs soft delete (is_deleted = true), checks is_deleted and updated_at.
 * 4. Attempts to update non-existent post (expects error).
 * 5. Attempts an invalid update with empty body (expects error).
 *
 * Steps:
 * 1. Create a member
 * 2. Create a board (with mock valid UUIDs)
 * 3. Create a thread in the board, by the member
 * 4. Create a post in the thread, by the member
 * 5. Update the post's title and body; verify changes and updated_at
 * 6. Soft delete post; verify is_deleted and updated_at
 * 7. Try update on non-existent post; check error
 * 8. Try update with empty body; check error
 */
export async function test_api_discussionboard_test_update_post_title_body_and_soft_delete(
  connection: api.IConnection,
) {
  // 1. Create a discussionboard member
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(member);

  // 2. Create a board (using valid random UUIDs for category/section)
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const sectionId = typia.random<string & tags.Format<"uuid">>();
  const board = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: categoryId,
      discussionboard_section_id: sectionId,
      name: RandomGenerator.paragraph()(),
      code: RandomGenerator.alphaNumeric(6),
      description: RandomGenerator.paragraph()(),
      is_active: true,
      is_visible: true,
    },
  });
  typia.assert(board);

  // 3. Create a thread in board as member
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: board.id,
      author_member_id: member.id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(thread);

  // 4. Create a post in the thread by member
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      discussionboard_member_id: member.id,
      discussionboard_board_id: board.id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);

  // 5. Update post title and body
  const newTitle = RandomGenerator.paragraph()();
  const newBody = RandomGenerator.content()()();
  const updated = await api.functional.discussionboard.posts.update(connection, {
    id: post.id,
    body: {
      title: newTitle,
      body: newBody,
    },
  });
  typia.assert(updated);
  TestValidator.equals("title updated")(updated.title)(newTitle);
  TestValidator.equals("body updated")(updated.body)(newBody);
  TestValidator.notEquals("updated_at changed")(updated.updated_at)(post.updated_at);

  // 6. Soft delete post and validate
  const softDeleted = await api.functional.discussionboard.posts.update(connection, {
    id: post.id,
    body: { is_deleted: true },
  });
  typia.assert(softDeleted);
  TestValidator.equals("is_deleted")(softDeleted.is_deleted)(true);
  TestValidator.notEquals("updated_at on delete")(softDeleted.updated_at)(updated.updated_at);

  // 7. Attempt to update with non-existent post id
  await TestValidator.error("update non-existent post")(() =>
    api.functional.discussionboard.posts.update(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { title: "ghost" },
    })
  );

  // 8. Attempt to update with invalid data (empty body)
  await TestValidator.error("update with empty body")(() =>
    api.functional.discussionboard.posts.update(connection, {
      id: post.id,
      body: {},
    })
  );
}

