import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";

/**
 * Verify soft deletion of a discussion board post and related behaviors.
 *
 * Business Context:
 * Deleting a discussion board post must mark it as deleted (soft delete) by setting its is_deleted flag to true, rather than fully removing the record. The post should remain retrievable (e.g. for audit review), and repeated DELETE calls should be idempotent. Deleting a non-existent post should fail with an appropriate error. The test covers both success and error scenarios, and verifies the integrity of the soft deletion mechanism.
 *
 * Steps:
 * 1. Create a test user (member).
 * 2. Create a board for posts.
 * 3. Create a thread associated with the board and user.
 * 4. Create a post in the created thread as the test user.
 * 5. Call DELETE (soft delete) on the post by id.
 * 6. (Skipped: Retrieval to check is_deleted due to API limitation.)
 * 7. Call DELETE again on the same post to check idempotency (should not error, or returns correct status).
 * 8. Attempt to soft-delete a random (non-existent) post—expect a business error.
 */
export async function test_api_discussionboard_test_soft_delete_post_and_retrieve_after_deletion(
  connection: api.IConnection,
) {
  // 1. Create a test member
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(member);

  // 2. Create a board
  const board = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.paragraph()(),
      code: RandomGenerator.alphaNumeric(8),
      is_active: true,
      is_visible: true,
    },
  });
  typia.assert(board);

  // 3. Create a thread
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: board.id,
      author_member_id: member.id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(thread);

  // 4. Create a post
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      discussionboard_member_id: member.id,
      discussionboard_board_id: board.id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);

  // 5. Soft-delete the post
  await api.functional.discussionboard.posts.erase(connection, { id: post.id });

  // 6. (Skipped: Retrieval to check is_deleted due to API limitation.)

  // 7. DELETE again to verify idempotency
  await api.functional.discussionboard.posts.erase(connection, { id: post.id });
  // If no error thrown, idempotency is respected

  // 8. DELETE a non-existent post id
  await TestValidator.error("Soft-delete non-existent post should error")(() =>
    api.functional.discussionboard.posts.erase(connection, { id: typia.random<string & tags.Format<"uuid">>() }),
  );
}

