import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IDiscussionboardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentReport";
import type { IPageDiscussionboardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardCommentReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { Idiscussionboard_comment_reports } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_comment_reports";

/**
 * Test paginated, filtered listing of comment reports for moderation & audit.
 *
 * This test sets up several members, their comments on various posts, and multiple comment reports with varying report types & reasons. Then, it validates the listing API for pagination & filtering.
 *
 * 1. Create several members with distinct usernames/emails (minimum 2-3)
 * 2. For each member, create at least one comment with a unique post id (randomly generated)
 * 3. Prepare at least two different report type ids (simulate random UUIDs since types registry not available)
 * 4. Submit several comment reports:
 *    - Each report references a comment id, member id, report type id, and distinct reason
 *    - Some comments should have multiple reports with different types or reasons
 * 5. Execute the listing API:
 *    a) Retrieve all reports paginated (no filter) and check all expected records present.
 *    b) Filter by a specific comment id and assert only reports for that ID are shown.
 *    c) Filter by report type id to validate type filter.
 *    d) Use pagination (page, limit) and verify returned records/offsets.
 *    e) Confirm that providing invalid or unlisted schema fields does NOT affect (but only schema fields work).
 *
 * Validations:
 * - All listing result data should be consistent with creation (cross-check IDs, reasons, report_type IDs, etc)
 * - No extraneous/filter-bypassing results
 */
export async function test_api_discussionboard_test_list_comment_reports_with_pagination_and_filtering(connection: api.IConnection) {
  // 1. Create members
  const memberA = await api.functional.discussionboard.members.create(connection, { body: { username: RandomGenerator.name(), email: typia.random<string & tags.Format<"email">>(), hashed_password: RandomGenerator.alphaNumeric(14), role: "member", is_active: true } });
  typia.assert(memberA);

  const memberB = await api.functional.discussionboard.members.create(connection, { body: { username: RandomGenerator.name(), email: typia.random<string & tags.Format<"email">>(), hashed_password: RandomGenerator.alphaNumeric(14), role: "member", is_active: true } });
  typia.assert(memberB);

  // 2. Create comments
  const postId1 = typia.random<string & tags.Format<"uuid">>();
  const postId2 = typia.random<string & tags.Format<"uuid">>();
  const commentA = await api.functional.discussionboard.comments.create(connection, { body: { discussionboard_post_id: postId1, discussionboard_member_id: memberA.id, body: RandomGenerator.content()()() } });
  typia.assert(commentA);

  const commentB = await api.functional.discussionboard.comments.create(connection, { body: { discussionboard_post_id: postId2, discussionboard_member_id: memberB.id, body: RandomGenerator.content()()() } });
  typia.assert(commentB);

  // 3. Report types
  const reportTypeA = typia.random<string & tags.Format<"uuid">>();
  const reportTypeB = typia.random<string & tags.Format<"uuid">>();

  // 4. Create comment reports
  const reportA1 = await api.functional.discussionboard.commentReports.create(connection, { body: { discussionboard_comment_id: commentA.id, discussionboard_member_id: memberB.id, discussionboard_report_type_id: reportTypeA, reason: "Spam content" } });
  typia.assert(reportA1);

  const reportA2 = await api.functional.discussionboard.commentReports.create(connection, { body: { discussionboard_comment_id: commentA.id, discussionboard_member_id: memberA.id, discussionboard_report_type_id: reportTypeB, reason: "Abusive language" } });
  typia.assert(reportA2);

  const reportB1 = await api.functional.discussionboard.commentReports.create(connection, { body: { discussionboard_comment_id: commentB.id, discussionboard_member_id: memberA.id, discussionboard_report_type_id: reportTypeA, reason: "Off-topic" } });
  typia.assert(reportB1);

  // Collect all created report objects for validation
  const allReports = [reportA1, reportA2, reportB1];

  // 5.a) Retrieve all reports paginated
  const pagedAll = await api.functional.discussionboard.commentReports.index(connection, { body: { page: 1, limit: 10 } });
  typia.assert(pagedAll);
  TestValidator.predicate("all reports included")(allReports.every(rep => pagedAll.data.some(r => r.id === rep.id)));

  // 5.b) Filter by comment id
  const pagedByCommentA = await api.functional.discussionboard.commentReports.index(connection, { body: { discussionboard_comment_id: commentA.id } });
  typia.assert(pagedByCommentA);
  TestValidator.equals("all reports are for commentA")(pagedByCommentA.data.every(r => r.discussionboard_comment_id === commentA.id))(true);

