/**
 * E2E test to validate creating a new comment report with all required, valid information.
 *
 * This test simulates a complete scenario:
 * - Preparation: create two members (one for authoring a comment, one as the reporting party)
 * - Prepare a valid report type (to use when filing the report)
 * - Author member creates a comment (the comment to be reported)
 * - Reporter member files a report on the comment, selecting the valid report type and providing a non-null, meaningful reason
 * - Validate: The report creation succeeds; the response record contains all correct fields and is type-validated
 * - Business validation: The returned report links correctly to the comment, reporter member, report type, and propagates the input reason. All required schema fields are present.
 * - (Optional) Future queries to confirm presence of report are out-of-scope due to lack of GET endpoints
 *
 * Steps:
 * 1. Create a member to act as the comment author
 * 2. Create a member who will be the reporter
 * 3. Create a valid report type (active)
 * 4. Author member creates a comment
 * 5. Reporter member files a report for the comment (valid report type, reason)
 * 6. Validate success and schema conformance of response
 * 7. Business checks: correct member/comment/type/reason in the report
 */
export async function test_api_discussionboard_test_create_comment_report_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create a member to act as comment author
  const authorData: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    role: "member",
    is_active: true,
  };
  const author = await api.functional.discussionboard.members.create(connection, { body: authorData });
  typia.assert(author);

  // 2. Create a member to be the reporting user
  const reporterData: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    role: "member",
    is_active: true,
  };
  const reporter = await api.functional.discussionboard.members.create(connection, { body: reporterData });
  typia.assert(reporter);

  // 3. Create a valid report type (active)
  const reportTypeData: Idiscussionboard_report_types.ICreate = {
    code: "abuse-" + RandomGenerator.alphabets(5).toLocaleLowerCase(),
    display_name: "신고유형 - " + RandomGenerator.alphabets(6),
    description: "테스트 신고 유형 설명", // Optional
    active: true,
  };
  const reportType = await api.functional.discussionboard.reportTypes.create(connection, { body: reportTypeData });
  typia.assert(reportType);

  // 4. Author creates a comment
  const commentData: IComment.ICreate = {
    discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_member_id: author.id,
    body: RandomGenerator.paragraph()(1),
    parent_id: null,
  };
  const comment = await api.functional.discussionboard.comments.create(connection, { body: commentData });
  typia.assert(comment);

  // 5. Reporter creates a comment report on the above comment
  const reportData: Idiscussionboard_comment_reports.ICreate = {
    discussionboard_comment_id: comment.id,
    discussionboard_member_id: reporter.id,
    discussionboard_report_type_id: reportType.id,
    reason: "해당 댓글은 정책 위반 의심이 있습니다. 자동신고테스트.",
  };
  const report = await api.functional.discussionboard.commentReports.create(connection, { body: reportData });
  typia.assert(report);

  // 6. Validate that all expected fields/relations and input values are preserved
  TestValidator.equals("reported comment id matches")(report.discussionboard_comment_id)(comment.id);
  TestValidator.equals("reporting member id matches")(report.discussionboard_member_id)(reporter.id);
  TestValidator.equals("report type id matches")(report.discussionboard_report_type_id)(reportType.id);
  TestValidator.equals("reason matches input")(report.reason)(reportData.reason);
  TestValidator.predicate("created_at is ISO string")(
    typeof report.created_at === "string" && !isNaN(Date.parse(report.created_at))
  );
}

