    body: {
      discussionboard_comment_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_report_type_id: typia.random<string & tags.Format<"uuid">>(),
      reason: "Initial reason - inappropriate language in comment.",
    } satisfies Idiscussionboard_comment_reports.ICreate,
  });
  typia.assert(initialReport);

