import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { INotificationTemplate } from "@ORGANIZATION/PROJECT-api/lib/structures/INotificationTemplate";

/**
 * Test permanent deletion of a notification template by ID.
 *
 * This test covers creation and permanent deletion of a template. Because there is no GET/read endpoint in the SDK, we cannot verify existence/non-existence of templates after deletion. We create a template, delete it, and ensure both steps complete with no errors thrown. We also create a second template as a control, which remains unaffected (though we cannot verify this due to missing SDK methods). This test is limited by the SDK's capabilities: only creation and deletion are checked.
 */
export async function test_api_discussionboard_test_delete_notification_template_successful(
  connection: api.IConnection,
) {
  // 1. Create the target notification template
  const targetTemplate = await api.functional.discussionboard.notificationTemplates.create(
    connection,
    {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        name: RandomGenerator.alphabets(12),
        description: RandomGenerator.paragraph()(),
        subject: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
        is_active: true,
      } satisfies INotificationTemplate.ICreate,
    },
  );
  typia.assert(targetTemplate);

  // 2. Create another template as a control
  const controlTemplate = await api.functional.discussionboard.notificationTemplates.create(
    connection,
    {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        name: RandomGenerator.alphabets(12),
        description: RandomGenerator.paragraph()(),
        subject: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
        is_active: true,
      } satisfies INotificationTemplate.ICreate,
    },
  );
  typia.assert(controlTemplate);

  // 3. Delete the target template
  await api.functional.discussionboard.notificationTemplates.erase(
    connection,
    { id: targetTemplate.id },
  );

  // NOTE: Cannot verify deletion by retrieval due to missing GET API. Test guarantees API calls complete without exception.
}

