 * 4. Confirm that the code for channel2 remains unchanged (still code2) after failed update by performing a no-op update.
 */
export async function test_api_discussionboard_test_update_channel_with_duplicate_code(
  connection: api.IConnection,
) {
  // 1. Create the first channel with a unique code
  const code1 = RandomGenerator.alphaNumeric(8);
  const channel1 = await api.functional.discussionboard.channels.create(connection, {
    body: {
      code: code1,
      name: RandomGenerator.alphaNumeric(12),
      description: RandomGenerator.alphaNumeric(24),
      position: typia.random<number & tags.Type<"int32">>(),
      active: true,
    } satisfies IDiscussionboardChannel.ICreate,
  });
  typia.assert(channel1);
  TestValidator.equals("first channel code matches")(channel1.code)(code1);

  // 2. Create the second channel with a different unique code
  const code2 = RandomGenerator.alphaNumeric(8);
  const channel2 = await api.functional.discussionboard.channels.create(connection, {
    body: {
      code: code2,
      name: RandomGenerator.alphaNumeric(12),
      description: RandomGenerator.alphaNumeric(24),
      position: typia.random<number & tags.Type<"int32">>(),
      active: true,
    } satisfies IDiscussionboardChannel.ICreate,
  });
  typia.assert(channel2);
  TestValidator.equals("second channel code matches")(channel2.code)(code2);

  // 3. Attempt to update the second channel's code to 'code1' (should fail)
  TestValidator.error("unique code constraint on update")(
    async () => {
      await api.functional.discussionboard.channels.update(connection, {
        id: channel2.id,
        body: {
          code: code1, // attempt duplicate
          name: channel2.name,
          description: channel2.description,
          position: channel2.position,
          active: channel2.active,
        } satisfies IDiscussionboardChannel.IUpdate,
      });
    },
  );

  // 4. Confirm channel2's code is still code2 by successfully updating with the same code2 value
  const stillChannel2 = await api.functional.discussionboard.channels.update(connection, {
    id: channel2.id,
    body: {
      code: code2,
      name: channel2.name,
      description: channel2.description,
      position: channel2.position,
      active: channel2.active,
    } satisfies IDiscussionboardChannel.IUpdate,
  });
  typia.assert(stillChannel2);
  TestValidator.equals("channel2's code remains unchanged")(stillChannel2.code)(code2);
}

